    #[Isco08Info(
        level: 1,
        code: '0',
        major_group: '0',
        sub_major_group: null,
        minor_group: null,
        unit_group: null,
        title: 'Armed Forces Occupations',
        definition: 'Armed forces occupations include all jobs held by members of the armed forces. Members of the armed forces are those personnel who are currently serving in the armed forces, including auxiliary services, whether on a voluntary or compulsory basis, and who are not free to accept civilian employment and are subject to military discipline. Included are regular members of the army, navy, air force and other military services, as well as conscripts enrolled for military training or other service for a specified period.',
        tasks_include: '',
        excluded_occupations: "Excluded from this group are: \n -  jobs held by persons in civilian employment of government establishments concerned with defence issues;\n -  police (other than military police);\n -  customs inspectors and members of border or other armed civilian services.",
        notes: 'Many jobs performed by members of the armed forces are similar, in terms of the nature of the work performed, to civilian occupations such as medical doctors, radio operators, cooks, secretaries and heavy truck drivers. Conceptually, it may be appropriate therefore, to classify such jobs in the armed forces with similar civilian jobs. This approach is adopted in several national occupation classifications. Typically such classifications also identify a number of military-specific occupational groups. In many countries, however, it is not possible to produce information about the nature of the work performed by members of the armed forces. In adapting ISCO-08 for national purposes countries may wish, therefore, to consider what approach best suits their circumstances and user needs. For purposes of international comparability, however, where data pertaining to members of the armed forces are reported and classified by occupation, they should be included, where possible, in ISCO-08 Major Group 0: Armed Forces Occupations.',
        occupational_titles: [],
        parent: null,
        ancestors: [],
        children: ['01', '02', '03'],
        descendants: ['01', '02', '03', '011', '021', '031', '0110', '0210', '0310'],
    )]
