    )]
    case ISCO08_26 = '26';

    #[Isco08Info(
        level: 2,
        code: '31',
        major_group: '3',
        sub_major_group: '31',
        minor_group: null,
        unit_group: null,
        title: 'Science and Engineering Associate Professionals',
        definition: 'Science and engineering associate professionals perform technical tasks connected with research and operational methods in science and engineering. They supervise and control technical and operational aspects of mining, manufacturing, construction and other engineering operations, and operate technical equipment including aircraft and ships. Competent performance in most occupations in this sub-major group requires skills at the third ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: setting up, monitoring and operating instruments and equipment, conducting and monitoring experiments and tests of systems; collecting and testing samples; recording observations and analysing data; preparing, revising and interpreting technical drawings and diagrams; coordinating, supervising, controlling and scheduling the activities of other workers; operating and monitoring switchboards, computerized control systems, and multi-function process control machinery; performing technical functions to ensure safe and efficient movement and operations ships, aircraft and other equipment.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '3',
        ancestors: ['3'],
        children: ['311', '312', '313', '314', '315'],
