    )]
    case ISCO08_31 = '31';

    #[Isco08Info(
        level: 2,
        code: '32',
        major_group: '3',
        sub_major_group: '32',
        minor_group: null,
        unit_group: null,
        title: 'Health Associate Professionals',
        definition: 'Health associate professionals perform technical and practical tasks to support diagnosis and treatment of illness, disease, injuries and impairments in humans and animals, and to support implementation of health care, treatment and referral plans usually established by medical, veterinary, nursing and other health professionals. Competent performance in most occupations in this sub-major group requires skills at the third ISCO skill level.',
        tasks_include: 'Tasks performed by workers in the sub-major group usually include: testing and operating medical imaging equipment and administering  radiation therapy; performing clinical tests on specimens of bodily fluids and tissues; preparing medications and other pharmaceutical compounds under the guidance of pharmacists; designing, fitting, servicing and repairing medical and dental devices and appliances; providing nursing and personal care and midwifery support services; using herbal and other therapies based on theories, beliefs and experiences originating in specific cultures.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '3',
        ancestors: ['3'],
        children: ['321', '322', '323', '324', '325'],
