    #[Isco08Info(
        level: 2,
        code: '41',
        major_group: '4',
        sub_major_group: '41',
        minor_group: null,
        unit_group: null,
        title: 'General and Keyboard Clerks',
        definition: 'General and keyboard clerks record, organize, store and retrieve information and perform a wide range of clerical and administrative tasks according to established procedures. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: recording, preparing, sorting, classifying and filing information; sorting, opening and sending mail; preparing reports and correspondence of a routine nature; photocopying and faxing documents; operating personal computers, word-processors or typewriters to record, input and process text and data; proofreading and correcting copy; preparing invoices and checking figures.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
