    #[Isco08Info(
        level: 2,
        code: '42',
        major_group: '4',
        sub_major_group: '42',
        minor_group: null,
        unit_group: null,
        title: 'Customer Services Clerks',
        definition: 'Customer services clerks deal with clients in connection with money-handling operations, travel arrangements, requests for information, making appointments, operating telephone switchboards, and interviewing for surveys or to complete applications for eligibility for services. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: performing money-handling operations in banks, post offices and betting and gambling establishments, or dealing with travel arrangements; supplying information requested by clients and making appointments; operating telephone switchboards; greeting and receiving visitors; interviewing survey respondents; interviewing applicants for services.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
