    #[Isco08Info(
        level: 2,
        code: '44',
        major_group: '4',
        sub_major_group: '44',
        minor_group: null,
        unit_group: null,
        title: 'Other Clerical Support Workers',
        definition: 'Other clerical support workers sort and deliver mail, file documents, prepare information for processing, maintain personnel records, check material for consistency with original source material, assist persons who cannot read or write, and perform various other specialized clerical duties. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: recording information regarding acquisition, issue and return of library books; classifying and filing various documents and other records; maintaining personnel records; sorting, recording and delivering mail from post offices, as well as from or within an enterprise; coding; correcting proofs; performing a range of miscellaneous clerical duties; writing on behalf of persons who are unable to read or write.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
