    #[Isco08Info(
        level: 2,
        code: '61',
        major_group: '6',
        sub_major_group: '61',
        minor_group: null,
        unit_group: null,
        title: 'Market-oriented Skilled Agricultural Workers',
        definition: 'Market-oriented skilled agricultural workers plan, organize and perform farming operations to grow and harvest field or tree and shrub crops and produce a variety of animals and animal products for sale or delivery on a regular basis to wholesale buyers, marketing organisations or at markets. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: preparing the soil; sowing, planting, spraying, fertilizing and harvesting field crops; growing fruit and other tree and shrub crops; growing garden vegetables and horticultural products; raising, breeding and tending animals mainly to obtain meat, milk, hair, fur, skin, or sericultural, apiarian or other products; storing and carrying out some processing of produce; selling their products to purchasers, marketing organizations or at markets. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: 'Jobs should be classified in Sub-major Group 63: Subsistence Farmers, Fishers, Hunters and Gatherers when goods (mostly food) are produced mainly for own consumption or for consumption by other members of the worker’s household. If a large surplus is produced, and more goods are sold than consumed, but the main aim of production was own consumption, the jobs should nevertheless be classified in Sub-major Group 63. Jobs should only be classified in Sub-major group 61: Market-oriented Skilled Agricultural Workers, or 62: Market-oriented Skilled Forestry, Fishery and Hunting Workers if the main aim of the activity is to produce goods for the market.',
        occupational_titles: [],
        parent: '6',
        ancestors: ['6'],
        children: ['611', '612', '613'],
        descendants: ['611', '612', '613', '6111', '6112', '6113', '6114', '6121', '6122', '6123', '6129', '6130'],
    )]
    case ISCO08_61 = '61';

    #[Isco08Info(
        level: 2,
        code: '62',
        major_group: '6',
        sub_major_group: '62',
        minor_group: null,
        unit_group: null,
        title: 'Market-Oriented Skilled Forestry, Fishery and Hunting Workers',
        definition: 'Market-oriented skilled forestry, fishery and hunting workers plan, organize and perform operations to cultivate, conserve and exploit natural and plantation forests, breed and raise fish, harvest and catch fish; and hunt and trap animals, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: renting or investing, equipment and machinery and purchasing supplies; planning and undertaking forestry, aquaculture, fishery and hunting operations; maintaining buildings, tanks, machinery and other equipment; delivering or marketing products; supervising and training other workers.',
        excluded_occupations: null,
        notes: 'Jobs should be classified in Sub-major Group 63: Subsistence Farmers, Fishers, Hunters and Gatherers, when goods (mostly food) are produced mainly for own consumption or for consumption by other members of the worker’s household. If a large surplus is produced, and more goods are sold than consumed, but the main aim of production was own consumption, the jobs should nevertheless be classified in Sub-major Group 63. Jobs should only be classified in Sub-major Group 61: Market-oriented Skilled Agricultural Workers, or 62, Market-oriented Skilled Forestry, Fishery and Hunting Workers if the main aim of the activity is to produce goods for the market.',
        occupational_titles: [],
        parent: '6',
        ancestors: ['6'],
        children: ['621', '622'],
        descendants: ['621', '622', '6210', '6221', '6222', '6223', '6224'],
    )]
    case ISCO08_62 = '62';

    #[Isco08Info(
        level: 2,
        code: '63',
        major_group: '6',
        sub_major_group: '63',
        minor_group: null,
        unit_group: null,
        title: 'Subsistence Farmers, Fishers, Hunters and Gatherers',
        definition: 'Subsistence farmers, fishers, hunters and gatherers grow and harvest field or tree and shrub crops, vegetables and fruit, gather wild fruits, medicinal and other plants, tend or hunt animals, catch fish and gather various forms of aquatic life in order to provide food, shelter and, in some cases, a minimum of cash income for themselves and their households. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: preparing the soil; sowing, planting, tending and harvesting field crops; growing vegetables, fruit and other tree and shrub crops; gathering wild fruits and medicinal and other plants; breeding, tending and feeding animals and poultry mainly to obtain meat, eggs, milk, hair, skin or other products; hunting or trapping animals; catching fish and gathering other forms of aquatic life; fetching water and gathering firewood; storing produce for later use and carrying out some processing of produce; building and maintaining houses and other shelters; making tools, clothes and utensils for use by the household; selling or bartering some products at local markets.',
        excluded_occupations: null,
        notes: "Jobs should be classified in Sub-major Group 63: Subsistence Farmers, Fishers, Hunters and gatherers, when goods (mostly food) are produced mainly for own consumption or for consumption by other members of the worker’s household. If a large surplus is produced, and more goods are sold than consumed, but the main aim of production was for own consumption, the jobs should nevertheless be classified in Sub-major Group 63. Jobs should only be classified in Sub-major Group 61: Market-oriented Skilled Agricultural Workers, or 62: Market-oriented Skilled Forestry, Fishery and Hunting Workers if the main aim of the activity is to produce goods for the market.\nJobs are also classified in Sub-major Group 63 when goods are produced only for own consumption or for consumption by members of the worker’s household, and no cash income or bartering is involved.",
        occupational_titles: [],
        parent: '6',
        ancestors: ['6'],
        children: ['631', '632', '633', '634'],
        descendants: ['631', '632', '633', '634', '6310', '6320', '6330', '6340'],
    )]
    case ISCO08_63 = '63';

    #[Isco08Info(
        level: 2,
        code: '71',
        major_group: '7',
        sub_major_group: '71',
        minor_group: null,
        unit_group: null,
        title: 'Building and Related Trades Workers (excluding Electricians)',
        definition: "Building and related trades workers construct, maintain and repair buildings, erect and repair foundations, walls and structures of brick, stone and similar materials; shape and finish stone for building and other purposes. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organization, the materials and tools used, and the nature and purpose of the final product.",
        tasks_include: "Tasks performed by workers in this sub-major group usually include: constructing, maintaining and repairing buildings and other structures, using traditional and\/or modern building techniques; constructing and repairing foundations, walls and structures of brick, stone and similar materials; breaking quarried stone into slabs or blocks; cutting, shaping and finishing stone for building, ornamental, monumental and other purposes; erecting reinforced concrete frameworks and structures as well as finishing and repairing cement surfaces; cutting, shaping, assembling and maintaining wooden structures and fittings; performing miscellaneous construction and building maintenance tasks. Supervision of other workers may be included.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '7',
        ancestors: ['7'],
        children: ['711', '712', '713'],
        descendants: ['711', '712', '713', '7111', '7112', '7113', '7114', '7115', '7119', '7121', '7122', '7123', '7124', '7125', '7126', '7127', '7131', '7132', '7133'],
    )]
    case ISCO08_71 = '71';

    #[Isco08Info(
        level: 2,
        code: '72',
        major_group: '7',
        sub_major_group: '72',
        minor_group: null,
        unit_group: null,
        title: 'Metal, Machinery and Related Trades Workers',
        definition: "Metal, machinery and related trades workers cast, weld, forge and, by other methods, form metal; erect, maintain and repair heavy metal structures; engage in machine-tool setting as well as in fitting, maintaining and repairing machinery, including engines, vehicles, or they produce tools and various non-precious-metal articles. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organisation, the materials and tools used, and the nature and purpose of the final product.",
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: making moulds and cores for casting metal; casting, welding and shaping metal; installing, erecting, maintaining and repairing heavy metal structures, tackle and related equipment; forging and forming steel and other non-precious metals to make and repair machinery, tools, equipment and other articles; setting for operators or setting and operating various machine tools; fitting, maintaining and repairing industrial machinery, including engines and vehicles. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '7',
        ancestors: ['7'],
        children: ['721', '722', '723'],
        descendants: ['721', '722', '723', '7211', '7212', '7213', '7214', '7215', '7221', '7222', '7223', '7224', '7231', '7232', '7233', '7234'],
    )]
    case ISCO08_72 = '72';

    #[Isco08Info(
        level: 2,
        code: '73',
        major_group: '7',
        sub_major_group: '73',
        minor_group: null,
        unit_group: null,
        title: 'Handicraft and Printing Workers',
        definition: "Handicraft and printing workers combine artistic and manual skills to design, produce, maintain and decorate precision instruments, musical instruments, jewellery and other precious-metals, pottery, porcelain and glassware, items made of wood or textile, leather or related materials, and printed products such as books, newspapers and magazines. They apply traditional and\/or recently developed techniques to carve, mould, assemble, weave and decorate various articles; to compose and set type prior to printing; to set up and operate printing presses; to bind and finish printed products; and to prepare stencils and operate screen printing equipment. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.\n\nThe work may be carried out by hand or involve the use of hand tools, hand-held power tools and in some cases the set-up and operation of machinery and machine tools. The tasks call for an understanding of the work organisation, the materials and tools used, and the nature and purpose of the final product.",
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: making and repairing nautical, meteorological, optical and other precision instruments and equipment; making and repairing musical instruments; making jewellery and precious metalware; making pottery, porcelain ware, ceramics and glassware; painting and decorating various articles; producing handicraft articles in wood or textile, leather and related materials; performing printing or book-binding tasks. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '7',
        ancestors: ['7'],
        children: ['731', '732'],
        descendants: ['731', '732', '7311', '7312', '7313', '7314', '7315', '7316', '7317', '7318', '7319', '7321', '7322', '7323'],
    )]
    case ISCO08_73 = '73';

    #[Isco08Info(
        level: 2,
        code: '74',
        major_group: '7',
        sub_major_group: '74',
        minor_group: null,
        unit_group: null,
        title: 'Electrical and Electronics Trades Workers',
        definition: "Electrical and electronics trades workers install, fit and maintain electrical wiring systems and machinery and other electrical apparatus, electrical transmission and supply lines and cables, and electronic and telecommunications equipment and systems. Competent performance in most occupations in this sub-major group requires skills at the second ISCO skill level.\n\nThe work is carried out by hand and by hand-powered and other tools which are used to reduce the amount of physical effort and time required for specific tasks, as well as to improve the quality of the products. The tasks call for an understanding of the work organisation, the materials and tools used, and the nature and purpose of the final product.",
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: installing, maintaining, fitting and adjusting electrical and electronic wiring systems, machinery and equipment; examining blueprints, wiring diagrams and specifications to determine sequences and methods of operation; inspecting and testing electrical and electronic systems, equipment, cables and machinery to identify hazards, defects, and the need for adjustment or repair; installing, maintaining and repairing electrical and telecommunications transmission lines; joining electrical, telecommunications and data cables; maintaining, troubleshooting, fitting, adjusting, testing and repairing electronic equipment such as commercial and office machines and electronic instruments and control systems, computers, telecommunications and data transmission equipment.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
