    #[Isco08Info(
        level: 2,
        code: '92',
        major_group: '9',
        sub_major_group: '92',
        minor_group: null,
        unit_group: null,
        title: 'Agricultural, Forestry and Fishery Labourers',
        definition: 'Agricultural, forestry and fishery labourers perform simple and routine tasks in the production of crops and livestock, cultivation and maintenance of gardens and parks, exploitation and conservation of forests, and conduct of aquaculture and fisheries operations. Most occupations in this sub-major group require skills at the first ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: digging, raking and shovelling using hand tools; loading unloading and stacking supplies, produce and other materials; watering, thinning, weeding and tending crops by hand or using hand tools; planting, harvesting picking and collecting produce by hand; feeding, watering, and cleaning animals and keeping their quarters clean; monitoring livestock, reporting on their condition; preparing and operating nets, lines and other fishing tackle and deck equipment; grading, sorting, bunching and packing produce into containers; performing minor repairs on fixtures, buildings, equipment, vessels and fences.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '9',
        ancestors: ['9'],
        children: ['921'],
        descendants: ['921', '9211', '9212', '9213', '9214', '9215', '9216'],
    )]
    case ISCO08_92 = '92';

    #[Isco08Info(
        level: 2,
        code: '93',
        major_group: '9',
        sub_major_group: '93',
        minor_group: null,
        unit_group: null,
        title: 'Labourers in Mining, Construction, Manufacturing and Transport',
        definition: 'Labourers in mining, construction, manufacturing and transport perform simple and routine manual tasks in mining, quarrying, civil engineering, building, manufacturing, transport and storage operations, and operate human-powered and animal-drawn vehicles and machinery. Most occupations in this sub-major group require skills at the first ISCO skill level.',
        tasks_include: 'Task performed by workers in this sub-major group usually include: digging holes and spreading excavated materials, sand, soil, and gravel using hand-held tools; sorting, loading, unloading, moving stacking and storing materials, equipment, products, supplies, baggage and cargo by hand; cleaning machinery, equipment, tools and work sites; packing and unpacking material and products and filling containers and shelves with products by hand; operating human-powered and animal-drawn vehicles and machinery',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '9',
        ancestors: ['9'],
        children: ['931', '932', '933'],
        descendants: ['931', '932', '933', '9311', '9312', '9313', '9321', '9329', '9331', '9332', '9333', '9334'],
    )]
    case ISCO08_93 = '93';

    #[Isco08Info(
        level: 2,
        code: '94',
        major_group: '9',
        sub_major_group: '94',
        minor_group: null,
        unit_group: null,
        title: 'Food Preparation Assistants',
        definition: 'Food preparation assistants prepare and cook to order a small variety of pre-cooked food or beverages, clear tables, clean kitchen areas and wash dishes. Most occupations in this sub-major group require skills at the first ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub- major group usually include: preparing simple or pre-prepared foods and beverages such as sandwiches, pizzas, fish and chips, salads and coffee; washing, cutting, measuring and mixing foods for cooking; operating cooking equipment such as grills, microwaves and deep-fat fryers; cleaning kitchens, food preparation areas and service areas; cleaning cooking and general utensils used in kitchens and restaurants.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '9',
        ancestors: ['9'],
        children: ['941'],
