    #[Isco08Info(
        level: 2,
        code: '95',
        major_group: '9',
        sub_major_group: '95',
        minor_group: null,
        unit_group: null,
        title: 'Street and Related Sales and Service Workers',
        definition: 'Street and related sales and service workers sell goods (excluding food) for immediate consumptions, and provide a variety of services on streets and in other public places such as stations. Most occupations in this sub-major group require skills at the first ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include: buying or making various items for sale; loading and unloading items for sale and transporting them; obtaining the materials necessary to perform services; approaching people on the street to offer goods or services; cleaning and polishing shoes; cleaning and polishing car windows; running errands; assisting drivers to find a parking place and ensuring car is not damaged during driver’s absence; handing out leaflets and free newspapers; receiving immediate payment.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
