    #[Isco08Info(
        level: 2,
        code: '96',
        major_group: '9',
        sub_major_group: '96',
        minor_group: null,
        unit_group: null,
        title: 'Refuse Workers and Other Elementary Workers',
        definition: 'Refuse workers and other elementary workers collect, process and recycle garbage from buildings, yards, streets and other public places. They keep streets and other public places clean and tidy, deliver and carry messages and packages and perform odd jobs for private households or establishments. Most occupations in this sub-major group require skills at the first ISCO skill level.',
        tasks_include: 'Tasks performed by workers in this sub-major group usually include:  collecting, loading and unloading garbage; sweeping streets, parks and other public places; chopping firewood; collecting and carrying firewood, water, packages, luggage and messages; beating dust out of carpets and performing other odd-job tasks.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
