    #[Isco08Info(
        level: 3,
        code: '111',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '111',
        unit_group: null,
        title: 'Legislators and Senior Officials',
        definition: 'Legislators and senior officials determine, formulate, advise on and direct the implementation of policies of national, state, regional or local governments or communities, and of special interest organizations. They make, ratify, amend or repeal laws, public rules and regulations and plan, organize, direct, control and evaluate the overall activities of government departments and agencies, traditional communities and special-interest organizations.',
        tasks_include: 'Tasks performed usually include: presiding over or participating in the proceedings of legislative bodies and administrative councils of governments, legislative assemblies, local communities and special-interest organizations; serving on government administrative boards or official committees; investigating matters of concern to the public and promoting the interests of constituents; formulating and advising on government policy, budgets, laws and regulations; establishing objectives for organizations and formulating or approving and evaluating programmes and policies and  procedures for their implementation; recommending, reviewing, evaluating and approving documents, briefs and reports submitted; ensuring appropriate systems and procedures are developed and implemented to provide budgetary control; allocating the use of communal land and other resources; performing ceremonial duties and representing the government, organization or community at official occasions and in meetings, negotiations, conventions and public hearings.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '11',
        ancestors: ['1', '11'],
        children: ['1111', '1112', '1113', '1114'],
        descendants: ['1111', '1112', '1113', '1114'],
    )]
    case ISCO08_111 = '111';

    #[Isco08Info(
        level: 3,
        code: '112',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '112',
        unit_group: null,
        title: 'Managing Directors and Chief Executives',
        definition: 'Managing directors and chief executives formulate and review the policies and plan, direct, coordinate and evaluate the overall activities of enterprises or organizations (except special-interest organizations and government departments) with the support of other managers, usually within guidelines established by a board of directors or a governing body to whom they are answerable for the operations undertaken and results.',
        tasks_include: 'Tasks performed usually include: planning, directing and coordinating the general functioning of an enterprise or organization; reviewing the operations and results of the enterprise or organization, and reporting to boards of directors and governing bodies; determining objectives, strategies, policies and programmes for the enterprise or organization; providing overall direction and management to organizations; establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; authorizing material, human and financial resources to implement organizational policies and programmes; monitoring and evaluating performance of the organization or enterprise against established objectives and policies; consulting with senior subordinate staff and reviewing recommendations and reports; representing the organization at official occasions, in negotiations, at conventions, seminars, public hearings and forums; selecting or approving the selection of senior staff; ensuring the organization complies with relevant legislation and regulations.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '11',
        ancestors: ['1', '11'],
        children: ['1120'],
        descendants: ['1120'],
    )]
    case ISCO08_112 = '112';

    #[Isco08Info(
        level: 3,
        code: '121',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '121',
        unit_group: null,
        title: 'Business Services and Administration Managers',
        definition: 'Business services and administration managers plan, organize, direct, control and coordinate the financial, administrative, human resource, policy and planning activities of organizations, or of enterprises that provide such services to other enterprises and organizations.',
        tasks_include: 'Tasks performed usually include: formulating and administering policy advice, strategic and financial planning; establishing and directing operational and administrative procedures; implementing, monitoring and evaluating strategies and policies; providing advice to senior managers and board members on financial, administrative strategic, policy, programme and legislative issues; ensuring compliance with relevant legislation, regulations and standards; controlling selection, training and performance of staff; preparing budgets and overseeing financial operations; consulting with the chief executive and with managers of other departments or sections; controlling expenditure and ensuring the efficient use of resources; representing the organization in negotiations, and at conventions, seminars, public hearings and forums.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '12',
        ancestors: ['1', '12'],
        children: ['1211', '1212', '1213', '1219'],
        descendants: ['1211', '1212', '1213', '1219'],
    )]
    case ISCO08_121 = '121';

    #[Isco08Info(
        level: 3,
        code: '122',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '122',
        unit_group: null,
        title: 'Sales, Marketing and Development Managers',
        definition: 'Sales, marketing and development managers plan, organize, direct, control and coordinate the advertising, public relations, research and development, and sales and marketing activities of enterprises and organizations, or of enterprises that provide such services to other enterprises and organizations.',
        tasks_include: 'Tasks performed usually include: formulating and implementing policies and plans for advertising, public relations, product development, sales and marketing in consultation with other managers; directing the development of initiatives for new products or scientific research; marketing, public relations and advertising campaigns; determining and directing sales activities, product mix, customer service standards and merchandising methods and distribution policy; setting prices and credit arrangements; establishing and managing budgets and controlling expenditure to ensure the efficient use of resources; overseeing the selection, training and performance of staff; representing the enterprise or organization at conventions, trade exhibitions and other forums.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '12',
        ancestors: ['1', '12'],
        children: ['1221', '1222', '1223'],
        descendants: ['1221', '1222', '1223'],
    )]
    case ISCO08_122 = '122';

    #[Isco08Info(
        level: 3,
        code: '131',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '131',
        unit_group: null,
        title: 'Production Managers in Agriculture, Forestry and Fisheries',
        definition: 'Production managers in agriculture, forestry and fisheries plan, direct, and coordinate production in large scale agricultural, horticultural, forestry aquaculture and fishery operations such as plantations, large ranches, collective farms and co-operatives to grow and harvest crops,  breed and raise livestock, fish and shellfish and to catch and harvest fish and other forms of aquatic life.',
        tasks_include: 'Tasks performed usually include: monitoring market activity and planning production to meet contract requirements and market demand; establishing and managing budgets, monitoring production output and costs, recording information such as farm and fisheries  management practices, and preparing financial and operational reports; conferring with buyers to arrange for the sale of crops, catch and stock;  contracting with farmers, skippers or independent owners for production of produce and  management of production; planning the type, intensity and sequence of operations; purchasing machinery, equipment, and supplies; identifying and controlling environmental toxins, weeds, pests and diseases; organizing  operations such as maintaining buildings, water supply systems and equipment; overseeing the selection, training and performance of workers and contractors.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '13',
        ancestors: ['1', '13'],
        children: ['1311', '1312'],
        descendants: ['1311', '1312'],
    )]
    case ISCO08_131 = '131';

    #[Isco08Info(
        level: 3,
        code: '132',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '132',
        unit_group: null,
        title: 'Manufacturing, Mining, Construction and Distribution Managers',
        definition: 'Manufacturing, mining, construction, and distribution managers plan, organize, and coordinate the manufacturing, mineral extraction, construction, supply, storage and transportation operations, either as the manager of a department or as the general manager of an enterprise or organization that does not have a hierarchy of managers.',
        tasks_include: 'Tasks performed usually include: planning details of activities in terms of output quality and quantity, cost, timeliness and labour requirements; controlling the operation of plant and quality procedures through planning of maintenance, designation of operating hours and supply of equipment; preparing tenders and contract bids; establishing and managing budgets, monitoring production output and costs, and adjusting processes and resources to minimize costs; overseeing the acquisition and installation of new plant and equipment; controlling the preparation of production records and reports; coordinating the implementation of health and safety requirements; planning and directing daily operations; overseeing the selection, training and performance of staff.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '13',
        ancestors: ['1', '13'],
        children: ['1321', '1322', '1323', '1324'],
        descendants: ['1321', '1322', '1323', '1324'],
    )]
    case ISCO08_132 = '132';

    #[Isco08Info(
        level: 3,
        code: '133',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '133',
        unit_group: null,
        title: 'Information and Communications Technology Service managers',
        definition: 'Information and communications technology service managers plan, direct, and coordinate the acquisition, development, maintenance and use of computer and telecommunication systems, either as the manager of a department or as the general manager of an enterprise or organization that does not have a hierarchy of managers.',
        tasks_include: "Tasks performed usually include: consulting with users, management, vendors, and technicians to assess computing needs and system requirements and specifying technology to meet those needs; formulating and directing information and communication technology (ICT) strategies, policies and plans; directing the selection and installation of ICT resources and the provision of user training; directing ICT operations, analysing workflow, establishing priorities, developing standards and setting deadlines; overseeing the security of ICT systems; assigning, reviewing, managing and leading the work of systems analysts, programmers, and other computer-related workers; evaluating the organization's technology use and needs and recommending improvements such as hardware and software upgrades; establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources; establishing and directing operational and administrative procedures; overseeing the selection, training and performance of staff; representing the enterprise or organization at ICT-related conventions, seminars and conferences.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '13',
        ancestors: ['1', '13'],
        children: ['1330'],
        descendants: ['1330'],
    )]
    case ISCO08_133 = '133';

    #[Isco08Info(
        level: 3,
        code: '134',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '134',
        unit_group: null,
        title: 'Professional Services Managers',
        definition: 'Professional services managers plan, direct and coordinate the provision of childcare, health, welfare, education and other professional services, and manage the branches of institutions providing financial and insurance services.',
        tasks_include: 'Tasks performed usually include: formulating policies and plans for the provision of services and operation of establishments; setting standards and objectives; developing and implementing programmes and services to meet the needs of clients; directing and coordinating the allocation of resources; liaising with parents, boards, funding bodies, the community representatives and related agencies to discuss areas of cooperation and coordination; monitoring and controlling expenditure; overseeing the selection, development and performance of staff; preparing, or arranging for the preparation of, reports, budgets and forecasts; representing the organization in negotiations other agencies, and at conventions, seminars, public hearings and forums.',
        excluded_occupations: null,
        notes: 'Professional services managers are responsible for planning, directing and coordinating the provision of specialized professional and technical services. Specialized qualifications and extensive experience relevant to one or more occupations classified in Major Group 2: Professionals, or Major Group 3: Technicians and Associate Professionals, are usually required.',
        occupational_titles: [],
        parent: '13',
        ancestors: ['1', '13'],
        children: ['1341', '1342', '1343', '1344', '1345', '1346', '1349'],
        descendants: ['1341', '1342', '1343', '1344', '1345', '1346', '1349'],
    )]
    case ISCO08_134 = '134';

    #[Isco08Info(
        level: 3,
        code: '141',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '141',
        unit_group: null,
        title: 'Hotel and Restaurant Managers',
        definition: 'Hotel and restaurant managers plan, organize and direct the operations of establishments that provide accommodation, meals, beverages and other hospitality services.',
        tasks_include: 'Tasks performed usually include: planning and organizing special functions, sporting, gaming and entertainment activities; directing and overseeing reservation, reception, room service and housekeeping activities; observing liquor, gaming, health and other laws and regulations; monitoring quality at all stages of preparation and presentation of food and services; controlling the selection, training and supervision of staff; ensuring compliance with occupational health and safety regulations.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '14',
        ancestors: ['1', '14'],
        children: ['1411', '1412'],
        descendants: ['1411', '1412'],
    )]
    case ISCO08_141 = '141';

    #[Isco08Info(
        level: 3,
        code: '142',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '142',
        unit_group: null,
        title: 'Retail and Wholesale Trade Managers',
        definition: 'Retail and wholesale trade managers plan, organize, coordinate and control the operations of establishments that sell goods on a retail or wholesale basis. They are responsible for the budgets, staffing and strategic and operational direction of shops, or of organizational units within shops that sell particular types of product.',
        tasks_include: "Tasks performed usually include - determining product mix, stock levels and service standards; formulating and implementing purchasing and marketing policies, and setting prices; promoting and advertising the establishment's goods and services; maintaining records of stock levels and financial transactions; undertaking budgeting for the establishment; controlling selection, training and supervision of staff; ensuring compliance with occupational health and safety regulations.",
        excluded_occupations: null,
        notes: "Retail and wholesale trade managers are frequently employed in relatively small establishments that do not have a hierarchy of managers. The managers of large retail establishments such as supermarkets and department stores, however, should also be classified in this group, although such establishments may have a hierarchy of managers and supervisors. General managers of groups of establishments such as supermarket or department store chains are classified, however, in Unit Group 1120: Managing Directors and Chief Executives. \nOperators of small shops for whom the management and supervision of staff is not a significant component of the work are classified in Unit Group 5221: Shopkeepers. \nStaff who control and direct the activities of shop sales assistants, checkout operators and other workers, but who do not take responsibility for determining product mix, overall setting of prices, budgets and staffing levels, selection and recruitment, are classified in Unit Group 5222: Shop Supervisors.",
        occupational_titles: [],
        parent: '14',
        ancestors: ['1', '14'],
        children: ['1420'],
        descendants: ['1420'],
    )]
    case ISCO08_142 = '142';

    #[Isco08Info(
        level: 3,
        code: '143',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '143',
        unit_group: null,
        title: 'Other Services Managers',
        definition: 'Other services managers plan, organize, and control the operations of establishments that provide sporting, cultural, recreational, travel, customer contact and other amenity services.',
        tasks_include: 'Tasks performed usually include: planning and organizing the range and mix of services or activities provided; ensuring that facilities are kept clean and in good condition; keeping abreast of new trends and developments relevant to the service provided; advising on the facilities available and promoting publicity; checking and keeping custody of all cash receipts and making regular stock checks; establishing and managing budgets; controlling expenditure and ensuring the efficient use of resources; planning and directing daily operations; controlling the selection, supervision and performance of staff; ensuring compliance with health and safety requirements.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '14',
        ancestors: ['1', '14'],
        children: ['1431', '1439'],
        descendants: ['1431', '1439'],
    )]
    case ISCO08_143 = '143';

    #[Isco08Info(
        level: 3,
        code: '211',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '211',
        unit_group: null,
        title: 'Physical and Earth Science Professionals',
        definition: 'Physical and earth science professionals conduct research; improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to physics, astronomy, meteorology, chemistry, geology and geophysics.',
        tasks_include: 'Tasks performed usually include: enlarging scientific knowledge through research and experiments related to mechanics, thermodynamics, optics, sonics, electricity, magnetism, electronics, nuclear physics, astronomy, various branches of chemistry, atmospheric conditions and the physical nature of the Earth; and advising on or applying this knowledge in such fields as manufacturing, agriculture, medicine, navigation, space exploration, oil, gas, water and mineral exploitation, telecommunications and other services, or civil engineering; preparing scientific papers and reports.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '21',
        ancestors: ['2', '21'],
        children: ['2111', '2112', '2113', '2114'],
        descendants: ['2111', '2112', '2113', '2114'],
    )]
    case ISCO08_211 = '211';

    #[Isco08Info(
        level: 3,
        code: '212',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '212',
        unit_group: null,
        title: 'Mathematicians, Actuaries and Statisticians',
        definition: 'Mathematicians, actuaries and statisticians conduct research, improve or develop mathematical, actuarial and statistical concepts, theories and operational models and techniques; and apply this knowledge to a wide range of tasks in such fields as engineering, business and social and other sciences.',
        tasks_include: 'Tasks performed usually include: studying, improving and developing mathematical, actuarial and statistical theories and techniques; advising on or applying mathematical principles, models and techniques to a wide range of tasks in the fields of engineering, natural, social or life sciences; conducting logical analyses of management problems, especially in terms of input-output effectiveness, and formulating mathematical models of each problem usually for programming and solution by computer; designing and putting into operation pension schemes and life, health, social and other types of insurance systems; applying mathematics, statistics, probability and risk theory to assess potential financial impacts of future events; planning and organizing surveys and other statistical collections, and designing questionnaires; evaluating, processing, analysing and interpreting statistical data and preparing them for publication; advising on or applying various data collection methods and statistical methods and techniques, and determining reliability of findings, especially in such fields as business or medicine as well as in other areas of natural, social or life sciences; preparing scientific papers and reports; supervising the work of mathematical, actuarial and statistical assistants and statistical clerks.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '21',
        ancestors: ['2', '21'],
        children: ['2120'],
        descendants: ['2120'],
    )]
    case ISCO08_212 = '212';

    #[Isco08Info(
        level: 3,
        code: '213',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '213',
        unit_group: null,
        title: 'Life Science Professionals',
        definition: 'Life science professionals apply knowledge gained from research into human, animal and plant life and their interactions with each other and the environment to develop new knowledge, improve agricultural and forestry production, and solve human health and environmental problems.',
        tasks_include: 'Tasks performed usually include: collecting, analysing and evaluating experimental and field data to identify and develop new processes and techniques; providing advice and support to governments, organizations and businesses about ecological sustainable development of natural resources.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '21',
        ancestors: ['2', '21'],
        children: ['2131', '2132', '2133'],
        descendants: ['2131', '2132', '2133'],
    )]
    case ISCO08_213 = '213';

    #[Isco08Info(
        level: 3,
        code: '214',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '214',
        unit_group: null,
        title: 'Engineering Professionals (excluding Electrotechnology)',
        definition: 'Engineering professionals (excluding electrotechnology) design, plan and organize the testing, construction, installation and maintenance of structures, machines and their components, and production systems and plants; and plan production schedules and work procedures to ensure engineering projects are undertaken safely, efficiently and in a cost effective manner.',
        tasks_include: 'Tasks performed usually include: planning and designing chemical process systems, civil engineering projects, mechanical equipment and systems, mining and drilling operations, and other engineering projects; specifying and interpreting drawings and plans, and determining construction methods; supervising the construction of structures, water and gas supply and transportation systems, and the manufacture, installation, operation and maintenance of equipment, machines and plant; organizing and managing project labour and the delivery of materials, plant and equipment; estimating total costs and preparing detailed cost plans and estimates as tools for budgetary control; resolving design and operational problems in the various fields of engineering through the application of engineering technology.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '21',
        ancestors: ['2', '21'],
        children: ['2141', '2142', '2143', '2144', '2145', '2146', '2149'],
        descendants: ['2141', '2142', '2143', '2144', '2145', '2146', '2149'],
    )]
    case ISCO08_214 = '214';

    #[Isco08Info(
        level: 3,
        code: '215',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '215',
        unit_group: null,
        title: 'Electrotechnology Engineers',
        definition: 'Electrotechnology engineers conduct research on and design, advise, plan and direct the construction and operation of electronic, electrical and telecommunications systems, components, motors and equipment. They organize and establish control systems to monitor the performance and safety of electrical and electronic assemblies and systems.',
        tasks_include: 'Tasks performed usually include: conducting research and advising on and directing the maintenance and repair of electrical, electronic and telecommunications products and systems; advising on and designing power stations and systems that generate, transmit and distribute electrical power; establishing control standards to monitor performance and safety of electrical, electronic and telecommunication systems and equipment.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '21',
        ancestors: ['2', '21'],
        children: ['2151', '2152', '2153'],
        descendants: ['2151', '2152', '2153'],
    )]
    case ISCO08_215 = '215';

    #[Isco08Info(
        level: 3,
        code: '216',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: null,
        title: 'Architects, Planners, Surveyors and Designers',
        definition: 'Architects, planners, surveyors and designers plan and design landscapes, building exteriors and interiors, products for manufacture, and visual and audio-visual content for the communication of information. They conduct survey work to precisely position geographical features; design, prepare and revise maps; and develop and implement plans and policies for controlling the use of land.',
        tasks_include: 'Tasks performed usually include: determining the objectives and constraints of the design brief by consulting with clients and stakeholders; formulating design concepts and plans that harmonize aesthetic considerations with technical, functional, ecological and production requirements; preparing sketches, diagrams, illustrations, animations; plans, maps, charts, samples and models to communicate design concepts and other information; analysing photographs, satellite imagery, survey documents and data, maps, records, reports and statistics; undertaking research and analysing functional, spatial, commercial, cultural, safety, environmental  and aesthetic requirements.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '21',
        ancestors: ['2', '21'],
        children: ['2161', '2162', '2163', '2164', '2165', '2166'],
        descendants: ['2161', '2162', '2163', '2164', '2165', '2166'],
    )]
    case ISCO08_216 = '216';

    #[Isco08Info(
        level: 3,
        code: '221',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '221',
        unit_group: null,
        title: 'Medical Doctors',
        definition: 'Medical doctors (physicians) study, diagnose, treat and prevent illness, disease, injury, and other physical and mental impairments in humans through the application of the principles and procedures of modern medicine. They plan, supervise and evaluate the implementation of care and treatment plans by other health care providers, and conduct medical education and research activities.',
        tasks_include: 'Tasks performed usually include: conducting physical examinations of patients and interviewing them and their families  to determine their health status; ordering diagnostic tests and analysing findings; prescribing and administering curative treatments and preventive measures; performing surgery and other clinical procedures; monitoring  patients’ progress and response to treatment; advising on health, nutrition and lifestyle behaviours which aid prevention or treatment of disease and disorders; identifying and managing complications before, during and after childbirth; planning, managing and implementing referral plans for patients in need of specialized, long-term or other types of health care services; exchanging medical information with other health professionals to ensure continuing and comprehensive care; reporting births, deaths and notifiable diseases to government authorities; conducting research into human disorders and illnesses and preventive or curative methods.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '22',
        ancestors: ['2', '22'],
        children: ['2211', '2212'],
        descendants: ['2211', '2212'],
    )]
    case ISCO08_221 = '221';

    #[Isco08Info(
        level: 3,
        code: '222',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '222',
        unit_group: null,
        title: 'Nursing and Midwifery Professionals',
        definition: 'Nursing and midwifery professionals provide treatment and care services for people who are physically or mentally ill, disabled or infirm, and others in need of care due to potential risks to health including before, during and after childbirth. They assume responsibility for the planning, management and evaluation of the care of patients, including the supervision of other health care workers, working autonomously or in teams with medical doctors and others in the practical application of preventive and curative measures.',
        tasks_include: "Tasks performed usually include: assessing, planning, providing and evaluating nursing and midwifery care for patients according to the practice and standards of modern nursing and midwifery; coordinating the care of patients in consultation with other health professionals and members of health teams; developing and implementing care plans, treatments and therapies, including administering medications; monitoring and alleviating pain and discomfort experienced by patients using a variety of therapies, including the use of pain-killing drugs; monitoring patients' health condition, including progress of pregnancy and responses to curative treatment; providing information to patients, families and communities about a range of health issues, including prevention of illness, treatment and care, pregnancy and childbirth and other topics; supervising and coordinating the work of other health care workers; conducting research on nursing and midwifery practice and preparing scientific papers and reports.",
        excluded_occupations: null,
        notes: 'The distinctions between nursing and midwifery professionals and associate professionals should be made on the basis of the nature of the work performed in relation to the tasks specified in this definition and in the relevant unit group definitions. The qualifications held by individuals or that predominate in the country are not the main factor in making this distinction, as training arrangements for nurses and midwives vary widely between countries and have varied over time within countries.',
        occupational_titles: [],
        parent: '22',
        ancestors: ['2', '22'],
        children: ['2221', '2222'],
        descendants: ['2221', '2222'],
    )]
    case ISCO08_222 = '222';

    #[Isco08Info(
        level: 3,
        code: '223',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '223',
        unit_group: null,
        title: 'Traditional and Complementary Medicine Professionals',
        definition: 'Traditional and complementary medicine professionals examine patients, prevent and treat illness, disease, injury, and other physical and mental impairments and maintain general health in humans by applying knowledge, skills and practices acquired through extensive study of  the theories, beliefs and experiences, originating in specific cultures.',
        tasks_include: "Tasks performed usually include: conducting physical examinations of patients and interviewing them and their families to determine their health status; developing and implementing treatment plans for physical, mental and psychosocial ailments using applications such as acupuncture, ayurvedic, homoeopathic and herbal medicine; evaluating and documenting patients' progress through treatment plans; providing health, nutrition and lifestyle advice to individuals, families and communities;  prescribing and preparing traditional medicines, such as herbal, plant, mineral and animal extracts, to stimulate the body's capacity for self-healing; exchanging information about patients with other health care workers as needed to ensure continuing and comprehensive health care; conducting research into traditional and complementary medicines and treatments and disseminating findings such as through scientific papers and reports.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '22',
        ancestors: ['2', '22'],
        children: ['2230'],
        descendants: ['2230'],
    )]
    case ISCO08_223 = '223';

    #[Isco08Info(
        level: 3,
        code: '224',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '224',
        unit_group: null,
        title: 'Paramedical Practitioners',
        definition: 'Paramedical practitioners provide advisory, diagnostic, curative and preventive medical services for humans more limited in scope and complexity than those carried out by medical doctors. They work autonomously or with limited supervision of medical doctors, and apply advanced clinical procedures for treating and preventing diseases, injuries and other physical or mental impairments common to specific communities.',
        tasks_include: "Tasks performed usually include: conducting physical examinations of patients and interviewing them and their families to determine their health status and recording patients' medical information; performing basic or more routine medical and surgical procedures, including prescribing and administering treatments, medications and other preventive or curative measures, especially for common diseases and disorders; administering or ordering diagnostic tests, such as X-ray, electrocardiogram, and laboratory tests; performing therapeutic procedures, such as injections, immunizations, suturing and wound care, and infection management; assisting medical doctors with complex surgical procedures; monitoring patients' progress and response to treatment, and identifying signs and symptoms requiring referral to medical doctors; advising patients and families on diet, exercise and other habits which aid prevention or treatment of disease and disorders; identifying and referring complex or unusual cases to medical doctors, hospitals or other places for specialized care; reporting births, deaths and notifiable diseases to government authorities to meet legal and professional reporting requirements.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '22',
        ancestors: ['2', '22'],
        children: ['2240'],
        descendants: ['2240'],
    )]
    case ISCO08_224 = '224';

    #[Isco08Info(
        level: 3,
        code: '225',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '225',
        unit_group: null,
        title: 'Veterinarians',
        definition: 'Veterinarians diagnose, prevent and treat diseases, injuries and dysfunctions of animals. They may provide care to a wide range of animals or specialize in the treatment of a particular animal group or in a particular area of specialization, or provide professional services to commercial firms producing biological and pharmaceutical products.',
        tasks_include: 'Tasks performed usually include: determining the presence and nature of abnormal conditions by physical examination, laboratory testing and through diagnostic imaging techniques including radiography and ultrasound; treating animals medically and surgically, and administering and prescribing drugs, analgesics, and general and local anaesthetics; performing surgery, dressing wounds and setting broken bones; rendering obstetric services to animals; participating in programmes designed to prevent the occurrence and spread of animal diseases; inoculating animals against, and testing for, infectious diseases and notifying authorities of outbreaks of infectious animal diseases; performing autopsies to determine cause of death; advising clients on health, nutrition and feeding, hygiene, breeding and care of animals.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '22',
        ancestors: ['2', '22'],
        children: ['2250'],
        descendants: ['2250'],
    )]
    case ISCO08_225 = '225';

    #[Isco08Info(
        level: 3,
        code: '226',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '226',
        unit_group: null,
        title: 'Other Health Professionals',
        definition: 'Other health professionals provide health services related to dentistry, pharmacy, environmental health and hygiene, occupational health and safety, physiotherapy, nutrition, hearing, speech, vision and rehabilitation therapies.  This minor group includes all human health professionals, except doctors, traditional and complementary medicine practitioners, nurses, midwives and paramedical professionals.',
        tasks_include: "Tasks performed may include: assessing patients or clients to determine the nature of the disorder, illness or problem; developing and implementing treatment plans and evaluating and documenting patients' progress; diagnosing and treating diseases, injuries and malformations of the teeth, mouth, jaws and associated tissues; storing, preserving, compounding testing and dispensing medicinal products and counselling on their proper use and adverse effects; assessing, planning and implementing programmes to recognize, monitor and control environmental factors that can potentially affect human health, to improve or restore human motor functions, maximize movement ability, relieve pain syndromes, or to enhance the impact of food and nutrition on human health; diagnosing, managing and treating physical disorders affecting human hearing, communication or swallowing, or disorders of the eyes and visual system; advising clients about continued treatment and care and providing or arranging rehabilitation services; referring clients to or conferring with other health professionals or associate professionals if required.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '22',
        ancestors: ['2', '22'],
        children: ['2261', '2262', '2263', '2264', '2265', '2266', '2267', '2269'],
        descendants: ['2261', '2262', '2263', '2264', '2265', '2266', '2267', '2269'],
    )]
    case ISCO08_226 = '226';

    #[Isco08Info(
        level: 3,
        code: '231',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '231',
        unit_group: null,
        title: 'University and Higher Education Teachers',
        definition: 'University and higher education teachers prepare and deliver lectures and conduct tutorials in one or more subjects within a prescribed course of study at a university or other higher educational institution.  They conduct research, and prepare scholarly papers and books.',
        tasks_include: 'Tasks performed usually include: designing and modifying curricula and preparing courses of study in accordance with requirements; preparing and delivering lectures and conducting tutorials, seminars and laboratory experiments; stimulating discussion and independent thought among students; supervising, where appropriate, experimental and practical work undertaken by students; administering, evaluating and marking examination papers and tests; directing research of post-graduate students or other members of department; researching into and developing concepts, theories and operational methods for application in industrial and other fields; preparing scholarly books, papers or articles; participating in departmental and faculty meetings and in conferences and seminars.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '23',
        ancestors: ['2', '23'],
        children: ['2310'],
        descendants: ['2310'],
    )]
    case ISCO08_231 = '231';

    #[Isco08Info(
        level: 3,
        code: '232',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '232',
        unit_group: null,
        title: 'Vocational education teachers',
        definition: 'Vocational education teachers teach or instruct vocational or occupational subjects in adult and further education institutions and to senior students in secondary schools and colleges. They prepare students for employment in specific occupations or occupational areas for which university or higher education is not normally required.',
        tasks_include: "Tasks performed usually include: developing curricula and planning course content and methods of instruction; determining training needs of students or workers and liaising with individuals, industry and other education sectors to ensure provision of relevant education and training programmes; presenting lectures and conducting discussions to increase students' knowledge and competence; instructing and monitoring students in the use of tools, equipment and materials and the prevention of injury and damage; observing and evaluating students' work to determine progress, provide feedback and make suggestions for improvement; administering oral, written or performance tests to measure progress, evaluate training effectiveness and assess competency; preparing reports and maintaining records such as student grades, attendance rolls, and training activity details; supervising independent or group projects, field placements, laboratory work, or other training; providing individualized instruction and tutorial or remedial instruction; conducting on-the-job training sessions to teach and demonstrate principles, techniques, procedures or methods of designated subjects.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '23',
        ancestors: ['2', '23'],
        children: ['2320'],
        descendants: ['2320'],
    )]
    case ISCO08_232 = '232';

    #[Isco08Info(
        level: 3,
        code: '233',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '233',
        unit_group: null,
        title: 'Secondary Education Teachers',
        definition: 'Secondary education teachers teach one or more subjects at secondary education level, excluding subjects intended to prepare students for employment in specific occupational areas.',
        tasks_include: "Tasks performed usually include: designing and modifying curricula and preparing educational courses of study in accordance with curriculum guidelines; establishing and enforcing rules for behaviour and procedures for maintaining order among students; preparing and giving lessons, discussions, and demonstrations in one or more subjects; establishing clear objectives for all lessons, units and projects and communicating those objectives to students; preparing materials and classrooms for class activities; adapting teaching methods and instructional materials to meet students' varying needs and interests; observing and evaluating students’ performance and behaviour; preparing, administering and marking tests, assignments and examinations to evaluate pupils' progress; preparing reports about pupils' work and conferring with other teachers and parents; participating in meetings concerning the school's educational or organizational policies; planning, organizing and participating in school activities such as excursions, sporting events and concerts.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '23',
        ancestors: ['2', '23'],
        children: ['2330'],
        descendants: ['2330'],
    )]
    case ISCO08_233 = '233';

    #[Isco08Info(
        level: 3,
        code: '234',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '234',
        unit_group: null,
        title: 'Primary School and Early Childhood Teachers',
        definition: 'Primary school and early childhood teachers teach a range of subjects at the primary level of education and organize educational activities for children below primary school age.',
        tasks_include: 'Tasks performed usually include: preparing programme of learning and giving instruction in a range of subjects at the primary education level, planning and organising activities designed to facilitate children’s development of language, physical and social skills; preparing reports. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '23',
        ancestors: ['2', '23'],
        children: ['2341', '2342'],
        descendants: ['2341', '2342'],
    )]
    case ISCO08_234 = '234';

    #[Isco08Info(
        level: 3,
        code: '235',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '235',
        unit_group: null,
        title: 'Other Teaching Professionals',
        definition: 'Other teaching professionals conduct research and advise on teaching methods, teach people with learning difficulties or special needs; teach non-native languages for migration and related purposes; give private tuition; teach arts, information technology and other subjects outside the mainstream primary, secondary and higher education systems; and provide other teaching services not classified elsewhere in Sub-major Group 23: Teaching Professionals..',
        tasks_include: 'Tasks performed usually include: conducting research and developing or advising on teaching methods, courses and aids; teaching physically handicapped children, young persons or adults or those with learning difficulties or other with special needs, teaching non-native languages for migration purposes; teaching students in practice, theory and performance of music, drama, dance, visual and other arts; developing, scheduling and conducting training programmes and courses for information technology users.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '23',
        ancestors: ['2', '23'],
        children: ['2351', '2352', '2353', '2354', '2355', '2356', '2359'],
        descendants: ['2351', '2352', '2353', '2354', '2355', '2356', '2359'],
    )]
    case ISCO08_235 = '235';

    #[Isco08Info(
        level: 3,
        code: '241',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '241',
        unit_group: null,
        title: 'Finance Professionals',
        definition: 'Finance professionals plan, develop, organize, administer, invest, manage and conduct quantitative analyses of either financial accounting systems or funds for individuals, establishments and public or private institutions.',
        tasks_include: 'Tasks performed usually include: preparing and organizing financial statements for an organization; reviewing financial materials of an organization; providing financial advice to individuals and organizations; preparing analytic reports concerning segments of the economy and the economy as a whole.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '24',
        ancestors: ['2', '24'],
        children: ['2411', '2412', '2413'],
        descendants: ['2411', '2412', '2413'],
    )]
    case ISCO08_241 = '241';

    #[Isco08Info(
        level: 3,
        code: '242',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '242',
        unit_group: null,
        title: 'Administration Professionals',
        definition: 'Administration professionals apply various concepts and theories related to improving the effectiveness of organizations and the individuals within the organization.',
        tasks_include: 'Tasks performed usually include: evaluating the structure of organizations and suggesting areas of improvement; ensuring that the operational activities of an organization are consistent with the policy objectives of the organization; recruiting, training, developing and counselling personnel within an organization.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '24',
        ancestors: ['2', '24'],
        children: ['2421', '2422', '2423', '2424'],
        descendants: ['2421', '2422', '2423', '2424'],
    )]
    case ISCO08_242 = '242';

    #[Isco08Info(
        level: 3,
        code: '243',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '243',
        unit_group: null,
        title: 'Sales, Marketing and Public Relations Professionals',
        definition: 'Sales, marketing and public relations professionals plan, develop, coordinate and implement programmes of information dissemination to promote organizations, goods and services; and represent companies in selling a range of technical, industrial, medical, pharmaceutical and ICT goods and services.',
        tasks_include: 'Tasks performed usually include: commissioning and undertaking market research, analysing the findings and planning advertising, marketing and public relations activities; supporting business growth and development through the preparation and execution of marketing objectives, policies and programmes; planning and organizing publicity campaigns; appraising and selecting material submitted by writers, photographers, illustrators and others to create favourable publicity; acquiring and updating knowledge of employers’ and competitors’ goods and services, and market conditions; assessing customers’ needs and explaining and demonstrating goods and services to them; visiting regular and prospective client businesses to establish and act on marketing opportunities; quoting and negotiating prices and credit terms, and completing contracts.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '24',
        ancestors: ['2', '24'],
        children: ['2431', '2432', '2433', '2434'],
        descendants: ['2431', '2432', '2433', '2434'],
    )]
    case ISCO08_243 = '243';

    #[Isco08Info(
        level: 3,
        code: '251',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '251',
        unit_group: null,
        title: 'Software and Applications Developers and Analysts',
        definition: 'Software and applications developers and analysts conduct research, plan, design, write, test, provide advice on and improve information technology systems such as hardware, software and other applications to meet specific requirements. Competent performance in most occupations in this sub-major group requires skills at the fourth ISCO skill level.',
        tasks_include: 'Tasks performed usually include: researching information technology use in business functions and identifying areas in which improvements could be made to maximise effectiveness and efficiency; conducting research into the theoretical aspects of and operational methods for the use of computers; evaluating, planning and designing hardware or software configurations for specific applications; designing, writing, testing and maintaining computer programmes for specific requirements; evaluating, planning and designing Internet, Intranet and multimedia systems.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '25',
        ancestors: ['2', '25'],
        children: ['2511', '2512', '2513', '2514', '2519'],
        descendants: ['2511', '2512', '2513', '2514', '2519'],
    )]
    case ISCO08_251 = '251';

    #[Isco08Info(
        level: 3,
        code: '252',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '252',
        unit_group: null,
        title: 'Database and Network Professionals',
        definition: 'Database and network professionals design, develop, control, maintain and support the optimal performance and security of information technology systems and infrastructure, including databases, hardware and software, networks and operating systems.',
        tasks_include: 'Tasks performed usually include: designing and developing database architecture, data structures,  dictionaries and naming conventions for information systems projects; designing, constructing, modifying, integrating, implementing and testing database management systems; developing and implementing security plans, data administration policy, documentation and standards; maintaining and administering computer networks and related computing environments; analysing, developing, interpreting and evaluating complex system design and architecture specifications, data models and diagrams in the development, configuration and integration of computer systems.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '25',
        ancestors: ['2', '25'],
        children: ['2521', '2522', '2523', '2529'],
        descendants: ['2521', '2522', '2523', '2529'],
    )]
    case ISCO08_252 = '252';

    #[Isco08Info(
        level: 3,
        code: '261',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '261',
        unit_group: null,
        title: 'Legal Professionals',
        definition: 'Legal professionals conduct research on legal problems, advise clients on legal aspects of problems, plead cases or conduct prosecutions in courts of law, preside over judicial proceedings in courts of law and draft laws and regulations',
        tasks_include: 'Tasks performed usually include: giving clients legal advice, undertaking legal business on clients’ behalf, and conducting litigation when necessary; presiding over judicial proceedings- and pronouncing judgement in courts of law. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '26',
        ancestors: ['2', '26'],
        children: ['2611', '2612', '2619'],
        descendants: ['2611', '2612', '2619'],
    )]
    case ISCO08_261 = '261';

    #[Isco08Info(
        level: 3,
        code: '262',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '262',
        unit_group: null,
        title: 'Librarians, Archivists and Curators',
        definition: 'Librarians, archivists and curators develop and maintain the collections of archives, libraries, museums, art galleries, and similar establishments.',
        tasks_include: 'Tasks performed usually include: appraising or developing and organizing the contents of archives and artefacts of historical, cultural and artistic interest, and ensuring their safe-keeping and preservation; organizing the collections of and exhibitions at museums, art galleries and similar establishments; developing and maintaining the systematic collection of recorded and published material and making it available to users in libraries and related institutions; preparing scholarly papers and reports; conducting research.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '26',
        ancestors: ['2', '26'],
        children: ['2621', '2622'],
        descendants: ['2621', '2622'],
    )]
    case ISCO08_262 = '262';

    #[Isco08Info(
        level: 3,
        code: '263',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: null,
        title: 'Social and Religious Professionals',
        definition: 'Social and religious professionals conduct research, improve or develop concepts, theories and operational methods; apply knowledge relating to philosophy, politics, economics, sociology, anthropology, history, psychology, and other social sciences; or provide social services to meet the needs of individuals and families in a community.',
        tasks_include: 'Tasks performed usually include: formulating and applying solutions to present or projected economic, political or social problems; researching into and analysing past events and activities and tracing the origin and evolution of the human race; studying mental processes and behaviour of individuals and groups; providing social services; preparing scholarly papers and reports. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '26',
        ancestors: ['2', '26'],
        children: ['2631', '2632', '2633', '2634', '2635', '2636'],
        descendants: ['2631', '2632', '2633', '2634', '2635', '2636'],
    )]
    case ISCO08_263 = '263';

    #[Isco08Info(
        level: 3,
        code: '264',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '264',
        unit_group: null,
        title: 'Authors, Journalists and Linguists',
        definition: 'Authors, journalists and linguists conceive and create literary works, interpret and communicate news and public affairs through the media; and translate or interpret from one language into another.',
        tasks_include: 'Tasks performed usually include: writing literary works; appraising merits of literary and other works of art; collecting information about current affairs and writing about them; researching, investigating, interpreting and communicating news and public affairs through newspapers, television, radio and other media; translating written material from one language to another; simultaneously translating from one language to another.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '26',
        ancestors: ['2', '26'],
        children: ['2641', '2642', '2643'],
        descendants: ['2641', '2642', '2643'],
    )]
