    #[Isco08Info(
        level: 3,
        code: '322',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '322',
        unit_group: null,
        title: 'Nursing and Midwifery Associate Professionals',
        definition: 'Nursing and midwifery associate professionals provide basic nursing and personal care for people who are physically or mentally ill, disabled or infirm, and others in need of care due to potential risks to health including before, during and after childbirth. They generally work under the supervision of, and in support of implementation of health care, treatment and referrals plans established by, medical, nursing, midwifery and other health professionals.',
        tasks_include: 'Tasks performed usually include: providing nursing and personal care, treatment and advice to patients according to care plans as established by health professionals; assisting professional nurses, midwives and medical doctors in administering medication and treatments; cleaning wounds and applying surgical dressings; providing advice to individuals, families and communities on topics related to health, contraception, pregnancy and childbirth; assessing progress during pregnancy and childbirth, providing or assisting in delivery care and recognizing signs and symptoms requiring referral to a health professional; providing care and support to women and newborns following childbirth.',
        excluded_occupations: null,
        notes: 'The distinctions between nursing and midwifery professionals and associate professionals should be made on the basis of the nature of the work performed in relation to the tasks specified in this definition and in the relevant unit group definitions. The qualifications held by individuals or that predominate in the country are not the main factor in making this distinction, as training arrangements for nurses and midwives vary widely between countries and have varied over time within countries.',
        occupational_titles: [],
        parent: '32',
        ancestors: ['3', '32'],
        children: ['3221', '3222'],
        descendants: ['3221', '3222'],
    )]
    case ISCO08_322 = '322';

    #[Isco08Info(
        level: 3,
        code: '323',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '323',
        unit_group: null,
        title: 'Traditional and Complementary Medicine Associate Professionals',
        definition: 'Traditional and complementary medicine associate professionals prevent, care for and treat human physical and mental illnesses, disorders and injuries using herbal and other therapies based on theories, beliefs and experiences originating in specific cultures. They administer treatments using traditional techniques and medicaments, either acting independently or according to therapeutic care plans established by a traditional medicine or other health professional.',
        tasks_include: 'Tasks performed usually include: examining patients and interviewing them and their families to determine their health status and the nature of physical or mental disorders or illnesses or other ailments; recommending and providing care and treatment for illnesses and other ailments using traditional techniques and medicaments, such as physical manipulation and exercises, blood-letting using natural vessels, and preparations using herbs, plants, insects and animal extracts; administering treatments such as acupuncture, ayurvedic, homeopathic and herbal medicine as per therapeutic care plans and procedures usually developed by a traditional medicine or other health professional; providing care and treatment for physical injuries such as setting and healing fractured and dislocated bones using traditional methods of physical manipulation and herbal therapies; advising individuals, families and the community on health, nutrition, hygiene, lifestyle and other issues to maintain or improve health and well-being; referring patients to, and exchanging information with, other health care providers to ensure comprehensive and continuing care.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '32',
        ancestors: ['3', '32'],
        children: ['3230'],
        descendants: ['3230'],
    )]
    case ISCO08_323 = '323';

    #[Isco08Info(
        level: 3,
        code: '324',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '324',
        unit_group: null,
        title: 'Veterinary Technicians and Assistants',
        definition: 'Veterinary technicians and assistants carry out advisory, diagnostic, preventive and curative veterinary tasks, more limited in scope and complexity than those carried out by veterinarians. They care for animals under treatment and in temporary residence at veterinary facilities and assist veterinarians to perform procedures and operations.',
        tasks_include: 'Tasks performed usually include: advising communities and individuals on the treatment of animals and their diseases and injuries; conducting examinations of animals to make diagnoses or refer more difficult cases to veterinarians when needed; treating ill or injured animals, especially for common diseases and disorders; cleaning and sterilizing examination tables and instruments and preparing materials used in the examination and treatment of animals; carrying out technical tasks connected with artificial insemination of animals; getting animals ready for examination or treatment and restraining or holding them during treatment;  assisting veterinarians to administer anaesthetics and oxygen during treatment; placing animals in cages for recovery from operations and monitoring their condition.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '32',
        ancestors: ['3', '32'],
        children: ['3240'],
        descendants: ['3240'],
    )]
    case ISCO08_324 = '324';

    #[Isco08Info(
        level: 3,
        code: '325',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: null,
        title: 'Other Health Associate Professionals',
        definition: 'Other health associate professionals perform technical tasks and provide support services in dentistry, medical records administration, community health, the correction of reduced visual acuity, physiotherapy, environmental health, emergency medical treatment and other activities to support and promote human health.',
        tasks_include: 'Tasks performed usually include: providing basic care services for the prevention and treatment of diseases and disorders of the teeth and mouth; advising communities and individuals on hygiene, diet and other preventive measures to reduce potential risks to health; compiling and maintaining patients’ medical records to document condition and treatment and to provide data for research, billing, cost control and care improvement; assisting families to develop the necessary skills and resources to improve their health status; providing advice and education on sanitation and hygiene to limit the spread of infectious diseases; fitting and dispensing optical lenses; investigate the implementation of rules and regulations relating to environmental and occupational factors that may potentially affect human health; massaging the soft tissues of the body; showing patients to examination rooms and preparing them for examination; attending and responding to accidents and emergencies and to requests for medical assistance.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '32',
        ancestors: ['3', '32'],
        children: ['3251', '3252', '3253', '3254', '3255', '3256', '3257', '3258', '3259'],
        descendants: ['3251', '3252', '3253', '3254', '3255', '3256', '3257', '3258', '3259'],
    )]
