    #[Isco08Info(
        level: 3,
        code: '331',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '331',
        unit_group: null,
        title: 'Financial and Mathematical Associate Professionals',
        definition: 'Financial and mathematical associate professionals place a value on various items and property, maintain records of financial transactions, analyse loan application information and render a decision, buy and sell financial instruments, and perform mathematical and related calculations.',
        tasks_include: 'Tasks performed usually include: recording and transmitting buy and sell orders for securities, stocks, bonds or other financial instruments and for foreign exchange for future or immediate delivery; submitting credit and loan applications to management with recommendations for approval or rejection; or approve or reject applications within authorized limits ensuring that credit standards of the institution are respected; maintaining complete records of all financial transactions of an undertaking according to general bookkeeping principles, with guidance from accountants; assisting in planning and performing mathematical, statistical, actuarial, accounting and related calculations.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '33',
        ancestors: ['3', '33'],
        children: ['3311', '3312', '3313', '3314', '3315'],
        descendants: ['3311', '3312', '3313', '3314', '3315'],
    )]
    case ISCO08_331 = '331';

    #[Isco08Info(
        level: 3,
        code: '332',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '332',
        unit_group: null,
        title: 'Sales and Purchasing Agents and Brokers',
        definition: 'Sales and purchasing agents and brokers represent companies, governments and other organizations to buy and sell commodities, goods, insurance, shipping and other services to industrial, professional, commercial or other establishments, or act as independent agents to bring together buyers and sellers of commodities and services.',
        tasks_include: 'Tasks performed usually include: obtaining information about employers’ and competitors’ goods and services; monitoring and analysing market trends and conditions; obtaining information about clients’ needs and identifying suitable products and services; explaining and demonstrating products and services to clients; negotiating prices, contracts, terms, conditions and shipping arrangements for purchase or sale of goods, services or commodities.',
        excluded_occupations: null,
        notes: 'Sales managers are classified in Minor Group 122: Sales Marketing and Development Managers. Technical, medical and ICT sales professionals are classified in Minor Group 243: Sales, Marketing and Public Relations Professionals. Securities and finance dealers are classified in Minor Group 331: Financial and Mathematical Associate Professionals.',
        occupational_titles: [],
        parent: '33',
        ancestors: ['3', '33'],
        children: ['3321', '3322', '3323', '3324'],
        descendants: ['3321', '3322', '3323', '3324'],
    )]
    case ISCO08_332 = '332';

    #[Isco08Info(
        level: 3,
        code: '333',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '333',
        unit_group: null,
        title: 'Business Services Agents',
        definition: 'Business service agents establish contacts to sell various business services such as advertising space in the media; carry out customs clearance activities ensuring that necessary documents are in order; match jobseekers with vacancies; find workers for employers; arrange contracts for the performance of athletes, entertainers and artists, as well as for the publication of books, the production of plays, or the recording, performance and sale of music; and plan and organize conferences and similar events.',
        tasks_include: 'Tasks performed usually include: carrying out customs clearing procedures for exports or imports; arranging and coordinating conference and event services, such as conference facilities, catering, signage, displays, audiovisual and computer equipment, accommodation, transport and social events, for participants; matching jobseekers with vacancies; finding workers for vacant posts for employers; showing real estate properties to be sold or leased to prospective buyers or tenants and explaining terms of sale or conditions of rent or lease; selling by auction various kinds of property, cars, commodities, livestock, art, jewellery and other objects; arranging contracts for performers and performances.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '33',
        ancestors: ['3', '33'],
        children: ['3331', '3332', '3333', '3334', '3339'],
        descendants: ['3331', '3332', '3333', '3334', '3339'],
    )]
    case ISCO08_333 = '333';

    #[Isco08Info(
        level: 3,
        code: '334',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '334',
        unit_group: null,
        title: 'Administrative and Specialized Secretaries',
        definition: 'Administrative and specialized secretaries provide organizational, communication and documentation support services, utilizing specialized knowledge of the business activity of the organization in which they are employed. They take supervisory responsibility for office clerks in the organization.',
        tasks_include: 'Tasks performed usually include: coordinating, assigning and reviewing the work of clerical support workers; desktop publishing; preparing and processing legal documents and papers such as deeds, wills, affidavits and briefs; implementing and supporting the communication, documentation and internal managerial co-ordination activities of an organizational unit, on some occasions utilizing specialized knowledge of the business activity of the organization; scheduling and confirming meetings and appointments and communicating messages for clients; compiling, recording and reviewing legal and medical records, reports, documents and correspondence.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '33',
        ancestors: ['3', '33'],
        children: ['3341', '3342', '3343', '3344'],
        descendants: ['3341', '3342', '3343', '3344'],
    )]
    case ISCO08_334 = '334';

    #[Isco08Info(
        level: 3,
        code: '335',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: null,
        title: 'Government Regulatory  Associate Professionals',
        definition: 'Government regulatory associate professionals administer, enforce or apply relevant government rules and regulations relating to national borders, taxes and social benefits; investigate facts and circumstances relating to crimes; and issue or examine applications for licences or authorizations in connection with travel, exports and imports of goods, establishment of businesses, erection of buildings and other activities subject to government regulations.',
        tasks_include: 'Tasks performed usually include: patrolling national borders and checking persons and vehicles, travel and transport documents and goods transported across the border to ensure enforcement of government rules and regulations; examining tax returns to determine taxes payable by persons and businesses; examining and deciding on applications for social benefits; examining and deciding on applications for government authorizations and licences necessary to travel, export or import goods, erect buildings, establish businesses or undertake other activities subject to government regulations; monitoring the application of price, wage or weights and measures regulations; obtaining and verifying evidence, interviewing witnesses and suspects and analysing documents and computer files. They may receive guidance from senior government officials or managers. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '33',
        ancestors: ['3', '33'],
        children: ['3351', '3352', '3353', '3354', '3355', '3359'],
        descendants: ['3351', '3352', '3353', '3354', '3355', '3359'],
    )]
    case ISCO08_335 = '335';

    #[Isco08Info(
        level: 3,
        code: '341',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '341',
        unit_group: null,
        title: 'Legal, Social and Religious Associate Professionals',
        definition: 'Legal, social and religious associate professionals provide technical and practical services and support functions in legal processes and investigations, social and community assistance programmes and religious activities.',
        tasks_include: 'Tasks performed usually include: assisting and supporting legal, social work and religious professionals; obtaining and analysing evidence, preparing legal documents and serving court orders; administering and implementing social assistance programmes and community services; assisting clients to deal with personal and social problems; providing practical assistance, guidance and moral support to individuals and communities.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '34',
        ancestors: ['3', '34'],
        children: ['3411', '3412', '3413'],
