    #[Isco08Info(
        level: 3,
        code: '342',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '342',
        unit_group: null,
        title: 'Sports and Fitness Workers',
        definition: 'Sports and fitness workers prepare for and compete in sporting events for financial gain, train amateur and professional sportsmen and women to enhance performance; promote participation and standards in sport; organize and officiate sporting events; and provide instruction, training and supervision for various forms of exercise and other recreational activities.',
        tasks_include: 'Tasks performed usually include: participating in competitive sporting events; conducting sports training to develop ability in and knowledge of the sport; compiling rules concerning the conduct of sporting competitions, and controlling the progress of these events; planning, organizing and conducting practice sessions; developing and designing fitness programmes; delivering group exercise classes and personal tuition in a variety of fitness activities; promoting sports and sports skills development; and overseeing the participation of young people in sport.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '34',
        ancestors: ['3', '34'],
        children: ['3421', '3422', '3423'],
        descendants: ['3421', '3422', '3423'],
    )]
    case ISCO08_342 = '342';

    #[Isco08Info(
        level: 3,
        code: '343',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '343',
        unit_group: null,
        title: 'Artistic, Cultural and Culinary Associate Professionals',
        definition: 'Artistic, cultural and culinary associate professionals combine creative skills and technical and cultural knowledge in taking and processing still photographs; design and decoration of theatre sets, shop displays and the interiors of homes; preparation of objects for display; maintenance of library and gallery collections, records and cataloguing systems; creation of menus and preparation and presentation of food; provision of support for stage, film and television production; and in other areas of artistic and cultural endeavour.',
        tasks_include: 'Tasks performed usually include: operating still cameras to photograph people, events, scenes, materials, products and other subjects; applying artistic techniques to product design, interior decoration and sales promotion; mounting and preparing objects for display; designing and arranging exhibit furnishings, display cases and display areas; designing menus and overseeing the preparation of food; assisting directors and performers with the staging of theatrical, motion picture, television or commercial productions.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '34',
        ancestors: ['3', '34'],
        children: ['3431', '3432', '3433', '3434', '3435'],
        descendants: ['3431', '3432', '3433', '3434', '3435'],
    )]
    case ISCO08_343 = '343';

    #[Isco08Info(
        level: 3,
        code: '351',
        major_group: '3',
        sub_major_group: '35',
        minor_group: '351',
        unit_group: null,
        title: 'Information and Communications Technology Operations and User Support Technicians',
        definition: 'Information and communications technology operations and user support technicians provide support for the day-to-day running of communications systems, computer systems and networks, and provide technical assistance to users',
        tasks_include: 'Tasks performed usually include: operating and controlling peripheral and related computer equipment; monitoring systems for equipment failure or errors in performance; loading peripheral equipment, such as printers, with selected materials for operating runs, or oversee loading of peripheral equipment by peripheral equipment operators; answering user inquiries regarding software or hardware operation to resolve problems; installing and performing minor repairs to hardware, software or peripheral equipment, following design or installation specifications; overseeing the daily performance of systems; setting up equipment for employee use, performing or ensuring proper installation of cables, operating systems or appropriate software; establishing, operating and maintaining network and other data communications systems; installing, monitoring and supporting the reliability and usability of Internet and Intranet websites or web server hardware or software; modifying web pages; and performing web server backup and recovery operations.',
        excluded_occupations: null,
        notes: null,
