    #[Isco08Info(
        level: 3,
        code: '521',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '521',
        unit_group: null,
        title: 'Street and Market Salespersons',
        definition: 'Street and market salespersons sell goods from stalls on markets or in streets and prepare and sell hot or cold food and beverages ready for immediate consumption in streets and public places.',
        tasks_include: 'Tasks performed usually include: obtaining permission to set up a stand at a particular place in streets, markets or other open spaces or to sell food and drinks on the street; buying or contracting a regular supply of products to be sold; erecting and dismantling stalls and stands; transporting, storing, loading and unloading products for sale; stacking, displaying and selling goods, food and drinks and accepting payment; wrapping and packing goods sold; preparing food and drinks for sale; pushing, pedalling or carrying handcart, trucks, trays or baskets to bring food and drinks to the desired place in the street, or to public places such as stations or cinemas; keeping accounts and maintaining a record of stock levels.',
        excluded_occupations: null,
        notes: 'Vendors in streets and public places of non-food items (or of pre-packaged non-perishable food items such as confectionery) from pushcarts, trucks, trays or baskets are classified in Minor Group 952: Street Vendors (excluding Food).',
        occupational_titles: [],
        parent: '52',
        ancestors: ['5', '52'],
        children: ['5211', '5212'],
        descendants: ['5211', '5212'],
    )]
    case ISCO08_521 = '521';

    #[Isco08Info(
        level: 3,
        code: '522',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '522',
        unit_group: null,
        title: 'Shop Aalespersons',
        definition: 'Shop salespersons sell a range of goods and services directly to the public or on behalf of retail and wholesale establishments. They explain functions and qualities of these goods and services, and may operate small shops or supervise the activities of shop sales assistants and cashiers.',
        tasks_include: 'Tasks performed usually include: determining customer requirements and advising on product range, price, delivery, warranties and product use and care; demonstrating, explaining and selling goods and services to customers; accepting payment for good and services by a variety of payment methods, and preparing sales invoices; undertaking or assisting with the ongoing management of stock such as product inventories, and participating in stock takes; stacking and displaying goods for sale, and wrapping and packing goods sold; determining product mix, stock and price levels for goods to be sold; supervising and coordinating the activities of shop sales assistants, checkout operators and other workers in supermarkets and department stores.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '52',
        ancestors: ['5', '52'],
        children: ['5221', '5222', '5223'],
        descendants: ['5221', '5222', '5223'],
    )]
    case ISCO08_522 = '522';

    #[Isco08Info(
        level: 3,
        code: '523',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '523',
        unit_group: null,
        title: 'Cashiers and Ticket Clerks',
        definition: 'Cashiers and ticket clerks operate cash registers, optical price scanners, computers or other equipment to record and accept payment for the purchase of goods, services and admissions in settings such as stores, restaurants and ticket offices.',
        tasks_include: 'Tasks performed usually include: receiving and verifying payment by cash, cheque, credit card or automatic debit in stores, ticket offices or similar establishments; giving change and issuing receipts; issuing tickets at ticket offices, and taking corresponding payments; counting and recording money received or paid out and balancing against cash register sales records; receiving incoming cash, checking it against sales slips and other documents, and preparing it for deposit at a bank; operating cash registers to calculate total to be paid from or to clients; scanning, weighing and recording prices of goods; wrapping and placing merchandise in bags.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '52',
        ancestors: ['5', '52'],
        children: ['5230'],
        descendants: ['5230'],
    )]
    case ISCO08_523 = '523';

    #[Isco08Info(
        level: 3,
        code: '524',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '524',
        unit_group: null,
        title: 'Other Sales Workers',
        definition: 'Other sales workers display, demonstrate, display and sell goods, food and services, usually to the general public, in contexts other than sales in markets, streets and shops. This group includes sales workers not classified in Minor Groups 521: Street and Market Salespersons, 522: Shop Salespersons and 523: Cashiers and Ticket Clerks.',
        tasks_include: 'Tasks performed may include: displaying and demonstrating items for sale; posing for photographs, film and video, advertising, still photography or for artistic creation; answering questions and offering advice on the use of goods and services; taking orders and making arrangements for payment, delivery and collection of goods or for provision of services; selling goods and services and soliciting business by approaching potential customers by going from door to door or using the telephone or other electronic communications media; selling fuel, lubricants and other automotive products at service stations; providing services such as fuelling, cleaning, lubricating and performing minor repairs to motor vehicles.',
        excluded_occupations: null,
        notes: 'Sales managers are classified in Minor Group 122: Sales, Marketing and Development Managers. Technical, medical and ICT sales professionals are classified in Minor Group 243: Sales, Marketing and Public Relations Professionals. Commercial sales and insurance representatives are classified in Minor Group 332: Sales and Purchasing Agents and Brokers.',
        occupational_titles: [],
        parent: '52',
        ancestors: ['5', '52'],
        children: ['5241', '5242', '5243', '5244', '5245', '5246', '5249'],
        descendants: ['5241', '5242', '5243', '5244', '5245', '5246', '5249'],
    )]
    case ISCO08_524 = '524';

