    #[Isco08Info(
        level: 3,
        code: '541',
        major_group: '5',
        sub_major_group: '54',
        minor_group: '541',
        unit_group: null,
        title: 'Protective Services Workers',
        definition: 'Protective services workers protect individuals and property against fire and other hazards, maintain law and order and enforce laws and regulations.',
        tasks_include: 'Tasks performed usually include: preventing, fighting and extinguishing fires; rescuing people from burning buildings and accident sites and those trapped in dangerous situations; maintaining law and order, enforcing laws and regulations, patrolling public areas and arresting suspected offenders; directing traffic and assuming authority in the event of accidents; watching over and maintaining order among inmates of prisons, reformatories or penitentiaries; patrolling or monitoring premises to guard property against theft and vandalism, controlling access to establishments and maintaining order and enforcing regulations at public events and within establishments. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '54',
        ancestors: ['5', '54'],
        children: ['5411', '5412', '5413', '5414', '5419'],
