    #[Isco08Info(
        level: 3,
        code: '611',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '611',
        unit_group: null,
        title: 'Market Gardeners and Crop Growers',
        definition: 'Market gardeners and crop growers plan, organize and perform operations to grow and harvest field crops, to grow fruit and other tree and shrub crops, to grow garden vegetables and medicinal and other plants; and to produce horticultural and horticultural nurseries products, for sale or delivery on a regular basis to wholesale buyers, marketing organisations or at markets.',
        tasks_include: 'Tasks performed usually include: monitoring market activity and conditions, determining types and quantities of crops to be grown, and planning and coordinating production accordingly; purchasing seeds, bulbs and fertilizer; investing in land and land improvements; preparing land and sowing, planting, cultivating and harvesting various crops; tending working animals and maintaining farm buildings, machinery and equipment; producing saplings, bulbs and seeds; storing and carrying out some processing of produce; delivering or marketing farm products. Supervision of other workers may be included.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '61',
        ancestors: ['6', '61'],
        children: ['6111', '6112', '6113', '6114'],
        descendants: ['6111', '6112', '6113', '6114'],
    )]
    case ISCO08_611 = '611';

    #[Isco08Info(
        level: 3,
        code: '612',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '612',
        unit_group: null,
        title: 'Animal Producers',
        definition: 'Animal producers plan, organize and perform farming operations to breed and raise domesticated animals, poultry, insects and non-domesticated animals for the production of meat, dairy products, honey, skins, textiles and other products, or for use as working, sporting or recreational animals, for sale or delivery to wholesale buyers, marketing organizations or at markets.',
        tasks_include: 'Task performed usually include: monitoring market activity and conditions, determining kinds and amounts of products to produce and planning and coordinating production accordingly; raising, feeding and tending animals; preparing animals or animal products for market; monitoring and examining animals to detect illness, injury, or disease, and to check physical condition such as rate of weight gain; performing duties related to animal reproduction, such as breeding, artificial insemination and helping with animal births; renting or investing in and maintaining and cleaning buildings, machinery, equipment and structures; storing and carrying out some processing of produce; promoting and marketing products, arranging the sale, purchase and transportation of stock, produce and supplies, and maintaining and evaluating records of activities and transactions; training and supervising workers in animal care procedures, maintenance duties and health and safety precautions, and hiring and discharging workers and contractors.',
        excluded_occupations: null,
        notes: null,
