    #[Isco08Info(
        level: 3,
        code: '613',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '613',
        unit_group: null,
        title: 'Mixed Crop and Animal Producers',
        definition: 'Mixed crop and animal producers plan, organize and perform farming operations to grow and harvest field, tree and various other crops, as well as to breed, raise and tend animals and to produce a variety of animal husbandry products, for sale or delivery to wholesale buyers, marketing organizations or at markets.',
        tasks_include: 'Tasks performed usually include: monitoring market activity and conditions, determining kinds and amounts of crops to be grown and animals to be raised, and planning and coordinating production accordingly; purchasing seeds, fertilizer and other supplies; performing operations such as land preparation and sowing, planting, cultivating and harvesting crops; producing or buying fodder and other food supplies; breeding, raising and tending animals; killing and skinning animals, and preparing animals or animal products for market; renting or investing in, and maintaining and cleaning, farm buildings, machinery, equipment and structures; storing and carrying out some processing of produce; promoting and marketing products, arranging the sale, purchase and transportation of livestock, produce and supplies, and maintaining and evaluating records of farm activities and transactions; training and supervising workers in animal care procedures, maintenance duties and health and safety precautions, and hiring and discharging workers and contractors.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '61',
        ancestors: ['6', '61'],
        children: ['6130'],
        descendants: ['6130'],
    )]
    case ISCO08_613 = '613';

    #[Isco08Info(
        level: 3,
        code: '621',
        major_group: '6',
        sub_major_group: '62',
        minor_group: '621',
        unit_group: null,
        title: 'Forestry and Related Workers',
        definition: 'Forestry and related workers plan, organize and perform operations to cultivate, conserve and exploit natural and plantation forests.',
        tasks_include: 'Tasks performed usually include: assessing sites for reforestation, selecting seedlings and planting trees using manual planting tools, and establishing and caring for forest stands; locating trees to be felled and estimating volume of timber; operating chainsaw and other power saws to thin young forest stands, trim, top and fell trees and saw them into logs; shaping rough wooden products from logs at felling site; stacking logs and loading them in chutes or floating them down rivers; keeping watch to detect forest fires, participating in firefighting operations, completing firefighting reports and maintaining firefighting equipment; controlling weeds and undergrowth in regenerating forest stands, using manual tools and chemicals; operating and maintaining a skidder, bulldozer or other prime mover to pull a variety of scarification or site preparation equipment over areas to be regenerated; collecting seed cones, pruning trees, assisting in planting surveys and marking trees for subsequent operations; training and supervising other workers in forestry procedures, including forestry labourers and plant operators.',
        excluded_occupations: null,
        notes: null,
        occupational_titles: [],
        parent: '62',
        ancestors: ['6', '62'],
        children: ['6210'],
        descendants: ['6210'],
    )]
    case ISCO08_621 = '621';

