    #[Isco08Info(
        level: 4,
        code: '1111',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '111',
        unit_group: '1111',
        title: 'Legislators',
        definition: 'Legislators determine, formulate, and direct policies of national, state, regional or local governments and international governmental agencies, and make, ratify, amend or repeal laws, public rules and regulations. They include elected and non-elected members of parliaments, councils and governments.',
        tasks_include: "Tasks include -\n(a)  presiding over or participating in the proceedings of legislative bodies and administrative councils of national, state, regional or local governments or legislative assemblies;\n(b)  determining, formulating and directing policies of national, state, regional or local governments;\n(c)  making, ratifying, amending or repealing laws, public rules and regulations within a statutory or constitutional framework;\n(d)  serving on government administrative boards or official committees;\n(e)  investigating matters of concern to the public and promoting the interests of the constituencies which they represent;\n(f)  attending community functions and meetings to provide service to the community, understand public opinion and provide information on government plans;\n(g)  negotiating with other legislators and representatives of interest groups in order to reconcile differing interests, and to create policies and agreements;\n(h)  as members of the government, directing senior administrators and officials of government departments and agencies in the interpretation and implementation of government policies.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Alderman', 'Alderwoman', 'Chancellor, government', 'Chief minister, government', 'Chief whip', 'Congressman', 'Congresswoman', 'Councillor, city', 'Councillor, government', 'Governor, Commonwealth', 'Governor, State', 'Governor-General', 'Head of State', 'Legislator', 'Mayor', 'Member, house of assembly', 'Member, legilslative assembly', 'Member, legilslative council', 'Member, local government', 'Member, parliament', 'Minister, government', 'Parliamentarian', 'Politician', 'Premier', 'President, government', 'Prime minister', 'Representative, legislative', 'Secretary of state', 'Senator', 'Speaker', 'Whip, chief', 'Whip, government', 'Whip, opposition'],
        parent: '111',
        ancestors: ['1', '11', '111'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1111 = '1111';

    #[Isco08Info(
        level: 4,
        code: '1112',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '111',
        unit_group: '1112',
        title: 'Senior Government Officials',
        definition: 'Senior government officials advise governments on policy matters, oversee the interpretation and implementation of government policies and legislation by government departments and agencies, represent their country abroad and act on its behalf, or carry out similar tasks in intergovernmental organizations. They plan, organize, direct, control and evaluate the overall activities of municipal or local, regional and national government departments, boards, agencies or commissions in accordance with legislation and policies established by government and legislative bodies.',
        tasks_include: "Tasks include -\n(a)  advising national, state, regional or local governments and legislators on policy matters;\n(b)  advising on the preparation of government budgets, laws and regulations, including amendments;\n(c)  establishing objectives for government departments or agencies in accordance with government legislation and policy;\n(d)  formulating or approving and evaluating programmes and procedures for the implementation of government policies in conjunction or consultation with government;\n(e)  recommending, reviewing, evaluating and approving documents, briefs and reports submitted by middle managers and senior staff members;\n(f)  ensuring appropriate systems and procedures are developed and implemented to provide budgetary control;\n(g)  coordinating activities with other senior government managers and officials;\n(h)  making presentations to legislative and other government committees regarding policies programmes or budgets;\n(i)  overseeing the interpretation and implementation of government policies and legislation by government departments and agencies.",
        excluded_occupations: null,
        notes: 'Chief executives of Government-owned enterprises are included in Unit Group 1120: Managing Directors and Chief Executives.',
        occupational_titles: ['Administrator, city', 'Administrator, government', 'Administrator, intergovernmental organization', 'Ambassador', 'Commissioner, civil service', 'Commissioner, fire', 'Commissioner, high: government', 'Commissioner, inland revenue', 'Commissioner, police', 'Constable, chief: police', 'Consul-general', 'Director-general, government administration', 'Director-general, government department', 'Director-general, intergovernmental organization', 'Head, chancery', 'Head, department: government', 'Head, government department', 'Head, permanent: government department', 'Inspector-general, police', 'Paymaster-general, government', 'Postmaster-general, government', 'Registrar-general, government', 'Representative, diplomatic', 'Representative, embassy', 'Secretary, embassy', 'Secretary, government: senior official', 'Secretary-general, government administration', 'Under-secretary, government'],
        parent: '111',
        ancestors: ['1', '11', '111'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1112 = '1112';

    #[Isco08Info(
        level: 4,
        code: '1113',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '111',
        unit_group: '1113',
        title: 'Traditional Chiefs and Heads of Villages',
        definition: "Traditional chiefs and heads of villages perform a variety of legislative, administrative and ceremonial tasks and duties, determined by ancient traditions, as well as by the division of rights and responsibilities \tbetween village chiefs and the local, regional and national authorities.",
        tasks_include: "Tasks include -\n(a)  allocating the use of communal land and other resources among households in the community or village;\n(b)  collecting and distributing surplus production of the community or village;\n(c)  settling disputes between members of the community or village;\n(d)  disciplining members of the community or village for violation of rules and customs;\n(e)  performing ceremonial duties in connection with births, marriages, deaths, harvests and other important occasions;\n(f)  representing the community or village on local or regional councils;\n(g)  informing the community or village about government rules and regulations.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Chief, village', 'Elder, tribal', 'Head, village'],
        parent: '111',
        ancestors: ['1', '11', '111'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1113 = '1113';

    #[Isco08Info(
        level: 4,
        code: '1114',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '111',
        unit_group: '1114',
        title: 'Senior Officials of Special-interest Organizations',
        definition: "Senior officials of special-interest organizations determine, formulate and direct the implementation of policies of special-interest organizations, such as political-party organizations, trade unions, employers' organizations, trade and industry associations, humanitarian or charity organizations, or sports associations, and represent their organizations and act on their behalf.",
        tasks_include: "Tasks include -\n(a)  determining and formulating the policies, rules and regulations of the organization;\n(b)  planning, directing and coordinating the general functioning of the organization;\n(c)  reviewing the operations and results of the organization and reporting to boards of directors and governing bodies, the organization’s membership and funding agencies;\n(d)  negotiating on behalf of the organization, its members and relevant special-interest groups; \n(e)  promoting the interests of the organization, its members and relevant special-interest groups before the legislature, government or general public; \n(f)  planning, organizing and directing sections charged with implementing the organization's policies, programmes, rules and regulations;\n(g)  ensuring appropriate systems and procedures are developed and implemented to provide budgetary control;\n(h)   monitoring and evaluating performance of the organization or enterprise against established objectives and policies;\n(i)  representing the organization at official occasions and board meetings, in negotiations, at conventions, public hearings and forums.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Chairperson, charity', "Chairperson, employers' organization", 'Chairperson, environment protection organization', 'Chairperson, humanitarian organization', 'Chairperson, human rights organization', 'Chairperson, political party', 'Chairperson, special-interest organization', 'Chairperson, sports association', 'Chairperson, trade union', 'Chairperson, wild life protection organization', "Director-general, employers' organization", 'Director-general, environment protection organization', 'Director-general, humanitarian organization', 'Director-general, human rights organization', 'Director-general, political party', 'Director-general, special-interest organization', 'Director-general, trade union', 'Director-general, wild life protection organization', 'Leader, political party', 'Leader, trade union', "Official, senior: employers' organization", 'Official, senior: humanitarian organization', 'Official, senior: political party', 'Official, senior: special-interest organization', 'Official, senior: trade union', "President, employers' organization", 'President, political party', 'President, trade union', "Secretary-general, employers' organization", 'Secretary-general, environment protection organization', 'Secretary-general, humanitarian organization', 'Secretary-general, human rights organization', 'Secretary-general, political party', 'Secretary-general, special-interest organization', 'Secretary-general, trade union', 'Secretary-general, wild life protection organization'],
        parent: '111',
        ancestors: ['1', '11', '111'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1114 = '1114';

    #[Isco08Info(
        level: 4,
        code: '1120',
        major_group: '1',
        sub_major_group: '11',
        minor_group: '112',
        unit_group: '1120',
        title: 'Managing Directors and Chief Executives',
        definition: 'Managing directors and chief executives formulate and review the policies and plan, direct, coordinate and evaluate the overall activities of enterprises or organizations (except special-interest organizations and government departments) with the support of other managers, usually within guidelines established by a board of directors or a governing body to whom they are answerable for the operations undertaken and results.',
        tasks_include: "Tasks include -\n(a)  planning, directing and coordinating the general functioning of an enterprise or organization;\n(b)  reviewing the operations and results of the enterprise, or organization and reporting to boards of directors and governing bodies;\n(c)  determining objectives, strategies, policies and programmes for the enterprise or organization;\n(d)  providing overall leadership and management to the enterprise or organization;\n(e)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(f)  authorising material, human and financial resources to implement organizational policies and programmes;\n(g)  monitoring and evaluating performance of the organization or enterprise against established objectives and policies;\n(h)  consulting with senior subordinate staff and reviewing recommendations and reports;\n(i)  representing the organization at official occasions and board meetings, in negotiations, at conventions, seminars, public hearings and forums; \n(j)  selecting or approving the selection of senior staff;\n(k)  ensuring the organization complies with relevant legislation and regulations.",
        excluded_occupations: null,
        notes: "Regional managers and other senior managers who coordinate and supervise the activities of subordinate managers who have a diverse range of functional responsibilities are included in Unit Group 1120: Managing Directors and Chief Executives. Managers responsible for specialized functions within a specific geographic area are excluded from this unit group. For example, regional sales managers are classified in Unit Group 1221: Sales and Marketing Managers. Jobs whose principle responsibility is to participate as a member of the board of directors of one or more enterprises or organizations are included in Unit Group 1120: Managing Directors and Chief Executives.\nChief executives of government owned enterprises are included in Unit Group 1120, Managing directors and chief executives.",
        occupational_titles: ['CEO', 'Chairperson, enterprise', 'Chancellor, university', 'Chief executive', 'COO', 'Director, company', 'Director, executive', 'Director, managing', 'Director, regional', 'Executive, chief', 'Manager, regional', 'Managing-director', 'Member, board', 'Officer, chief executive', 'Officer, chief operating', 'President, company', 'President, enterprise', 'Rector, college', 'Rector, university', 'Vice-chancellor, university'],
        parent: '112',
        ancestors: ['1', '11', '112'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1120 = '1120';

    #[Isco08Info(
        level: 4,
        code: '1211',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '121',
        unit_group: '1211',
        title: 'Finance Managers',
        definition: 'Finance managers plan, direct and coordinate the financial operations of an enterprise or organization, in consultation with senior managers and with managers of other departments or sections, or of enterprises that provide financial services to other enterprises and organizations.',
        tasks_include: "Tasks include -\n(a)  planning, directing and coordinating the financial operations of an enterprise or organization;\n(b)  assessing the financial situation of the enterprise or organization, preparing budgets and overseeing financial operations;\n(c)  consulting with the chief executive and with managers of other departments or sections\n(d)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(e)  establishing and directing operational and administrative procedures;\n(f)  planning and directing daily operations;\n(g)  overseeing the selection, training and performance of staff;\n(h)  representing the enterprise or organization in dealings with outside bodies.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Financial institution branch manager - 1346\n- Financial controller - 2411\n- Management accountant - 2411",
        notes: null,
        occupational_titles: ['Banker', 'CFO', 'Director, accounting', 'Director, accounts', 'Director, budgeting', 'Director, finance', 'Manager, accounting', 'Manager, accounts', 'Manager, auditing firm', 'Manager, budgeting', 'Manager, department: accounting', 'Manager, department: budgeting', 'Manager, department: finance', 'Manager, finance', 'Officer, chief financial', 'Purser, chief: ship', 'Registrar, company', 'Secretary, company', 'Treasurer, company'],
        parent: '121',
        ancestors: ['1', '12', '121'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1211 = '1211';

    #[Isco08Info(
        level: 4,
        code: '1212',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '121',
        unit_group: '1212',
        title: 'Human Resource Managers',
        definition: 'Human resource managers, plan, direct and coordinate policies concerning the personnel, industrial relations and occupational health and safety activities of an enterprise or organization, or of enterprises that provide human resource services to other enterprises and organizations.',
        tasks_include: "Tasks include -\n(a)  planning, directing and coordinating the personnel and industrial relations activities, policies and practices of an enterprise or organization;\n(b)  planning and organizing procedures for recruitment, training, promotion, transfer and dismissal of staff;\n(c)  planning and organizing negotiations and procedures for determination of wage structures and level and for consultation with workers on conditions of employment;\n(d)  overseeing safety, health and related programmes and activities;\n(e)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(f)  establishing and directing operational and administrative procedures;\n(g)  overseeing the development and implementation of management information systems;\n(h)  ensuring compliance with standards and legislation relating to employees rights, health and safety, equal opportunity and related concerns;\n(i)  overseeing the selection, training and performance of staff for the entire enterprise or organization;\n(j)  consulting with senior management and with managers of other departments;\n(k)  representing the enterprise or organization in dealings with outside bodies.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Director, human resources', 'Director, personnel', 'Director, recruitment', 'Manager, department: employee relations', 'Manager, department: industrial relations', 'Manager, department: personnel', 'Manager, department: recruitment', 'Manager, department: workplace relations', 'Manager, employee relations', 'Manager, human resources', 'Manager, industrial relations', 'Manager, personnel', 'Manager, recruitment', 'Manager, workplace relations'],
        parent: '121',
        ancestors: ['1', '12', '121'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1212 = '1212';

    #[Isco08Info(
        level: 4,
        code: '1213',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '121',
        unit_group: '1213',
        title: 'Policy and Planning Managers',
        definition: 'Policy and planning managers plan, organize, direct and coordinate policy advice and strategic planning activities within government or for non-government organizations and private sector agencies, or manage the activities of enterprises that provide policy and strategic planning services.',
        tasks_include: "Tasks include – \n(a)  developing, implementing and monitoring strategic plans, programmes, policies, processes, systems and procedures to achieve goals, objectives and work standards; \n(b)  developing, directing, administering and participating in policy research and analysis;\n(c)  coordinating the implementation of policies and practices; \n(d)  establishing activity measures and measurements of accountability;\n(e)  planning and directing daily operations;\n(f)  leading and managing the activities of policy development and strategic planning staff;\n(g)  overseeing the selection, training and performance of staff; \n(h)  consulting with senior management and with managers of other departments;\n(i)  representing the enterprise or organization in negotiations, and at conventions, seminars, public hearings and forums.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Coordinator, policy: government', 'Director, compliance', 'Director, policy and planning', 'Director, strategic planning', 'Manager, business planning', 'Manager, compliance', 'Manager, corporate planning', 'Manager, fisheries: conservation', 'Manager, fisheries: policy', 'Manager, planning: policy', 'Manager, planning: strategic', 'Manager, policy and planning', 'Manager, policy development', 'Manager, public policy', 'Manager, social administration', 'Manager, social planning', 'Manager, strategic planning', 'Officer, chief compliance'],
        parent: '121',
        ancestors: ['1', '12', '121'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1213 = '1213';

    #[Isco08Info(
        level: 4,
        code: '1219',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '121',
        unit_group: '1219',
        title: 'Business Services and Administration Managers Not Elsewhere Classified',
        definition: 'This unit group covers business services and administration managers not classified elsewhere in Minor Group 121: Business Services and Administration Managers. For instance, the group includes occupations such as facilities manager, cleaning services manager, administrative services manager employed either as the manager of a department of a large enterprise and organization, or of an enterprise that provides such services to other enterprises and organizations.',
        tasks_include: "In such cases tasks would include:\n(a)  providing administrative, strategic planning and operational support, research and advice to senior management on matters such as the management of building facilities and administrative services;\n(b)  developing and managing the organization's administrative and physical resources;\n(c)  developing and implementing administrative and procedural statements and guidelines for use by staff in the organization; \n(d)  analysing complex resource management issues and initiatives that affect the organization, and preparing associated reports, correspondence and submissions;\n(e)  providing information and support for the preparation of financial reports and budgets;\n(f)  leading, managing and developing administrative staff to ensure smooth business operations and the provision of accurate and timely information;\n(g)  representing the enterprise or organization in negotiations, and at conventions, seminars, public hearings and forums;\n(h)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(i)  planning and directing daily operations;\n(j)  overseeing the selection, training and performance of staff.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Director, administrative services', 'Director, corporate services', 'Director, facilities management', 'Manager, administrative services', 'Manager, cleaning service', 'Manager, corporate services', 'Manager, department: administration', 'Manager, department: business services', 'Manager, department: cleaning', 'Manager, facilities', 'Manager, general: business services', 'Manager, general: cleaning'],
        parent: '121',
        ancestors: ['1', '12', '121'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1219 = '1219';

    #[Isco08Info(
        level: 4,
        code: '1221',
        major_group: '1',
        sub_major_group: '12',
        minor_group: '122',
        unit_group: '1221',
        title: 'Sales and Marketing Managers',
        definition: 'Sales and marketing managers plan, direct and coordinate the sales and marketing activities of an enterprise or organization, or of enterprises that provide sales and marketing services to other enterprises and organizations.',
        tasks_include: "Tasks include -\n(a)  planning and organizing special sales and marketing programmes based on sales records and market assessments;\n(b)  determining price lists, discount and delivery terms, sales promotion budgets, sales methods, special incentives and campaigns;\n(c)  establishing and directing operational and administrative procedures related to sales and marketing activities;\n(d)  leading and managing the activities of sales and marketing staff;\n(e)  planning and directing daily operations; \n(f)  establishing and managing budgets and controlling expenditure to ensure the efficient use of resources;\n(g)  overseeing the selection, training and performance of staff;\n(h)  representing the enterprise or organization at sales and marketing conventions, trade exhibitions and other forums.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Director, marketing', 'Director, sales', 'Manager, commercial', 'Manager, department: marketing', 'Manager, department: sales', 'Manager, department: sales promotion', 'Manager, exports', 'Manager, marketing', 'Manager, sales'],
