    #[Isco08Info(
        level: 4,
        code: '1311',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '131',
        unit_group: '1311',
        title: 'Agricultural and Forestry Production Managers',
        definition: 'Agricultural and forestry production managers plan, direct, and coordinate production in large scale agricultural, horticultural and forestry operations such as plantations, large ranches, collective farms and agricultural cooperatives to grow and harvest crops, and breed and raise livestock.',
        tasks_include: "Tasks include -\n(a)  monitoring agricultural and forestry market activity and planning production to meet contract requirements and market demand;\n(b)  establishing and managing budgets, monitoring production output and costs, recording information such as farm management practices, and preparing financial and operational reports; \n(c)  conferring with buyers to arrange for the sale of crops and livestock;\n(d)  contracting with farmers or independent owners for production of crops and livestock, or for management of production;\n(e)  planning the type, intensity and sequence of farm operations (e.g. determining the best times for planting, spraying and harvesting);\n(f)  analysing soil to determine types and quantities of fertilizer required for maximum production;\n(g)  purchasing machinery, equipment, and supplies such as tractors, seed, fertilizer, and chemicals; \n(h)  identifying and controlling agricultural and forest environmental toxins, weeds, pests and diseases;\n(i)  organizing farming operations such as maintaining buildings, water supply systems and equipment;\n(j)  directing and coordinating activities such as planting, irrigation, chemical application, harvesting, and grading; \n(k)  inspecting plantations and fields to determine maturity dates of crops, or to estimate potential crop damage from weather; \n(l)  overseeing the selection, training and performance of agricultural and forestry workers and contractors.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Manager, agricultural production', 'Manager, forestry', 'Manager, operations: agriculture', 'Manager, operations: forestry', 'Manager, plantation', 'Manager, production: agriculture', 'Manager, production: forestry', 'Manager, ranch'],
        parent: '131',
        ancestors: ['1', '13', '131'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1311 = '1311';

    #[Isco08Info(
        level: 4,
        code: '1312',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '131',
        unit_group: '1312',
        title: 'Aquaculture and Fisheries Production Managers',
        definition: 'Aquaculture and fisheries production managers plan, direct, and coordinate production in large-scale aquaculture and fishery operations to catch and harvest fish and shellfish, and to grow fish shellfish or other forms of aquatic life, as cash crops or for release into freshwater or saltwater.',
        tasks_include: "Tasks include -\n(a)  monitoring aquaculture and fishery market activity and planning production and fishing activities to meet contract requirements and market demand;\n(b)  establishing and managing budgets, monitoring production output and costs, recording information such as fisheries management practices, and preparing financial and operational reports; \n(c)  conferring with buyers to arrange for the sale of produce and catches;\n(d)  contracting with fishing skippers or owners of vessels and aquaculture farms for fishing and aquaculture operations, or for management of production;\n(e)  conducting and organizing aquaculture or fishery stock examinations in order to identify diseases or parasites;\n(f)  devising and coordinating activities to improve fish hatching and growth rates, and to prevent disease in hatcheries;\n(g)  monitoring environments to maintain or improve conditions for aquatic life;\n(h)  directing and monitoring trapping and spawning of fish, egg incubation, and fry rearing, applying knowledge of management and fish culturing techniques;\n(i)  coordinating the selection and maintenance of brood stock;\n(j)  directing and monitoring the transfer of mature fish to lakes, ponds, streams, or commercial tanks;\n(k)  purchasing machinery, equipment, and supplies such as vessels and nets;\n(l)  organizing operations such as maintenance of ships, boats and equipment;\n(m)  overseeing the selection, training and performance of aquaculture or fishery workers and contractors.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Fish farmer - 6221\n- Fish hatchery manager - 6221\n- Oyster Farmer - 6221\n- Seafood Farmer - 6221 \n- Fishing vessel skipper (coastal waters) - 6222\n- Fishing master (deep sea) – 6223",
        notes: null,
        occupational_titles: ['Captain, shore: fishing', 'Manager, aquaculture', 'Manager, fisheries: fishing operations', 'Manager, fisheries: production', 'Manager, fish hatchery', 'Manager, general: fishing', 'Manager, operations: fishing', 'Manager, production: aquaculture', 'Manager, production: fishing', 'Manager, trawler'],
        parent: '131',
        ancestors: ['1', '13', '131'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1312 = '1312';

    #[Isco08Info(
        level: 4,
        code: '1321',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '132',
        unit_group: '1321',
        title: 'Manufacturing Managers',
        definition: 'Manufacturing managers plan, direct and coordinate activities concerned with the production of goods, the production and distribution of electricity gas and water, and the collection, treatment and disposal of waste. They may manage the production departments of large enterprises or be the managers of small manufacturing companies.',
        tasks_include: "Tasks include -\n(a)  determining, implementing and monitoring production strategies, policies and plans; \n(b)  planning details of production activities in terms of output quality and quantity, cost, time available and labour requirements;\n(c)  controlling the operation of production plant and quality procedures through planning of maintenance, designation of operating hours and supply of parts and tools; \n(d)  establishing and managing budgets, monitoring production output and costs, and adjusting processes and resources to minimize costs;\n(e)  consulting with and informing other managers about production matters;\n(f)  overseeing the acquisition and installation of new plant and equipment; \n(g)  controlling the preparation of production records and reports;\n(h)  coordinating the implementation of occupational health and safety requirements;\n(i)  identifying business opportunities and determining products to be manufactured;\n(j)  researching and implementing regulatory and statutory requirements affecting manufacturing operations and the environment;\n(k)  overseeing the provision of quotes for the manufacture of specialized goods and establishing contracts with customers and suppliers;\n(l)  overseeing the selection, training and performance of staff.",
        excluded_occupations: "Some related occupations classified elsewhere:\n - Production supervisor (manufacturing) - 3122",
        notes: null,
        occupational_titles: ['Director, power station', 'Manager, general: manufacturing', 'Manager, manufacturing', 'Manager, operations: manufacturing', 'Manager, plant: power generation', 'Manager, power station', 'Manager, production: chemicals', 'Manager, production: gas supply', 'Manager, production: oil refinery', 'Manager, production: petroleum refinery', 'Manager, production: power generation', 'Manager, production: waste management', 'Manager, production: water supply and treatment', 'Manager, production and operations: manufacturing', 'Manufacturer'],
        parent: '132',
        ancestors: ['1', '13', '132'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1321 = '1321';

    #[Isco08Info(
        level: 4,
        code: '1322',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '132',
        unit_group: '1322',
        title: 'Mining Managers',
        definition: 'Mining managers plan, direct and coordinate the production of activities of mining, quarrying and oil and gas extraction operations, either as the manager of a department or as the general manager of an enterprise or organization that does not have a hierarchy of managers.',
        tasks_include: "Tasks include -\n(a)  conferring with other managers to set production quotas, plan extraction sites and develop policies for the removal of raw materials;\n(b)  evaluating efficiency of production sites to determine adequacy of personnel, equipment and technologies used, and make changes to work schedule or equipment when necessary;\n(c)  planning details of production activities in terms of output quality and quantity, cost, time available and labour requirements;\n(d)  controlling the operation of plant and quality procedures through planning of maintenance, designation of operating hours and supply of equipment;\n(e)  establishing and managing budgets, monitoring production output and costs, and adjusting processes and resources to minimize costs;\n(f)  overseeing the acquisition and installation of new plant and equipment; \n(g)  controlling the preparation of production records and reports;\n(h)  coordinating the implementation of health and safety requirements;\n(i)  researching and implementing regulatory and statutory requirements affecting mineral extraction operations and the environment;\n(j)  overseeing the selection, training and performance of staff.",
        excluded_occupations: "Some related occupations classified elsewhere:\nMine deputy - 3121\nMine supervisor - 3121\nMine under-manager - 3121\nQuarry supervisor - 3121",
        notes: null,
        occupational_titles: ['Controller, production: mining', 'Manager, general: operation (mining)', 'Manager, metallurgy', 'Manager, mine', 'Manager, mining', 'Manager, offshore installation: oil or gas', 'Manager, operations: mining', 'Manager, plant: mining', 'Manager, processing: mining', 'Manager, production: mine', 'Manager, production: oil and gas extraction', 'Manager, production: quarry', 'Manager, quarry', 'Manager, works: mining'],
        parent: '132',
        ancestors: ['1', '13', '132'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1322 = '1322';

    #[Isco08Info(
        level: 4,
        code: '1323',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '132',
        unit_group: '1323',
        title: 'Construction Managers',
        definition: 'Construction managers plan, direct and coordinate the construction of civil engineering projects, buildings and dwellings, either as the manager of a department or as the general manager of an enterprise or organization that does not have a hierarchy of managers.',
        tasks_include: "Tasks include - \n(a)  interpreting architectural drawings and specifications;\n(b)  coordinating labour resources and procurement and delivery of materials, plant and equipment; \n(c)  negotiating with building owners, property developers and subcontractors involved in the construction process to ensure projects are completed on time and within budget;\n(d)  preparing tenders and contract bids; \n(e)  operating and implementing coordinated work programmes for sites; \n(f)  ensuring adherence to building legislation and standards of performance, quality, cost and safety;\n(g)  arranging submission of plans to local authorities; \n(h)  building under contract, or subcontracting specialized building services;\n(i)  arranging building inspections by relevant authorities;\n(j)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(k)  overseeing the selection, training and performance of staff and subcontractors;",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Building construction supervisor - 3123\n- House builder - 7111",
        notes: null,
        occupational_titles: ['Builder, project', 'Contractor, building: project management', 'Manager, construction', 'Manager, demolition', 'Manager, general: construction', 'Manager, project: civil engineering', 'Manager, project: construction'],
        parent: '132',
        ancestors: ['1', '13', '132'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1323 = '1323';

    #[Isco08Info(
        level: 4,
        code: '1324',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '132',
        unit_group: '1324',
        title: 'Supply, Distribution and Related Managers',
        definition: 'Supply, distribution and related managers plan, direct and coordinate passenger transportation systems and facilities and the supply, transportation, storage and distribution of goods, either as the manager of a department or as the general manager of an enterprise or organization that does not have a hierarchy of managers.',
        tasks_include: "Tasks include - \n(a)  determining, implementing and monitoring purchasing, storage and distribution strategies, policies and plans; \n(b)  preparing and implementing plans to maintain required stock levels at minimum cost; \n(c)  negotiating contracts with suppliers to meet quality, cost and delivery requirements; \n(d)  monitoring and reviewing storage and inventory systems to meet supply requirements and control stock levels; \n(e)  overseeing the dispatch of road vehicles, trains, vessels or aircraft;\n(f)  operating recording systems to track all movements of goods, and ensuring reordering and restocking at optimal times;\n(g)  liaising with other departments and customers concerning requirements for outward goods and associated forwarding transportation;\n(h)  overseeing the recording of purchase, storage and distribution transactions;\n(i)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(j)  establishing and directing operational and administrative procedures; \n(k)  planning and directing daily operations;\n(l)  overseeing the selection, training and performance of staff.",
        excluded_occupations: null,
        notes: 'Chief executives of major airports, railway companies, urban transit systems and other transportation corporations that have hierarchies of managers are included in Unit Group 1120: Managing directors and chief executives.',
        occupational_titles: ['Captain, shore: shipping', 'Director, logistics', 'Manager, airport operations', 'Manager, air ramp', 'Manager, bus station', 'Manager, courier service', 'Manager, department: transportation', 'Manager, distribution', 'Manager, flight operations', 'Manager, general: storage', 'Manager, general: transport', 'Manager, imports', 'Manager, imports and exports', 'Manager, logistics', 'Manager, mail operations', 'Manager, metropolitan railway station', 'Manager, postal service', 'Manager, purchasing', 'Manager, railway station', 'Manager, storage', 'Manager, supplies', 'Manager, supply and distribution', 'Manager, supply chain', 'Manager, traffic', 'Manager, transport', 'Manager, transport company', 'Manager, urban transit system', 'Manager, warehouse', 'Master, railway station', 'Master, station: railway', 'Postmaster', 'Stationmaster, railway', 'Superintendent, rail operations'],
        parent: '132',
