    case ISCO08_1324 = '1324';

    #[Isco08Info(
        level: 4,
        code: '1330',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '133',
        unit_group: '1330',
        title: 'Information and Communications Technology Service Managers',
        definition: 'Information and communications technology service managers plan, direct and coordinate the acquisition, development, maintenance and use of computer and telecommunication systems, either as the manager of a department or as the general manager of an enterprise or organization that does not have a hierarchy of managers.',
        tasks_include: "Tasks include -\n(a)  consulting with users, management, vendors, and technicians to assess computing needs and system requirements and specifying technology to meet those needs; \n(b)  formulating and directing information and communication technology (ICT) strategies, policies and plans; \n(c)  directing the selection and installation of ICT resources and the provision of user training; \n(d)  directing ICT operations, analysing workflow, establishing priorities, developing standards and setting deadlines;\n(e)  overseeing the security of ICT systems;\n(f)  assigning, reviewing, managing and leading the work of systems analysts, programmers, and other computer-related workers;\n(g)  evaluating the organization's technology use and needs and recommending improvements such as hardware and software upgrades;\n(h)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(i)  establishing and directing operational and administrative procedures; \n(j)  overseeing the selection, training and performance of staff; \n(k)  representing the enterprise or organization at ICT related conventions, seminars and conferences.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['CIO', 'Director, information systems', 'Manager, application development', 'Manager, communications: technology', 'Manager, computer services company', 'Manager, computer services department', 'Manager, computer systems', 'Manager, data operations', 'Manager, data processing', 'Manager, ICT development', 'Manager, information technology', 'Manager, internet: department', 'Manager, internet: managing business', 'Manager, internet service provider', 'Manager, ISP', 'Manager, IT', 'Manager, network', 'Manager, operations: computer systems', 'Manager, project: information technology', 'Manager, systems development', 'Manager, telecommunications services', 'Officer, chief information', 'Officer, chief technology', 'Provider, internet service'],
        parent: '133',
