    case ISCO08_1330 = '1330';

    #[Isco08Info(
        level: 4,
        code: '1341',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '134',
        unit_group: '1341',
        title: 'Child Care Service Managers',
        definition: 'Child care service managers plan, direct, and coordinate and evaluate the provision of care for children in before-school, after-school, vacation and day care centres and services.',
        tasks_include: "Tasks include - \n(a)  developing and implementing programmes to enhance the physical, social, emotional and intellectual development of young children;\n(b)  establishing and monitoring budgets and determining allocation of funds for staff, supplies, materials, equipment and maintenance;\n(c)  overseeing and coordinating the provision care for children in before-school, after-school, day, and vacation care centres;\n(d)  directing and supervising child carers in providing care and supervision for young children;\n(e)  managing physical facilities and making sure all buildings and equipment are maintained to ensure the centre is a safe area for children, staff and visitors;\n(f)  reviewing and interpreting government codes, and developing procedures to meet codes (e.g., concerning safety and security);\n(g)  monitoring children’s progress and conferring with parents or guardians;\n(h)  preparing and maintaining records and accounts for a child care centre;\n(i)  recruiting and evaluating staff and coordinating their professional development.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Director, after school care', 'Director, childcare', 'Director, childcare centre', "Director, children's services", 'Director, day care centre: children', 'Licensee, childcare centre', 'Manager, care: out of school hours', 'Manager, centre: childcare', 'Manager, childcare', 'Manager, child care centre', "Manager, children's services", 'Manager, crèche', 'Manager, day care centre: children', 'Manager, kindergarten', 'Manager, nursery: childcare', 'Manager, playgroup'],
        parent: '134',
        ancestors: ['1', '13', '134'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1341 = '1341';

    #[Isco08Info(
        level: 4,
        code: '1342',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '134',
        unit_group: '1342',
        title: 'Health Service Managers',
        definition: 'Health service managers plan, direct, coordinate and evaluate the provision of clinical and community health care services in hospitals, clinics, public health agencies and similar organizations.',
        tasks_include: "Tasks include - \n(a)  providing overall direction and management for the service, facility, organization or centre; \n(b)  directing, supervising and evaluating the work activities of medical, nursing, technical, clerical, service, maintenance, and other personnel;\n(c)  establishing objectives and evaluative or operational criteria for units they manage; \n(d)  directing or conducting recruitment, hiring and training of personnel;\n(e)  developing, implementing and monitoring procedures, policies and performance standards for medical, nursing, technical and administrative staff;\n(f)  monitoring the use of diagnostic services, inpatient beds, facilities and staff to ensure effective use of resources, and assess the need for additional staff, equipment, and services;\n(g)  controlling administrative operations such as budget planning, report preparation and expenditure on supplies, equipment and services;\n(h)  liaising with other health and welfare service providers, boards and funding bodies to coordinate the provision of services;\n(i)  advising government bodies about measures to improve health and welfare services and facilities; \n(j)  representing the organization in negotiations, and at conventions, seminars, public hearings and forums.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Aged care service manager - 1343",
        notes: null,
        occupational_titles: ['Administrator, health facility', 'Administrator, hospital', 'Administrator, medical', 'Coordinator, community health care', 'Director, clinical', 'Director, health facility', 'Director, health service', 'Director, medical', 'Director, nursing', 'Manager, health facility', 'Manager, health service', 'Matron, hospital', 'Officer, chief clinical', 'Officer, chief public health', 'Officer, clinical: chief', 'Officer, nursing: principal', 'Officer, principal nursing', 'Officer, public health: chief'],
        parent: '134',
        ancestors: ['1', '13', '134'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1342 = '1342';

