    #[Isco08Info(
        level: 4,
        code: '1345',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '134',
        unit_group: '1345',
        title: 'Education Managers',
        definition: 'Education managers plan, direct, coordinate and evaluate the educational and administrative aspects of education services, primary and secondary schools, colleges and faculties and departments in universities and other educational institutions.',
        tasks_include: "Tasks include - \n(a)  determining educational programmes based on frameworks established by education authorities and governing bodies;\n(b)  implementing systems and procedures to monitor school performance and student enrolments; \n(c)  directing administrative and clerical activities concerning student admissions and educational services;\n(d)  controlling administrative operations such as budget planning, report preparation, and expenditure on supplies, equipment and services;\n(e)  providing leadership and guidance to teaching, academic and administrative staff as well as to students;\n(f)  evaluating the work of teachers and lecturers by visiting classrooms, observing teaching methods, reviewing instructional objectives and examining learning materials;\n(g)  promoting the educational programme, and representing the service or institution in the wider community;\n(h)  supervising the maintenance of educational facilities;\n(i)  developing and enforcing a disciplinary code to create a safe and conducive environment for students and teachers;\n(j)  organizing and implementing methods of raising additional funds in conjunction with parent and community groups and sponsors;\n(k)  controlling selection, training and supervision of staff.",
        excluded_occupations: null,
        notes: null,
