    #[Isco08Info(
        level: 4,
        code: '1346',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '134',
        unit_group: '1346',
        title: 'Financial and Insurance Services Branch managers',
        definition: 'Financial and insurance services branch managers plan, direct, and coordinate the branches of institutions that provide financial and insurance services, such as banks, building societies, credit unions and insurance companies. They provide advice and assistance to clients on financial and insurance matters.',
        tasks_include: "Tasks include -\n(a)  planning, directing and coordinating the activities of staff in the branch;\n(b)  establishing and maintaining relationships with individual and business customers;\n(c)  providing advice and assistance to customers on their financial and insurance needs and with matters such as changes in law that may affect customers;\n(d)  examining, evaluating and processing loan and insurance applications;\n(e)  monitoring credit extension decisions;\n(f)  conducting financial investigations;\n(g)  overseeing the flow of cash and financial instruments, and the preparation of financial and regulatory reports;\n(h)  approving or rejecting, or coordinating the approval or rejection of, lines of credit commercial, real estate and personal loans;\n(i)  coordinating cooperation with other branches of the company;\n(j)  managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(k)  overseeing the selection, training and performance of staff.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Finance manager - 1211\n- Credit and loans officer - 3312\n- Insurance agent - 3321",
        notes: null,
        occupational_titles: ['Director, bank', 'Manager, bank', 'Manager, branch: bank', 'Manager, branch: building society', 'Manager, branch: credit union', 'Manager, branch: financial institution', 'Manager, branch: insurance company', 'Manager, building society', 'Manager, credit union', 'Manager, insurance agency'],
        parent: '134',
        ancestors: ['1', '13', '134'],
        children: [],
