    #[Isco08Info(
        level: 4,
        code: '1349',
        major_group: '1',
        sub_major_group: '13',
        minor_group: '134',
        unit_group: '1349',
        title: 'Professional Services Managers Not Elsewhere Classified',
        definition: 'This unit group covers managers who plan, direct coordinate and evaluate the provision of specialized professional and technical services and are not classified in Minor Group 121: Business Services and Administration Managers, or elsewhere in Minor Group 134: Professional Services Managers. For instance, managers responsible for the provision of policing, corrective, library, legal and fire services are classified here.',
        tasks_include: "In such cases tasks would include -\n(a)  providing overall direction and management for a service, facility, organization or centre; \n(b)  developing, implementing and monitoring procedures, policies and standards for staff; \n(c)  directing, supervising and evaluating the work activities of professional technical, clerical, service, maintenance, and other personnel; \n(d)  monitoring and evaluating resources devoted to the provision of services;\n(e)  controlling administrative operations such as budget planning, report preparation, and expenditure on supplies, equipment and services; \n(f)  planning, directing and coordinating the provision of services;\n(g)  coordinating cooperation with other service provision agencies in the same or related fields;\n(h)  managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(i)  overseeing the selection, training and performance of staff.",
        excluded_occupations: null,
        notes: 'Professional services managers are responsible for planning, directing and coordinating the provision of specialized professional and technical services. Specialized qualifications and extensive experience relevant to one or more occupations classified in Major Group 2: Professionals, or Major Group 3: Technicians and Associate Professionals, are usually required.',
        occupational_titles: ['Director, design service', 'Director, legal service', 'Governor, prison', 'Librarian, chief', 'Manager, air safety', 'Manager, archives', 'Manager, art gallery', 'Manager, correctional services', 'Manager, corrective services', 'Manager, department: cultural activities', 'Manager, department: recreation', 'Manager, department: sporting activities', 'Manager, design service service', 'Manager, emergency services', 'Manager, fire services', 'Manager, flight safety', 'Manager, laboratory', 'Manager, legal service', 'Manager, library', 'Manager, museum', 'Manager, publishing', 'Officer, immigration: chief', 'Publisher', 'Superintendent, police'],
        parent: '134',
        ancestors: ['1', '13', '134'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1349 = '1349';

    #[Isco08Info(
        level: 4,
        code: '1411',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '141',
        unit_group: '1411',
        title: 'Hotel Managers',
        definition: 'Hotel managers plan, organize and direct the operations of hotels, motels and similar establishments to provide guest accommodation and other services.',
        tasks_include: "Tasks include - \n(a)  directing and overseeing reservation, reception, room service and housekeeping activities;\n(b)  supervising security arrangements and garden and property maintenance;\n(c)  planning and supervising bar, restaurant, function and conference activities;\n(d)  observing liquor, gaming, and other laws and regulations;\n(e)  assessing and reviewing customer satisfaction;\n(f)  overseeing accounting and purchasing activities;\n(g)  undertaking budgeting for the establishment;\n(h)  controlling selection, training and supervision of staff;\n(i)  ensuring compliance with occupational health and safety regulations;\n(j)  providing guests with local tourism information, and arranging tours and transportation.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Bed and breakfast operator - 5152",
        notes: "Operators of small establishments, such as some bed and breakfast establishments and small guest houses, that provide accommodation and limited meal services to clients effectively as paying guests in private households, and for whom the management and supervision of staff is not a significant component of the work, are classified in Unit group 5152: Domestic Housekeepers.\nChief executive officers and specialized managers of hotel management companies or hotel chains are classified in the relevant unit group in Sub-major Groups 11 and 12.",
        occupational_titles: ['Director, hotel', 'Innkeeper', 'Manager, boarding house', 'Manager, department: hotel', 'Manager, guest-house', 'Manager, hostel', 'Manager, hotel', 'Manager, inn', 'Manager, lodging-house', 'Manager, motel', 'Manager, youth hostel'],
        parent: '141',
        ancestors: ['1', '14', '141'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1411 = '1411';

    #[Isco08Info(
        level: 4,
        code: '1412',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '141',
        unit_group: '1412',
        title: 'Restaurant Managers',
        definition: 'Restaurant managers plan, organize and direct the operations of cafes, restaurants and related establishments to provide dining and catering services.',
        tasks_include: "Tasks include - \n(a)  planning menus in consultation with chefs and cooks;\n(b)  planning and organizing special functions;\n(c)  arranging the purchasing and pricing of goods according to budget;\n(d)  maintaining records of stock levels and financial transactions;\n(e)  ensuring dining, kitchen and food storage facilities comply with health regulations and are clean, functional and of suitable appearance;\n(f)  conferring with customers to assess their satisfaction with meals and service;\n(g)  selecting, set staff work schedules, training and supervising waiting and kitchen staff;\n(h)  taking reservations, greeting guests and assisting in taking orders;\n(i)  negotiating arrangements with clients and suppliers;\n(j)  ensuring compliance with occupational health and safety regulations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Chef - 3434",
        notes: 'Operators of small cafes, restaurants and bars for whom the management and supervision of staff is not a significant component of the work, are classified in Unit Groups 5120: Cooks, 5131: Waiters or 5132: Bartenders, depending on the main tasks performed.',
        occupational_titles: ['Manager, café', 'Manager, canteen', 'Manager, catering', 'Manager, restaurant', 'Manager, self-service restaurant', 'Manager, snack-bar', 'Restaurateur'],
        parent: '141',
        ancestors: ['1', '14', '141'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1412 = '1412';

    #[Isco08Info(
        level: 4,
        code: '1420',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '142',
        unit_group: '1420',
        title: 'Retail and Wholesale Trade Managers',
        definition: 'Retail and wholesale trade managers, plan, organize, co-ordinate and control the operations of establishments that sell goods on a retail or wholesale basis. They are responsible for the budgets, staffing and strategic and operational direction of shops, or of organizational units within shops that sell particular types of product.',
        tasks_include: "Tasks include - \n(a)  determining product mix, stock levels and service standards; \n(b)  formulating and implementing purchasing and marketing policies, and setting prices; \n(c)  promoting and advertising the establishment’s goods and services; \n(d)  maintaining records of stock levels and financial transactions; \n(e)  undertaking budgeting for the establishment; \n(f)  controlling selection, training and supervision of staff; \n(g)  ensuring compliance with occupational health and safety regulations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Sales manager - 1221\n- Shopkeeper - 5221\n- Shop supervisor - 5222\n- Shop sales assistant - 5223",
        notes: "Retail and wholesale trade managers are frequently employed in relatively small establishments that do not have a hierarchy of managers. The managers of large retail establishments such as supermarkets and department stores, however, should generally also be classified in this group, although such establishments may have a hierarchy of managers and supervisors. General managers of groups of establishments such as supermarket or department store chains are classified, however, in Unit Group 1120: Managing Directors and Chief Executives. \nOperators of small shops for whom the management and supervision of staff is not a significant component of the work are classified in Unit Group 5221: Shopkeepers.\nStaff who control and direct the activities of shop sales assistants, checkout operators and other workers, but who do not take responsibility for determining product mix, overall setting of prices, budgets and staffing levels, selection and recruitment are classified in Unit Group 5222: Shop Supervisors.",
        occupational_titles: ['Dealer, car: managing and supervising staff', 'Director, franchise', 'Manager, chain store', 'Manager, charity shop', 'Manager, department: retail trade', 'Manager, department: shop', 'Manager, department: supermarket', 'Manager, department: wholesale trade', 'Manager, department store', 'Manager, discount store', 'Manager, garden centre', 'Manager, general: chain store', 'Manager, general: discount store', 'Manager, general: mail-order store', 'Manager, general: self-service store', 'Manager, general: shop', 'Manager, general: wholesale trade', 'Manager, grocery', 'Manager, mail-order store', 'Manager, retail', 'Manager, self-service store', 'Manager, shop', 'Manager, station, service', 'Manager, store: retail', 'Manager, supermarket', 'Merchant, retail trade', 'Merchant, wholesale trade', 'Wholesaler'],
        parent: '142',
        ancestors: ['1', '14', '142'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1420 = '1420';

    #[Isco08Info(
        level: 4,
        code: '1431',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '143',
        unit_group: '1431',
        title: 'Sports, Recreation and Cultural Centre Managers',
        definition: 'Sports, recreation and cultural centre managers plan, organize and control the operations of establishments that provide sporting, artistic, theatrical and other recreational and amenity services.',
        tasks_include: "Tasks include -\n(a)  planning and organizing the range and mix of entertainment, attractions, cultural activities, and sports and fitness programmes to be offered by the centre; \n(b)  ensuring that facilities are kept clean and in good condition;\n(c)  keeping abreast of new trends and developments in the creative arts and arranging theatrical productions and performances by bands and orchestras;\n(d)  advising on the facilities available and promoting publicity in relation to events, shows and activities;\n(e)  checking and keeping custody of all cash receipts and making regular stock checks;\n(f)  establishing and managing budgets, controlling expenditure and ensuring the efficient use of resources;\n(g)  planning and directing daily operations;\n(h)  controlling the selection, supervision and performance of staff;\n(i)  ensuring compliance with health and safety regulations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n-Art gallery manager – 1349\nLibrary manager – 1349\nMuseum manager – 1349",
        notes: null,
        occupational_titles: ['Director, cultural centre', 'Director, leisure centre', 'Manager, amusement centre', 'Manager, amusement park', 'Manager, billiards hall', 'Manager, casino', 'Manager, cinema', 'Manager, cultural centre', 'Manager, leisure centre', 'Manager, pool hall', 'Manager, riding school', 'Manager, snooker hall', 'Manager, sports centre', 'Manager, swimming pool', 'Manager, theatre', 'Manager, theme park'],
        parent: '143',
        ancestors: ['1', '14', '143'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1431 = '1431';

    #[Isco08Info(
        level: 4,
        code: '1439',
        major_group: '1',
        sub_major_group: '14',
        minor_group: '143',
        unit_group: '1439',
        title: 'Services Managers Not Elsewhere Classified',
        definition: 'This unit group covers managers that plan, direct and coordinate the provision of services and are not classified in Sub-major Group 13: Production and Specialized Services Managers or elsewhere in Sub-major Group 14: Hospitality, Retail and Other Services Managers. For instance, managers of travel agencies, conference centres, contact centres and shopping centres are classified here.',
        tasks_include: '',
        excluded_occupations: null,
        notes: 'Excluded from this unit group are occupations that involve managing the provision of specialized professional and technical services and require specialized qualifications and experience relevant to one or more occupations classified in Major Group 2: Professionals, or in Major Group 3: Technicians and Associate Professionals. These managerial occupations are classified in various unit groups in Sub-major Groups 12: Administrative and Commercial Managers and 13: Production and Specialized Services Managers.',
        occupational_titles: ['Manager, camp site', 'Manager, caravan park', 'Manager, conference centre', 'Manager, contact centre', 'Manager, department: production and operations (travel agency)', 'Manager, general: camping site', 'Manager, general: caravan park', 'Manager, general: travel agency', 'Manager, information: tourist', 'Manager, shopping centre', 'Manager, travel agency'],
        parent: '143',
        ancestors: ['1', '14', '143'],
        children: [],
        descendants: [],
    )]
    case ISCO08_1439 = '1439';

    #[Isco08Info(
        level: 4,
        code: '2111',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '211',
        unit_group: '2111',
        title: 'Physicists and Astronomers',
        definition: 'Physicists and astronomers conduct research and improve or develop concepts, theories and operational methods concerning matter, space, time, energy, forces and fields and the interrelationship between these physical phenomena. They apply scientific knowledge relating to physics and astronomy in industrial, medical, military or other fields.',
        tasks_include: "Tasks include -\n(a)  conducting research and improving or developing concepts, theories, instrumentation, software and operational methods related to physics and astronomy;\n(b)  conducting experiments, tests and analyses on the structure and properties of matter in fields such as mechanics, thermodynamics, electronics, communications, power generation and distribution, aerodynamics, optics and lasers, remote sensing, medicine, sonics, magnetism, and nuclear physics;\n(c)  evaluating results of investigations and experiments and expressing conclusions, mainly using mathematical techniques and models;\n(d)  applying principles, techniques and processes to develop or improve industrial, medical, military and other practical applications of the principles and techniques of physics or astronomy; \n(e)  ensuring the safe and effective delivery of radiation (ionising and non-ionising) to patients to achieve a diagnostic or therapeutic result as prescribed by a medical practitioner;\n(f)  ensuring the accurate measurement and characterization of physical quantities used in medical applications; \n(g)  testing, commissioning and evaluating equipment used in applications such as imaging, medical treatment and dosimetry; \n(h)  advising and consulting with medical practitioners and other health care professionals in optimizing the balance between the beneficial and deleterious effects of radiation; \n(i)  observing, analysing and interpreting celestial phenomena and developing methods, numerical models and techniques to extend knowledge of fields such as navigation, satellite communication, space exploration, celestial bodies and cosmic radiation;\n(j) developing, implementing and maintaining standards and protocols for the measurement of physical phenomena and for the use of nuclear technology in industrial and medical applications;\n(k) preparing scientific papers and reports.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Radiation oncologist - 2212\n- Radiologist - 2212\n- Specialist physician (nuclear medicine) - 2212\n- Radiographer - 3211",
        notes: 'It should be noted that, while they are appropriately classified in this unit group with other physicists, medical physicists are considered to be an integral part of the health work force alongside those occupations classified in Sub-major Group 22: Health Professionals and others classified in a number of other unit groups in Major Group 2: Professionals.',
        occupational_titles: ['Aerodynamicist', 'Astronomer', 'Astronomer, radio', 'Astrophysicist', 'Ballistician', 'Hydrodynamicist', 'Physicist', 'Physicist, clinical', 'Physicist, medical', 'Physicist, nuclear', 'Researcher, physics', 'Rheologist', 'Thermodynamicist'],
        parent: '211',
        ancestors: ['2', '21', '211'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2111 = '2111';

    #[Isco08Info(
        level: 4,
        code: '2112',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '211',
        unit_group: '2112',
        title: 'Meteorologists',
        definition: 'Meteorologists prepare short-term or long-term weather forecasts used in aviation, shipping, agriculture and other areas and for the information of the general public. They conduct research related to the composition, structure and dynamics of the atmosphere.',
        tasks_include: "Tasks include -\n(a)  investigating direction and speed of air movements, pressures, temperatures, humidity, physical and chemical transformation of pollutants and other phenomena such as cloud formation and precipitation, electrical disturbances or solar radiation;\n(b)  studying data collected from meteorological stations, radar and satellite imagery and computer model output to plot and forecast weather conditions; \n(c)  preparing and reporting short-term or long-term weather maps, forecasts and warnings relating to atmospheric phenomena such as cyclones, storms and other hazards to life and property and disseminating information about atmospheric conditions through a variety of media including radio, television, print and the Internet;\n(d)  conducting experiments in fog dispersal, cloud seeding, rain enhancement and other types of weather modification programmes; \n(e)  developing and testing mathematical computer models of weather and climate for experimental or operational use;\n(f)  participating in studies of the effect of weather on the environment;\n(g)  analysing the impact of industrial projects and human activity on the climate and quality of the air and working with the social science, engineering and economic communities to develop appropriate mitigation strategies;\n(h)  engaging in the design and development of new equipment and procedures for meteorological data collection, remote sensing, or for related applications;\n(i)  conducting research on and improving or developing concepts, theories and operational methods related to the composition, structure and dynamics of the atmosphere and preparing scientific papers and reports on the outcome of this research.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Climatologist', 'Forecaster, weather', 'Hydrometeorologist', 'Meteorologist'],
        parent: '211',
        ancestors: ['2', '21', '211'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2112 = '2112';

    #[Isco08Info(
        level: 4,
        code: '2113',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '211',
        unit_group: '2113',
        title: 'Chemists',
        definition: 'Chemists conduct research, improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to chemistry, to develop new knowledge or products and for quality and process control.',
        tasks_include: "Tasks include - \n(a)  conducting research and improving or developing concepts, instruments, theories and operational methods related to chemistry;\n(b)  conducting experiments, tests and analyses to investigate chemical composition and energy and chemical changes in various natural or synthetic substances, materials and products;\n(c)  developing procedures for environmental control, quality control and various other procedures for manufacturers or users;\n(d)   conducting programmes of sample and data collection and analysis to identify and quantify environmental toxicants;\n(e)  participating in interdisciplinary research and development projects working with chemical engineers, biologists, microbiologists, agronomists, geologists or other professionals;\n(f)  using micro-organisms to convert substances into new compounds;\n(g)  determining ways to strengthen or combine materials or develop new materials. \n(h)  reproducing and synthesizing naturally occurring substances and creating new artificial substances;\n(i)  preparing scientific papers and reports.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Biochemist - 2131\n- Pharmacologist - 2131\n- Pharmacist - 2262",
        notes: null,
        occupational_titles: ['Chemist', 'Chemist, industrial', 'Chemist, pharmaceutical', 'Chemist, research', 'Crystallographer', 'Researcher, chemical'],
        parent: '211',
        ancestors: ['2', '21', '211'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2113 = '2113';

    #[Isco08Info(
        level: 4,
        code: '2114',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '211',
        unit_group: '2114',
        title: 'Geologists and geophysicists',
        definition: 'Geologists and geophysicists conduct research; improve or develop concepts, theories and operational methods, or apply scientific knowledge relating to geology and geophysics in such fields as oil, gas and mineral exploration and extraction, water conservation, civil engineering, telecommunications and navigation, and assessment and mitigation of the effects of development and waste disposal projects on the environment.',
        tasks_include: "Tasks include -\n(a)  conducting research and improving or developing concepts, theories and operational methods related to geology and geophysics;\n(b)  studying composition and structure of the Earth's crust, examining rocks, minerals, fossils and other materials to determine processes affecting the development of the Earth, trace evolution of past life, establish nature and chronology of geological formations and assess their commercial applications;\n(c)  interpreting research data and preparing geological reports, maps, charts and diagrams, reports and papers;\n(d)  applying geological knowledge to problems encountered in civil engineering projects such as the construction of dams, bridges, tunnels, and large buildings; and land reclamation projects;\n(e)  using various remote sensing programmes to investigate and measure seismic, gravitational, electrical, thermal, and magnetic forces affecting the Earth;\n(f)  estimating weight, size and mass of the Earth and composition and structure of its interior, and studying the nature, activity and predictability of volcanoes, glaciers and earthquakes;\n(g)  charting the Earth's magnetic field and applying this and other collected data for broadcasting, navigation and other purposes;\n(h)  studying and measuring physical properties of seas and the atmosphere and their inter-relationship, such as the exchange of thermal energy;\n(i)  locating and determining the nature and extent of oil, gas and mineral deposits using seismological, gravimetric, magnetic, electrical or radiometric methods;\n(j)  identifying deposits of construction materials and determining their characteristics and suitability for use as concrete aggregates, road fill or for other applications;\n(k)  researching the movement, distribution and physical properties of ground and surface waters; \n(l)  advising in areas such as waste management, route and site selection and the restoration of contaminated sites.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Gemmologist', 'Geochemist', 'Geohydrologist', 'Geologist', 'Geologist, engineering', 'Geomagnetician', 'Geomorphologist', 'Geophysicist', 'Geoscientist', 'Geotechnologist', 'Glaciologist', 'Hydrogeologist', 'Hydrologist', 'Hydrometrist', 'Micropalaeontologist', 'Mineralogist', 'Oceanographer, geological', 'Oceanographer, geophysical', 'Palaeontologist', 'Petrologist', 'Seismologist', 'Stratigrapher', 'Volcanologist'],
        parent: '211',
        ancestors: ['2', '21', '211'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2114 = '2114';

    #[Isco08Info(
        level: 4,
        code: '2120',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '212',
        unit_group: '2120',
        title: 'Mathematicians, Actuaries and Statisticians',
        definition: 'Mathematicians, actuaries and statisticians conduct research and improve or develop mathematical, actuarial and statistical concepts, theories and operational methods and techniques and advise on or engage in their practical application in such fields as engineering, business and social and other sciences.',
        tasks_include: "Tasks include -\n(a)  studying, improving and developing mathematical, actuarial and statistical theories and techniques;\n(b)  advising on or applying mathematical principles, models and techniques to a wide range of tasks in the fields of engineering, natural, social or life sciences;\n(c)  conducting logical analyses of management problems, especially in terms of input-output effectiveness, and formulating mathematical models of each problem usually for programmeming and solution by computer;\n(c)  designing and putting into operation pension schemes and life, health, social and other types of insurance systems;\n(e)  applying mathematics, statistics, probability and risk theory to assess potential financial impacts of future events;\n(f)  planning and organizing surveys and other statistical collections, and designing questionnaires;\n(g)  evaluating, processing, analysing, and interpreting statistical data and preparing them for publication;\n(h)  advising on or applying various data collection methods and statistical methods and techniques, and determining reliability of findings, especially in such fields as business or medicine as well as in other areas of natural, social or life sciences;\n(i)  preparing scientific papers and reports;\n(j)  supervising the work of mathematical, actuarial and statistical assistants and statistical clerks.",
        excluded_occupations: "Some related occupations classified elsewhere:\n-  Information systems analyst - 2511\n-  Actuarial assistant - 3314\n-  Mathematical assistant - 3314\n-  Statistical assistant- 3314\n-  Actuarial clerk - 4312\n-  Statistical clerk - 4312",
        notes: null,
        occupational_titles: ['Actuary', 'Analyst, operations research', 'Biometrician', 'Biostatistician', 'Demographer', 'Mathematician', 'Statistician'],
        parent: '212',
        ancestors: ['2', '21', '212'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2120 = '2120';

    #[Isco08Info(
        level: 4,
        code: '2131',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '213',
        unit_group: '2131',
        title: 'Biologists, Botanists, Zoologists and Related Professionals',
        definition: 'Biologists, botanists, zoologists and related professionals study living organisms and their interactions with each other and with the environment, and apply this knowledge to solve human health and environmental problems. They work in diverse fields such as botany, zoology, ecology, marine biology, genetics, immunology, pharmacology, toxicology, physiology, bacteriology and virology.',
        tasks_include: "Tasks include -\n(a)  undertaking research in laboratories and in the field to increase scientific knowledge of living organisms; to discover new information; to test hypotheses; to solve problems in areas such as the environment, agriculture and health; and to develop new products, processes and techniques for pharmaceutical, agricultural and environmental use;\n(b)  designing and conducting experiments and tests;\n(c)  gathering human, animal, insect and plant specimens and data, and studying their origin, development, chemical and physical form, structure, composition, and life and reproductive processes;\n(d)  examining living organisms using a variety of specialised equipment, instruments, technologies and techniques such as electron microscopes, telemetry, global positioning systems, biotechnology, satellite imaging, genetic engineering, digital imaging analysis, polymerase chain reaction and computer modelling;\n(e)  identifying, classifying, recording and monitoring living organisms and maintaining databases;\n(f)  writing scientific papers and reports detailing research and any new findings which are then made available to the scientific community in scientific journals or at conferences for scrutiny and further debate;\n(g)  designing and carrying out environmental impact assessments to identify changes caused by natural or human factors;\n(h)  providing advice to governments, organizations and businesses in areas such as conservation, management of natural resources, the effects of climate change and pollution.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ecologist - 2133",
        notes: 'Medical research professionals who participate in biomedical research using living organisms and do not undertake clinical practice are classified in Unit Group 2131: Biologists, Botanists, Zoologists and Related Professionals. Those who also undertake clinical practice are classified in Minor Group 221: Medical Doctors.',
        occupational_titles: ['Anatomist', 'Associate, research: clinical', 'Associate, research: medical', 'Bacteriologist', 'Behaviourist, animal', 'Biochemist', 'Biologist', 'Biologist, marine', 'Biologist, molecular', 'Biophysicist', 'Biotechnologist', 'Botanist', 'Cytologist', 'Embryologist', 'Engineer, genetics', 'Entomologist', 'Epidemiologist', 'Geneticist', 'Geneticist, cell', 'Geneticist, molecular', 'Helminthologist', 'Herpetologist', 'Histologist', 'Hydrobiologist', 'Ichthyologist', 'Immunologist', 'Kinesiologist', 'Lepidopterist', 'Mammalogist', 'Microbiologist', 'Mycologist', 'Ornithologist', 'Parasitologist', 'Pathologist, plant', 'Pharmacologist', 'Physiologist', 'Researcher, biomedical', 'Researcher, clinical', 'Researcher, medical', 'Researcher, midwifery', 'Researcher, nursing', 'Scientist, clinical', 'Scientist, food', 'Scientist, health', 'Scientist, medical', 'Taxonomist', 'Toxicologist', 'Zoologist'],
        parent: '213',
        ancestors: ['2', '21', '213'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2131 = '2131';

    #[Isco08Info(
        level: 4,
        code: '2132',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '213',
        unit_group: '2132',
        title: 'Farming, Forestry and Fisheries Advisers',
        definition: 'Farming, forestry and fisheries advisers study and provide assistance and advice on farm, forestry and fisheries management, including cultivation, fertilization, harvesting, soil erosion and composition, disease prevention, nutrition, crop rotation and marketing. They develop techniques for increasing productivity, and study and develop plans and policies for land and fisheries management.',
        tasks_include: "Tasks include -\n(a)  collecting and analysing data and samples related to produce, feed, soil, water quality and other factors affecting farm, forest or fishery production;\n(b)  advising on techniques for improving the production of crops, livestock and fish, and alternative production options;\n(c)  advising on livestock and crop disease, control of pests and weeds, soil improvement, animal husbandry and feeding programmes;\n(d)  studying the environmental factors affecting commercial crop production, pasture growth, animal breeding, fish stocks and the growth and health of forest trees; \n(e)  studying the effects of cultivation techniques, soils, insects, diseases and fisheries practices on animal, crop, forestry and fisheries yield;\n(f)  studying fish migration, growth, feeding and spawning and devising methods of collecting, fertilizing, incubating and hatching fish eggs; \n(g)  researching into characteristics, use capability and productivity of soils and applying findings to development of improved agricultural, horticultural and forestry practices;\n(h)  developing procedures and techniques for solving agricultural problems and improving the efficiency of production; \n(i)  managing forest and fisheries resources to maximize their long-term commercial, recreational and environmental benefits;\n(j)  studying the propagation and culture of forest trees, methods for improving the growth of stock, and the effects of thinning on forest yields; \n(k)  investigating, planning and implementing management procedures to cope with the effects of fires, floods, droughts, soil erosion, pests and diseases;\n(l)  preparing scientific reports and conducting advisory information sessions and lectures for farming, forestry and fishing communities and other groups.",
        excluded_occupations: null,
        notes: null,
