    #[Isco08Info(
        level: 4,
        code: '2133',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '213',
        unit_group: '2133',
        title: 'Environmental Protection Professionals',
        definition: 'Environmental protection professionals study and assess the effects on the environment of human activity such as air, water and noise pollution, soil contamination, climate change, toxic waste and depletion and degradation of natural resources. They develop plans and solutions to protect, conserve, restore, minimize and prevent further damage to the environment.',
        tasks_include: "Tasks include -\n(a)  conducting research, performing tests, collecting samples, performing field and laboratory analysis to identify sources of environmental problems and recommending ways to prevent, control and remediate the impact of environmental problems;\n(b)  assessing the likely impact that potential or proposed activities, projects and developments may have on the environment, and recommending whether such developments should proceed;\n(c)  developing and coordinating the implementation of environmental management systems to enable organizations to identify, monitor and control the impact of their activities, products and services on the environment;\n(d)  conducting audits to evaluate environmental impact of existing activities, processes, wastes, noises and substances;\n(e)  assessing an organization's compliance with government and internal environmental regulations and guidelines, identifying violations and determining appropriate remedial action;\n(f)  providing technical advice and support services to organizations on how best to deal with environmental problems in order to reduce environmental damage and minimize financial loss;\n(g)  developing conservation plans.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Environmental Engineer - 2143",
        notes: null,
        occupational_titles: ['Adviser, environmental', 'Adviser, environmental management', 'Analyst, air pollution', 'Analyst, land degradation', 'Analyst, water quality', 'Auditor, environmental', 'Conservationist, soil', 'Consultant, ecological', 'Consultant, environmental', 'Consultant, environmental management', 'Consultant, land management: environmental management', 'Consultant, natural resource management', 'Coordinator, catchment: environment', 'Coordinator, environmental', 'Ecologist', 'Ecologist, plant', 'Environmentalist', 'Limnologist', 'Officer, catchment management', 'Officer, conservation', 'Officer, environmental', 'Officer, environmental management', 'Officer, environmental protection', 'Officer, environmental rehabilitation', 'Officer, environmental waste', 'Officer, flora and fauna management', 'Officer, natural resource: ecology', 'Officer, natural resource management', 'Officer, rehabilitation: environmental rehabilitation', 'Officer, revegetation', 'Officer, soil conservation', 'Officer, tree management', 'Officer, vegetation management', 'Officer, water quality', 'Officer, waterways: policy development', 'Officer, waterways management', 'Officer, waterways program', 'Ranger, park: environmental protection', 'Researcher, environmental', 'Researcher, salinity', 'Researcher, water quality', 'Researcher, water resources', 'Scientist, air quality', 'Scientist, computer modelling: salinity', 'Scientist, conservation', 'Scientist, environmental', 'Scientist, environmental research', 'Scientist, salinity', 'Scientist, water quality', 'Scientist, water resources', 'Toxicologist, environmental'],
