    #[Isco08Info(
        level: 4,
        code: '2141',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '214',
        unit_group: '2141',
        title: 'Industrial and Production Engineers',
        definition: 'Industrial and production engineers conduct research and design, organize and oversee the construction, operation and maintenance of industrial production processes and installations. They establish programmes for the coordination of manufacturing activities and assess cost effectiveness and safety.',
        tasks_include: "Tasks include -\n(a)  studying functional statements, organizational charts and project information to determine functions and responsibilities of workers and work units and to identify areas of duplication;\n(b)  establishing work measurement programmes and analysing work samples to develop standards for labour utilization;\n(c)  analysing workforce utilization, facility layout, operational data and production schedules and costs to determine optimum worker and equipment efficiencies;\n(d)  developing specifications for manufacture, and determining materials, equipment, piping, material flows, capacities and layout of plant and systems;\n(e)  organizing and managing project labour and the delivery of materials, plant and equipment;\n(f)  establishing standards and policies for installation, modification, quality control, testing, inspection and maintenance according to engineering principles and safety regulations;\n(g)  inspecting plant to improve and maintain performance;\n(h)  directing the maintenance of plant buildings and equipment, and coordinating the requirements for new designs, surveys and maintenance schedules;\n(i)  advising management on new production methods, techniques and equipment;\n(j)  liaising with materials buying, storing and controlling departments to ensure a steady flow of supplies.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Manufacturing production manager - 1321",
        notes: null,
        occupational_titles: ['Engineer, food processing', 'Engineer, industrial', 'Engineer, industrial efficiency', 'Engineer, industrial layout', 'Engineer, industrial plant', 'Engineer, manufacturing', 'Engineer, methods', 'Engineer, planning: production', 'Engineer, process: manufacturing', 'Engineer, production', 'Engineer, time and motion study', 'Engineer, work study', 'Technologist, packaging'],
        parent: '214',
        ancestors: ['2', '21', '214'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2141 = '2141';

    #[Isco08Info(
        level: 4,
        code: '2142',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '214',
        unit_group: '2142',
        title: 'Civil Engineers',
        definition: 'Civil engineers conduct research, advise on, design, and direct construction; manage the operation and maintenance of civil engineering structures; or study and advise on technological aspects of particular materials.',
        tasks_include: "Tasks include -\n(a)  conducting research and developing new or improved theories and methods related to civil engineering;\n(b)  advising on and designing structures such as bridges, dams, docks, roads, airports, railways, canals, pipelines, waste-disposal and flood-control systems, and industrial and other large buildings;\n(c)  determining and specifying construction methods, materials and quality standards, and directing construction work;\n(d)  establishing control systems to ensure efficient functioning of structures as well as safety and environmental protection;\n(e)  organising and directing maintenance and repair of existing civil engineering structures;\n(f)  analysing the behaviour of soil and rock when placed under pressure by proposed structures and designing structural foundations;\n(g)  analysing the stability of structures and testing the behaviour and durability of materials used in their construction.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Civil engineering project manager - 1323\n- Geoscientist - 2114\n- Metallurgist - 2146\n- Mining engineer - 2146\n- Town and traffic planner - 2164",
        notes: null,
        occupational_titles: ['Engineer, building structure', 'Engineer, civil', 'Engineer, construction', 'Engineer, dredging', 'Engineer, geotechnical', 'Engineer, hydraulics', 'Engineer, hydrology', 'Engineer, irrigation', 'Engineer, public health', 'Engineer, sanitary', 'Engineer, soil mechanics', 'Engineer, structural', 'Technologist, building: materials', 'Technologist, engineering: civil'],
        parent: '214',
        ancestors: ['2', '21', '214'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2142 = '2142';

    #[Isco08Info(
        level: 4,
        code: '2143',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '214',
        unit_group: '2143',
        title: 'Environmental Engineers',
        definition: 'Environmental engineers conduct research, advise on, design and direct implementation of solutions to prevent, control or remedy negative impacts of human activity on the environment utilizing a variety of engineering disciplines. They conduct environmental assessments of construction and civil engineering projects and apply engineering principles to pollution control, recycling and waste disposal.',
        tasks_include: "Tasks include -\n(a)  conducting research, assessing and reporting on the environmental impact of existing and proposed construction, civil engineering and other activities;\n(b)  inspecting industrial and municipal facilities and programmes to evaluate operational effectiveness and ensure compliance with environmental regulations; \n(c)  designing and overseeing the development of systems, processes and equipment for control, management, or remediation of water, air, or soil quality;\n(d)  providing environmental engineering assistance in network analysis, regulatory analysis, and planning or reviewing database development;\n(e)  obtaining, updating, and maintaining plans, permits, and standard operating procedures; \n(f)  providing engineering and technical support for environmental remediation and litigation projects, including remediation system design and determination of regulatory applicability;\n(g)  monitoring progress of environmental improvement programmes;\n(h)  advising corporations and government agencies of procedures to follow in cleaning up contaminated sites to protect people and the environment;\n(i)  collaborating with environmental scientists, planners, hazardous waste technicians, engineers from other disciplines and specialists in law and business to address environmental problems.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Environmental Scientist - 2133\n- Radiation Protection Expert - 2263",
        notes: null,
        occupational_titles: ['Analyst, environmental', 'Consultant, air pollution control', 'Consultant, environmental remediation', 'Engineer, air pollution control', 'Engineer, environmental', 'Engineer, process: wastewater', 'Specialist, environmental remediation'],
        parent: '214',
        ancestors: ['2', '21', '214'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2143 = '2143';

    #[Isco08Info(
        level: 4,
        code: '2144',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '214',
        unit_group: '2144',
        title: 'Mechanical Engineers',
        definition: 'Mechanical engineers conduct research; advise on, design and direct production of machines, aircraft, ships, machinery and industrial plant, equipment and systems; advise on and direct their functioning, maintenance and repair; or study and advise on mechanical aspects of particular materials, products or processes.',
        tasks_include: "Tasks include -\n(a)  advising on and designing machinery and tools for manufacturing, mining, construction, agricultural, and other industrial purposes;\n(b)  advising on and designing steam, internal combustion and other non-electric motors and engines used for propulsion of railway locomotives, road vehicles or aircraft, or for driving industrial or other machinery;\n(c)  advising on and designing: hulls, superstructures and propulsion systems of ships; mechanical plant and equipment for the release, control and utilization of energy; heating, ventilation and refrigeration systems, steering gear, pumps and other mechanical equipment;\n(d)  advising on and designing airframes, undercarriages and other equipment for aircraft as well as suspension systems, brakes, vehicle bodies and other components of road vehicles; \n(e)  advising on and designing non-electrical parts of apparatus or products such as word processors, computers, precision instruments, cameras and projectors;\n(f)  establishing control standards and procedures to ensure efficient functioning and safety of machines, machinery, tools, motors, engines, industrial plant, equipment, or systems;\n(g)  ensuring that equipment, operation and maintenance comply with design specifications and safety standards.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ships' engineer - 3151",
        notes: null,
        occupational_titles: ['Architect, marine', 'Architect, naval', 'Designer, aircraft', 'Designer, engine', 'Designer, motor', 'Engineer, aeronautical', 'Engineer, aeronautics', 'Engineer, aerospace', 'Engineer, agricultural machines', 'Engineer, air-conditioning', 'Engineer, automotive', 'Engineer, cryogenic', 'Engineer, diesel', 'Engineer, gas turbine', 'Engineer, heating', 'Engineer, industrial machinery and tools', 'Engineer, instruments: mechanical', 'Engineer, internal: combustion engine', 'Engineer, jet engine', 'Engineer, locomotive engine', 'Engineer, lubrication', 'Engineer, marine', 'Engineer, mechanical', 'Engineer, mechatronics', 'Engineer, motors and engines: mechanical', 'Engineer, naval', 'Engineer, naval: construction', 'Engineer, refrigeration: mechanical', 'Engineer, ship construction', 'Technologist, engineering: mechanical', 'Technologist, welding'],
