    #[Isco08Info(
        level: 4,
        code: '2161',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: '2161',
        title: 'Building Architects',
        definition: 'Building architects design commercial, industrial, institutional, residential and recreational buildings and plan and monitor their construction, maintenance and rehabilitation.',
        tasks_include: "Tasks include -\n(a)  developing new or improved architectural theories and methods;\n(b)  inspecting sites and consulting clients, management and other stakeholders to determine type, style and size of proposed buildings and alterations to existing buildings;\n(c)  providing information regarding designs, materials and estimated building times;\n(d)  preparing project documentation, including sketches and scale drawings, and integrating structural, mechanical and aesthetic elements in final designs;\n(e)  writing specifications and contract documents for use by builders and calling tenders on behalf of clients;\n(f)  making necessary contacts to ensure feasibility of projects regarding style, cost, timing and compliance with regulations;\n(g)  identifying and finding best solutions for problems regarding function and quality of interior environments of buildings and making necessary designs, drawings and plans;\n(h)  monitoring construction or rehabilitation work to ensure compliance with specifications and quality standards;\n(i)  maintaining technical liaison and consultancy with other relevant specialists.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Landscape architect - 2162\n- Interior decorator - 3432\n- Interior designer - 3432",
        notes: null,
        occupational_titles: ['Architect, building', 'Architect, interior'],
        parent: '216',
        ancestors: ['2', '21', '216'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2161 = '2161';

    #[Isco08Info(
        level: 4,
        code: '2162',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: '2162',
        title: 'Landscape Architects',
        definition: 'Landscape architects plan and design landscapes and open spaces for projects such as, parks, schools, institutions, roads, external areas for commercial, industrial and residential sites, and plan and monitor their construction, maintenance and rehabilitation.',
        tasks_include: "Tasks include -\n(a)  developing new or improved theories and methods and providing advice on policy related to landscape architecture;\n(b)  inspecting sites and consulting clients, management and other stakeholders to determine type, style and size of proposed buildings, parks, roads and other open spaces;\n(c)  compiling and analysing site and community data about geographical and ecological features, landforms, soils, vegetation, site hydrology, visual characteristics and human-made structures, to formulate land use and development recommendations, feasibility studies and environmental impact statements;\n(d)  preparing reports, strategic plans, site plans, working drawings, specifications and cost estimates for land development, showing location and details of proposals, including ground modelling, structures, vegetation and access;\n(e)  writing specifications and contract documents for use by builders and civil engineering contractors and calling tenders on behalf of clients;\n(f)  making necessary contacts to ensure feasibility of projects regarding style, cost, timing and compliance with regulations;\n(g)  identifying and finding best solutions for problems regarding function and quality of exterior environments and making necessary designs, drawings and plans;\n(h)  monitoring construction or rehabilitation work to ensure compliance with specifications and quality standards;\n(i)  maintaining technical liaison and consultancy with other relevant specialists.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Building architect - 2161\n- Urban planner - 2164",
        notes: null,
        occupational_titles: ['Architect, landscape'],
        parent: '216',
        ancestors: ['2', '21', '216'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2162 = '2162';

    #[Isco08Info(
        level: 4,
        code: '2163',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: '2163',
        title: 'Product and Garment Designers',
        definition: 'Product and garment designers design and develop products for manufacture and prepare designs and specifications of products for mass, batch and one-off production.',
        tasks_include: "Tasks include -\n(a)  determining the objectives and constraints of the design brief by consulting with clients and stakeholders;\n(b)  formulating design concepts for clothing, textiles, industrial, commercial and consumer products, and jewellery;\n(c)  harmonizing aesthetic considerations with technical, functional, ecological and production requirements;\n(d)  preparing sketches, diagrams, illustrations, plans, samples and models to communicate design concepts;\n(e)  negotiating design solutions with clients, management, and sales and manufacturing staff;\n(f)  selecting, specifying and recommending functional and aesthetic materials, production methods and finishes for manufacture;\n(g)  detailing and documenting the selected design for production;\n(h)  preparing and commissioning prototypes and samples;\n(i)  supervising the preparation of patterns, programmes and tooling, and of the manufacturing process.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Engine designer - 2144\n- Building architect - 2161\n- Landscape architect - 2162\n- Interior designer - 3432",
        notes: null,
        occupational_titles: ['Designer, clothing', 'Designer, commercial: products', 'Designer, costume', 'Designer, dress', 'Designer, fashion', 'Designer, furniture', 'Designer, garment', 'Designer, industrial', 'Designer, jewellery', 'Designer, package', 'Designer, products', 'Designer, textile'],
        parent: '216',
        ancestors: ['2', '21', '216'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2163 = '2163';

    #[Isco08Info(
        level: 4,
        code: '2164',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: '2164',
        title: 'Town and Traffic Planners',
        definition: 'Town and traffic planners develop and implement plans and policies for the controlled use of urban and rural land and for traffic systems. They conduct research and provide advice on economic, environmental and social factors affecting land use and traffic flows.',
        tasks_include: "Tasks include -\n(a)  planning layout and coordinating development of urban areas;\n(b)  compiling and analysing data on economic, legal, political, cultural, demographic, sociological, physical and environmental factors affecting land use;\n(c)  conferring with government authorities, communities and specialists in fields such as architecture, planning, social science the environment and the law;\n(d)  devising and recommending use and development of land, and presenting narrative and graphic plans, programmes and designs to groups and individuals; \n(e)  advising governments, companies and communities on urban and regional planning issues and proposals;\n(f)  reviewing and evaluating environmental impact reports;\n (g)  planning and coordinating the development of land areas for parks, schools, institutions, airports, roadways and related projects, and for commercial, industrial and residential sites;\n(h)  planning and advising on routing and control of road traffic and public transportation systems for efficiency and safety.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Building architect - 2161\n- Landscape architect - 2162",
        notes: null,
        occupational_titles: ['Planner, land', 'Planner, town', 'Planner, traffic', 'Planner, urban'],
        parent: '216',
        ancestors: ['2', '21', '216'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2164 = '2164';

    #[Isco08Info(
        level: 4,
        code: '2165',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: '2165',
        title: 'Cartographers and Surveyors',
        definition: 'Cartographers and surveyors determine the exact position of, or prepare and revise digital, graphic and pictorial maps, charts or other visual representation of, natural and constructed features and boundaries of land, seas, underground areas and celestial bodies, applying scientific and mathematical principles.',
        tasks_include: "Tasks include -\n(a)  surveying, measuring and describing land surfaces, mines, underground surfaces, sea, river and lake beds;\n(b)  noting exact position of various features and recording survey data in digital form;\n(c)  making charts and maps to be used in determining navigable waters and channels and in planning construction of marine structures;\n(d)  planning and conducting aerial photographic surveys;\n(e)  designing, compiling and revising maps and charts using aerial and other photographs, satellite imagery, survey documents and data, existing maps and records, reports and statistics;\n(f)  undertaking research and development of surveying and photogrammetric measurement systems, cadastral systems and land information systems;\n(g)  studying and advising on technical, aesthetic and economic aspects of map production;\n(h)  maintaining technical liaison and consultancy with other relevant specialists.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Quantity Surveyor- 2149\n- Building Surveyor - 3112\n- Marine Surveyor - 3115",
        notes: null,
        occupational_titles: ['Cartographer', 'Geodesist', 'Maker, map', 'Photogrammetrist', 'Surveyor, aerial', 'Surveyor, cadastral', 'Surveyor, geodesic', 'Surveyor, hydrographic', 'Surveyor, land', 'Surveyor, mine', 'Surveyor, photogrammetric', 'Surveyor, photographic', 'Surveyor, topographic'],
        parent: '216',
        ancestors: ['2', '21', '216'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2165 = '2165';

    #[Isco08Info(
        level: 4,
        code: '2166',
        major_group: '2',
        sub_major_group: '21',
        minor_group: '216',
        unit_group: '2166',
        title: 'Graphic and Multimedia Designers',
        definition: 'Graphic and multimedia designers design visual and audio-visual content for the communication of information using print, film, electronic, digital and other forms of visual and audio media. They create graphics, special effects, animation or other visual images for use in computer games, movies, music videos, print media and advertisements.',
        tasks_include: "Tasks include -\n(a)  determining the objectives and constraints of the design brief by consulting with clients and stakeholders;\n(b)  undertaking research and analysing functional communication requirements;\n(c)  formulating design concepts for the subject to be communicated;\n(d)  preparing sketches, diagrams, illustrations and layouts to communicate design concepts;\n(e)  designing complex graphics and animation to satisfy functional, aesthetic and creative requirements of the design brief; \n(f)  creating two-dimensional and three-dimensional images depicting objects in motion or illustrating a process, using computer animation or modelling programmes;\n(g)  negotiating design solutions with clients, management, sales and production staff;\n(h)  selecting, specifying or recommending functional and aesthetic materials and media for publication, delivery or display;\n(i)  detailing and documenting the selected design for production;\n(j)  supervising or carrying out production in the chosen media.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Interior architect - 2161\n- Multimedia developer – 2513\n- Web developer - 2513\n- Visual artist - 2651\n- Interior designer -3432",
        notes: null,
        occupational_titles: ['Animator', 'Artist, commercial', 'Artist, digital', 'Author, dvd', 'Author, html', 'Author, internet content', 'Author, multimedia', 'Author, web', 'Author, website', 'Designer, animation', 'Designer, computer games', 'Designer, graphic', 'Designer, multimedia', 'Designer, poster', 'Designer, publication', 'Designer, typographical', 'Designer, website', 'Illustrator'],
        parent: '216',
        ancestors: ['2', '21', '216'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2166 = '2166';

    #[Isco08Info(
        level: 4,
        code: '2211',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '221',
        unit_group: '2211',
        title: 'Generalist Medical Practitioners',
        definition: 'Generalist medical practitioners (including family and primary care doctors) diagnose, treat and prevent illness, disease, injury and other physical and mental impairments and maintain general health in humans through application of the principles and procedures of modern medicine. They do not limit their practice to certain disease categories or methods of treatment, and may assume responsibility for the provision of continuing and comprehensive medical care to individuals, families and communities.',
        tasks_include: "Tasks include -\n(a)  conducting physical examinations of patients and interviewing them and their families to determine their health status;\n(b)  ordering laboratory tests, X-rays and other diagnostic procedures and analysing findings to determine the nature of disorders or illnesses;\n(c)  providing continuing medical care for patients including prescribing, administering, counselling on and monitoring curative treatments and preventive measures;\n(d)  performing surgery and other clinical procedures;\n(e)  advising individuals, families and communities on health, nutrition and lifestyle which aid prevention or treatment of disease and disorders;\n(f)  providing referrals to patients and families for specialized care in hospitals, rehabilitation centres or other types of health care centres;\n(g)  identifying, managing and providing referrals for complications before, during and after childbirth;\n(h)  recording patients' medical information and history and exchanging information with specialist practitioners and other health workers as required for continuing medical care;\n(i)  reporting births, deaths and notifiable diseases to government authorities to meet legal and professional requirements; \n(j)  conducting research in human health and medical services and disseminating the findings such as through scientific reports\n(k)  planning and participating in programmes designed to prevent the occurrence and spread of common diseases.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Psychiatrist - 2212\n- Specialist physician - 2212\n- Surgeon - 2212\n- Clinical officer (paramedical) - 2240\n- Feldscher - 2240",
        notes: 'Occupations included in this unit group require completion of a university-level degree in basic medical education plus postgraduate clinical training or equivalent for competent performance. Medical interns or residents who have completed their university education in basic medical education and are undertaking postgraduate clinical training in general medicine without any area of specialization are included here. Although in some countries “general practice” and “family medicine” may be considered as medical specializations, these occupations should always be classified here.',
        occupational_titles: ['Consultant, medical: general practice', 'Doctor, family', 'Doctor, general practice', 'Doctor, medical: general', 'Doctor-therapist, district medical', 'Intern, medical', 'Officer, medical: general', 'Officer, resident medical: specializing in general practice', 'Physician, general medicine', 'Physician, primary health care', 'Practitioner, general', 'Practitioner, medical', 'Practitioner, medical: family', 'Registrar, medical: general medicine', 'Resident, medical: general medicine'],
        parent: '221',
        ancestors: ['2', '22', '221'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2211 = '2211';

    #[Isco08Info(
        level: 4,
        code: '2212',
        major_group: '2',
        sub_major_group: '22',
        minor_group: '221',
        unit_group: '2212',
        title: 'Specialist Medical Practitioners',
        definition: 'Specialist medical practitioners (medical doctors) diagnose, treat and prevent illness, disease, injury, and other physical and mental impairments in humans, using specialized testing, diagnostic, medical, surgical, physical and psychiatric techniques, through application of the principles and procedures of modern medicine. They specialize in certain disease categories, types of patient or methods of treatment and may conduct medical education and research in their chosen areas of specialization.',
        tasks_include: "Tasks include -\n(a)  conducting physical examinations of patients and interviewing them and their families to determine their health status; \n(b)  considering medical information provided by a referring doctor or other health care provider;\n(c)  ordering specialized diagnostic tests to determine the nature of disorders or illnesses;\n(d)  prescribing, administering and monitoring patients' responses to treatments, medications, anaesthetics, psychotherapies, physical rehabilitation programmes and other preventive and curative measures;\n(e)  performing surgery of a general or specialized nature;\n(f)  managing complications before, during and after childbirth;\n(g)  recording patients' medical information and exchanging information with other health professionals to ensure the provision of comprehensive care;\n(h)  reporting births, deaths and notifiable diseases to government authorities to meet legal and professional requirements;\n(i)  providing information to patients and families and communities about preventive measures, treatment and care for specific ailments;\n(j)  performing autopsies to determine cause of death; \n(k)  conducting research into specific human disorders and illnesses and preventive or curative methods and disseminating the findings such as through scientific reports;\n(l)  planning and participating in programmes designed to prevent the occurrence and spread of specific diseases.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Biomedical researcher - 2131\n- General practitioner - 2211\n- Resident medical officer specializing in general practice - 2211\n- Dental practitioner - 2261\n- Dental surgeon - 2261\n- Oral and maxillofacial surgeon - 2261\n- Clinical psychologist - 2634",
        notes: "Occupations included in this unit group require completion of a university-level degree in basic medical education plus postgraduate clinical training in a medical specialization (except general practice) or equivalent. Resident medical officers training as specialist practitioners (except general practice) are included here. Although in some countries “stomatology” may be considered as a medical specialization, stomatologists should be included in Unit Group 2261: Dentists.\nMedical research professionals who participate in biomedical research using living organisms and do not undertake clinical practice are classified in Unit Group 2131: Biologists, Botanists, Zoologists and Related Professionals.",
        occupational_titles: ['Allergist, clinical', 'Anaesthesiologist', 'Anaesthetist', 'Cardiologist', 'Consultant, endocrinology', 'Consultant, medical: specialist', 'Consultant, medical: specialist physician', 'Dermatologist', 'Diabetologist', 'Doctor, anaesthetics', 'Doctor, cardiology', 'Doctor, dermatology', 'Doctor, gynaecology', 'Doctor, medical: specialist', 'Doctor, neurology', 'Doctor, obstetrics', 'Doctor, ophthalmology', 'Doctor, otolaryngology', 'Doctor, otorhinolaryngology', 'Doctor, pediatrics', 'Doctor, psychiatry', 'Doctor, radiology', 'Endocrinologist', 'Gastroenterologist', 'Geriatrician', 'Gynaecologist', 'Haematologist, clinical', 'Histopathologist', 'Immunologist, clinical', 'Intern, medical: in specialist training', 'Laryngologist', 'Neonatologist', 'Nephrologist', 'Neurologist', 'Neuropathologist', 'Neurosurgeon', 'Obstetrician', 'Officer, medical: specialist', 'Officer, resident medical: in specialist training', 'Oncologist', 'Oncologist, radiation', 'Ophthalmologist', 'Otolaryngologist', 'Otologist', 'Otorhinolaryngologist', 'Paediatrician', 'Pathologist', 'Pathologist, clinical', 'Pathologist, forensic', 'Pathologist, histopathology', 'Pathologist, medical', 'Pathologist, neuropathology', 'Pathologist, surgical', 'Pediatrician', 'Physician, specialist', 'Physician, specialist: internal medicine', 'Physician, specialist: nuclear medicine', 'Physician, sports', 'Pneumologist', 'Practitioner, medical: specialist (public health)', 'Psychiatrist', 'Radiologist', 'Registrar, anaesthetics', 'Registrar, cardiology', 'Registrar, dermatology', 'Registrar, endocrinology', 'Registrar, gastroenterology', 'Registrar, geriatrics', 'Registrar, gynaecology', 'Registrar, intensive care', 'Registrar, internal medicine', 'Registrar, medical: specialist', 'Registrar, neurology', 'Registrar, obstetrics', 'Registrar, oncology', 'Registrar, ophthalmology', 'Registrar, otorhinolaryngology', 'Registrar, pediatrics', 'Registrar, psychiatry', 'Registrar, radiology', 'Resident, medical: specialist', 'Rheumatologist', 'Rhinologist', 'Specialist, emergency medicine', 'Specialist, intensive care', 'Specialist, internal medicine', 'Specialist, medical', 'Specialist, preventive medicine', 'Surgeon', 'Surgeon, cardiology', 'Surgeon, cardiothoracic', 'Surgeon, medical', 'Surgeon, neurosurgery', 'Surgeon, orthopaedic', 'Surgeon, osteopathic', 'Surgeon, plastic', 'Surgeon, thoracic', 'Urologist'],
        parent: '221',
        ancestors: ['2', '22', '221'],
        children: [],
