    #[Isco08Info(
        level: 4,
        code: '2352',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '235',
        unit_group: '2352',
        title: 'Special Needs Teachers',
        definition: 'Special needs teachers teach physically or mentally handicapped children, young persons, or adults, or those with learning difficulties or other special needs. They promote the social, emotional, intellectual and physical development of their students.',
        tasks_include: "Tasks include -\n(a)  assessing students' abilities and limitations with regard to intellectual, physical, social and emotional impairments, exceptional intellectual gifts, or other specific problems; \n(b)  designing or modifying curricula and preparing and delivering programmes, lessons and activities adapted to students’ abilities and needs;\n(c)  giving instruction on an individual or group basis using special techniques or aids appropriate to students’ needs;\n(d)  employing special educational strategies and techniques during instruction to improve the development of sensory- and perceptual-motor skills, language, cognition, and memory;\n(e)  establishing  and enforcing rules for behaviour and policies and procedures to maintain order among students;\n(f)  teaching academic subjects and practical and self-help skills to students with  hearing, sight and other impairments;\n(g)  stimulating and developing students’ confidence interests, abilities, manual skills and coordination;\n(h)  conferring with other staff members to plan and schedule lessons for special needs students;\n(i)  preparing and maintaining student data and other records and submitting reports;\n(j)  administering various forms of assessment and evaluating progress of each student;\n(k)  conferring with students, parents, head teacher and other relevant professionals involved in the students’ care to develop individual educational plans designed to promote students' development.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Vocational education teacher - 2320\n- Secondary school teacher - 2330\n- Primary school teacher - 2341",
        notes: null,
        occupational_titles: ['Teacher, for the blind', 'Teacher, for the deaf', 'Teacher, for the dumb', 'Teacher, for the mentally handicapped', 'Teacher, for the physically handicapped', 'Teacher, learning support', 'Teacher, of gifted children', 'Teacher, of the hearing impaired', 'Teacher, of the sight impaired', 'Teacher, remedial', 'Teacher, special education', 'Teacher, special education: learning disabilities'],
        parent: '235',
        ancestors: ['2', '23', '235'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2352 = '2352';

    #[Isco08Info(
        level: 4,
        code: '2353',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '235',
        unit_group: '2353',
        title: 'Other Language Teachers',
        definition: 'Other language teachers teach non-native languages to adults and children who are learning a language for reasons of migration, to fulfil employment requirements or opportunities, to facilitate participation in educational programmes delivered in a foreign language, or for personal enrichment. They work outside the mainstream primary, secondary and higher education systems, or in support of students and teachers within those systems.',
        tasks_include: "Tasks include -\n(a)  assessing the level of ability and the extent of language difficulties of students,  and establishing students' needs and learning goals; \n(b)  planning, preparing and delivering lessons and workshops for groups and individuals with content and rate of progression adapted to students’ abilities and needs; \n(c)  designing and producing teaching materials and adapting existing materials; \n(d)  assessing students' progress;\n(e)  assisting students in classroom settings where subjects are taught in a language other than the students’ native language;\n(f)  providing assistance to other teachers by designing special teaching programmes for students still learning the main language of instruction;\n(g)  assigning and correcting work, and preparing and grading exams; \n(h)  assessing, recording and reporting on students’ progress.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- University lecturer - 2310\n- Vocational education teacher – 2320\n- Secondary school teacher - 2330\n- Primary school teacher - 2341",
        notes: null,
        occupational_titles: ['Teacher, EFL', 'Teacher, English as a second language', 'Teacher, ESL', 'Teacher, intensive language', 'Teacher, migrant education', 'Teacher, practical language', 'Teacher, second language', 'Tutor, after school: languages', 'Tutor, language: private tuition'],
        parent: '235',
        ancestors: ['2', '23', '235'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2353 = '2353';

    #[Isco08Info(
        level: 4,
        code: '2354',
        major_group: '2',
        sub_major_group: '23',
        minor_group: '235',
        unit_group: '2354',
        title: 'Other Music Teachers',
        definition: 'Other music teachers teach students in the practice, theory and performance of music outside the mainstream primary, secondary and higher education systems, but may provide private or small group tuition as an extra curricular activity in association with mainstream educational institutions.',
        tasks_include: "Tasks include -\n(a)  assessing the students’ level of ability and determining needs and learning goals; \n(b)  planning, preparing and delivering programmes of study, lessons and workshops for individual students and groups;\n(c)  preparing and presenting material on the theory and interpretation of music;\n(d)  instructing and demonstrating practical aspects of singing or of playing a particular instrument;\n(e)  teaching students to read and write musical notation;\n(f)  assigning exercises and teaching pieces of music relevant to students’ level of ability, interests and talents;\n(g)  assessing students and offering advice, criticism and encouragement;\n(h)  revising curricula, course content, course materials and methods of instruction; \n(i)  preparing students for examinations, performances and assessments;\n(j)  arranging visits and tours to musical performances;\n(k)  organizing and assisting in auditions or performances of students' work.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- University lecturer - 2310\n- Vocational education teacher – 2320\n- Secondary school teacher - 2330\n- Primary school teacher - 2341",
        notes: 'Regular secondary and primary school teachers who teach music are classified in Unit Groups 2330: Secondary Education Teachers, and 2341: Primary School Teachers respectively.',
        occupational_titles: ['Coach, vocal', 'Teacher, guitar: private tuition', 'Teacher, music: private tuition', 'Teacher, piano: private tuition', 'Teacher, singing: private tuition', 'Teacher, violin: private tuition', 'Tutor, music: private tuition', 'Tutor, private tuition: music', 'Tutor, private tuition: singing'],
        parent: '235',
        ancestors: ['2', '23', '235'],
        children: [],
        descendants: [],
    )]
