    #[Isco08Info(
        level: 4,
        code: '2411',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '241',
        unit_group: '2411',
        title: 'Accountants',
        definition: 'Accountants plan, organize and administer accounting systems for individuals and establishments. Some occupations classified here examine and analyse the accounting and financial records of individuals and establishments to ensure accuracy and compliance with established accounting standards and procedures.',
        tasks_include: "(a)  advising on, planning and installing budgetary, accounts controlling and other accounting policies and systems;\n(b)  preparing and certifying financial statements for presentation to management, shareholders and statutory or other bodies;\n(c)  preparing tax returns, advising on taxation problems and contesting disputed claims before tax officials;\n(d)  preparing or reporting on profit forecasts and budgets;\n(e)  conducting financial investigations in such matters as suspected fraud, insolvency and bankruptcy;\n(f)  auditing accounts and bookkeeping records;\n(g)  conducting investigations and advising management on financial aspects of productivity, stockholdings, sales, new products, etc.;\n(h)  devising and controlling a system to determine unit cost of products and services.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Finance manager - 1211\n- Accounting assistant - 3313\n- Bookkeeper - 3313",
        notes: null,
