    #[Isco08Info(
        level: 4,
        code: '2413',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '241',
        unit_group: '2413',
        title: 'Financial Analysts',
        definition: 'Financial analysts conduct quantitative analyses of information affecting investment programmes of public or private institutions.',
        tasks_include: "(a)  analysing financial information to produce forecasts of business, industry, and economic conditions for use in making investment decisions;\n(b)  maintaining knowledge and staying abreast of developments in the fields of industrial technology, business, finance, and economic theory;\n(c)  interpreting data affecting investment programmes, such as price, yield, stability, future trends in investment risks and economic influences;\n(d)  monitoring economic, industrial, and corporate developments through analysis of information obtained from financial publications and services, investment banking firms, government agencies, trade publications, company sources and personal interviews;\n(e)  recommending investments and investment timing to companies, investment firm staff or the investing public;\n(f)  determining the prices at which securities should be syndicated and offered to the public;\n(g)  preparing plans of action for investment based on financial analyses;\n(h)  evaluating and comparing the relative quality of various securities in a given industry;\n(i)  presenting oral and written reports on general economic trends, individual corporations, and entire industries.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Analyst, bond', 'Analyst, financial: investments', 'Analyst, investment', 'Analyst, securities', 'Consultant, investment: financial analysis', 'Consultant, securities'],
        parent: '241',
        ancestors: ['2', '24', '241'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2413 = '2413';

    #[Isco08Info(
        level: 4,
        code: '2421',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '242',
        unit_group: '2421',
        title: 'Management and Organization Analysts',
        definition: 'Management and organization analysts assist organizations to achieve greater efficiency and solve organizational problems. They study organizational structures, methods, systems and procedures.',
        tasks_include: "(a)  assisting and encouraging the development of objectives, strategies and plans aimed at achieving customer satisfaction and the efficient use of organizations’ resources;\n(b)  analysing and evaluating current systems and structures;\n(c)  discussing current systems with staff and observing systems at all levels of organization;\n(d)  directing clients towards more efficient organization and developing solutions to organizational problems; \n(e)  undertaking and reviewing work studies by analysing existing and proposed methods and procedures such as administrative and clerical procedures; \n(f)  recording and analysing organizations’ workflow charts, records, reports, manuals and job descriptions;\n(g)  preparing and recommending proposals to revise methods and procedures, alter work flows, redefine job functions and resolve organizational problems; \n(h)  assisting in implementing approved recommendations, issuing revised instructions and procedure manuals, and drafting other documentation; \n(i)  reviewing operating procedures and advising of departures from procedures and standards.",
        excluded_occupations: "Some related occupations classified elsewhere:\nBusiness Analysts (IT) - 2511",
        notes: null,
        occupational_titles: ['Analyst, cost', 'Analyst, management', 'Analyst, organization and methods', 'Consultant, business', 'Consultant, management', 'Facilitator, quality', 'Inspector, quality: services', 'Specialist, business efficiency'],
        parent: '242',
        ancestors: ['2', '24', '242'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2421 = '2421';

