    #[Isco08Info(
        level: 4,
        code: '2432',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '243',
        unit_group: '2432',
        title: 'Public Relations Professionals',
        definition: "Public relations professionals plan, develop, implement and evaluate information and communication \tstrategies that create an understanding and a favourable view of businesses and other organizations, their goods and services, and their role in the community.",
        tasks_include: "Tasks include -\n(a)  planning and organizing publicity campaigns and communication strategies; \n(b)  advising executives on the public relations implications of their policies, programmes and practices preparing and controlling the issue of news and press releases; \n(c)  undertaking and commissioning public opinion research, analysing the findings and planning public relations and promotional campaigns; \n(d)  organizing special events, seminars, entertainment, competitions and social functions to promote goodwill and favourable publicity; \n(e)  representing organizations and arranging interviews with publicity media; \n(f)  attending business, social and other functions to promote the organization; \n(g)  commissioning and obtaining photographs and other illustrative material; \n(h)  selecting, appraising and revising material submitted by publicity writers, photographers, illustrators and others to create favourable publicity.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Agent, publicity', 'Analyst, communications: except computers', 'Consultant, communications', 'Consultant, public relations', 'Copywriter, publicity', 'Executive, account: public relations', 'Lobbyist', 'Manager, account: public relations', 'Officer, press liaison', 'Officer, public affairs', 'Officer, public information', 'Officer, public relations', 'Publicist', 'Secretary, press', 'Writer, copy: publicity', 'Writer, copy: public relations', 'Writer, publicity'],
        parent: '243',
        ancestors: ['2', '24', '243'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2432 = '2432';

    #[Isco08Info(
        level: 4,
        code: '2433',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '243',
        unit_group: '2433',
        title: 'Technical and Medical Sales Professionals (excluding ICT)',
        definition: 'Technical and medical sales professionals (excluding ICT) represent companies in selling a range of industrial, medical and pharmaceutical goods and services to industrial, business, professional and other establishments.',
        tasks_include: "Tasks include - \n(a)  compiling lists of prospective client businesses using directories and other sources; \n(b)  acquiring and updating knowledge of employers’ and competitors’ goods and services, and market conditions; \n(c)  visiting regular and prospective client businesses to establish and act on selling opportunities; \n(d)  assessing clients' needs and resources and recommending appropriate goods or services; \n(e)  providing input to product design where goods or services must be tailored to suit clients’ needs; \n(f)  developing reports and proposals as part of sales presentation to demonstrate benefits from use of goods or service;\n(g)  estimating costs of installing and maintaining equipment or service; \n(h)  monitoring customers’ changing needs and competitor activity, and reporting these developments to sales management; \n(i)  quoting and negotiating prices and credit terms, and preparing and administering sales contracts; \n(j)  arranging delivery of goods, installation of equipment and the provision of services; \n(k)  reporting to sales management on sales made and the marketability of goods and services; \n(l)  consulting with clients after sale to ensure a satisfactory resolution of any problems and provide ongoing support.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Sales representative (communications technology) – 2434\n- Sales representative (computers) – 2434\n- Commercial sales representative - 3322",
        notes: null,
        occupational_titles: ['Agent, sales: engineering', 'Agent, sales: medical', 'Agent, sales: technical', 'Consultant, sales: engineering', 'Consultant, sales: technical (except ICT)', 'Engineer, sales: except ICT', 'Executive, account: sales (industrial products)', 'Executive, account: sales (medical products)', 'Executive, account: sales (pharmaceuticals)', 'Manager, account: sales (industrial products)', 'Manager, account: sales (medical products)', 'Manager, account: sales (pharmaceuticals)', 'Representative, sales: engineering', 'Representative, sales: industrial products', 'Representative, sales: medical and pharmaceutical products', 'Representative, sales: technical (except ICT)', 'Salesperson, engineering'],
        parent: '243',
        ancestors: ['2', '24', '243'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2433 = '2433';

    #[Isco08Info(
        level: 4,
        code: '2434',
        major_group: '2',
        sub_major_group: '24',
        minor_group: '243',
        unit_group: '2434',
        title: 'Information and Communications Technology Sales Professionals',
        definition: 'Information and communications technology (ICT) sales professionals sell, at the wholesale level, a range of computer hardware, software and other information and communications technology goods and services including installations and provide specialized information as required.',
        tasks_include: "Tasks include -\n(a)  soliciting orders and selling goods to retail, industrial, wholesale and other establishments;\n(b)  selling technical equipment, supplies and related services to business establishments or individuals;\n(c)  discussing the needs of new and existing customers and providing specialized information about how particular equipment, supplies and services meet those needs;\n(d)  quoting and negotiating prices and credit terms, and completing contracts and recording orders;\n(e)  updating customer records and preparing sales reports;\n(f)  arranging delivery of goods, installation of equipment and the provision of services;\n(g)  reporting customers' reactions and requirements to manufacturers.",
        excluded_occupations: "Some related occupations classified elsewhere:\nShop sales assistant - 5223",
        notes: null,
        occupational_titles: ['Agent, sales: communications (technology)', 'Agent, sales: computer (systems)', 'Agent, sales: information technology', 'Consultant, sales: computer systems', 'Consultant, sales: information technology', 'Consultant, sales: technical (ICT)', 'Engineer, sales: ICT', 'Executive, account: sales (information and communications technology)', 'Manager, account: computer technology', 'Manager, account: ICT', 'Manager, account: sales (information and communications technology)', 'Manager, business development: ICT', 'Representative, sales: communications technology', 'Representative, sales: computer systems', 'Representative, sales: ICT', 'Representative, sales: information technology', 'Representative, sales: technical (ICT)', 'Salesperson, communications technology', 'Salesperson, computer systems', 'Salesperson, information technology'],
        parent: '243',
        ancestors: ['2', '24', '243'],
