    #[Isco08Info(
        level: 4,
        code: '2511',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '251',
        unit_group: '2511',
        title: 'Systems Analysts',
        definition: 'Systems analysts conduct research, analyse and evaluate client information technology requirements, procedures or problems, and develop and implement proposals, recommendations and plans to improve current or future information systems.',
        tasks_include: "Tasks include -\n(a)  consulting with users to formulate and document requirements and with management to ensure agreement on systems principles;\n(b)  identifying and analysing business processes, procedures and work practices;\n(c)  identifying and evaluating inefficiencies and recommending optimal business practices and system functionality and behaviour;\n(d)  taking responsibility for deploying functional solutions, such as creating, adopting and implementing system test plans;\n(e)  developing functional specifications for use by systems developers;\n(f)  expanding or modifying systems to improve workflow or serve new purposes;\n(g)  coordinating and linking the computer systems within an organization to increase compatibility.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Administrator, SAP: business analysis', 'Analyst, business: IT', 'Analyst, business: systems design', 'Analyst, computer: business analysis', 'Analyst, information systems', 'Analyst, SAP', 'Analyst, systems: computers', 'Architect, business: business analysis', 'Architect, business solutions', 'Architect, information: business analysis', 'Architect, solutions: business', 'Consultant, business: information technology', 'Consultant, systems: computers', 'Designer, systems: computers', 'Designer, systems: IT', 'Engineer, business process: information technology', 'Scientist, computer', 'Technologist, information: business analysis'],
        parent: '251',
        ancestors: ['2', '25', '251'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2511 = '2511';

    #[Isco08Info(
        level: 4,
        code: '2512',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '251',
        unit_group: '2512',
        title: 'Software Developers',
        definition: 'Software developers research, analyse and evaluate requirements for existing or new software applications and operating systems, and design, develop, test and maintain software solutions to meet these requirements.',
        tasks_include: "Tasks include -\n(a)   researching, analysing and evaluating requirements for software applications and operating systems;\n(b)  researching, designing, and developing computer software systems;\n(c)  consulting with engineering staff to evaluate interfaces between hardware and software;\n(d)  developing and directing software testing and validation procedures;\n(e)  modifying existing software to correct errors, to adapt it to new hardware or to upgrade interfaces and improve performance;\n(f)  directing software programming and development of documentation;\n(g)  assessing, developing, upgrading and documenting maintenance procedures for operating systems, communications environments and applications software;\n(h)  consulting with customers concerning maintenance of software system.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Applications programmer -  2514",
        notes: null,
        occupational_titles: ['Analyst, programme: computers', 'Analyst, programmer', 'Designer, computer software', 'Designer, software', 'Developer, applications: computing (except web)', 'Developer, software', 'Engineer, computer: applications', 'Engineer, computer: software', 'Engineer, computer: systems', 'Engineer, software', 'Engineer, systems : computer', 'Programmer-analyst'],
        parent: '251',
        ancestors: ['2', '25', '251'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2512 = '2512';

    #[Isco08Info(
        level: 4,
        code: '2513',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '251',
        unit_group: '2513',
        title: 'Web and Multimedia Developers',
        definition: 'Web and multimedia development professionals combine design and technical knowledge to research, analyse, evaluate, design, programme and modify websites and applications that draw together text, graphics, animations, imaging, audio and video displays and other interactive media.',
        tasks_include: "Tasks include -\n(a)  analysing, designing and developing Internet sites by applying a mixture of artistry and creativity with software programming and scripting languages and interfacing with operating environments;\n(b)  designing and developing digital animations, imaging, presentations, games, audio and video clips, and Internet applications using multimedia software, tools and utilities, interactive graphics and programming languages;\n(c)  communicating with network specialists regarding web-related issues, such as security and hosting web sites, to control and enforce Internet and web server security, space allocation, user access, business continuity, web site backup and disaster recovery planning; \n(d)  designing, developing and integrating computer code with other specialised inputs, such as image files, audio files and scripting languages, to produce, maintain and support web sites;\n(e)   assisting in analysing, specifying and developing Internet strategies, web-based methodologies and development plans.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Website designer - 2166\n- Webmaster - 3514\n- Website administrator - 3514\n- Website technician-  3514",
        notes: null,
        occupational_titles: ['Architect, information: computing (website)', 'Architect, website', 'Consultant, internet: developing websites', 'Consultant, internet: programming', 'Developer, applications: computing (internet)', 'Developer, applications: computing (web)', 'Developer, computer game', 'Developer, dhtml', 'Developer, flash', 'Developer, game: computer', 'Developer, html', 'Developer, interactive', 'Developer, internet', 'Developer, internet applications', 'Developer, internet multimedia', 'Developer, internet software', 'Developer, multimedia', 'Developer, video game', 'Developer, web', 'Developer, web applications', 'Developer, webpage', 'Developer, website', 'Developer, web software', 'Engineer, internet: developing websites', 'Engineer, internet: programming', 'Programmer, animation', 'Programmer, computer: games', 'Programmer, computer: internet', 'Programmer, computer: web', 'Programmer, computer: website', 'Programmer, dhtml', 'Programmer, html', 'Programmer, internet', 'Programmer, internet applications', 'Programmer, multimedia', 'Programmer, web', 'Programmer, website', 'Specialist, multimedia'],
