    #[Isco08Info(
        level: 4,
        code: '2521',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '252',
        unit_group: '2521',
        title: 'Database Designers and Administrators',
        definition: 'Database designers and administrators design, develop, control, maintain and support the optimal performance and security of databases.',
        tasks_include: "Tasks include -\n(a)  designing and developing database architecture, data structures, tables, dictionaries and naming conventions for information systems projects;\n(b)  designing, constructing, modifying, integrating, implementing and testing database management systems;\n(c)  conducting research and providing advice on the selection, application and implementation of database management tools;\n(d)  developing and implementing data administration policy, documentation, standards and models;\n(e)  developing policies and procedures for database access and usage and for the backup and recovery of data;\n(f)  performing the operational establishment and preventive maintenance of backups, recovery procedures, and enforcing security and integrity controls.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Network administrator - 2522\n- Systems administrator (computers) - 2522\n- Webmaster - 3514\n- Website administrator - 3514",
        notes: null,
        occupational_titles: ['Administrator, data', 'Administrator, database', 'Analyst, database', 'Architect, database', 'Developer, database', 'Manager, database', 'Programmer, database'],
        parent: '252',
