    #[Isco08Info(
        level: 4,
        code: '2522',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '252',
        unit_group: '2522',
        title: 'Systems Aministrators',
        definition: 'Systems administrators develop, control, maintain and support the optimal performance and security of information technology systems.',
        tasks_include: "Tasks include -\n(a)  maintaining and administering computer networks and related computing environments including computer hardware, systems software, applications software and all configurations;\n(b)  recommending changes to improve systems and network configurations, and determining hardware or software requirements related to such changes;\n(c)  diagnosing hardware and software problems;\n(d)  performing data backups and disaster recovery operations;\n(e)  operating master consoles to monitor the performance of computer systems and networks, and to coordinate computer network access and use.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Database administrator - 2521\n- Network analyst - 2523\n- Website administrator - 3514\n- Website technician - 3514",
        notes: null,
        occupational_titles: ['Administrator, computer: systems administration', 'Administrator, computer systems', 'Administrator, IT systems', 'Administrator, network', 'Administrator, systems: computers', 'Administrator, unix', 'Administrator, WAN', 'Analyst, infrastructure: systems administration', 'Consultant, computer systems: managing system', 'Consultant, information systems: managing system', 'Consultant, information technology: managing system', 'Consultant, information technology: systems administration', 'Consultant, information technology: unix administration', 'Coordinator, information services: managing computer system', 'Engineer, server', 'Manager, computer systems: systems administration', 'Manager, information systems: systems administration', 'Manager, information technology: systems administration', 'Officer, computer systems: managing system', 'Officer, support: network administration', 'Officer, systems support: systems administration', 'Officer, technology: systems administration', 'Specialist, network: computing (managing system)', 'Technologist, information: systems administration'],
