    #[Isco08Info(
        level: 4,
        code: '2523',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '252',
        unit_group: '2523',
        title: 'Computer Network Professionals',
        definition: 'Computer network professionals research, analyse, design, test and recommend strategies for network architecture and development. They implement, manage, maintain and configure network hardware and software, and monitor, troubleshoot and optimize performance.',
        tasks_include: "Tasks include -\n(a)  analysing, developing, interpreting and evaluating complex system design and architecture specifications, data models and diagrams in the development, configuration and integration of computer systems;\n(b)  researching, analysing, evaluating and monitoring network infrastructure to ensure networks are configured to operate at optimal performance;\n(c)  assessing and recommending improvements to network operations and integrated hardware, software, communications and operating systems;\n(d)  providing specialist skills in supporting and troubleshooting network problems and emergencies;\n(e)  installing, configuring, testing, maintaining and administering new and upgraded networks, software database applications, servers and workstations;\n(f)  preparing and maintaining procedures and documentation for network inventory, and recording diagnosis and resolution of network faults, enhancements and modifications to networks and maintenance instructions;\n(g)  monitoring network traffic and activity, capacity and usage to ensure continued integrity and optimal network performance.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Systems  analyst  - 2511\n- Network administrator - 2522",
        notes: null,
        occupational_titles: ['Analyst, communications: computers', 'Analyst, network', 'Programmer, communications'],
        parent: '252',
        ancestors: ['2', '25', '252'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2523 = '2523';

    #[Isco08Info(
        level: 4,
        code: '2529',
        major_group: '2',
        sub_major_group: '25',
        minor_group: '252',
        unit_group: '2529',
        title: 'Database and Network Professionals Not Elsewhere Classified',
        definition: "This unit group includes database and network professionals not classified elsewhere in Minor Group 252: Database and Network Professionals.  \tFor instance, the group includes information and communications technology security specialists.",
        tasks_include: "In such cases tasks would include -\n(a)  developing plans to safeguard computer files against accidental or unauthorized modification, destruction or disclosure and to meet emergency data processing needs;\n(b)  training users and promoting security awareness to ensure system security and to improve server and network efficiency;\n(c)  conferring with users to discuss issues such as computer data access needs, security violations, and programming changes;\n(d)  monitoring current reports of computer viruses to determine when to update virus protection systems;\n(e)  modifying computer security files to incorporate new software, correct errors or change individual access status;\n(f)  monitoring use of data files and regulate access to safeguard information in computer files;\n(g)  performing risk assessments and executing tests of data processing system to ensure functioning of data processing activities and security measures;\n(h)  encrypting data transmissions and erecting firewalls to conceal confidential information as it is being transmitted and to keep out tainted digital transfers.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Analyst, data mining', 'Analyst, security: computer', 'Analyst, security: data', 'Analyst, security: ICT', 'Auditor, information technology', 'Consultant, data mining', 'Consultant, digital forensics', 'Consultant, security: computer', 'Consultant, security: data', 'Consultant, security: ICT', 'Miner, data', 'Scientist, data mining', 'Specialist, data mining', 'Specialist, digital forensics', 'Specialist, security: computer', 'Specialist, security: data', 'Specialist, security: ICT'],
        parent: '252',
        ancestors: ['2', '25', '252'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2529 = '2529';

    #[Isco08Info(
        level: 4,
        code: '2611',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '261',
        unit_group: '2611',
        title: 'Lawyers',
        definition: 'Lawyers give clients legal advice on a wide variety of subjects, draw up legal documents, represent clients before administrative boards or tribunals and plead  cases or conduct prosecutions in courts of justice, or instruct barristers to plead in higher courts of justice.',
        tasks_include: "Tasks include -\n(a)  giving clients legal advice on a wide variety of subjects and undertaking legal business on clients’ behalf;\n(b)  researching legal principles, statutes and previous court decisions related to specific cases;\n(c)  gathering evidence to formulate a defence or to initiate legal actions, by such means as interviewing clients and witnesses to ascertain the facts of a case;\n(d)  evaluating findings and develop strategies and arguments in preparation for presentation of cases;\n(e)  pleading clients’ cases before courts of law, tribunals and administrative boards or instructing barristers to plead in higher courts of justice;\n(f)  accepting briefs and pleading in the higher court;\n(g)  acting as prosecutor on behalf of the Government;\n(h)  negotiating settlements in matters which involve legal disputes;\n(i)  drafting legislation and preparing government regulations based on existing laws;\n(j)  drawing up legal documents such as contracts, real estate transactions and wills and preparing statements of legal opinions.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Notary - 2619\n- Conveyancing clerk - 3411\n- Law clerk - 3411",
        notes: null,
        occupational_titles: ['Adviser, legal', 'Adviser, legislative', 'Advocate, legal', 'Attaché, legal', 'Attorney', 'Barrister', 'Counsel, legal', 'Drafter, parliamentary', 'Jurisconsult', 'Jurist, lawyer', 'Lawyer', 'Litigator', 'Officer, legal', 'Partner, law', 'Prosecutor', 'Solicitor'],
        parent: '261',
        ancestors: ['2', '26', '261'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2611 = '2611';

    #[Isco08Info(
        level: 4,
        code: '2612',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '261',
        unit_group: '2612',
        title: 'Judges',
        definition: 'Judges preside over civil and criminal proceedings in courts of law.',
        tasks_include: "Tasks include -\n(a)  presiding over trials and hearings;\n(b)  interpreting and enforcing rules of procedure and making rulings regarding the admissibility of evidence;\n(c)  determining the rights and obligations of the parties involved, and, in cases tried by jury;\n(d)  instructing the jury on points of law that are applicable to the case;\n(e)  weighing and considering evidence in non-jury trials and deciding legal guilt or innocence or degree of liability of the accused or defendant;\n(f)  passing sentence on persons convicted in criminal cases, determining damages or other appropriate remedy in civil cases and issuing court orders;\n(g)  researching legal issues and writing opinions on the issues.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Court clerk - 3411\n- Justice of the Peace - 3411",
        notes: null,
        occupational_titles: ['Chief, justice', 'Judge', 'Jurist, judge', 'Justice', 'Justice, chief', 'Magistrate'],
        parent: '261',
        ancestors: ['2', '26', '261'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2612 = '2612';

    #[Isco08Info(
        level: 4,
        code: '2619',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '261',
        unit_group: '2619',
        title: 'Legal Professionals Not Elsewhere Classified',
        definition: "This unit group covers legal professionals not classified elsewhere in Minor Group 261: Legal professionals. \tFor instance, the group includes those who perform legal functions other than pleading or prosecuting cases or presiding over judicial  proceedings.",
        tasks_include: "In such cases tasks would include:\n(a)  giving advice on legal aspects of various personal, business and administrative problems;\n(b)  drawing up legal documents and contracts;\n(c)  arranging property transfers;\n(d)  determining, by inquest, the causes of any death not obviously due to natural causes.",
        excluded_occupations: null,
