    #[Isco08Info(
        level: 4,
        code: '2621',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '262',
        unit_group: '2621',
        title: 'Archivists and Curators',
        definition: 'Archivists and curators collect, appraise and ensure the safekeeping and preservation of the contents of archives, artefacts and records of historical, cultural, administrative and artistic interest, and of art and other objects. They plan, devise and implement systems for the safekeeping of records and historically valuable documents.',
        tasks_include: "Tasks include -\n(a)  evaluating and preserving records for administrative, historical, legal, evidential and other purposes;\n(b)  directing or carrying out the preparation of indexes, bibliographies, microfilm copies and other reference aids to the collected material and making them available to users;\n(c)  researching the origin, distribution and use of materials and objects of cultural and historical interest;\n(d)  organizing, developing and maintaining collections of artistic, cultural, scientific or historically significant items;\n(e)  directing or undertaking classification and cataloguing of museum and art gallery collections and organizing exhibitions;\n(f)  researching into, appraising, organizing and preserving historically significant and valuable documents such as government papers, private papers, photographs, maps, manuscripts and audiovisual materials;\n(g)  preparing scholarly papers and reports;\n(h)  planning and implementing the computerized management of archives and electronic records;\n(i)  organizing exhibitions at museums and art galleries, publicizing exhibits and arranging special displays for general, specialized or educational interest;\n(j)  appraising and acquiring archival materials to build and develop an archival collection for research purposes.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Archivist', 'Conservator', 'Curator, art gallery', 'Curator, museum', 'Manager, data', 'Manager, information', 'Manager, records'],
        parent: '262',
        ancestors: ['2', '26', '262'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2621 = '2621';

    #[Isco08Info(
        level: 4,
        code: '2622',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '262',
        unit_group: '2622',
        title: 'Librarians and Related Information Professionals',
        definition: 'Librarians and related information professionals collect, select, develop, organize and maintain library collections and other information repositories, organize and control other library services and provide information for users.',
        tasks_include: "Tasks include -\n(a)  organizing, developing and maintaining a systematic collection of books, periodicals and other printed or audiovisually and digitally recorded material;\n(b)  selecting and recommending acquisitions of books and other printed or audiovisually and digitally recorded material;\n(c)  organizing, classifying and cataloguing library material;\n(d)  managing library borrowing and interlibrary loan facilities and information networks;\n(e)  retrieving material and providing information to business and other users based on the collection itself or on library and information-network systems;\n(f)  conducting research and analysing or modifying library and information services in accordance with changes in users' needs;\n(g)  devising and implementing schemes and conceptual models for the storage, organization, classification and retrieval of information;\n(h)  preparing scholarly papers and reports;\n(i)  performing manual, on-line and interactive media reference searches, making interlibrary loans and performing other functions to assist users in accessing library materials.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Bibliographer', 'Cataloguer', 'Documentalist', 'Librarian', 'Officer, information', 'Scientist, information'],
        parent: '262',
        ancestors: ['2', '26', '262'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2622 = '2622';

    #[Isco08Info(
        level: 4,
        code: '2631',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: '2631',
        title: 'Economists',
        definition: 'Economists conduct research, monitor data, analyse information and prepare reports and plans to resolve economic and business problems and develop models to analyse, explain and forecast economic behaviour and patterns. They provide advice to business, interest groups and governments to formulate solutions to present or projected economic and business problems.',
        tasks_include: "Tasks include -\n(a)  forecasting changes in the economic environment for short-term budgeting, long-term planning and investment evaluation;\n(b)  formulating recommendations, policies and plans for the economy, corporate strategies and investment, and undertaking feasibility studies for projects;\n(c)  monitoring economic data to assess the effectiveness, and advise on the appropriateness, of monetary and fiscal policies; \n(d)  forecasting production and consumption of specific products and services based on records of past production and consumption and general economic and industry-specific conditions;\n(e)  preparing forecasts of income and expenditure, interest rates and exchange rates;\n(f)  analysing factors that determine labour force participation, employment, wages, unemployment and other labour market outcomes; \n(g)  applying mathematical formulae and statistical techniques and apply to test economic theories and devise solutions to economic problems;\n(h)  compiling, analysing and interpreting economic data using economic theory and a variety of statistical and other techniques;\n(i)  evaluating the outcome of political decisions concerning public economy and finances and advising on economic policy and possible courses of action in the light of past, present and projected economic factors and trends;\n(j)  preparing scholarly papers and reports;\n(k)  examining problems related to the economic activities of individual companies;\n(l)  conducting research on market conditions in local, regional or national areas to set sales and pricing levels for goods and services, to assess market potential and future trends and to develop business strategies.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Statistician - 2120",
        notes: null,
        occupational_titles: ['Adviser, economic', 'Adviser, economic policy', 'Analyst, business: economics', 'Analyst, economic', 'Consultant, economic development', 'Econometrician', 'Economist', 'Economist, labour', 'Macroeconomist'],
        parent: '263',
        ancestors: ['2', '26', '263'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2631 = '2631';

    #[Isco08Info(
        level: 4,
        code: '2632',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: '2632',
        title: 'Sociologists, Anthropologists and Related Professionals',
        definition: 'Sociologists, anthropologists and related professionals investigate and describe the structure, origin and evolution of societies and the interdependence between environmental conditions and human activities. They provide advice on the practical application of their findings in the formulation of economic and social policies.',
        tasks_include: "Tasks include -\n(a)  conducting research on the origin, development, structure, social patterns, organizations and interrelationships of human society;\n(b)  tracing the origin and evolution of humanity through the study of changing characteristics and cultural and social institutions; \n(c)  tracing the development of humanity through the material remains of its past, such as dwellings, temples, tools, pottery, coins, weapons or sculpture;\n(d)  studying physical and climatic aspects of areas and regions, and correlating these findings with economic, social and cultural activities;\n(e)  developing theories, models and methods to interpret and describe social phenomena;\n(f)  evaluating the outcome of political decisions concerning social policy;\n(g)  analysing and evaluating social data;\n(h)  advising on the practical application of findings in the formulation of economic and social policies for population groups and regions, and for the development of markets;\n(i)  preparing scholarly papers and reports.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Anthropologist', 'Archaeologist', 'Criminologist', 'Ethnologist', 'Geographer', 'Pathologist, social', 'Penologist', 'Researcher, social', 'Scientist, social', 'Sociologist'],
        parent: '263',
        ancestors: ['2', '26', '263'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2632 = '2632';

    #[Isco08Info(
        level: 4,
        code: '2633',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: '2633',
        title: 'Philosophers, Historians and Political Scientists',
        definition: 'Philosophers, historians and political scientists conduct research into the nature of human experience and existence, phases or aspects of human history, and political structures, movements and behaviour. They document and report on findings to inform and guide political and individual actions',
        tasks_include: "Tasks include -\n(a)  researching, mostly by reasoning, into the general causes, principles and meanings of the world, human actions, experience and existence, and interpreting and developing philosophical concepts and theories;\n(b)  consulting and comparing primary sources, such as original or contemporary records of past events, and secondary sources such as archaeological or anthropological findings;\n(c)  extracting relevant material, checking its authenticity, and researching into and describing the history of a particular period, country or region, or a particular facet - for example economic, social or political - of its history;\n(d)  conducting research in such fields as political philosophy, or past and present theory and practice of political systems, institutions or behaviour;\n(e)  observing contemporary political institutions and opinions, collecting data on them from various sources, including interviews with government and political party officials and other relevant persons;\n(f)  developing theories, models and methods to interpret and describe the nature of human experience and historical and political events and behaviour;\n(g)  presenting findings and conclusions for publication or use by government, political parties or other organizations and interested persons;\n(h)  preparing scholarly papers and reports.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Political adviser - 2422",
        notes: null,
        occupational_titles: ['Futurologist', 'Genealogist', 'Historian', 'Philosopher', 'Researcher, peace', 'Researcher, political', 'Scientist, political'],
        parent: '263',
        ancestors: ['2', '26', '263'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2633 = '2633';

    #[Isco08Info(
        level: 4,
        code: '2634',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: '2634',
        title: 'Psychologists',
        definition: 'Psychologists research into and study the mental processes and behaviour of human beings as individuals or in groups, and apply this knowledge to promote personal, social, educational or occupational adjustment and development.',
        tasks_include: "Tasks include -\n(a)  planning and carrying out tests to measure mental, physical and other characteristics such as intelligence, abilities, aptitudes, potentialities, etc., interpreting and evaluating results, and providing advice;\n(b)  analysing the effect of heredity, social, occupational and other factors on individual thought and behaviour;\n(c)  conducting counselling or therapeutic interviews with individuals and groups, and providing follow-up services;\n(d)  maintaining required contacts, such as those with family members, educational authorities or employers, and recommending possible solutions to, and treatment of, problems;\n(e)  studying psychological factors in the diagnosis, treatment and prevention of mental illnesses and emotional or personality disorders, and conferring with related professionals;\n(f)  preparing scholarly papers and reports;\n(g)  formulating achievement, diagnostic and predictive tests for use by teachers in planning methods and content of instruction;\n(h)  conducting surveys and research studies on job design, work groups, morale, motivation, supervision and management;\n(e)  developing theories, models and methods to interpret and describe human behaviour.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Psychiatrist - 2212",
        notes: null,
        occupational_titles: ['Analyst, psychological', 'Psychoanalyst', 'Psychologist', 'Psychologist, clinical', 'Psychologist, educational', 'Psychologist, organizational', 'Psychologist, sports', 'Psychometrist', 'Psychotherapist', 'Therapist, psychological'],
        parent: '263',
        ancestors: ['2', '26', '263'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2634 = '2634';

    #[Isco08Info(
        level: 4,
        code: '2635',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: '2635',
        title: 'Social Work and Counselling Professionals',
        definition: 'Social work and counselling professionals provide advice and guidance to individuals, families, groups, communities and organizations in response to social and personal difficulties.  They assist clients to develop skills and access resources and support services needed to respond to issues arising from unemployment, poverty, disability, addiction, criminal and delinquent behaviour, and marital and other problems.',
        tasks_include: "Tasks include -\n(a)  interviewing clients individually, in families, or in groups, to assess their situation and problems and determine the types of services required;\n(b)  analysing the client's situation and presenting alternative approaches to resolving problems;\n(c)  compiling case records or reports for courts and other legal proceedings;\n(d)  providing counselling, therapy and mediation services and facilitating group sessions to assist clients to develop skills and insights needed to deal with and resolve their social and personal problems;\n(e)  planning and implementing programmes of assistance for clients including crisis intervention and referral to agencies that provide financial assistance, legal aid, housing, medical treatment and other services;\n(f)  investigating cases of abuse or neglect and taking action to protect children and other at risk persons;\n(g)  working with offenders during and after sentence, to help them to integrate into the community and to change attitudes and behaviour in order to reduce further offending;\n(h)  providing advice to prison governors and to probation and parole review boards that helps determine whether, and under what conditions, an offender should be incarcerated, released from prison or undergo alternative correctional measures;\n(i)  acting as advocates for client groups in the community and lobbying for solutions to problems affecting them;\n(j)  developing prevention and intervention programmes to meet community needs;\n(k)  maintaining contact with other social service agencies, educational institutions and health care providers involved with clients to provide information and obtain feedback on clients' overall situation and progress.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Psychologist - 2634\n- Welfare support worker - 3412",
        notes: null,
        occupational_titles: ['Almoner, professional', 'Caseworker, professional', 'Counsellor, addictions', 'Counsellor, bereavement', 'Counsellor, child and youth', 'Counsellor, family', 'Counsellor, marriage', 'Counsellor, sexual assault', 'Housefather, professional', 'Housemaster, professional: approved school', 'Housemistress, professional: approved school', 'Housemother, professional', 'Officer, district: social welfare', 'Officer, parole', 'Officer, probation', "Organizer, women's welfare", 'Professional, counselling', 'Psychoeducator', 'Therapist, family', 'Therapist, marriage', 'Therapist, relationship', 'Therapist, sex', 'Warden, community centre: professional', 'Warden, probation home: professional', 'Worker, delinquency: professional', 'Worker, social', 'Worker, social: probation', 'Worker, welfare: professional'],
        parent: '263',
        ancestors: ['2', '26', '263'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2635 = '2635';

    #[Isco08Info(
        level: 4,
        code: '2636',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '263',
        unit_group: '2636',
        title: 'Religious Professionals',
        definition: 'Religious professionals function as perpetuators of sacred traditions, practices and beliefs.  They conduct religious services, celebrate or administer the rites of a religious faith or denomination, provide spiritual and moral guidance and perform other functions associated with the practice of a religion.',
        tasks_include: "Tasks include -\n(a)  perpetuating sacred traditions, practices and beliefs;\n(b)  conducting religious services, rites and ceremonies;\n(c)  undertaking various administrative and social duties, including participating in committees and meetings of religious organizations;\n(d)  providing spiritual and moral guidance in accordance with the religion professed;\n(e)  propagating religious doctrines in own country or abroad;\n(f)  preparing and presenting religious sermons;\n(g)  developing and directing study courses and religious education programmes;\n(h)  counselling individuals regarding interpersonal, health, financial, and religious problems;\n(i)  scheduling and participating in special events such as camps, conferences, seminars, and retreats.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Lay preacher - 3413\n- Monk - 3413\n- Nun - 3413",
        notes: 'Members of religious orders whose work involves performing the tasks of other occupations, for example as teachers, nurses or welfare support workers, should be classified according to the main tasks and duties performed in the job.',
