    #[Isco08Info(
        level: 4,
        code: '2641',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '264',
        unit_group: '2641',
        title: 'Authors and Related Writers',
        definition: 'Authors and related writers plan, research and write books, scripts, storyboards, plays, essays, speeches, manuals, specifications and other non-journalistic articles (excluding material for newspapers, magazines and other periodicals) for publication or presentation.',
        tasks_include: "Tasks include -\n(a)  conceiving, writing and editing novels, plays, scripts, poetry and other material for publication or presentation;\n(b)  conducting research to establish factual content and to obtain other necessary information;\n(c)  writing scripts and continuities and preparing programmes for stage, film, radio and television productions;\n(d)  analysing material, such as specifications, notes and drawings, and creating manuals, instructions for use, user guides and other documents to explain clearly and concisely the installation, operation and maintenance of software, electronic, mechanical and other equipment;\n(e)  writing brochures, handbooks and similar technical publications;\n(f)  selecting material for publication, checking style, grammar and accuracy of content, arranging for any necessary revisions and checks proof copies before printing.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Advertising copy writer - 2431\n- Public relations copy writer - 2432\n- Journalist - 2642\n- Newspaper editor- 2642",
        notes: null,
