    #[Isco08Info(
        level: 4,
        code: '2642',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '264',
        unit_group: '2642',
        title: 'Journalists',
        definition: 'Journalists research, investigate, interpret and communicate news and public affairs through newspapers, television, radio and other media.',
        tasks_include: "Tasks include -\n(a)  collecting local, national and international news through interviews, investigation and observation, attending public events, seeking out records, reviewing written work, attending film and stage performances;\n(b)  collecting, reporting and commenting on news and current affairs for publication in newspapers and periodicals, or for broadcasting by radio, television or webcast media;\n(c)  receiving, analysing and verifying news and other copy for accuracy; \n(d)  interviewing politicians and other public figures at press conferences and on other occasions, including individual interviews recorded for radio, television or webcast media;\n(e)  researching and reporting on developments in specialized fields such as medicine, science and technology;\n(f)  writing editorials and commentaries on topics of current interest to stimulate public interest and express the views of a publication or broadcasting station;\n(g)  writing critical reviews of literary, musical and other artistic works based on knowledge, judgement and experience for newspapers, television, radio and other media;\n(h)  selecting material for publication, checking style, grammar, accuracy and legality of content and arranging for any necessary revisions;\n(i)  liaising with production staff in checking final proof copies immediately prior to printing;\n(j)  selecting, assembling and preparing publicity material about business or other organizations for issue through press, radio, television and other media.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Public relations officer- 2432\n- Author - 2641\n- Book editor – 2641\n- Photo journalist - 3431\n- Camera operator – 3521",
        notes: null,
        occupational_titles: ['Blogger', 'Columnist', 'Commentator, extempore', 'Commentator, news', 'Commentator, sports', 'Copywriter, news media', 'Correspondent, media', 'Critic', 'Critic, art', 'Editor, city', 'Editor, copy', 'Editor, fashion', 'Editor, features', 'Editor, financial', 'Editor, foreign', 'Editor, newspapers', 'Editor, periodicals', 'Editor, political', 'Editor, press', 'Editor, sports', 'Editor, sub', 'Editor-in-chief', 'Interviewer, media', 'Journalist', "Producer, news: TV\/radio", 'Reporter, crime', 'Reporter, fashion', 'Reporter, journalism', 'Reporter, media', "Reporter, news: TV\/radio", 'Reporter, newspaper', 'Reporter, sports', 'Sub-editor', 'Writer, copy: news media', 'Writer, feature', 'Writer, newspaper', 'Writer, sports'],
        parent: '264',
        ancestors: ['2', '26', '264'],
