    #[Isco08Info(
        level: 4,
        code: '2643',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '264',
        unit_group: '2643',
        title: 'Translators, Interpreters and Other Linguists',
        definition: 'Translators, interpreters and other linguists translate or interpret from one language into another and study the origin, development and structure of languages.',
        tasks_include: "Tasks include -\n(a)  studying relationships between ancient parent languages and modern language groups, tracing the origin and evolution of words, grammar and language forms, and presenting findings;\n(b)  advising on or preparing language classification systems, grammars, dictionaries and similar materials;\n(c)  translating from one language into another and ensuring that the correct meaning of the original is retained, that legal, technical or scientific works are correctly rendered, and that the phraseology and terminology of the spirit and style of literary works are conveyed as far as possible;\n(d)  developing methods for the use of computers and other instruments to improve productivity and quality of translation;\n(e)  interpreting from a spoken or a signed language into another spoken or signed language , in particular at conferences, meetings and similar occasions, and ensuring that the correct meaning and, as far as possible, the spirit of the original are transmitted;\n(f)  revising and correcting translated material.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Author - 2641\n- Book editor - 2641\n- Journalist - 2642",
        notes: null,
        occupational_titles: ['Etymologist', 'Graphologist', 'Interpreter', 'Interpreter, sign language', 'Lexicographer', 'Linguist', 'Morphologist', 'Philologist', 'Phonologist', 'Semasiologist', 'Subtitler', 'Translator', 'Translator-reviser', 'Writer, dictionary'],
        parent: '264',
        ancestors: ['2', '26', '264'],
        children: [],
        descendants: [],
    )]
    case ISCO08_2643 = '2643';

    #[Isco08Info(
        level: 4,
        code: '2651',
        major_group: '2',
        sub_major_group: '26',
        minor_group: '265',
        unit_group: '2651',
        title: 'Visual Artists',
        definition: 'Visual artists create and execute works of art by sculpting, painting, drawing, creating cartoons, engraving or using other techniques.',
        tasks_include: "Tasks include -\n(a)  conceiving and developing ideas, designs and styles for paintings, drawings and sculptures;\n(b)  arranging objects, positioning models, and selecting landscapes and other visual forms according to chosen subject matter;\n(c)  selecting artistic media, method and materials;\n(d)  creating representational or abstract three-dimensional or relief forms by shaping, carving and working and combining materials such as, wood, stone, clay, metal, ice or paper;\n(e)  creating representational or abstract drawings and paintings using pencils, ink, chalk, oil paints, water colours or through the application of other techniques;\n(f)  creating drawings and engraving or etching them on metal, wood, or other materials;\n(g)  creating cartoons to depict persons and events, often in caricature;\n(h)  restoring damaged, soiled and faded paintings and other art objects.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Industrial designer – 2163\n- Graphic designer - 2166\n- Painting teacher (private tuition) – 2355\n- Potter - 7314\n- Decorative painter - 7316",
        notes: null,
        occupational_titles: ['Artist, ceramic', 'Artist, graphic', 'Artist, landscape', 'Artist, paintings', 'Artist, poster', 'Artist-painter', 'Caricaturist', 'Cartoonist', 'Engraver-etcher, artistic', 'Modeller, sculpture', 'Painter, artistic', 'Painter, miniatures', 'Painter, portrait', 'Restorer, picture', 'Sculptor'],
