    #[Isco08Info(
        level: 4,
        code: '3111',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3111',
        title: 'Chemical and Physical Science Technicians',
        definition: 'Chemical and physical science technicians perform technical tasks to aid in research in chemistry, physics, geology, geophysics, meteorology and astronomy, and in the development of industrial, medical, military and other practical applications of research results.',
        tasks_include: "Tasks include -\n(a)  collecting samples and preparing materials and equipment for experiments, tests and analyses;\n(b)  carrying out routine laboratory tests and performing a variety of technical support functions to assist chemical and physical scientists in research, development, analysis and testing;\n(c)  controlling the quality and quantity of laboratory supplies by testing samples and monitoring usage and preparing detailed estimates of quantities and costs of materials and labour required for projects, according to the specifications given; \n(d)  setting up, operating, and maintaining laboratory instruments and equipment, monitoring experiments, making observations, and calculating and recording results; \n(e)  preparing materials for experimentation such as freezing and slicing specimens and mixing chemicals; \n(f)  collecting and testing earth and water samples, recording observations and analysing data in support of geologists or geophysicists.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Chemical engineering technician - 3116\n- Chemical process technician - 3133\n- Life science technician - 3141",
        notes: null,
        occupational_titles: ['Technician, astronomy', 'Technician, chemistry', 'Technician, geology', 'Technician, geophysics', 'Technician, meteorology', 'Technician, oceanography', 'Technician, physics'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3111 = '3111';

    #[Isco08Info(
        level: 4,
        code: '3112',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3112',
        title: 'Civil Engineering Technicians',
        definition: 'Civil engineering technicians perform technical tasks in civil engineering research and in the design, construction, operation, maintenance and repair of buildings and other structures such as water supply and wastewater treatment systems, bridges, roads, dams and airports.',
        tasks_include: "Tasks include -\n(a)  performing or assisting with field and laboratory tests of soils and construction materials;\n(b)  providing technical assistance connected with the construction of buildings and other structures, and with surveys or the preparation of survey reports;\n(c)  ensuring compliance with design specifications, relevant legislation and regulations, and maintenance of desired standards of materials and work;\n(d)  applying technical knowledge of building and civil engineering principles and practices in order to identify and solve problems arising;\n(e)  assisting with the preparation of detailed estimates of quantities and costs of materials and labour required for projects, according to the specifications given;\n(f)  organizing maintenance and repairs;\n(g)  inspecting buildings and structures during and after construction to ensure that they comply with building, grading, zoning and safety laws and approved plans, specifications and standards, as well as with other rules concerning quality and safety of buildings; (h)  inspecting industrial plant, hotels, cinemas and other buildings and structures to detect fire hazards and advise on how they can be removed; (i)  advising on the installation of fire detectors and sprinkler systems and the use of materials in the construction of buildings, and means of transportation to reduce risk of fire and extent of damage and danger if fire occurs.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Quantity Surveyor - 2149\n- Marine Surveyor - 3115\n- Fire investigator - 3119",
        notes: null,
        occupational_titles: ['Clerk of works', 'Consultant, fire prevention', 'Estimator, engineering: civil', 'Inspector, building', 'Inspector, fire', 'Specialist, fire prevention', 'Surveyor, building', 'Technician, engineering: civil', 'Technician, engineering: construction', 'Technician, geotechnical', 'Technician, surveying'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3112 = '3112';

    #[Isco08Info(
        level: 4,
        code: '3113',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3113',
        title: 'Electrical Engineering Technicians',
        definition: 'Electrical engineering technicians perform technical tasks to aid in electrical engineering research and in the design, manufacture, assembly, construction, operation, maintenance and repair of electrical equipment, facilities and distribution systems.',
        tasks_include: "Tasks include -\n(a)  providing technical assistance in research on and development of electrical equipment and facilities, or testing prototypes;\n(b)  designing and preparing blueprints of electrical installations and circuitry according to the specifications given;\n(c)  preparing detailed estimates of quantities and costs of materials and labour required for manufacture and installation, according to the specifications given;\n(d)  monitoring technical aspects of the manufacture, installation, utilization, maintenance and repair of electrical systems and equipment to ensure satisfactory performance and compliance with specifications and regulations;\n(e)  planning installation methods, checking completed installation for safety and controls or undertaking the initial running of the new electrical equipment or systems;\n(f)  assembling, installing, testing, calibrating, modifying and repairing electrical equipment and installations to conform with regulations and safety requirements.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Electronics engineering technician -3114\n- Power production plant operator – 3131\n- Electrical mechanic - 7412",
        notes: null,
        occupational_titles: ['Estimator, engineering: electrical', 'Inspector, quality: electrical (products)', 'Inspector, safety and health: electricity', 'Technician, engineering: electrical', 'Technician, engineering: electric illumination', 'Technician, engineering: electric power transmission'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3113 = '3113';

    #[Isco08Info(
        level: 4,
        code: '3114',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3114',
        title: 'Electronics Engineering Technicians',
        definition: 'Electronics engineering technicians perform technical tasks to aid in electronic research and in the design, manufacture, assembly, construction, operation, maintenance and repair of electronic equipment.',
        tasks_include: "Tasks include -\n(a)  providing technical assistance in research and development of electronic equipment, or testing prototypes;\n(b)  designing and preparing blueprints of electronic circuitry according to the specifications given; \n(c)  preparing detailed estimates of quantities and costs of materials and labour required for the manufacture and installation of electronic equipment, according to the specifications given;\n(d)  monitoring technical aspects of the manufacture, utilization, maintenance and repair of electronic equipment to ensure satisfactory performance and ensure compliance with specifications and regulations; \n(e)  assisting in the design, development, installation, operation and maintenance of electronic systems;\n(f)  planning installation methods, checking completed installation for safety and controls or undertaking the initial running of the new electronic equipment or system;\n(g)  conducting tests of electronic systems, collecting and analysing data, and assembling circuitry in support of electronics engineers.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Electrical engineering technician - 3113\n- Telecommunications engineering technician – 3522\n- Electronics mechanic – 7421\n- Electronic equipment assembler - 8212",
        notes: null,
        occupational_titles: ['Assistant, computer: engineering (hardware)', 'Estimator, engineering: electronics', 'Inspector, quality: electronic products', 'Technician, engineering: computer hardware design', 'Technician, engineering: electronics', 'Technician, engineering: instrumentation', 'Technician, engineering: semiconductors'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3114 = '3114';

    #[Isco08Info(
        level: 4,
        code: '3115',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3115',
        title: 'Mechanical Engineering Technicians',
        definition: 'Mechanical engineering technicians perform technical tasks to aid in mechanical engineering research, and in the design, manufacture, assembly, construction, operation, maintenance and repair of machines, components and mechanical equipment.',
        tasks_include: "Tasks include -\n(a)  providing technical assistance in research on and development of machines and mechanical installations, facilities and components, or testing prototypes;\n(b)  designing and preparing layouts of machines and mechanical installations, facilities and components according to the specifications given; \n(c)  preparing detailed estimates of quantities and costs of materials and labour required for manufacture and installation according to the specifications given; \n(d)  monitoring technical aspects of manufacture, utilization, maintenance and repair of machines and mechanical installations, facilities and components to ensure satisfactory performance and compliance with specifications and regulations;\n(e)  developing and monitoring the implementation of safety standards and procedures for marine survey work in relation to ships' hulls, equipment and cargoes; \n(f)  assembling and installing new and modified mechanical assemblies, components, machine tools and controls, and hydraulic power systems;\n(g)  conducting tests of mechanical systems, collecting and analysing data and assembling and installing mechanical assemblies in support of mechanical engineers;\n(h)  ensuring that mechanical engineering designs and finished work are within specifications, regulations and contract provisions.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Industrial machinery mechanic - 7233\n- Mechanical machinery assembler - 8211",
        notes: null,
        occupational_titles: ['Dockmaster, dry: dock', 'Dockmaster, graving: dock', 'Estimator, engineering: mechanical', 'Inspector, quality: mechanical products', 'Inspector, safety and health: vehicles', 'Inspector, vehicle', 'Surveyor, marine', 'Technician, engineering: aeronautics', 'Technician, engineering: agricultural (machinery)', 'Technician, engineering: air-conditioning', 'Technician, engineering: automotive', 'Technician, engineering: diesel (engines)', 'Technician, engineering: gas (turbines)', 'Technician, engineering: heating', 'Technician, engineering: industrial (machinery and tools)', 'Technician, engineering: internal combustion', 'Technician, engineering: jet engine', 'Technician, engineering: locomotive (engines)', 'Technician, engineering: lubrication', 'Technician, engineering: marine', 'Technician, engineering: mechanical', 'Technician, engineering: mechatronics', 'Technician, engineering: motor', 'Technician, engineering: naval', 'Technician, engineering: nuclear power', 'Technician, engineering: refrigeration', 'Technician, engineering: ship (construction)', 'Technician, mechatronics: engineering'],
