    #[Isco08Info(
        level: 4,
        code: '3117',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3117',
        title: 'Mining and metallurgical technicians',
        definition: 'Mining and metallurgical technicians perform technical tasks to assist in research and experiments related to metallurgy, in improving methods of extracting solid minerals, oil and gas, and in the design, construction, operation, maintenance and repair of mines and mine installations, of systems for transporting and storing oil and natural gas, and for extraction of metals from ores.',
        tasks_include: "Tasks include -\n(a)  providing technical assistance to aid in research on and development of processes to determine the properties of metals and new alloys;\n(b)  providing technical assistance in geological and topographical surveys, and in the design and layout of oil, natural gas and mineral ore extraction and transportation systems, and processing and refining plants for minerals and metals;\n(c)  preparing detailed estimates of quantities and costs of materials and labour required for mineral, oil and natural gas exploration, extraction, processing and transport projects;\n(d)  monitoring technical, regulatory and safety aspects of the construction, installation, operation, maintenance and repair of mineral ore, oil and natural gas exploration, extraction, transport and storage installations and of mineral processing plants;\n(e)  helping plan and design mines, mine shafts, tunnels and underground first-aid facilities;\n(f)  collecting and preparing rock, mineral and metal samples, performing laboratory tests to determine properties, analysing and reporting test results and maintaining testing equipment;\n(g)  using microscopes, electromagnetic irradiation machines, spectrometers, spectrographs, densitometers and tension testing machines;\n(h)   assisting scientists in the use of electrical, sonic or nuclear measuring instruments in both laboratory and production activities to obtain data indicating potential sources of metallic ore, gas, or petroleum.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Geology technician - 3111\n- Miner - 8111\n- Mining plant operator - 8111\n- Quarrier - 8111",
        notes: null,
        occupational_titles: ['Acidiser, oil and gas well', 'Cementer, oil and gas well', 'Inspector, mine', 'Inspector, safety: mines', 'Sampler, coal', 'Sampler, mine', 'Sampler, ore', 'Sampler, quarry', 'Sampler, underground', 'Shooter, oil and gas wells', 'Technician, engineering: mining', 'Technician, engineering: petroleum and natural gas extraction', 'Technician, metallurgical', 'Technician, metallurgy', 'Tester, hardness', 'Treater, well acidising'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3117 = '3117';

    #[Isco08Info(
        level: 4,
        code: '3118',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3118',
        title: 'Draughtspersons',
        definition: "Draughtspersons prepare technical drawings, maps and illustrations from sketches, measurements \tand other data, and copy final drawings and paintings onto printing plates.",
        tasks_include: "Tasks include -\n(a)  preparing and revising working drawings from sketches and specifications prepared by engineers and designers for the manufacture, installation and erection of machinery and equipment or for the construction, modification, maintenance and repair of buildings, dams, bridges, roads and other architectural and civil engineering projects;\n(b)  operating computer-aided design and drafting equipment to create, modify and generate hard-copy and digital representations of working drawings;\n(c)  operating digitizing table or similar equipment to transfer hard-copy representation of working drawings, maps and other curves to digital form;\n(d)  preparing and revising illustrations for reference works, brochures and technical manuals dealing with the assembly, installation, operation, maintenance and repair of machinery and other equipment and goods;\n(e)  copying drawings and paintings onto stone or metal plates for printing;\n(f)  preparing wiring diagrams, circuit board assembly diagrams and layout drawings used for manufacture, installation and repair of electrical equipment in factories, power plants, and buildings;\n(g)  creating detailed working diagrams of machinery and mechanical devices, including dimensions, fastening methods and other engineering information;\n(h)  arranging for completed drawings to be reproduced for use as working drawings.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Cartographer - 2165\n- Surveyor -  2165",
        notes: null,
        occupational_titles: ['Draughtsperson', 'Draughtsperson, aeronautical', 'Draughtsperson, architectural', 'Draughtsperson, CAD', 'Draughtsperson, cartographical', 'Draughtsperson, civil', 'Draughtsperson, die', 'Draughtsperson, electrical', 'Draughtsperson, electronics', 'Draughtsperson, engineering', 'Draughtsperson, geological', 'Draughtsperson, heating and ventilation systems', 'Draughtsperson, jig and tool', 'Draughtsperson, lithographic', 'Draughtsperson, marine', 'Draughtsperson, mechanical', 'Draughtsperson, structural', 'Draughtsperson, technical', 'Draughtsperson, topographical', 'Illustrator, engineering', 'Illustrator, technical'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3118 = '3118';

    #[Isco08Info(
        level: 4,
        code: '3119',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '311',
        unit_group: '3119',
        title: 'Physical and Engineering Science Technicians Not Elsewhere Classified',
        definition: 'This unit group covers physical and engineering science technicians not classified elsewhere in Minor Group 311: Physical and Engineering Science Technicians. For instance, the unit group includes those who assist scientists and engineers engaged in developing procedures or conducting research on safety, biomedical, environmental or industrial and production engineering.',
        tasks_include: "In such cases tasks would include -\n(a)  collecting data and providing technical assistance regarding: efficient, safe and economic utilization of personnel, material and equipment; methods of work and sequence of operations and supervision of their implementation; and efficient layout of plant or establishment;\n(b)  aiding in the identification of potential hazards and introducing safety procedures and devices;\n(c)  modifying and testing equipment and devices used in the prevention, control, and remediation of environmental pollution, site remediation and land reclamation; \n(d)  assisting in the development of environmental pollution remediation devices under the direction of an engineer;\n(e)  assisting engineers in testing and designing robotics equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Production engineer - 2141\n- Quantity surveyor - 2149\n- Aeronautics engineering technician - 3115",
        notes: null,
        occupational_titles: ['Investigator, fire', 'Technician, engineering: industrial efficiency', 'Technician, engineering: industrial layout', 'Technician, engineering: methods', 'Technician, engineering: planning', 'Technician, engineering: production', 'Technician, engineering: safety', 'Technician, engineering: systems (except computers)', 'Technician, engineering: time and motion study', 'Technician, engineering: value', 'Technician, engineering: work study', 'Technician, forensic science', 'Technician, quantity: surveying', 'Technician, robotics', 'Technician, time and motion study', 'Technician, work study'],
        parent: '311',
        ancestors: ['3', '31', '311'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3119 = '3119';

    #[Isco08Info(
        level: 4,
        code: '3121',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '312',
        unit_group: '3121',
        title: 'Mining Supervisors',
        definition: 'Mining supervisors oversee mining and quarrying operations and directly supervise and coordinate the activities of miners working in underground and surface mines and quarries.',
        tasks_include: "Tasks include -\n(a)  supervising and coordinating the activities of workers who extract minerals and other natural deposits from the earth, and who operate underground conveyances or heavy equipment in surface mines and quarries;\n(b)  establishing methods to meet work schedules and recommending measures to mining managers to improve productivity;\n(c)  working with managerial and technical personnel, other departments and contractors to resolve operational problems and coordinate activities;\n(d)  providing reports and other information to mining managers about all aspects of mining or quarrying operations;\n(e)  determining staffing and material needs for the mine or quarry.",
        excluded_occupations: "Some related occupations classified elsewhere:\n-  Mine manager - 1322\n-  Mine  inspector - 3117\n-  Miner - 8111\n-  Quarrier - 8111",
        notes: null,
        occupational_titles: ['Boss, shift: mining', 'Coordinator, production: mining', 'Coordinator, shift: mining', 'Deputy, mine', 'Examiner, open cut: mining', 'Manager, under: mine', 'Officer, mining technical', 'Officer, technical: mining', 'Overman, mine', 'Overseer, mine', 'Overwoman, mine', 'Supervisor, mine', 'Supervisor, mining', 'Supervisor, production: mining', 'Supervisor, quarry', 'Supervisor, shift: mining', 'Supervisor, underground: mine', 'Under-manager, mine'],
        parent: '312',
