    #[Isco08Info(
        level: 4,
        code: '3131',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '313',
        unit_group: '3131',
        title: 'Power Production Plant Operators',
        definition: 'Power production plant operators operate, monitor and maintain switchboards and related equipment in electrical control centres which control the production and distribution of electrical or other power in transmission networks. The equipment operated includes reactors, turbines, generators and other auxiliary equipment in electrical power generating stations.',
        tasks_include: "Tasks include -\n(a)  operating, monitoring and inspecting various types of energy generating power plants; \n(b)  operating and controlling power generating systems and equipment including boilers, turbines, generators, condensers, and reactors in hydro, thermal, coal, oil, natural gas, and nuclear power plants to generate and distribute electrical power;\n(c)  controlling start-up and shut-down of power plant equipment, controlling switching operations, regulating water levels and communicating with systems operators to regulate and coordinate transmission loads, frequency and line voltages;\n(d)  taking readings from charts, meters and gauges at established intervals, troubleshooting and performing corrective action as necessary; \n(e)  completing and maintaining station records, logs and reports, and communicating with other plant personnel to assess equipment operating status;\n(f)  cleaning and maintaining equipment such as generators, boilers, turbines, pumps, and compressors in order to prevent equipment failure or deterioration.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Steam engine and boiler operators - 8182",
        notes: null,
        occupational_titles: ['Dispatcher, load: electrical (power station)', 'Operator, control-panel: nuclear reactor', 'Operator, control-panel: power (production)', 'Operator, distribution control', 'Operator, electric power plant', 'Operator, gas plant: electric power generation', 'Operator, generating station', 'Operator, generator: electric power', 'Operator, geo-thermal power plant', 'Operator, hydroelectric power plant', 'Operator, natural gas plant: electric power generating', 'Operator, nuclear power plant', 'Operator, power system', 'Operator, reactor: nuclear-power', 'Operator, rectifier: electric current', 'Operator, solar power plant', 'Operator, steam power plant', 'Operator, switchboard: electrical power station', 'Operator, switchboard: power station generator', 'Operator, tidal power plant', 'Operator, turbine: electricity generation', 'Operator, turbine: power station', 'Operator, wind-energy plant: electric power generation'],
        parent: '313',
        ancestors: ['3', '31', '313'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3131 = '3131';

    #[Isco08Info(
        level: 4,
        code: '3132',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '313',
        unit_group: '3132',
        title: 'Incinerator and Water Treatment Plant Operators',
        definition: 'Incinerator and water treatment plant operators monitor and operate computerized control systems and related equipment in solid and liquid waste treatment plants to regulate the treatment and disposal of sewage and wastes, and in water filtration and treatment plants to regulate the treatment and distribution of water.',
        tasks_include: "Tasks include -\n(a)  operating and monitoring computerized control systems, machinery and related equipment in wastewater treatment, sewage treatment, and liquid waste plants to regulate flow, treatment and disposal of sewage and wastes, and in water filtration and treatment plants to regulate the treatment and distribution of water for human consumption and for later disposal into natural water systems;\n(b) controlling the operation of multiple-hearth incinerator furnaces and related equipment to burn sludge and solid waste in waste treatment plants;\n(c)  inspecting equipment and monitoring operating conditions, meters, filters, chlorinators and gauges in central control room to determine load requirements, to verify that flows, pressures and temperatures are within specification, and to detect malfunctions;\n(d)  monitoring and adjusting controls of auxiliary equipment, such as exhaust emissions, scrubbers and incinerator heat recovery units;\n(e)  collecting and testing water and sewage samples for chemical and bacterial content, using test equipment and colour analysis standards;\n(f)  analysing test results to make adjustments to plant equipment and systems to disinfect and deodorize water and other liquids;\n(g)  performing security and safety checks in plant and on grounds;\n(h)  completing and maintaining plant logs and reports.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Operator, control-panel: incinerator', 'Operator, control-panel: water treatment', 'Operator, desilting basin', 'Operator, filter: water', 'Operator, furnace: refuse disposal', 'Operator, incinerator: refuse disposal', 'Operator, liquid waste process', 'Operator, pumping-station', 'Operator, pumping-station: water and sewerage', 'Operator, purification plant: water', 'Operator, refrigeration system', 'Operator, reservoir: water', 'Operator, sewage plant', 'Operator, treater: water', 'Operator, wastewater', 'Operator, water purification plant', 'Operator, water treatment plant', 'Tender, water dam'],
        parent: '313',
        ancestors: ['3', '31', '313'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3132 = '3132';

    #[Isco08Info(
