    #[Isco08Info(
        level: 4,
        code: '3135',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '313',
        unit_group: '3135',
        title: 'Metal Production Process Controllers',
        definition: 'Metal production process controllers operate and monitor multi-function process control machinery and equipment to control the processing of metal converting and refining furnaces, metal-rolling mills, metal heat-treating or metal-extrusion plant.',
        tasks_include: "Tasks include -\n(a)  coordinating and monitoring the operation of a particular aspect of metal processing production through control panels, computer terminals or other control systems, usually from a central control room;\n(b)  operating multi-function central process control machinery to grind, separate, filter, melt, roast, treat, refine or otherwise process metals;\n(c)  observing computer printouts, video monitors and gauges to verify specified processing conditions and to make necessary adjustments; \n(d)  coordinating and supervising production crew such as machine and process operators, assistants and helpers;\n(e)  starting up and shutting down the production system in cases of emergency or as required by schedule;\n(f)  providing and organising training for members of production crew;\n(g)  maintaining shift log of production and other data and preparing production and other reports.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ladle pourer - 8121\n- Steel roller - 8121\n- Metal finishing machine operator - 8122",
        notes: null,
        occupational_titles: ['Caster, central control', 'Operator, control-panel: blast furnace', 'Operator, control-panel: metal production', 'Operator, control-panel: smelting', 'Operator, control: rolling mill', 'Operator, furnace: blast', 'Operator, furnace: converting (non-ferrous metal)', 'Operator, furnace: converting (steel)', 'Operator, furnace: melting (metal)', 'Operator, furnace: metal smelting (blast furnace)', 'Operator, furnace: refining (non-ferrous metal)', 'Operator, furnace: refining (steel)', 'Operator, furnace: smelting (metal)', 'Operator, furnace: steel refining (electric-arc furnace)', 'Operator, furnace: steel refining (open-hearth furnace)', 'Operator, pot: aluminium', 'Operator, potline: aluminium', 'Operator, pot room: aluminium', 'Operator, smelter'],
