    #[Isco08Info(
        level: 4,
        code: '3141',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '314',
        unit_group: '3141',
        title: 'Life Science Technicians (excluding Medical)',
        definition: 'Life science technicians (excluding medical) provide technical support to life science professionals undertaking research, analysis and testing of living organisms, and development and application of products and processes resulting from research in areas such as natural resource management, environmental protection, plant and animal biology, microbiology, and cell and molecular biology.',
        tasks_include: "Tasks include -\n(a) assisting in designing, setting up and conducting experiments;\n(b) setting up, calibrating, operating and maintaining laboratory instruments and equipment;\n(c) collecting and preparing specimens and samples, chemical solutions and slides and growing cultures for use in experiments;\n(d) performing routine field and laboratory tests;\n(e) monitoring experiments to ensure adherence to correct laboratory quality control procedures and health and safety guidelines;\n(f) making observations of tests and analysing, calculating, recording and reporting test results using appropriate scientific methods;\n(g) preserving, classifying and cataloguing specimens and samples;\n(h) keeping detailed logs of worked performed;\n(i) using computers to develop models and analyse data;\n(j) using complex and high-powered equipment to perform work;\n(k) participating in the research, development and manufacture of products and processes;\n(l) ordering and stocking laboratory supplies;\n(m) maintaining relevant databases.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Forensic science technician - 3119\n- Medical laboratory technician - 3212\n- Pathology laboratory technician - 3212\n- Pharmaceutical technician - 3213",
        notes: null,
        occupational_titles: ['Technician, anatomy', 'Technician, bacteriology', 'Technician, biochemistry', 'Technician, biology', 'Technician, biophysics', 'Technician, botany', 'Technician, ecology', 'Technician, fisheries', 'Technician, genetics', 'Technician, herbarium', 'Technician, life science', 'Technician, medical science', 'Technician, pharmacology', 'Technician, physiology', 'Technician, plant breeding', 'Technician, serology', 'Technician, tissue culture', 'Technician, wildlife', 'Technician, zoology'],
        parent: '314',
        ancestors: ['3', '31', '314'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3141 = '3141';

    #[Isco08Info(
        level: 4,
        code: '3142',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '314',
        unit_group: '3142',
        title: 'Agricultural Technicians',
        definition: 'Agricultural technicians perform tests and experiments, and provide technical and scientific support to agricultural scientists, farmers and farm managers.',
        tasks_include: "Tasks include -\n(a)  preparing materials and equipment for experiments, tests and analyses;\n(b)  collecting and preparing specimens such as soils, plant or animal cells, tissues or parts or animal organs for experiments, tests and analyses;\n(c)  assisting with and performing experiments, tests and analyses applying methods and techniques such as microscopy, histochemistry, chromatography, electrophoresis and spectroscopy;\n(d)  identifying pathogenic micro-organisms and insects, parasites, fungi and weeds harmful to crops and livestock, and assisting in devising methods of control;\n(e)  analysing produce to set and maintain standards of quality;\n(f)  conducting or supervising operational programmes such as fish hatchery, greenhouse and livestock production programmes;\n(g)  analysing samples of seeds for quality, purity and germination rating;\n(h)  collecting data and estimating quantities and costs of materials and labour required for projects;\n(i)  organizing maintenance and repairs of research equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Artificial inseminator 3240\n- Veterinary technician 3240",
        notes: null,
        occupational_titles: ['Demonstrator, farm', 'Officer, technical: field crop', 'Officer, technical: horticulture', 'Officer, technical: poultry', 'Technician, agronomy', 'Technician, aquaculture', 'Technician, crop research', 'Technician, dairy', 'Technician, field crop', 'Technician, floriculture', 'Technician, horticultural', 'Technician, olericulture', 'Technician, pomology', 'Technician, poultry', 'Technician, soil science', 'Tester, herd'],
        parent: '314',
        ancestors: ['3', '31', '314'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3142 = '3142';

    #[Isco08Info(
        level: 4,
        code: '3143',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '314',
        unit_group: '3143',
        title: 'Forestry Technicians',
        definition: 'Forestry technicians perform technical and supervisory functions in support of forestry research and forest management, harvesting, resource conservation and environmental protection.',
        tasks_include: "Tasks include -\n(a)  conducting forest inventories, surveys and field measurements following accepted scientific and operational procedures;\n(b)  assisting in and performing technical functions in the preparation of forest management and harvest plans using photogrammetric and mapping techniques and computerized information systems;\n(c)  assisting in planning and supervision of construction of access routes and forest roads;\n(d)  implementing, supervising and performing technical functions in silvicultural operations involving site preparation, planting, and tending of tree crops; \n(e)  coordinating activities such as timber scaling, forest fire suppression, disease or insect control or pre-commercial thinning of forest stands;\n(f)  supervising and performing technical functions in forest harvesting operations;\n(g)  ensuring adherence to regulations and policies concerning environmental protection, resource utilization, fire safety and accident prevention;\n(h)  supervising forest tree nursery operations;\n(i)  providing technical support to forestry research programmes in areas such as tree improvement, seed orchard operations, insect and disease surveys or experimental forestry and forest engineering research;\n(j) preparing forest cultivation and cutting plans.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Technician, arboriculture', 'Technician, forestry', 'Technician, forest survey', 'Technician, silviculture', 'Technologist, forestry'],
        parent: '314',
        ancestors: ['3', '31', '314'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3143 = '3143';

    #[Isco08Info(
        level: 4,
        code: '3151',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '315',
        unit_group: '3151',
        title: "Ships' Engineers",
        definition: 'Ships’ engineers control and participate in the operation, maintenance and repair of mechanical, electrical and electronic equipment and machinery on board ship, or perform related supporting functions on shore.',
        tasks_include: "Tasks include -\n(a)  controlling and participating in the operation, maintenance and repair of mechanical, electrical and electronic equipment and machinery on board ship;\n(b)  ordering fuel and other engine-room department stores and maintaining record of operations;\n(c)  performing technical supervision of the installation, maintenance and repair of ship’s machinery and equipment to ensure compliance with specifications and regulations;\n(d)  inspecting and conducting maintenance and emergency repairs to engines, machinery and auxiliary equipment;\n(e)  standing engine room watch, monitoring and noting performance of engines, machinery and auxiliary equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Marine engineer - 2144",
        notes: null,
        occupational_titles: ['Engineer, chief: ship', "Engineer, ship's", 'Superintendent, marine: technical'],
        parent: '315',
        ancestors: ['3', '31', '315'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3151 = '3151';

    #[Isco08Info(
        level: 4,
        code: '3152',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '315',
        unit_group: '3152',
        title: "Ships' Deck Officers and Pilots",
        definition: 'Ships’ deck officers and pilots command and navigate ships and similar vessels, and perform related functions on shore.',
        tasks_include: "Tasks include -\n(a)  commanding and navigating ship or similar vessel at sea or on inland waterways;\n(b)  controlling and participating in deck and bridge-watch activities;\n(c)  navigating vessels into and out of ports and through channels, straits and other waters where special knowledge is required;\n(d)  ensuring safe loading and unloading of cargo and observance of safety regulations and procedures by crew and passengers;\n(e)  performing technical supervision of maintenance and repair of ship to ensure compliance with specifications and regulations;\n(f)  applying knowledge of principles and practices relating to ship’s operation and navigation in order to identify and solve problems arising in the course of their work;\n(g)  ordering ship’s stores and recruiting crew as required and maintaining record of operations;\n(h)  transmitting and receiving routine and emergency information with shore stations and other ships.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Coastal fishery skipper - 6222\n- Trawler skipper - 6223\n- Sailor - 8350",
        notes: null,
