    #[Isco08Info(
        level: 4,
        code: '3153',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '315',
        unit_group: '3153',
        title: 'Aircraft Pilots and Related Associate Professionals',
        definition: 'Aircraft pilots and related associate professionals control the operation of mechanical, electrical and electronic equipment, in order to navigate aircraft for transporting passengers, mail and freight, and perform related pre-flight and in-flight tasks.',
        tasks_include: "Tasks include -\n(a)  flying and navigating aircraft in accordance with established control and operating procedures;\n(b)  preparing and submitting flight plan or examining standard flight plan;\n(c)  controlling the operation of mechanical, electrical and electronic equipment and ensuring that all instruments and controls work properly;\n(d)  applying knowledge of principles and practices of flying in order to identify and solve problems arising in the course of their work;\n(e)  examining maintenance records and conducting inspections to ensure that aircraft are mechanically sound, maintenance has been performed and that all equipment is operational.;\n(f)  signing necessary certificates and maintaining official records of flight;\n(g)  obtaining briefings and clearances before flights and maintaining contact with air traffic or flight control during flight.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Astronaut', 'Captain, aircraft', 'Engineer, flight', 'Instructor, flying', 'Navigator, flight', 'Pilot, aircraft', 'Pilot, check', 'Pilot, helicopter', 'Pilot, seaplane', 'Pilot, test', 'Sprayer, crop: aerial', 'Test-pilot, aircraft'],
        parent: '315',
        ancestors: ['3', '31', '315'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3153 = '3153';

    #[Isco08Info(
        level: 4,
        code: '3154',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '315',
        unit_group: '3154',
        title: 'Air Traffic Controllers',
        definition: 'Air traffic controllers direct aircraft movements in airspace and on the ground, using radio, radar and lighting systems, and provide information relevant to the operation of aircraft.',
        tasks_include: "Tasks include -\n(a)  directing and controlling aircraft approaching and leaving airport and their movement on the ground;\n(b)  directing and controlling aircraft operating in designated airspace sector;\n(c)  examining and approving flight plans;\n(d)  informing flight crew and operations staff about weather conditions, operational facilities, flight plans and air traffic;\n(e) applying knowledge of principles and practices of air traffic control in order to identify and solve problems arising in the course of their work;\n(f)  initiating and organizing emergency, search and rescue services and procedures;\n(g)  directing activities of all aircraft and service vehicles on or near airport runways;\n(h)  maintaining radio and telephone contact with adjacent control towers, terminal control units and other control centres, and coordinating the movement of aircraft into adjoining areas.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Controller, air traffic', 'Operator, air-traffic control equipment'],
        parent: '315',
        ancestors: ['3', '31', '315'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3154 = '3154';

    #[Isco08Info(
        level: 4,
        code: '3155',
        major_group: '3',
        sub_major_group: '31',
        minor_group: '315',
        unit_group: '3155',
        title: 'Air Traffic Safety Electronics Technicians',
        definition: 'Air traffic safety electronics technicians perform technical tasks concerning the design, installation, management, operation, maintenance and repair of air traffic control and air navigation systems.',
        tasks_include: "Tasks include -\n(a)  carrying out technical duties related to the development of electronic and computerized air navigation systems and equipment, and testing prototypes; \n(b)  providing technical help in the design and layout of specific interface circuitry of air navigation and aircraft detection tracking systems; \n(c)  preparing and contributing to the preparation of cost estimates and technical and training specifications for air traffic control and safety equipment; \n(d)  providing or assisting with the technical supervision of construction, installation and operation of ground-based air navigation equipment and its maintenance and repair to ensure that standards and specifications are met; \n(e)  applying the knowledge and skills of air traffic safety engineering principles and practices in order to identify and solve problems arising in the course of their work; \n(f) developing, modifying and debugging system software;\n(g)  modifying existing ground-based air navigation systems and equipment to adapt them to new air traffic control procedures,  in order to improve capability, reliability and integrity, or to facilitate air traffic control procedures and airspace designation;\n(h)  controlling, monitoring and certifying communication navigation and surveillance air traffic management equipment and calibrating the ground-based air navigation system to ensure maximum accuracy and safety of flight, take-off and landing operations; \n(i)  providing technical training and supervising other workers.",
        excluded_occupations: "Some related occupations classified elsewhere:\n-  Aeronautical engineer - 2144\n-  Electronics engineer - 2152\n-  Aeromechanic - 7232\n-  Aircraft maintenance engineer (avionics) -7421\n-  Avionics technician - 7421",
        notes: null,
        occupational_titles: ['Engineer, air traffic safety', 'Technician, air traffic safety'],
