        ancestors: ['3', '31', '315'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3155 = '3155';

    #[Isco08Info(
        level: 4,
        code: '3211',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '321',
        unit_group: '3211',
        title: 'Medical Imaging and Therapeutic Equipment Technicians',
        definition: 'Medical imaging and therapeutic equipment technicians test and operate radiographic, ultrasound and other medical imaging equipment to produce images of body structures for the diagnosis and treatment of injury, disease and other impairments. They may administer radiation treatments to patients under the supervision of a radiologist or other health professional.',
        tasks_include: "Tasks include -\n(a)  operating or overseeing operation of radiologic, ultrasound and magnetic imaging equipment to produce images of the body for diagnostic purposes;\n(b)  explaining procedures, observing and positioning patients, and using protection devices to ensure safety and comfort during examination, scan or treatment;\n(c)  position imaging or treatment equipment, monitoring video displays, and adjusting settings and controls according to technical specifications;\n(d)  reviewing and evaluating developed x-rays, video tape or computer generated information to determine if images are satisfactory for diagnostic purposes, and recording results of procedures; \n(e)  monitoring patients' conditions and reactions, and reporting abnormal signs to a medical practitioner;\n(f)  measuring and recording radiation dosage or radiopharmaceuticals received and used for patients, following prescription issued by a medical practitioner;\n(g)  administering, detecting and mapping radiopharmaceuticals or radiation in patients' bodies, using radioisotope, camera or other equipment for diagnosing and treating diseases; \n(h)  recording and disposing of radioactive materials and storing radiopharmaceuticals, following radiation safety procedures.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Medical physicist - 2111\n- Radiologist - 2212\n- Radiation protection expert - 2263\n- Medical imaging assistant- 5329",
        notes: null,
        occupational_titles: ['Mammographer', 'Operator, audiometric equipment', 'Operator, electrocardiographic equipment', 'Operator, electroencephalographic equipment', 'Operator, medical radiography equipment', 'Operator, medical ultrasound', 'Operator, medical x-ray equipment', 'Operator, scanning equipment: medical', 'Operator, scanning equipment: optical', 'Radiographer', 'Radiographer, medical: diagnostic', 'Sonographer', 'Technician, audiometric equipment', 'Technician, electrocardiographic equipment', 'Technician, electroencephalographic equipment', 'Technician, magnetic resonance imaging', 'Technician, mammography', 'Technician, medical radiography equipment', 'Technician, medical ultrasound', 'Technician, medical x-ray equipment', 'Technician, MRI', 'Technician, nuclear medicine', 'Technician, polysomnography', 'Technician, radiation therapy', 'Technician, scanning equipment: medical', 'Technologist, cat scan', 'Technologist, computer aided tomography', 'Technologist, ct scan', 'Technologist, magnetic resonance imaging', 'Technologist, medical imaging', 'Technologist, MRI', 'Technologist, neurodiagnostic', 'Technologist, nuclear medicine', 'Technologist, polysomnography', 'Technologist, radiation therapy', 'Therapist, medical radiation', 'Therapist, nuclear medicine', 'Ultrasonographer'],
