    #[Isco08Info(
        level: 4,
        code: '3212',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '321',
        unit_group: '3212',
        title: 'Medical and Pathology Laboratory Technicians',
        definition: 'Medical and pathology laboratory technicians perform clinical tests on specimens of bodily fluids and tissues in order to obtain information about the health of a patient or cause of death.',
        tasks_include: "Tasks include -\n(a)  conducting chemical analysis of body fluids, including blood, urine and spinal fluid, to determine presence of normal and abnormal components;\n(b)  operating, calibrating and maintaining equipment used in quantitative and qualitative analysis, such as spectrophotometers, calorimeters, flame photometers and computer-controlled analysers;\n(c)  entering data from analysis of laboratory tests and clinical results into records-keeping systems and reporting results to medical practitioners and other health professionals; \n(d)  analysing samples of biological material for chemical content or reaction;\n(e)  setting up, cleaning and maintaining laboratory equipment;\n(f)  analysing laboratory findings to check the accuracy of the results;\n(g)  establishing and monitoring programmes to ensure the accuracy of laboratory results and developing, standardizing, evaluating, and modifying procedures, techniques and tests used in the analysis of specimens;\n(h)  obtaining specimens, cultivating, isolating and identifying microorganisms for analysis; \n(i)  examining cells stained with dye to locate abnormalities;\n(j)  inoculating fertilized eggs, broths or other bacteriological media with organisms.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Pathologist - 2212\n- Forensic science technician - 3119\n- Veterinary technician - 3240\n- Phlebotomist - 5329",
        notes: null,
        occupational_titles: ['Technician, blood-bank', 'Technician, cytology', 'Technician, haematology', 'Technician, histology', 'Technician, medical laboratory', 'Technician, pathology', 'Technician, pathology laboratory'],
        parent: '321',
        ancestors: ['3', '32', '321'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3212 = '3212';

    #[Isco08Info(
        level: 4,
        code: '3213',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '321',
        unit_group: '3213',
        title: 'Pharmaceutical Technicians and Assistants',
        definition: 'Pharmaceutical technicians and assistants perform a variety of tasks associated with dispensing  medicinal products under the guidance of a pharmacist or other health professional.',
        tasks_include: "Tasks include - \n(a)  preparing medications and other pharmaceutical compounds under the guidance of a pharmacist or other health professional;\n(b)  dispensing medicines and drugs to clients and giving written and oral instructions on their use, as prescribed by medical doctors, veterinarians or other health professionals;\n(c)  receiving prescriptions or refill requests from health professionals and verifying that information is complete and accurate according to medical record-keeping standards;\n(d)  maintaining proper storage and security conditions for drugs;\n(e)  filling and labelling containers with prescribed medications;\n(f)  assisting clients by answering questions, locating items or referring them to a pharmacist for medication information; \n(g)  pricing and filing prescriptions that have been filled and establish and maintaining patient records, including lists of medications taken by individual patients;\n(h)  ordering, labelling, and counting stock of medications, chemicals and supplies, and entering inventory data into records-keeping systems;\n(i)  cleaning and preparing equipment and containers used to prepare and dispense medicines and pharmaceutical compounds.",
        excluded_occupations: "Some related occupations classified elsewhere: \n- Pharmacist - 2262\n- Pharmacology technician - 3141\n- Pharmacy aide - 5329",
        notes: null,
        occupational_titles: ['Assistant, pharmaceutical', 'Assistant, pharmacy: dispensing', 'Technician, dispensing', 'Technician, pharmaceutical', 'Technician, pharmacy'],
        parent: '321',
        ancestors: ['3', '32', '321'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3213 = '3213';

    #[Isco08Info(
        level: 4,
        code: '3214',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '321',
        unit_group: '3214',
        title: 'Medical and Dental Prosthetic Technicians',
        definition: 'Medical and dental prosthetic technicians design, fit, service and repair medical and dental devices and appliances following prescriptions or instructions established by a health professional. They may service a wide range of support instruments to correct physical medical or dental problems such as neck braces, orthopaedic splints, artificial limbs, hearing aids, arch supports, dentures, and dental crowns and bridges.',
        tasks_include: "Tasks include -\n(a)  examining, interviewing, and measuring patients in order to determine their appliance needs, and to identify factors that could affect appliance fit;\n(b)  conferring with medical and dental practitioners in order to formulate specifications and prescriptions for devices and appliances;\n(c)  interpreting prescriptions or specifications to determine the type of product or device to be fabricated, and the materials and tools that will be required;\n(d)  making or receiving casts or impressions of patients' torsos, limbs, mouths or teeth for use as fabrication patterns;\n(e)  designing and making orthotic and prosthetic devices using materials such as thermoplastic and thermosetting materials, metal alloys and leather, and hand and power tools;\n(f)  fitting appliances and devices onto patients, testing and evaluating them, and making adjustments for proper fit, function and comfort; \n(g)  repairing, modifying and maintaining medical and dental prosthetic and supportive devices, according to specifications; \n(h)  bending, forming, and shaping fabric or material so that it conforms to prescribed contours needed to fabricate structural components;\n(i)  fabricating full and partial dentures and constructing mouth guards, crowns, metal clasps, inlays, bridgework and other aids;\n(j)  instructing patients in the use and care of prosthetic or orthotic devices.",
        excluded_occupations: "Some related occupations classified elsewhere: \n- Dental aide - 5329\n- Surgical instrument maker - 7311",
        notes: 'Occupations included in this category normally require some medical, dental and anatomical and engineering knowledge obtained through formal training. Technicians who construct and repair precision medical and surgical instruments are not included here.',
        occupational_titles: ['Denturist', 'Fitter, artificial limb', 'Fitter, prosthesis', 'Maker, artificial limb', 'Maker, brace: orthopaedic', 'Maker, dentures', 'Maker, orthopaedic: appliance', 'Maker, prosthesis', 'Maker, surgical: appliance', 'Mechanic, dental', 'Orthotist', 'Prosthetist', 'Prosthetist, dental', 'Repairer, orthopaedic appliance', 'Repairer, prosthesis', 'Repairer, surgical: appliance', 'Technician, dental', 'Technician, hearing aid', 'Technician, orthopaedic', 'Technician, orthotic', 'Technician, prosthetic'],
        parent: '321',
        ancestors: ['3', '32', '321'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3214 = '3214';

    #[Isco08Info(
        level: 4,
        code: '3221',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '322',
        unit_group: '3221',
        title: 'Nursing Associate Professionals',
        definition: 'Nursing associate professionals provide basic nursing and personal care for people in need of such care due to effects of ageing, illness, injury or other physical or mental impairment. They generally work under the supervision of, and in support of implementation of health care, treatment and referrals plans established by, medical, nursing and other health professionals.',
        tasks_include: "Tasks include -\n(a)  providing nursing and personal care and treatment and health advice to patients according to care plans established by health professionals; \n(b)  administering medications and other treatments to patients, monitoring patients' condition and responses to treatment, and referring patients and their families to a health professional for specialised care as needed;\n(c)  cleaning wounds and applying surgical dressings;\n(d)  updating information on patients' condition and treatments received in record-keeping systems;\n(e)  assisting in planning and managing the care of individual patients;\n(f)   assisting in giving first-aid treatment in emergencies.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Clinical nurse consultant - 2221\n- Professional nurse - 2221\n- Specialist nurse - 2221\n- Professional midwife - 2222\n- Associate professional midwife - 3222\n- Nursing aide (clinic or hospital) - 5321\n- Nursing aide (home) - 5322",
        notes: 'The distinction between professional and associate professional nurses should be made on the basis of the nature of the work performed in relation to the tasks specified in this definition. The qualifications held by individuals or that predominate in the country are not the main factor in making this distinction, as training arrangements for nurses vary widely between countries and have varied over time within countries.',
        occupational_titles: ['Nurse, assistant', 'Nurse, associate professional', 'Nurse, enrolled', 'Nurse, practical', 'Sister, nursing: associate professional'],
        parent: '322',
        ancestors: ['3', '32', '322'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3221 = '3221';

    #[Isco08Info(
        level: 4,
        code: '3222',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '322',
        unit_group: '3222',
        title: 'Midwifery Associate Professionals',
        definition: 'Midwifery associate professionals provide basic health care and advice before, during and after pregnancy and childbirth. They implement care, treatment and referral plans usually established by medical, midwifery and other health professionals.',
        tasks_include: "Tasks include -\n(a)  providing advice to women, families and communities on health, nutrition, hygiene, exercise, birth and emergency plans, breastfeeding, infant care, family planning and contraception, lifestyle and other topics related to pregnancy and childbirth;\n(b)  assessing progress during pregnancy and childbirth, and recognizing signs and symptoms requiring referral to a health professional;\n(c)  providing delivery care, usually only in the absence of identified potential complications, or assisting medical doctors or midwifery professionals with delivery care;\n(d)  providing care and support to women and newborns following childbirth, monitoring their health status, and identifying signs and symptoms requiring referral to a health professional.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Clinical nurse consultant - 2221 \n- Professional nurse - 2221\n- Specialist nurse - 2221 \n- Professional midwife - 2222\n- Birth Assistant – 5321",
        notes: "This unit group includes occupations for which competent performance requires knowledge and skills in routine and emergency midwifery care acquired through formal or informal training. The criteria for inclusion of individuals in this unit group should be based on the nature of the work performed in relation to the tasks specified in this definition, and not the qualifications held by individuals or that predominate in the country. Traditional and lay midwives, who provide basic pregnancy and birthing care and advice based primarily on experience and knowledge acquired informally through the traditions and practices of the communities where they originated, are classified here.\n\nBirth assistants, who provide emotional support and general care and advice to women and families during pregnancy and labour, are classified in Minor Group 532: Personal Care Workers in Health Services.",
        occupational_titles: ['Midwife, assistant', 'Midwife, associate professional', 'Midwife, lay', 'Midwife, traditional', 'Nurse, associate professional: maternity', 'Nurse, associate professional: obstetrics'],
        parent: '322',
        ancestors: ['3', '32', '322'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3222 = '3222';

    #[Isco08Info(
        level: 4,
        code: '3230',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '323',
        unit_group: '3230',
        title: 'Traditional and Complementary Medicine Associate Professionals',
        definition: 'Traditional and complementary medicine associate professionals prevent, care for and treat human physical and mental illnesses, disorders and injuries using herbal and other therapies based on theories, beliefs and experiences originating in specific cultures. They administer treatments using traditional techniques and medicaments, either acting independently or according to therapeutic care plans established by a traditional medicine or other health professional.',
        tasks_include: "Tasks include - \n(a)  examining patients and interviewing them and their families to determine their health status and the nature of physical or mental disorders or illnesses or other ailments;\n(b)  recommending and providing care and treatment for illnesses and other ailments using traditional techniques and medicaments, such as physical manipulation and exercises, blood-letting using natural vessels, and preparations using herbs, plants, insects and animal extracts;\n(c)  administering treatments such as acupuncture, ayurvedic, homeopathic and herbal medicine according to therapeutic care plans and procedures usually developed by a traditional medicine or other health professional;\n(d)  providing care and treatment for physical injuries such as setting and healing fractured and dislocated bones using traditional methods of physical manipulation and herbal therapies;\n(e)  advising individuals, families and the community on health, nutrition, hygiene, lifestyle and other issues to maintain or improve health and well-being;\n(f)  referring patients to, and exchanging information with, other health care providers to ensure comprehensive and continuing care.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Acupuncturist - 2230\n- Ayurvedic practitioner - 2230\n- Chinese herbal medicine practitioner - 2230\n- Homeopath - 2230\n- Naturopath – 2230\n- Chiropractor – 2269\n- Osteopath - 2269\n- Traditional midwife - 3222\n- Acupressure therapist - 3255\n- Hydrotherapist - 3255\n- Faith healer - 3413",
        notes: "Occupations in traditional and complementary medicine for which competent performance requires an extensive understanding of the benefits and applications of traditional and complementary therapies, developed as the result of extended formal study of these techniques as well as human anatomy and elements of modern medicine, are classified in Unit Group 2230: Traditional and Complementary Medicine Professionals. Those occupations whose practice requires a less extensive understanding, based on relatively short periods of formal or informal education and training, or informally through the traditions and practices of the communities where they originated, are included in Unit Group 3230: Traditional and Complementary Medicine Associate Professionals. Practitioners working in the singular application of approaches to herbal medicines, spiritual therapies or manual therapeutic techniques are excluded from Unit Group 2230.\nFaith healers who treat human ailments through spiritual therapies, without using herbal therapies or other medicaments or physical treatments, are included in Unit Group 3413: Religious Associate Professionals. \nOccupations that provide therapy using traditional forms of massage and the application of pressure, such as acupressure and shiatsu therapists are classified in Unit Group 3255: Physiotherapy Technicians and Assistants. \nTraditional and lay midwives, who provide basic pregnancy and birthing care and advice based primarily on experience and knowledge acquired informally through the traditions and practices of the communities where they originated, are classified in Unit Group 3222: Midwifery Associate Professionals.",
        occupational_titles: ['Bonesetter', 'Doctor, witch', 'Healer, drugless treatment', 'Healer, herbal', 'Healer, village', 'Herbalist', 'Reflexologist', 'Setter, bone', 'Technician, acupuncture', 'Technician, ayurvedic', 'Technician, homeopathy', 'Therapist, scraping and cupping'],
        parent: '323',
        ancestors: ['3', '32', '323'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3230 = '3230';

    #[Isco08Info(
        level: 4,
        code: '3240',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '324',
        unit_group: '3240',
        title: 'Veterinary Technicians and Assistants',
        definition: 'Veterinary technicians and assistants carry out advisory, diagnostic, preventive and curative veterinary tasks more limited in scope and complexity than those carried out by, and with the guidance of, veterinarians. They care for animals under treatment and in temporary residence at veterinary facilities, perform routine procedures and assist veterinarians to perform procedures and operations.',
        tasks_include: "Tasks include -\n(a)  advising communities and individuals on the treatment of animals and their diseases and injuries;\n(b)  conducting examinations of animals to make diagnoses or refer more difficult cases to veterinarians when needed;\n(c)  treating ill or injured animals, especially for common diseases and disorders;\n(d)  cleaning and sterilising examination tables and instruments and preparing materials used in the examination and treatment of animals;\n(e)  carrying out technical tasks connected with artificial insemination of animals;\n(f)  getting animals ready for examination or treatment and restraining or holding them during treatment;\n(g)  assisting veterinarians to administer anaesthetics and oxygen during treatment;\n(h)  placing animals in cages for recovery from operations and monitoring their condition;\n(i)  producing radiographs, collecting samples and performing other laboratory tests to assist in diagnosis of animal health problems;\n(j)  performing routine animal dental procedures and assisting veterinarians with animal dentistry.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Veterinarian - 2250\n- Animal attendant - 5164\n- Veterinary aide - 5164",
        notes: null,
        occupational_titles: ['Assistant, veterinary', 'Inseminator, artificial', 'Nurse, veterinary', 'Technician, veterinary', 'Vaccinator, veterinary'],
        parent: '324',
        ancestors: ['3', '32', '324'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3240 = '3240';

    #[Isco08Info(
        level: 4,
        code: '3251',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3251',
        title: 'Dental Assistants and Therapists',
        definition: 'Dental assistants and therapists provide basic dental care services for the prevention and treatment of diseases and disorders of the teeth and mouth, according to care plans and procedures established by a dentist or other oral health professional.',
        tasks_include: "Tasks include - \n(a)  advising communities and individuals on dental hygiene, diet and other preventive measures to reduce potential risks to oral health;\n(b)  conducting visual and physical examinations of patients' mouths, teeth and related structures to assess oral health status;\n(c)  identifying cases of patients with poor oral health or oral disease requiring referral to a dentist or other health professional\n(d)  assisting dentists during complex dental procedures\n(e)  providing fluoride treatments, cleaning and removing deposits from teeth, preparing cavities and placing fillings, administering local anaesthesia, and performing other types of basic or routine clinical dental procedures;\n(f)  preparing, cleaning and sterilizing dental instruments, equipment and materials used in the examination and treatment of patients;\n(g)  getting patients ready for examination or treatment including explaining procedures and correct positioning;\n(h)  taking impressions of the mouth and dental radiographs to support diagnosis and fitting of dental prosthetics.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Dentist - 2261\n- Dental mechanic- 3214\n- Dental prosthetist - 3214\n- Dental technician - 3214\n- Dental aide - 5329",
        notes: null,
        occupational_titles: ['Assistant, dental', 'Assistant, dental: school service', 'Auxiliary, dental', 'Hygienist, dental', 'Hygienist, oral', 'Therapist, dental'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3251 = '3251';

    #[Isco08Info(
        level: 4,
        code: '3252',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3252',
        title: 'Medical Records and Health Information Technicians',
        definition: 'Medical records and health information technicians develop, maintain and implement health records processing, storage and retrieval systems in medical facilities and other health care settings to meet the legal professional, ethical and administrative records-keeping requirements of health services delivery.',
        tasks_include: "Tasks include - \n(a)  planning, developing, maintaining and operating a variety of health record indexes and storage and retrieval systems to collect, classify, store and analyse information; \n(b)  transcribing, compiling and processing patient medical records, admission and discharge documents and other medical reports into records-keeping systems to provide data for patient monitoring and referral, epidemiological monitoring, research, billing, cost control and care improvement; \n(c)  reviewing records for completeness, accuracy and compliance with regulations; \n(d)  translating narrative descriptions and numeric information from medical records and other documents on health services delivery into codes associated with standard classification systems;\n(e)  protecting the security of medical records to ensure that confidentiality is maintained and releasing information to authorized persons and agencies in accordance with regulations; \n(f)  supervising clerical and administrative workers involved in the maintenance of medical records.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Medical secretary - 3344\n- Data entry clerk - 4132\n- Filing clerk - 4415",
        notes: "Occupations included in this unit group normally require knowledge of medical terminology, legal aspects of health information, health data standards and computer- or paper-based data management as obtained through formal education and\/or on-the-job training.",
        occupational_titles: ['Analyst, medical records', 'Clerk, coding: clinical', 'Clerk, information: health', 'Clerk, records: medical', 'Coder, clinical', 'Manager, information: health', 'Manager, records: health', 'Supervisor, medical records unit', 'Technician, disease registry', 'Technician, health information', 'Technician, medical records'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3252 = '3252';

    #[Isco08Info(
        level: 4,
        code: '3253',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3253',
        title: 'Community Health Workers',
        definition: 'Community health workers provide health education, referral and follow up, case management, basic preventive health care and home visiting services to specific communities. They provide support and assistance to individuals and families in navigating the health and social services system.',
        tasks_include: "Tasks include - \n(a)  providing information to families and communities on a range of health issues including nutrition, hygiene, infant and child care, immunizations, family planning, risk factors and prevention of common infectious diseases, poisoning prevention, first aid for treatment of simple and common ailments, substance abuse, domestic violence, and other topics;\n(b)  visiting families in their homes to provide information on the health, social and other services available and support them in gaining access to these services; \n(c)  visiting families who do not usually access medical establishments to monitor on a regular basis certain conditions, such as progress with pregnancy, child growth and development, and environmental sanitation;\n(d)  distributing to households medical supplies for the prevention and treatment of endemic diseases such as malaria, pneumonia and diarrhoeal diseases, and instructing family and community members in the use of these products;\n(e)  conducting outreach efforts to groups who do not usually access medical establishments with information and basic medical supplies for prevention and management of certain health conditions for which they are most at risk, such as HIV\/AIDS and other communicable diseases;\n(f)  collecting data from households and communities who do not usually access medical establishments for purposes of patient monitoring and referral and reporting to meet health regulations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Traditional midwife - 3222\n- Village healer - 3230\n- Home care aide - 5322",
        notes: 'Occupations included in this unit group normally require formal or informal training and supervision recognized by the health and social services authorities. Providers of routine personal care and traditional medicine practitioners are not included here.',
        occupational_titles: ['Aide, community health', 'Assistant, medical: family planning', 'Promoter, community health', 'Worker, community: health', 'Worker, village health'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3253 = '3253';

    #[Isco08Info(
        level: 4,
        code: '3254',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3254',
        title: 'Dispensing Opticians',
        definition: 'Dispensing opticians design, fit and dispense optical lenses based on a prescription from an ophthalmologist or optometrist for the correction of reduced visual acuity. They service corrective eyeglasses, contact lenses, low-vision aids and other optical devices.',
        tasks_include: "Tasks include -\n(a)  examining and taking facial and eye measurements of clients for fitting of eyeglasses and other optical devices; \n(b)  providing advice to clients with selection and maintenance of eyeglasses and frames, types of contact lenses and other optical devices for performance, safety, comfort and lifestyle; \n(c)  interpreting optical prescriptions and preparing work order for optical laboratory for grinding and mounting of lenses in frames, preparation of contact lenses and other required work; \n(d)  verifying exactness of finished optical appliances and devices to the original prescription and fit of clients.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ophthalmologist - 2212\n- Ophthalmic optician - 2267\n- Optometrist - 2267 \n- Orthoptist - 2267",
        notes: null,
        occupational_titles: ['Dispenser, optical', 'Optician, contact lens', 'Optician, dispensing'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3254 = '3254';

    #[Isco08Info(
        level: 4,
        code: '3255',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3255',
        title: 'Physiotherapy Technicians and Assistants',
        definition: 'Physiotherapy technicians and assistants provide physical therapeutic treatments to patients in circumstances where functional movement is threatened by injury, disease or impairment. Therapies are usually provided as per rehabilitative plans established by a physiotherapist or other health professional.',
        tasks_include: "Tasks include -\n(a)  administering manual treatments such as massage therapy or pressure point therapy;\n(b)  administering electrical modality treatments, ultrasound and other physical therapies using specialized techniques and equipment; \n(c)  instructing, motivating, safeguarding and assisting patients as they practice physical exercises, relaxation techniques and functional activities; \n(d)  conferring with physiotherapists or other health care providers to evaluate patient information for planning, modifying, and coordinating treatment;\n(e)  monitoring and recording patients' progress during treatments, including measuring their range-of-joint motion and vital signs; \n(f)  fitting patients for orthopaedic braces, prostheses and other physical supportive devices such as crutches, and instructing patients in the use of such devices.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Physiotherapist - 2264\n- Chiropractor - 2269\n- Occupational therapist - 2269\n- Podiatrist - 2269",
        notes: null,
        occupational_titles: ['Aide, therapist: physiotherapy', 'Aide, therapy: physiotherapy', 'Assistant, allied health: physiotherapy', 'Assistant, hydrotherapy', 'Assistant, physiotherapy', 'Assistant, technical: physiotherapy', 'Assistant, therapy: physiotherapy', 'Electrotherapist', 'Hydrotherapist', 'Masseur', 'Masseuse', 'Technician, hydrotherapy', 'Technician, physical rehabilitation', 'Technician, physiotherapy', 'Therapist, acupressure', 'Therapist, hydrotherapy', 'Therapist, massage', 'Therapist, shiatsu'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3255 = '3255';

    #[Isco08Info(
        level: 4,
        code: '3256',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3256',
        title: 'Medical Assistants',
        definition: 'Medical assistants perform basic clinical and administrative tasks to support patient care under the direct supervision of a medical practitioner or other health professional.',
        tasks_include: "Tasks include -\n(a)  interviewing patients and their families to obtain information on their health status and medical history;\n(b)  assisting medical doctors and other health professionals to examine and treat patients, including measuring and recording vital signs, administering medications and performing routine clinical procedures such as giving injections and removing sutures; \n(c)  getting patients ready for examination and treatment, including explaining procedures and showing them to examination rooms; \n(d)  preparing and handling medical instruments and supplies, including sterilizing instruments and disposing of contaminated supplies in accordance with safety procedures;\n(e)  collecting blood, tissue or other specimens, and preparing them for laboratory testing; \n(f)  providing information to patients and families on health care topics including medications prescribed by a medical doctor or other health professional; \n(g)  providing prescription and drug refill information to pharmacies; \n(h)  maintaining cleanliness of patient waiting and examination rooms; \n(i)  recording information on patients' medical history, diagnostic testing and treatment procedures and results, and other information in medical records-keeping systems; \n(j)  scheduling appointments with patients, and preparing documentation required for billing, reporting and insurance purposes.",
        excluded_occupations: "Some related occupations classified elsewhere: \n- Clinical officer (paramedical) - 2240\n- Medical prosthetic technician - 3214\n- Dental assistant - 3251\n- Physiotherapy assistant - 3255\n- Medical secretary - 3344\n- Medical imaging assistant - 5329",
        notes: 'Occupations included in this unit group normally require formal training in health services provision. Clinical care providers with advanced training and skills to provide independent medical diagnostic and treatment services are classified in Unit Group 2240: Paramedical Practitioners.',
        occupational_titles: ['Assistant, clinical: helping doctor', "Assistant, doctor's", 'Assistant, medical: helping doctor', 'Assistant, ophthalmic'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
