    #[Isco08Info(
        level: 4,
        code: '3257',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3257',
        title: 'Environmental and Occupational Health Inspectors and Associates',
        definition: 'Environmental and occupational health inspectors and associates investigate the implementation of rules and regulations relating to environmental factors that may affect human health, safety in the workplace, and safety of processes for the production of goods and services. They may implement and evaluate programmes to restore or improve safety and sanitary conditions under the supervision of a health professional.',
        tasks_include: "Tasks include -\n(a)  advising employers’ and workers’ representatives on the implementation of government and other rules and regulations concerning occupational safety and the working environment;\n(b)  inspecting places of work to ensure that the working environment, machinery and equipment conform to government and other rules, regulations and standards related to sanitation and\/or occupational and environmental health and safety;\n(c)  giving advice on environmental sanitary problems and techniques;\n(d)  inspecting places of work and, by interviews, observations and other means, obtaining information about work practices and accidents to determine compliance with safety rules and regulations;\n(e)  inspecting areas of production, processing, transport, handling, storage and sale of products to ensure conformity with government and other rules, regulations and standards;\n(f)  advising enterprises and the general public on the implementation of government and other rules and regulations concerning hygiene, sanitation, purity and grading of primary products, food, drugs, cosmetics and similar goods;\n(g)  inspecting establishments to ensure that they conform to government and other rules and regulations concerning emission of pollutants and disposal of dangerous wastes;\n(h)  initiating action to maintain or improve hygiene and prevent pollution of water, air, food or soil;\n(i)  promoting preventive and corrective measures such as control of disease carrying organisms and of harmful substances in the air, hygienic food handling, proper disposal of waste and cleaning of public places;\n(j)  estimating quantities and costs of materials and labour required for health, safety and sanitation remediation projects;",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Environmental health officer - 2263\n- Occupational health and safety adviser - 2263\n- Occupational hygienist - 2263\n- Radiation protection expert - 2263",
        notes: null,
        occupational_titles: ['Inspector, food sanitation and safety', 'Inspector, health', 'Inspector, meat', 'Inspector, occupational health and safety', 'Inspector, pollution', 'Inspector, product safety', 'Inspector, safety and health', 'Inspector, safety and health: child care', 'Inspector, safety and health: consumer (protection)', 'Inspector, safety and health: establishments', 'Inspector, safety and health: factories', 'Inspector, safety and health: industrial (waste-processing)', 'Inspector, safety and health: labour', 'Inspector, safety and health: pollution', 'Inspector, safety and health: shops', 'Inspector, safety and health: working conditions', 'Inspector, sanitary', 'Sanitarian'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3257 = '3257';

    #[Isco08Info(
        level: 4,
        code: '3258',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3258',
        title: 'Ambulance Workers',
        definition: 'Ambulance workers provide emergency health care to patients who are injured, sick, infirm, or otherwise physically or mentally impaired prior to and during transport to medical facilities.',
        tasks_include: "Tasks include -\n(a)  assessing health status of persons involved in accidents, natural disasters and other emergency situations, and determining needs for immediate and specialized medical assistance; \n(b)  performing medical procedures and administering drugs and other therapies according to protocol for emergency medical treatment, including resuscitating and defibrillating patients and operating life-support equipment; \n(c)  monitoring changes in health status of patients during transport to and from medical, rehabilitation and other health care facilities; \n(d)  providing information and training to community groups and essential service workers in first aid for initial care of an illness or injury; \n(e)  attending and\/or patrolling large-scale public gatherings and other events where health emergencies are more likely to occur; \n(f)  recording information on patients' conditions and treatments provided in medical records-keeping systems.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Paramedical practitioner - 2240\n- Ambulance driver - 8322",
        notes: 'Occupations included in this unit group normally require formal training in emergency medical treatment, patient transport, ambulance principles and practice, or a related field. Ambulance drivers who do not provide health care are classified in Unit group 8322: Car, Taxi and Van Drivers.',
        occupational_titles: ['Ambulanceman', 'Ambulancewoman', 'Attendant, ambulance', 'Man, ambulance', 'Officer, ambulance', 'Paramedic, ambulance', 'Paramedic, emergency', 'Technician, emergency medical', 'Woman, ambulance', 'Worker, ambulance'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3258 = '3258';

    #[Isco08Info(
        level: 4,
        code: '3259',
        major_group: '3',
        sub_major_group: '32',
        minor_group: '325',
        unit_group: '3259',
        title: 'Health Associate Professionals Not Elsewhere Classified',
        definition: 'This unit group covers health associate professionals not classified elsewhere in Sub-major Group 32: Health Associate Professionals. For instance, the group includes occupations such as HIV counsellor, family planning counsellor and other health associate professionals.',
        tasks_include: "In such cases tasks would include:\n(a)  interviewing and examining patients to obtain information on their health status and the nature and extent of injury, illness or other physical or mental health condition; \n(b) providing information and counselling to patients and families about certain health conditions, prevention and treatment options, treatment adherence, and personal behaviours that can affect health outcomes;\n(c)  administering therapeutic care and treatment to patients;\n(d ) performing certain basic clinical procedures, such as administration of HIV antibody tests or insertion of intrauterine devices;\n(e) dispensing and advising on dietary supplements, antiretroviral and prophylaxis medications, and other healthcare products\n(f)  monitoring patients' progress through treatment plans, and identifying signs and symptoms requiring referral to a medical doctor or other health professional;\n(g)  recording information on patients' health status and responses to treatment in medical records-keeping systems;\n(h)  sharing information with other health care providers when required to ensure continuing and comprehensive care.",
        excluded_occupations: null,
        notes: 'Occupations included in this unit group normally require formal training in health service provision.',
        occupational_titles: ['Assistant, speech therapy', 'Counsellor, AIDS', 'Counsellor, family planning', 'Counsellor, HIV', 'Technician, anaesthesia ', 'Technician, respiratory therapy', 'Trichologist'],
        parent: '325',
        ancestors: ['3', '32', '325'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3259 = '3259';

    #[Isco08Info(
        level: 4,
        code: '3311',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '331',
        unit_group: '3311',
        title: 'Securities and Finance Dealers and Brokers',
        definition: 'Securities and finance dealers and brokers buy and sell securities, stocks, bonds and other financial instruments, and deal on the foreign exchange, on spot, or on futures markets, on behalf of their own company or for customers on a commission basis. They recommend transactions to clients or senior management.',
        tasks_include: "Tasks include -\n(a)  obtaining information about the financial circumstances of customers and companies in which investments may be made;\n(b)  analysing market trends for securities, bonds, stocks and other financial instruments, including foreign exchange;\n(c)  informing prospective customers about market conditions and prospects;\n(d)  advising on and participating in the negotiation of terms for, and organization of, loans and placement of stocks and bonds in the financial market to raise capital for customers;\n(e)  recording and transmitting buy and sell orders for securities, stocks, bonds or other financial instruments and for foreign exchange for future or immediate delivery.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Bond analyst - 2413\n- Commodities broker - 3324\n- Commodity futures dealer - 3324\n- Securities clerk - 4312",
        notes: null,
        occupational_titles: ['Broker, finance', 'Broker, foreign exchange', 'Broker, futures: financial', 'Broker, investment', 'Broker, lease', 'Broker, mortgage', 'Broker, securities', 'Broker, stocks and shares', 'Dealer, bond', 'Dealer, foreign exchange', 'Dealer, futures: financial', 'Dealer, investment', 'Dealer, securities', 'Jobber, stock', 'Salesperson, bond', 'Salesperson, securities', 'Sharebroker', 'Stockbroker', 'Trader, bond', 'Trader, derivatives', 'Trader, financial', 'Trader, foreign exchange', 'Trader, futures: financial', 'Trader, securities', 'Trader, stock', 'Underwriter, investments'],
        parent: '331',
        ancestors: ['3', '33', '331'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3311 = '3311';

    #[Isco08Info(
        level: 4,
        code: '3312',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '331',
        unit_group: '3312',
        title: 'Credit and Loans Officers',
        definition: 'Credit and loans officers analyse and evaluate financial information on applications for credit and loans and determine approval or disapproval of the client for the credit or loan, or recommend to management approval or disapproval.',
        tasks_include: "Tasks include - \n(a)  interviewing applicants for personal, mortgage, student and business loans;\n(b)  researching and evaluating loan applicant’s financial status, references, credit and ability to repay the loan;\n(c)  submitting credit and loan applications to management with recommendations for approval or rejection; \n(d) approving or rejecting loan applications within authorized limits ensuring that credit standards of the institution are respected;\n(e)  keeping records of payments, and preparing routine letters requesting payment for overdue accounts and forwarding these for legal action;\n(f)  completing credit and loan documentation.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Financial institution branch manager - 1346",
        notes: null,
        occupational_titles: ['Analyst, credit: assessing credit or loans', 'Analyst, financial: assessing credit worthiness of clients', 'Analyst, loans', 'Analyst, risk: assessing credit worthiness of clients', 'Assessor, credit', 'Assessor, loans', 'Clerk, finance: approving or assessing credit or loans', 'Clerk, finance: processing credit applications or loans', 'Controller, credit: assessing credit worthiness of clients', 'Officer, acceptance: financial institution', 'Officer, bank: loans or lending', 'Officer, bank lending', 'Officer, credit: bank, building society or credit union', 'Officer, finance: approving, assessing or processing loans', 'Officer, home loans', 'Officer, lending services: bank, building society or credit union', 'Officer, loans', 'Officer, mortgage', 'Officer, securities: loans or lending', 'Officer, settlements: loans or financial settlements', 'Processor, loans', 'Supervisor, credit: assessing credit or finance', 'Underwriter, loans', 'Underwriter, mortgages', 'Writer, loan', 'Writer, mortgage'],
        parent: '331',
        ancestors: ['3', '33', '331'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3312 = '3312';

    #[Isco08Info(
        level: 4,
        code: '3313',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '331',
        unit_group: '3313',
        title: 'Accounting Associate Professionals',
        definition: 'Accounting associate professionals maintain complete records of financial transactions of an undertaking and verify accuracy of documents and records relating to such transactions.',
        tasks_include: "Tasks include -\n(a)  maintaining complete records of all financial transactions of an undertaking according to general bookkeeping principles, with guidance from Accountants;\n(b)  verifying accuracy of documents and records relating to payments, receipts and other financial transactions;\n(c)  preparing financial statements and reports for specified periods;\n(d)  applying knowledge of bookkeeping principles and practices in order to identify and solve problems arising in the course of their work;\n(e)  using standard computer software packages to perform accounting and related calculations;\n(f)  supervising the work of accounts and bookkeeping clerks.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Accountant - 2411\n- Actuarial assistant - 3314\n- Bookkeeping clerk- 4311",
        notes: null,
        occupational_titles: ['Assistant, accounting', 'Auditor, night: hotel', 'Bookkeeper'],
