    #[Isco08Info(
        level: 4,
        code: '3314',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '331',
        unit_group: '3314',
        title: 'Statistical, Mathematical and Related Associate Professionals',
        definition: 'Statistical, mathematical and related associate professionals assist in planning the collection, processing and presentation of statistical, mathematical or actuarial data and in carrying out these operations, usually working under the guidance of statisticians, mathematicians and actuaries.',
        tasks_include: "Tasks include -\n(a)  assisting in planning and performing statistical, mathematical, actuarial and related calculations;\n(b)  preparing detailed estimates of quantities and costs of materials and labour required for statistical census and survey operations;\n(c)  performing technical tasks connected with establishing, maintaining and using registers and sampling frames for census and survey operations;\n(d)  performing technical tasks connected with data collection and quality control operations in censuses and surveys;\n(e)  using standard computer software packages to perform mathematical, actuarial, statistical, accounting and related calculations;\n(f)  preparing statistical, mathematical, actuarial, accounting and other results for presentation in graphical or tabular form;\n(g)  applying knowledge of statistical, mathematical, actuarial, accounting and related principles and practices in order to identify and solve problems arising in the course of their work;\n(h)  supervising the work of statistical clerks.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Actuary - 2120\n- Mathematician - 2120\n- Statistician - 2120\n- Accounting assistant - 3313\n- Statistical clerk - 4312",
        notes: null,
        occupational_titles: ['Assistant, actuarial', 'Assistant, mathematical', 'Assistant, statistical'],
        parent: '331',
        ancestors: ['3', '33', '331'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3314 = '3314';

