    #[Isco08Info(
        level: 4,
        code: '3322',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '332',
        unit_group: '3322',
        title: 'Commercial Sales Representatives',
        definition: 'Commercial sales representatives represent companies to sell various goods and services to businesses and other organizations and provide product-specific information as required.',
        tasks_include: "Tasks include -\n(a)  soliciting orders and selling goods to retail, industrial, wholesale and other establishments;\n(b)  selling equipment, supplies and related services to business establishments or individuals;\n(c)  obtaining and updating knowledge of market conditions and of employer’s and competitors’ goods and services;\n(d)  providing prospective customers with information about the characteristics and functions of the products and equipment for sale, and demonstrating its use or qualities;\n(e)  quoting prices and credit terms, recording orders and arranging deliveries;\n(f)  reporting customers’ reactions and requirements to suppliers and manufacturers;\n(g)  following up clients to ensure satisfaction with products purchased.",
        excluded_occupations: "Some related occupations classified elsewhere:\nSales manager - 1221\nMedical sales representative - 2433\nTechnical sales representative - 2433\nInformation and communications technology sales professional - 2434\nShop sales assistant - 5223\nDoor-to-door sales representative - 5243",
        notes: null,
        occupational_titles: ['Adviser, after-sales service', 'Agent, sales: commercial', 'Agent, sales: manufacturing', 'Canvasser', 'Consultant, sales: manufacturing', 'Executive, account: sales (except ICT, industrial, medical and pharmaceutical products)', 'Manager, account: sales (except ICT, industrial, medical and pharmaceutical products)', 'Representative, sales', 'Representative, sales: manufacturing', 'Salesperson, commercial', 'Salesperson, manufacturing', 'Salesperson, travelling', 'Traveller, commercial'],
        parent: '332',
