    #[Isco08Info(
        level: 4,
        code: '3323',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '332',
        unit_group: '3323',
        title: 'Buyers',
        definition: 'Buyers buy goods and services for use or resale on behalf of industrial, commercial, government or other establishments and organizations.',
        tasks_include: "Tasks include -\n(a)  determining or negotiating contract terms and conditions, awarding supplier contracts or recommending contract awards for the purchase of equipment, raw materials, products, services and merchandise for resale;\n(b)  obtaining information about requirements and stock and developing specifications for quantity and quality to be purchased, costs, delivery dates and other contract conditions; \n(c)  purchasing general and specialized equipment, materials or business services for use or for further processing by their establishment;\n(d)  inviting tenders, consulting with suppliers and reviewing quotations; \n(e)  purchasing merchandise for resale by retail or wholesale establishments;\n(f)  studying market reports, trade periodicals and sales promotion materials and visiting trade shows, showrooms, factories and product design events; \n(g)  selecting the merchandise or products that best fit the establishment's requirements; \n(h)  interviewing  suppliers and negotiating prices, discounts, credit terms and transportation arrangements; \n(i)  overseeing distribution of merchandise to outlets and maintaining adequate stock levels; \n(j)  establishing delivery schedules, monitoring progress and contacting clients and suppliers to resolve problems.",
        excluded_occupations: "Some related occupations classified elsewhere:\nCommodities broker - 3324",
        notes: null,
        occupational_titles: ['Agent, procurement', 'Agent, purchasing', 'Buyer', 'Merchandiser, buying', 'Merchandiser, purchasing', 'Officer, procurement', 'Officer, purchasing', 'Officer, supply', 'Purchaser, merchandise'],
        parent: '332',
