    #[Isco08Info(
        level: 4,
        code: '3339',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '333',
        unit_group: '3339',
        title: 'Business Services Agents Not Elsewhere Classified',
        definition: 'This unit group covers business services agents not classified elsewhere in Minor Group 333: Business Services Agents. For instance, the group includes those who establish business contacts, sell business services such as advertising space in the media, arrange contracts for performances of athletes, entertainers and artists, for the publication of books, the production of plays, or the recording, performance and sale of music, sell property and goods by auction and who design and organize package and group tours.',
        tasks_include: "In such cases tasks would include -\n(a)  obtaining information about services to be sold and needs of prospective buyers;\n(b)  negotiating contracts on behalf of seller or buyer and explaining terms of sale and payment to client;\n(c)  signing agreements on behalf of seller or buyer and ensuring that contract is honoured;\n(d)  making sure that the business service purchased is made available to the buyer in the agreed format at the agreed time;\n(e)  selling by auction various kinds of property, cars, commodities, livestock, art, jewellery and other objects.\n(f)  organizing group tours for business or vacation travel and making bulk travel and accommodation bookings.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Agent, literary', 'Agent, musical performance', 'Agent, patent', 'Agent, sports', 'Agent, theatrical', 'Auctioneer', 'Dealer, art', 'Operator, tour', 'Promoter, sports', 'Salesperson, advertising', 'Salesperson, business services'],
        parent: '333',
        ancestors: ['3', '33', '333'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3339 = '3339';

    #[Isco08Info(
        level: 4,
        code: '3341',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '334',
        unit_group: '3341',
        title: 'Office Supervisors',
        definition: 'Office supervisors supervise and coordinate the activities of workers in Major Group 4: Clerical Support Workers.',
        tasks_include: "Tasks include - \n(a)  coordinating, assigning and reviewing the work of clerks engaged in the following duties: word processing, record keeping and filing, operating telephones and switchboards; data entry, desktop publishing and other activities involving general office and administrative skills; \n(b)  establishing work schedules and procedures and co-coordinating activities with other work units or departments;\n(c)  resolving work-related problems and preparing and submitting progress and other reports; \n(d)  training and instructing employees in job duties, safety procedures and company policies, or arranging for training to be provided; \n(e)  evaluating employees’ job performance and conformity with regulations, and recommending appropriate personnel action; \n(f)  assisting in recruitment, interviewing and selection of employees.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Medical records unit supervisor  - 3252",
        notes: 'Workers who supervise the activities of clerical support workers in law offices and legal departments are classified in Unit Group 3342: Legal Secretaries. Those who supervise the activities of clerical support workers in health facilities where the work requires specialist knowledge related to health and medicine, such as processing medical records and hospital admission details, are classified in Unit Group 3344: Medical secretaries. Those who provide direct secretarial and administrative support to a manager or professional (except legal and health professionals) and also supervise the activities of clerical support workers are classified in Unit Group 3343: Administrative and Executive Secretaries.',
        occupational_titles: ['Administrator, office', 'Controller, typist', 'Coordinator, administration: office administration or management', 'Leader, team: call centre', 'Leader, team: contact centre', 'Manager, call centre team', 'Manager, contact centre team', 'Manager, front office: hospital or school', 'Manager, office', 'Manager, team: call centre', 'Planner, call centre workforce', 'Planner, contact centre workforce', 'Planner, workforce: contact centre', 'Supervisor, call centre', 'Supervisor, clerical', 'Supervisor, contact centre', 'Supervisor, data entry', 'Supervisor, filing clerks', 'Supervisor, personnel clerks', 'Supervisor, switchboard', 'Supervisor, typist', 'Supervisor, word processing'],
        parent: '334',
        ancestors: ['3', '33', '334'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3341 = '3341';

    #[Isco08Info(
        level: 4,
        code: '3342',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '334',
        unit_group: '3342',
        title: 'Legal Secretaries',
        definition: 'Legal secretaries apply specialized knowledge of legal terminology and procedures in providing support to legal professionals with communication, documentation and internal managerial co-ordination activities, in law offices, legal departments of large firms and governments.',
        tasks_include: "Tasks include -\n(a)  preparing and processing legal documents and papers, such as deeds, wills, affidavits and briefs;\n(b)  reviewing and proofreading documents and correspondence to ensure compliance with legal procedures;\n(c)  mailing, faxing or arranging for delivery of legal correspondence to clients, witnesses and court officials;\n(d)  organizing and maintaining documents, case files and law libraries;\n(e)  screening requests for meetings, and scheduling and organizing meetings;\n(f)  assisting in the preparation of budgets, monitoring of expenditures, drafting of contracts and purchasing or acquisition orders;\n(g)  supervising the work of office support workers.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Legal assistant - 3411",
        notes: null,
        occupational_titles: ['Assistant, administrative: legal', 'Assistant, executive: legal', 'Assistant, legal: secretarial tasks', 'Manager, legal practice', 'Manager, practice: legal', 'Paralegal, secretarial tasks', 'Secretary, conveyancing', 'Secretary, legal', 'Secretary, litigation', 'Secretary, paralegal', 'Stenographer, legal'],
        parent: '334',
        ancestors: ['3', '33', '334'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3342 = '3342';

    #[Isco08Info(
        level: 4,
        code: '3343',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '334',
        unit_group: '3343',
        title: 'Administrative and Executive Secretaries',
        definition: "Administrative and executive secretaries perform liaison, coordination and organizational tasks in support of managers and professionals and\/or prepare correspondence, reports and records of proceedings and other specialized documentation.",
        tasks_include: "Tasks include -\n(a)  drafting administrative correspondence and minutes;\n(b)  obtaining, proposing and monitoring deadlines and follow-up dates;\n(c)  screening requests for meetings, and scheduling and organizing meetings and travel arrangements;\n(d)  assisting in the preparation of budgets, monitoring of expenditures, drafting of contracts and purchasing or acquisition orders;\n(e)  liaising with other staff about a range of matters relating to the organization’s operations;\n(f)  writing and answering business or technical letters and other similar correspondence;\n(g)  preparing verbatim reports of proceedings in legislative assemblies, courts of law or other places using shorthand or specialized office equipment.\n(h)  supervising the work of  clerical support workers.",
        excluded_occupations: "Some related occupations classified elsewhere:\nMedical transcriptionist - 3344\nSecretary (general) - 4120",
        notes: null,
        occupational_titles: ['Assistant, administrative', 'Assistant, correspondence', 'Assistant, executive', 'Assistant, personal', 'Reporter, administrative: verbatim', 'Reporter, court', 'Reporter, verbatim', 'Secretary, administrative', 'Secretary, committee', 'Secretary, executive'],
        parent: '334',
        ancestors: ['3', '33', '334'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3343 = '3343';

    #[Isco08Info(
        level: 4,
        code: '3344',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '334',
        unit_group: '3344',
        title: 'Medical Secretaries',
        definition: 'Medical secretaries, using specialized knowledge of medical terminology and health care delivery procedures, assist health professionals and other workers by performing a variety of communication, documentation, administrative and  internal coordination functions, to support health workers in medical facilities and other health-care related organizations.',
        tasks_include: "Tasks include -\n(a)  scheduling and confirming medical appointments and communicating messages for medical staff; and patients;\n(b)  compiling, recording and reviewing medical charts, reports, documents and correspondence;\n(c)  interviewing patients to complete forms, documents and case histories;\n(d)  completing insurance and other claims forms;\n(e)  maintaining medical files and records and technical library;\n(f)  preparing financial statements and billing procedures;\n(g)  assisting in the preparation of budgets, drafting of contracts and purchasing or acquisition orders;\n(h)  supervising the work of office support workers and other office staff.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Medical records technician - 3252\n- Medical assistant - 3256\n- Secretary (general) - 4120\n- Medical office receptionist - 4226",
        notes: null,
        occupational_titles: ['Assistant, administrative: doctors surgery', 'Assistant, administrative: medical office', 'Assistant, secretarial: doctors surgery', 'Assistant, secretarial: medical', 'Manager, medical practice', 'Manager, practice: medical', 'Secretary, dental', "Secretary, doctor's", 'Secretary, hospital ward', 'Secretary, medical', 'Secretary, medical insurance billing', 'Secretary, medical laboratory', 'Secretary, pathology', 'Secretary, patient care', 'Stenographer, medical', 'Transcriptionist, medical'],
        parent: '334',
        ancestors: ['3', '33', '334'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3344 = '3344';

    #[Isco08Info(
        level: 4,
        code: '3351',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: '3351',
        title: 'Customs and Border Inspectors',
        definition: 'Customs and border inspectors check persons and vehicles crossing national borders to administer and enforce relevant government rules and regulations.',
        tasks_include: "Tasks include -\n(a)  patrolling national borders and coastal waters to stop persons from illegally entering or leaving the country and from illegally importing or exporting currency or goods;\n(b)  checking travel documents of persons crossing national borders to ensure that they have the necessary authorizations and certificates;\n(c)  inspecting the luggage of persons crossing national borders to ensure that it conforms to government rules and regulations concerning import or export of goods and currencies;\n(d)  examining transport documents and freight of vehicles crossing national borders to ensure conformity with government rules and regulations concerning goods in transit and the import and export of goods, and to verify that necessary payments have been made;\n(e)  detaining persons and seizing prohibited and undeclared goods found to be in violation of immigration and customs laws;\n(f)  coordinating and cooperating with other agencies involved in law enforcement, deportation and prosecution;\n(g)  performing related administrative tasks to record findings, transactions, violations and determinations;\n(h)  when necessary, testifying in a court of law about the circumstances and results of investigations carried out.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Guard, border', 'Inspector, border', 'Inspector, customs', 'Officer, customs', 'Officer, immigration', 'Officer, passport: checking'],
        parent: '335',
        ancestors: ['3', '33', '335'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3351 = '3351';

    #[Isco08Info(
        level: 4,
        code: '3352',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: '3352',
        title: 'Government Tax and Excise Officials',
        definition: 'Government tax and excise officials examine tax returns, bills of sale and other documents to determine the type and amount of taxes, duties and other types of fees to be paid by individuals or businesses, referring exceptional or important cases to accountants, senior government officials or Managers.',
        tasks_include: "Tasks include -\n(a)  advising organizations, enterprises and the public on government laws, rules and regulations concerning the determination and payment of taxes, duties and other government fees, and on the public’s rights and obligations;\n(b)  examining tax returns, bills of sale and other relevant documents to determine type and amount of taxes, duties and other types of fees to be paid;\n(c)  investigating filed tax returns and accounting records, systems and internal controls of organizations to ensure compliance with taxation laws and regulations;\n(d)  performing related administrative tasks to document findings, maintain records and report on actions taken for cases.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Accountant – 2411 \n- Auditor – 2411",
        notes: null,
        occupational_titles: ['Collector, tax', 'Examiner, tax', 'Inspector, taxation', 'Officer, excise', 'Officer, tax'],
        parent: '335',
        ancestors: ['3', '33', '335'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3352 = '3352';

    #[Isco08Info(
        level: 4,
        code: '3353',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: '3353',
        title: 'Government Social Benefits Officials',
        definition: 'Government social benefits officials examine applications for government, financial or service programmes to determine eligibility and amount of benefit or appropriate services, referring exceptional or important cases to senior government officials or managers.',
        tasks_include: "Tasks include -\n(a)  advising individuals and organizations on government laws, rules and regulations concerning government benefit programmes and the determination and disbursement of payments or referral to services, as well as on the public’s rights and obligations;\n(b)  examining applications and other relevant documents to determine types and amounts of benefit which individuals are eligible to receive;\n(c)  assessing documentation and interviewing benefit recipients to ensure eligibility for continuing benefits or services;\n(d)  performing related administrative tasks to maintain client records and prepare reports on determinations regarding eligibility, referral decisions, termination of benefits and abuse or fraud.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Counselling professionals - 2635\n- Social workers - 2635",
        notes: null,
        occupational_titles: ['Inspector, pensions', 'Officer, pensions', 'Officer, social benefits', 'Officer, social security: claims'],
        parent: '335',
        ancestors: ['3', '33', '335'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3353 = '3353';

    #[Isco08Info(
        level: 4,
        code: '3354',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: '3354',
        title: 'Government Licensing Officials',
        definition: 'Government licensing officials examine applications for licences to export or import goods, set up businesses, build houses or other structures, or to obtain passports, determine eligibility of applications for issuing licences or passports, and identify specific conditions or restrictions to be attached to licences issued, referring exceptional or important cases to senior government officials or managers.',
        tasks_include: "Tasks include -\n(a)  advising individuals on government laws and regulations concerning the type of licence required and the conditions attached to such licences, and on the public's rights and obligations;\n(b)  examining applications and relevant documents and determining whether a licence can be granted and the conditions which should be attached;\n(c)  examining applications and approving the issue of passports;\n(d)  performing related administrative tasks to process applications, document activities, evaluations and determinations, and to prepare correspondence to inform applicants of licensing decisions;\n(e)  administering and scoring tests required to license applicants.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Building inspectors - 3112 \n- Fire inspectors - 3112",
        notes: null,
        occupational_titles: ['Inspector, licensing', 'Officer, building permit: licensing', 'Officer, business permit: licensing', 'Officer, licensing', 'Officer, passport: issuing'],
        parent: '335',
        ancestors: ['3', '33', '335'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3354 = '3354';

    #[Isco08Info(
        level: 4,
        code: '3355',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: '3355',
        title: 'Police Inspectors and Detectives',
        definition: 'Police inspectors and detectives investigate facts and circumstances relating to crimes committed in order to identify suspected offenders and obtain information not readily available or apparent concerning establishments or the circumstances and behaviour of persons, mostly in order to prevent crimes.',
        tasks_include: "Tasks include -\n(a)  establishing contacts and sources of information about crimes planned or committed, in order to prevent crimes or identify suspected offenders;\n(b)  obtaining and verifying evidence by examining crime and accident scenes for clues and physical evidence, interviewing witnesses and suspects and analysing documents and computer files;\n(c)  analysing evidence in order to solve crimes, identify criminal activity and gather information for court cases;\n(d)  establishing contacts and sources of information not readily available or apparent concerning establishments or the circumstances and behaviour of persons, usually with the aim of preventing a crime;\n(e)  making arrests;\n(f)  testifying in courts of law or reporting to superiors about circumstances and results of investigations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Police commissioner - 1112\n- Police inspector-general - 1112\n- Police superintendent - 1349\n- Private detective - 3411\n- Police officer - 5412",
        notes: null,
        occupational_titles: ['Agent, inquiry: police', 'Constable, detective', 'Detective, police', 'Inspector, detective', 'Inspector, police', 'Investigator, police', 'Officer, police: detective', 'Officer, police: inspector', 'Sergeant, detective'],
        parent: '335',
        ancestors: ['3', '33', '335'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3355 = '3355';

    #[Isco08Info(
        level: 4,
        code: '3359',
        major_group: '3',
        sub_major_group: '33',
        minor_group: '335',
        unit_group: '3359',
        title: 'Government Regulatory AssociatePprofessionals Not Elsewhere Classified',
        definition: 'This unit group covers government regulatory associate professionals not classified elsewhere. For instance the group includes agricultural, fisheries, forestry, prices, wages and weights and measures inspectors.',
        tasks_include: "In such cases tasks would include -\n(a)  examining places of business to ensure the use of correct weights and measures in trade;\n(b)  monitoring price regulations to assess appropriateness of costs for goods and services to protect consumer interests;\n(c)  monitoring wage regulations to ensure appropriate levels of pay for work performed and to assess compliance with employment standards legislation;\n(d)  performing related investigative and administrative tasks to record findings, document compliance problems or inappropriate business practices and to prepare reports and correspondence.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Fire inspector-3112 \n- Health Inspector - 3257\n- Occupational health and safety inspector- 3257\n- Pollution inspector - 3257\n- Sanitary inspector - 3257",
        notes: null,
        occupational_titles: ['Courier, diplomatic', 'Inspector, agricultural', 'Inspector, civil service', 'Inspector, fisheries', 'Inspector, forestry', 'Inspector, government: administration', 'Inspector, prices', 'Inspector, wage', 'Inspector, weights and measures', 'Official, consular', 'Official, electoral'],
