    #[Isco08Info(
        level: 4,
        code: '3411',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '341',
        unit_group: '3411',
        title: 'Legal and Related Associate Professionals',
        definition: 'Legal and related associate professionals perform support functions in courts of law or in law offices, provide services related to such legal matters as insurance contracts, the transferring of property and the granting of loans and other financial transactions or conduct investigations for clients.',
        tasks_include: "Tasks include -\n(a)  documenting court proceedings and judgements;\n(b)  serving statements of claims, summonses, warrants, subpoenas and other court orders;\n(c)  maintaining order in court and hearing rooms;\n(d)  preparing legal documents including trial briefs, pleadings, appeals, wills and contracts and preparing, papers summarizing legal positions or setting out conditions of loans or insurance;\n(e)  investigating facts, assembling evidence and researching relevant statutes, decisions and other legal documents to prepare cases; \n(f)  advising clients on legal matters;\n(g)  examining documentation such as mortgages, liens, judgements, easements, contracts and maps in order to verify properties’ legal descriptions and ownership;\n(h)  preparing documents relating to transfer of real estate, stocks or other matters requiring formal registration;\n(i)  investigating possible cases of theft of goods, money or information from business establishments and of other possible cases of unlawful behaviour by customers or employees; \n(j)  investigating establishments or the circumstances and behaviour of persons on behalf of clients.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Lawyer - 2611\n- Judge - 2612\n- Notary - 2619\n- Legal secretary - 3342",
        notes: null,
        occupational_titles: ['Agent, inquiry: private', "Assistant, barrister's", 'Assistant, legal', "Assistant, solicitor's", 'Bailiff', 'Clerk, conveyancing', 'Clerk, court', "Clerk, judge's", 'Clerk, law', 'Clerk, probate', 'Detective, private', 'Detective, store', 'Investigator, private', 'Justice of the Peace', 'Paralegal', 'Registrar, court', 'Searcher, title'],
        parent: '341',
        ancestors: ['3', '34', '341'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3411 = '3411';

    #[Isco08Info(
        level: 4,
        code: '3412',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '341',
        unit_group: '3412',
        title: 'Social Work Associate Professionals',
        definition: 'Social work associate professionals administer and implement social assistance programmes and community services and assist clients to deal with personal and social problems.',
        tasks_include: "Tasks include -\n(a)  collecting information relevant to clients’ needs and assessing their relevant skills, strengths and deficits;\n(b)  helping persons with disabilities or the elderly to obtain services and to improve their ability to function in society;\n(c)  assisting clients to identify options and develop plans of action while providing necessary support and assistance;\n(d)  assisting clients to identify and access community resources including legal, medical and financial assistance, housing, employment, transportation, assistance with moves, day care and other referral services; \n(e)  counselling clients living in group homes and half-way houses, supervising their activities and assisting in pre-release and release planning;\n(f)  participating in the selection and admission of clients to appropriate programmes; \n(g)  providing crisis intervention and emergency shelter services;\n(h)  implementing life skills workshops, substance abuse treatment programmes, behaviour management programmes, youth services programmes and other community and social service programmes under the supervision of social work or health care professionals;\n(i)  assisting in evaluating the effectiveness of interventions and programmes by monitoring and reporting on clients' progress;\n(j)  maintaining contact with other social service agencies, schools and health care providers involved with clients to provide information and obtain feedback on clients' overall situation and progress.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Marriage counsellor - 2635\n- Parole officer - 2635\n- Probation officer - 2635\n- Social worker - 2635",
        notes: null,
        occupational_titles: ['Almoner, associate professional', 'Caseworker, associate professional', 'Housefather, associate professional', 'Housemaster, associate professional: approved school', 'Housemistress, associate professional: approved school', 'Housemother, associate professional', 'Instructor, life skills', 'Officer, parole: associate professional', 'Officer, probation: associate professional', "Supervisor, women's shelter", 'Warden, community centre: associate professional', 'Warden, probation home: associate professional', 'Worker, community development', 'Worker, community services', 'Worker, crisis intervention', 'Worker, delinquency: associate professional', 'Worker, disability services', 'Worker, family services', 'Worker, mental health support', 'Worker, social: associate professional', 'Worker, welfare support', 'Worker, youth services'],
        parent: '341',
        ancestors: ['3', '34', '341'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3412 = '3412';

    #[Isco08Info(
        level: 4,
        code: '3413',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '341',
        unit_group: '3413',
        title: 'Religious Associate Professionals',
        definition: 'Religious associate professionals provide support to ministers of religion or to a religious community, undertake religious works, preach and propagate the teachings of a particular religion and endeavour to improve well-being through the power of faith and spiritual advice.',
        tasks_include: "Tasks include -\n(a)  undertaking religious works;\n(b)  preaching and propagating the teachings of a particular religious faith;\n(c)  assisting at services of public worship and religious rites;\n(d)  providing religious education, spiritual guidance and moral support to individuals and communities; \n(e)  administering and participating in programmes to provide food, clothing and shelter to those in need;\n(f)  advising communities and individuals on proper behaviour and faith to preserve or improve well-being.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Bonze - 2636\n- Imam - 2636\n- Minister of religion - 2636\n- Poojari - 2636\n- Priest - 2636\n- Rabbi - 2636\n- Herbalist - 3230 \n- Village healer - 3230\n- Witch doctor- 3230",
        notes: null,
