        parent: '341',
        ancestors: ['3', '34', '341'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3413 = '3413';

    #[Isco08Info(
        level: 4,
        code: '3421',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '342',
        unit_group: '3421',
        title: 'Athletes and Sports Players',
        definition: 'Athletes and sport players participate in competitive sporting events. They train and compete, either individually or as part of a team, in their chosen sport.',
        tasks_include: "Tasks include -\n(a)  participating in competitive sporting events;\n(b)  participating in regular practice and training sessions and undertaking private training to maintain the required standard of fitness and skill;\n(c)  undertaking sports promotional activities and media interviews;\n(d)  maintaining a high degree of expertise in a particular sport;\n(e)  deciding on strategies in consultation with coaches;\n(f)  assessing other competitors and conditions at venues; \n(g)  competing in sporting events;\n(h)  adhering to the rules and regulations associated with a specific sport.",
        excluded_occupations: null,
