    #[Isco08Info(
        level: 4,
        code: '3432',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '343',
        unit_group: '3432',
        title: 'Interior Designers and Decorators',
        definition: 'Interior designers and decorators plan and design commercial, industrial, public, retail and residential building interiors to produce an environment tailored to a purpose, taking into consideration factors that enhance living and working environments and sales promotion. They coordinate and participate in their construction and decoration.',
        tasks_include: "Tasks include -\n(a)  determining the objectives and constraints of the design brief by consulting with clients and stakeholders;\n(b)  researching and analysing spatial, functional, efficiency, safety and aesthetic requirements;\n(c)  formulating design concepts for the interiors of buildings;\n(d)  preparing sketches, diagrams, illustrations and plans to communicate design concepts;\n(e)  negotiating design solutions with clients, management, suppliers and construction staff;\n(f)  selecting, specifying and recommending functional and aesthetic materials, furniture and products for interiors;\n(g)  detailing and documenting selected design for construction;\n(h)  coordinating the construction and the decoration of interiors;\n(i)  designing and painting stage scenery;\n(j)   designing and decorating show windows and other display areas to promote products and services.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Interior architect - 2161",
        notes: null,
        occupational_titles: ['Decorator, display', 'Decorator, film set', 'Decorator, interior', 'Designer, armorial', 'Designer, decoration', 'Designer, display', 'Designer, exhibition', 'Designer, interior', 'Designer, scenery', 'Designer, set', 'Designer, stage', 'Dresser, window', 'Merchandiser, visual'],
