    #[Isco08Info(
        level: 4,
        code: '3433',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '343',
        unit_group: '3433',
        title: 'Gallery, Museum and Library Technicians',
        definition: 'Gallery, museum and library technicians prepare artworks, specimens and artefacts for collections, arrange and construct gallery exhibits, and assist librarians to organize and operate systems for handling recorded material and files.',
        tasks_include: "Tasks include -\n(a)  mounting and preparing objects for display;\n(b)  designing and arranging exhibit furnishings, display cases and display areas;\n(c)  assisting in setting up lighting and display equipment;\n(d)  receiving, shipping, packing and unpacking exhibits;\n(e)  ordering new library materials and maintaining library records and circulation systems;\n(f)  cataloguing printed and recorded material;\n(g)  entering data into databases and editing computer records;\n(h)  operating audiovisual and reprographic equipment;\n(i)  searching and verifying bibliographic data.",
        excluded_occupations: null,
