    #[Isco08Info(
        level: 4,
        code: '3434',
        major_group: '3',
        sub_major_group: '34',
        minor_group: '343',
        unit_group: '3434',
        title: 'Chefs',
        definition: 'Chefs design menus, create dishes and oversee the planning, organization preparation and cooking of meals in hotels, restaurants and other eating places, on board ships, on passenger trains and in private households.',
        tasks_include: "Tasks include -\n(a)  planning and developing recipes and menus, estimating food and labour costs, and ordering food supplies;\n(b)  monitoring quality of dishes at all stages of preparation and presentation;\n(c)  discussing food preparation issues with managers, dieticians, kitchen and waiting staff; \n(d)  supervising and coordinating the activities of cooks and other workers engaged in food preparation;\n(e)  inspecting supplies, equipment, and work areas to ensure conformity to established standards;\n(f)  determining how food should be presented, and creating decorative food displays. \n(g)  instructing cooks and other workers in the preparation, cooking, garnishing and presentation of food;\n(h)  participating on the recruitment of kitchen staff and monitoring their performance;\n(i)  preparing, seasoning and cooking speciality foods and complex dishes;\n(j)  explaining and enforcing hygiene and food safety regulations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Cook - 5120\n- Fast food preparer - 9411",
        notes: null,
        occupational_titles: ['Chef', 'Chef, executive', 'Chef, head', 'Chef, pastry', 'Chef de cuisine', 'Cook, chief', 'Cook, head', 'Saucier', 'Sous-chef'],
