    #[Isco08Info(
        level: 4,
        code: '3511',
        major_group: '3',
        sub_major_group: '35',
        minor_group: '351',
        unit_group: '3511',
        title: 'Information and Communications Technology Operations Technicians',
        definition: 'Information and communications technology operations technicians support the day-to-day processing, operation and monitoring of information and communications technology systems,  peripherlas, hardware, software and related computer equipment to ensure optimal performance and identify any problems.',
        tasks_include: "Tasks include - \n(a)  operating and controlling peripheral and related computer equipment;\n(b)  entering commands, using computer terminal, and activating controls on computer and peripheral equipment to integrate and operate equipment; \n(c)  monitoring systems for equipment failure or errors in performance;\n(d)  notifying supervisor or maintenance technician of equipment malfunctions;\n(e)  responding to programme error messages by finding and correcting problems, escalating the problem to other staff or terminating the programme;\n(f)  reading job set-up instructions to determine equipment to be used, order of use, material such as disks and paper to be loaded, and control settings;\n(g)  retrieving, separating and sorting programme output as needed, and sending data to specified users;\n(h)  loading peripheral equipment, such as printers, with selected materials for operating runs, or overseeing loading of peripheral equipment by peripheral equipment operators.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Computer network technician - 3513",
        notes: null,
        occupational_titles: ['Assistant, computer: engineering (operations)', 'Operator, computer', 'Operator, computer printer: high-speed', 'Operator, high-speed printer (computer)', 'Operator, peripheral equipment: computer', 'Technician, engineering: systems (computers)'],
        parent: '351',
        ancestors: ['3', '35', '351'],
        children: [],
        descendants: [],
    )]
    case ISCO08_3511 = '3511';

    #[Isco08Info(
        level: 4,
        code: '3512',
        major_group: '3',
        sub_major_group: '35',
        minor_group: '351',
        unit_group: '3512',
        title: 'Information and Communications Technology User Support Technicians',
        definition: 'Information and communications technology user support technicians provide technical assistance to users, either directly or by telephone, email or other electronic means, including diagnosing and resolving issues and problems with software, hardware, computer peripheral equipment, networks, databases and the Internet, and providing guidance and support in the deployment, installation and maintenance of systems.',
        tasks_include: "Tasks include -\n(a)  answering user inquiries regarding software or hardware operation to resolve problems;\n(b)  entering commands and observing system functioning to verify correct operations and detect errors; \n(c)  installing and performing minor repairs to hardware, software or peripheral equipment, following design or installation specifications;\n(d)  overseeing the daily performance of communications and computer systems;\n(e)  setting up equipment for employee use and performing or ensuring proper installation of cables, operating systems or appropriate software; \n(f)  maintaining records of daily data communication transactions, problems and remedial actions taken, or installation activities.\n(g)  emulating or reproducing technical problems encountered by users;\n(h)  consulting user guides, technical manuals and other documents to research and implement solutions;\n(i)  assisting applications programmers, systems developers and other ICT professionals to develop and test ICT products and services.",
        excluded_occupations: null,
