    #[Isco08Info(
        level: 4,
        code: '4110',
        major_group: '4',
        sub_major_group: '41',
        minor_group: '411',
        unit_group: '4110',
        title: 'General Office Clerks',
        definition: 'General office clerks perform a range of clerical and administrative tasks according to established procedures.',
        tasks_include: "Tasks include -\n(a)  recording, preparing, sorting, classifying and filing information;\n(b)  sorting, opening and sending mail;\n(c)  photocopying and faxing documents;\n(d)  preparing reports and correspondence of a routine nature;\n(e)  recording issue of equipment to staff;\n(f)  responding to telephone or electronic enquiries or forwarding to appropriate person;\n(g)  checking figures, preparing invoices and recording details of financial transactions made;\n(h)  transcribing information onto computers, and proofreading and correcting copy.",
        excluded_occupations: null,
        notes: 'In distinguishing the work of general office clerks from that of workers classified in Unit Group 4120: Secretaries (general), it should be noted that the work of secretaries is primarily concerned with the transcription, formatting and processing of correspondence and other documentation. Whilst general office clerks may perform some work of this nature, the transcription and processing of documentation is not the main focus of the work.',
        occupational_titles: ['Clerk', 'Clerk, general: office', 'Clerk, office'],
        parent: '411',
        ancestors: ['4', '41', '411'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4110 = '4110';

    #[Isco08Info(
        level: 4,
        code: '4120',
        major_group: '4',
        sub_major_group: '41',
        minor_group: '412',
        unit_group: '4120',
        title: 'Secretaries (general)',
        definition: 'Secretaries (general) use typewriters, personal computers or other word-processing equipment to transcribe correspondence and other documents, check and format documents prepared by other staff, deal with incoming and outgoing mail, screen requests for meetings or appointments, and perform a variety of administrative support tasks.',
        tasks_include: "Tasks include -\n(a)  checking, formatting and transcribing correspondence, minutes and reports from dictation, electronic documents or written drafts to conform to office standards, using typewriter, personal computer or other word processing equipment;\n(b)  using various computer software packages including spreadsheets to provide administrative support;\n(c)  dealing with incoming or outgoing mail;\n(d)  scanning, recording and distributing mail, correspondence and documents;\n(e)  screening requests for meetings or appointments and helping to organize meetings;\n(f)  screening and recording staff-members' leave and other entitlements;\n(g)  organizing and supervising filing systems;\n(h)  dealing with routine correspondence on their own initiative.",
        excluded_occupations: "Some related occupations classified elsewhere:\n-  Legal secretary - 3342\n-  Administrative secretary - 3343\n-  Executive secretary - 3343\n-  Medical secretary - 3344",
        notes: null,
        occupational_titles: ['Secretary', 'Secretary, stenography', 'Secretary, typing', 'Secretary, word processing'],
