    #[Isco08Info(
        level: 4,
        code: '4213',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '421',
        unit_group: '4213',
        title: 'Pawnbrokers and Money-lenders',
        definition: 'Pawnbrokers and money-lenders lend money against articles deposited as pledges, or against property or other security.',
        tasks_include: "Tasks include -\n(a)  evaluating articles offered as pledges, calculating interest, and lending money;\n(b)  returning articles when the loan is paid or, in the event of non-payment, selling pledged articles;\n(c)  lending money as personal loans against success of future harvest and other similar undertakings;\n(d)  collecting loans when the pledge involved the success of future harvest and other similar undertakings;\n(e)  keeping a record of items received and money distributed and received.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Lender, money', 'Money-lender', 'Pawnbroker'],
