    #[Isco08Info(
        level: 4,
        code: '4221',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4221',
        title: 'Travel Consultants and Clerks',
        definition: 'Travel consultants and clerks provide information about travel destinations, arrange travel itineraries, obtain travel and accommodation reservations and register passengers at check-in and departure.',
        tasks_include: "Tasks include -\n(a)  obtaining information about the availability, cost and convenience of different types of transport and accommodation, ascertaining customer’s requirements and advising them on travel arrangements;\n(b) providing information about local and regional attractions, sightseeing tours, restaurants, arts and entertainment, and providing maps and brochures;\n(c)  preparing itineraries;\n(d)  making and confirming reservations for travel, tours and accommodation;\n(e)  issuing tickets, boarding passes and vouchers;\n(f)  helping customers in obtaining necessary travel documents such as visas;\n(g)  verifying travel documentation and registering passengers and luggage at check-in and departure;\n(h)  preparing bills and receiving payments.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Travel agency manager - 1439 \n- Conference and event planner - 3332\n- Tour operator - 3339\n- Tour escort - 5113\n- Tourist guide - 5113\n- Ticket issuing clerk (entertainment and sporting events) - 5230",
        notes: null,
        occupational_titles: ['Adviser, travel', 'Agent, booking: travel', 'Agent, check-in', 'Agent, ticket: airline', 'Agent, ticket: travel', 'Agent, travel', 'Attendant, airport: check-in', 'Attendant, check-in: airline', 'Clerk, bookings: travel', 'Clerk, check-in: airport', 'Clerk, information: travel', 'Clerk, reservations: travel', 'Clerk, ticket issuing: travel', 'Clerk, tourism information', 'Clerk, travel', 'Clerk, travel agency', 'Clerk, travel desk', 'Consultant, travel', 'Counsellor, tourism information', 'Counsellor, travel', 'Counsellor, visitor information', 'Officer, tourism information'],
        parent: '422',
        ancestors: ['4', '42', '422'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4221 = '4221';

    #[Isco08Info(
        level: 4,
        code: '4222',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4222',
        title: 'Contact Centre Information Clerks',
        definition: 'Contact centre information clerks provide advice and information to clients, respond to queries regarding a company’s or an organization’s goods, services or policies, and process financial transactions using the telephone or electronic communications media, such as email. They are located in premises that may be remote from clients or other operations of the organizations or companies about whom information is provided.',
        tasks_include: "Tasks include -\n(a)  dealing with incoming calls and messages from clients, whether to answer queries, handle calls for service or sort out complaints; \n(b)  identifying requirements and entering events into a computer system; \n(c)  dispatching tasks to other units, when relevant; \n(d)  invoicing or handling payments, where necessary;\n(e)  sending letters, information sheets and other documents to clients;\n(f)  advising clients of additional products or services.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Telephone operator - 4223\n- Market research interviewer - 4227\n- Call centre salesperson - 5244\n- Customer contact centre salesperson - 5244\n- Telemarketing salesperson - 5244",
        notes: "Only workers who respond to requests for information and\/or handle straightforward transactions are classified in Unit Group 4222, Contact Centre Information Clerks. Those who provide specialized services, such as travel consultants, are classified in the relevant specialized group whether or not they are located in customer contact centres.",
        occupational_titles: ['Agent, directory assistance', 'Assistant, call centre', 'Clerk, call centre', 'Clerk, customer contact centre', 'Clerk, information: call centre', 'Clerk, information: customer contact centre', 'Coach, call centre', 'Coach, contact centre', 'Coach, phone', 'Officer, customer service: call centre', 'Officer, customer service: directory assistance', 'Operator, call centre', 'Operator, directory assistance'],
        parent: '422',
        ancestors: ['4', '42', '422'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4222 = '4222';

    #[Isco08Info(
        level: 4,
        code: '4223',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4223',
        title: 'Telephone Switchboard Operators',
        definition: 'Telephone switchboard operators operate telephone communications switchboards and consoles to establish telephone connections, receive caller inquiries and service problem reports, and record and relay messages to staff or clients.',
        tasks_include: "Tasks include -\n(a)  operating switchboards and consoles to connect, hold, transfer, and disconnect telephone calls;\n(b)  making connections for outgoing calls;\n(c)  dealing with telephone inquiries and recording messages;\n(d)  forwarding messages to staff or clients;\n(e)  investigating operating system problems and informing repair services.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Operator, answering service', 'Operator, switchboard: telephone', 'Operator, telephone', 'Telephonist'],
        parent: '422',
        ancestors: ['4', '42', '422'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4223 = '4223';

    #[Isco08Info(
        level: 4,
        code: '4224',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4224',
        title: 'Hotel Receptionists',
        definition: 'Hotel receptionists welcome and register guests in hotels and other establishments that provide accommodation services. They assign rooms, issue keys, provide information concerning the services provided, make room reservations, keep a record of rooms available for occupancy and present statements of charges to departing guests and receive payment.',
        tasks_include: "Tasks include -\n(a)  maintaining an inventory of rooms available for occupancy, reservations and room assignments; \n(b)  registering arriving guests, assigning rooms; verifying customer’s credit and issuing room keys;\n(c)  providing information regarding hotel services and services available in the community;\n(d)  providing information about availability of accommodation and making room reservations;\n(e)  responding to guests’ requests for housekeeping and maintenance services as well as complaints; \n(f)  contacting housekeeping or maintenance services when guests report problems;\n(g)  compiling and checking guest accounts for charges using computerized or manual systems;\n(h)  receiving and forwarding messages in person or using telephone or telephone switchboard;\n(i)  reviewing statements of charges to departing guests and receiving payment.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Clerk, hotel front desk', 'Receptionist, hotel'],
        parent: '422',
        ancestors: ['4', '42', '422'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4224 = '4224';

    #[Isco08Info(
        level: 4,
        code: '4225',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4225',
        title: 'Inquiry Clerks',
        definition: 'Inquiry clerks respond to personal, written, electronic mail, and telephone inquiries and complaints about the organization’s goods, services and policies, provide information and refer people to other sources. They are employed in locations which put them in direct contact with clients or with the production of the goods and services provided.',
        tasks_include: "Tasks include -\n(a)  answering inquiries about goods services, and policy and providing information about their availability, location, price and related issues; \n(b)  responding to inquiries about problems and providing advice, information and assistance;\n(c)  recording information about inquiries and complaints;\n(d)  referring complex inquiries to team leaders or expert advisers;\n(e)  issuing relevant forms, information kits and brochures to interested parties.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Clerk, enquiry', 'Clerk, information', 'Clerk, inquiries: counter'],
        parent: '422',
        ancestors: ['4', '42', '422'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4225 = '4225';

    #[Isco08Info(
        level: 4,
        code: '4226',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4226',
        title: 'Receptionists (general)',
        definition: 'Receptionists (general) receive and welcome visitors, clients or guests and respond to inquiries and requests including arranging for appointments.',
        tasks_include: "Tasks include -\n(a)  receiving and welcoming visitors, guests or clients;\n(b)  making appointments for clients;\n(c)  dealing with telephone requests for information or appointments;\n(d)  directing clients to appropriate location or person;\n(e)  supplying information pamphlets, brochures or forms.",
        excluded_occupations: "Some related occupations classified elsewhere:\nMedical secretary - 3344\nHotel receptionist - 4224",
