    #[Isco08Info(
        level: 4,
        code: '4229',
        major_group: '4',
        sub_major_group: '42',
        minor_group: '422',
        unit_group: '4229',
        title: 'Client Information Workers Not Elsewhere Classified',
        definition: 'This unit group includes client information workers not included elsewhere in Minor Group 422: Client information workers. For instance, it includes workers who obtain and process information from clients needed to determine eligibility for services.',
        tasks_include: "In such cases tasks would include -\n(a)  interviewing patients to obtain and process information required to provide hospital services;\n(b)  interviewing applicants for public assistance to gather information pertinent to their application;\n(c)  verifying the accuracy of information provided;\n(d)  initiating procedures to grant, modify, deny or terminate assistance;\n(e)  providing information and answering questions concerning benefits and claims procedures;\n(f)  referring patients or applicants to other organizations if they are ineligible for services.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Clerk, hospital admissions', 'Clerk, ward', 'Consultant, eligibility', 'Interviewer, eligibility', 'Specialist, eligibility'],
