    #[Isco08Info(
        level: 4,
        code: '4311',
        major_group: '4',
        sub_major_group: '43',
        minor_group: '431',
        unit_group: '4311',
        title: 'Accounting and Bookkeeping Clerks',
        definition: 'Accounting and bookkeeping clerks compute, classify and record numerical data to keep financial records complete. They perform any combination of routine calculating, posting and verifying duties to obtain primary financial data for use in maintaining accounting records.',
        tasks_include: "Tasks include -\n(a)  checking figures, postings and documents for correct entry, mathematical accuracy and proper codes; \n(b)  operating computers programmed with accounting software to record, store and analyse information;\n(c)  classifying, recording and summarizing numerical and financial data to compile and keep financial records, using journals and ledgers or computers; \n(d)  calculating, preparing and issuing bills, invoices, account statements and other financial statements according to established procedures. \n(e)  compiling statistical, financial, accounting or auditing reports and tables pertaining to such matters as cash receipts, expenditures, accounts payable and receivable, and profits and losses.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Accounting assistant- 3313\n- Bookkeeper - 3313",
        notes: null,
        occupational_titles: ['Clerk, accounts', 'Clerk, auction', 'Clerk, bookkeeping', 'Clerk, cash-accounting', 'Clerk, cost computing', 'Clerk, invoice', 'Clerk, ledger', 'Clerk, office cash'],
        parent: '431',
        ancestors: ['4', '43', '431'],
        children: [],
        descendants: [],
    )]
    case ISCO08_4311 = '4311';

    #[Isco08Info(
        level: 4,
        code: '4312',
        major_group: '4',
        sub_major_group: '43',
        minor_group: '431',
        unit_group: '4312',
        title: 'Statistical, Finance and Insurance Clerks',
        definition: 'Statistical, finance and insurance clerks obtain, compile and compute statistical or actuarial data or perform clerical tasks relating to the transactions of insurance establishments, banks and other financial establishments.',
        tasks_include: "Tasks include -\n(a)  processing insurance enrolments, cancellations, claims transactions, policy changes and payments;\n(b)  obtaining and compiling statistical or actuarial data based on routine or special sources of information;\n(c)  calculating totals, averages, percentages and other details and presenting them in the required tabular form;\n(d)  preparing financial documents, and calculating interest or brokerage charges and stamp duties payable;\n(e)  maintaining records of bonds, shares and other securities bought or sold on behalf of clients or employer.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Stocks and shares broker- 3311\n- Accounting assistant- 3313\n- Statistical assistant- 3314\n- Trade broker- 3324\n- Accounts clerk - 4311\n- Bookkeeping clerk- 4311",
        notes: null,
        occupational_titles: ["Assistant, broker's", 'Assistant, insurance: adjustment', 'Assistant, insurance: claims', 'Assistant, insurance: policy', 'Clerk, actuarial', 'Clerk, adjustment', 'Clerk, audit', 'Clerk, bond', 'Clerk, brokerage', 'Clerk, collateral', 'Clerk, credit', 'Clerk, estimating', 'Clerk, finance', 'Clerk, insurance', 'Clerk, investment', 'Clerk, mortgage', 'Clerk, rating', 'Clerk, securities', 'Clerk, statistical', 'Clerk, tax'],
