    #[Isco08Info(
        level: 4,
        code: '4313',
        major_group: '4',
        sub_major_group: '43',
        minor_group: '431',
        unit_group: '4313',
        title: 'Payroll Clerks',
        definition: 'Payroll clerks collect, verify and process payroll information and compute pay and benefit entitlements for employees within a department, company or other establishment.',
        tasks_include: "Tasks include -\n(a)  maintaining records of employee attendance, leave and overtime to calculate pay and benefit entitlements, using manual or computerized systems;\n(b)  preparing and verifying statements of earnings for employees, indicating gross and net salaries and deductions such as taxes, union dues, garnishments and insurance and pension plans; \n(c)  preparing employee payments and benefit payments by cheque or electronic transfer; \n(d)  reviewing time sheets, work charts, wage computation and other information to detect and reconcile payroll discrepancies; \n(e)  verifying attendance, hours worked and pay adjustments, and posting information onto designated records.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Accounting assistant- 3313\n- Bookkeeper - 3313\n- Accounts clerk - 4311\n- Bookkeeping clerk- 4311",
        notes: null,
        occupational_titles: ['Clerk, payroll', 'Clerk, salaries', 'Clerk, wages'],
