    #[Isco08Info(
        level: 4,
        code: '4413',
        major_group: '4',
        sub_major_group: '44',
        minor_group: '441',
        unit_group: '4413',
        title: 'Coding, Proofreading and Related Clerks',
        definition: 'Coding, proofreading and related clerks convert information into codes, verify and correct proofs, and perform a number of miscellaneous clerical duties.',
        tasks_include: "Tasks include -\n(a)  converting information into codes and classifying information by codes for data-processing purposes;\n(b)  comparing proofs of texts and related material prepared for printing with original material, correcting errors and marking texts for printer according to the established rules;\n(c)  sorting forms and marking them with identification numbers; \n(d)  sorting documents for filing or to collate sets of pages; \n(e)  addressing circulars and envelopes by hand.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Clerk, classification: data processing', 'Clerk, classification: statistics', 'Clerk, coding', 'Clerk, coding: data-processing', 'Clerk, coding: statistics', 'Clerk, listing', 'Clerk, proofreading', 'Clerk, scripts', 'Coder, clerical', 'Coder, data-processing', 'Coder, statistics', 'Proofreader', 'Reader, proof'],
