    #[Isco08Info(
        level: 4,
        code: '4415',
        major_group: '4',
        sub_major_group: '44',
        minor_group: '441',
        unit_group: '4415',
        title: 'Filing and Copying Clerks',
        definition: 'Filing and copying clerks file correspondence, cards, invoices, receipts and other records in alphabetical or numerical order or according to the filing system used. They locate and remove material from file when requested and photocopy, scan or fax documents.',
        tasks_include: "Tasks include - \n(a)  sorting or classifying materials according to guidelines such as content, purpose, user criteria, or chronological, alphabetical, or numerical order;\n(b)  filing material in drawers, cabinets and storage boxes;\n(c)  locating and remove materials from files when requested;\n(d)  keeping records of materials filed and removed;\n(e)  photocopying, scanning or faxing documents.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Clerk, copying', 'Clerk, document duplication', 'Clerk, filing', 'Clerk, photocopying', 'Clerk, reproduction processes: office'],
