    #[Isco08Info(
        level: 4,
        code: '4416',
        major_group: '4',
        sub_major_group: '44',
        minor_group: '441',
        unit_group: '4416',
        title: 'Personnel Clerks',
        definition: 'Personnel clerks maintain and update personnel records such as information on transfers and promotions, performance evaluations, employee leave taken and accumulated, salaries, qualifications and training.',
        tasks_include: "Tasks include -\n(a)  updating information on, employment history, salaries, performance evaluations, qualifications and training and leave taken and accumulated;\n(b)  initiating records for newly appointed workers and checking records for completeness;\n(c)  processing applications for employment and promotions and advising applicants of results;\n(d)  receiving and answering inquiries about employment entitlements and conditions;\n(e)  sending out job applications and announcements of job openings and job examinations;\n(f)  maintaining and updating manual and computerized filing and registration systems, and compiling and preparing reports and documents relating to personnel activities;\n(g)  storing and retrieving personnel records and files on request.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Assistant, human resource', 'Clerk, human resources', 'Clerk, leave', 'Clerk, personnel', 'Clerk, records: personnel', 'Clerk, recruitment', 'Clerk, roster', 'Clerk, rostering workers', 'Clerk, staff', 'Coordinator, crewing', 'Officer, crewing', 'Officer, rostering', 'Programmer, workforce', 'Scheduler, crew'],
