    #[Isco08Info(
        level: 4,
        code: '4419',
        major_group: '4',
        sub_major_group: '44',
        minor_group: '441',
        unit_group: '4419',
        title: 'Clerical Support Workers Not Elsewhere Classified',
        definition: 'This unit group covers clerical support workers not classified elsewhere in Major Group 4: Clerical Support Workers. For instance, the group includes, correspondence clerks, press clippers and publication clerks.',
        tasks_include: "In such cases tasks would include -\n(a)  receiving customers' orders for classified advertising, writing and editing copy, calculating advertising rates and billing customers;\n(b)  writing business and government correspondence such as replies to requests for information and assistance, damage claims, credit and billing enquiries and service complaints;\n(c)  assisting in the preparation of periodicals, advertisements, catalogues, directories and other material for publication; \n(d)  reading newspapers, magazines, press releases and other publications to locate and file articles of interest to staff and clients.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Clerk, addressing machine', 'Clerk, advertising', 'Clerk, classified advertising', 'Clerk, compilation: directory', 'Clerk, correspondence', 'Clerk, list: addresses', 'Clerk, list: mail', 'Clerk, publication', 'Clipper, press', 'Compiler, directory'],
