    #[Isco08Info(
        level: 4,
        code: '5111',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '511',
        unit_group: '5111',
        title: 'Travel Attendants and Travel Stewards',
        definition: 'Travel attendants and travel stewards ensure the comfort and safety of passengers, serve meals and beverages and render personal services, usually on aircraft and on board ships. They may plan and coordinate housekeeping and social activities on ships.',
        tasks_include: "Tasks include -\n(a)  greeting passengers entering aircraft or ships, checking tickets or boarding passes, and directing them to their seats or berths;\n(b)  announcing, explaining and demonstrating safety and emergency procedures, such as the use of oxygen masks, seat belts, and life jackets;\n(c)  assembling and serving pre-prepared meals and  beverages;\n(d)  selling duty-free and other goods;\n(e)  taking care of general needs and comfort of passengers, answering inquiries, and keeping cabins clean and tidy;\n(f)  directing and assisting passengers and following prescribed procedures in the event of an emergency, such as evacuating an aircraft following an emergency landing;\n(g)  verifying that first aid kits and other emergency equipment are in working order;\n(h)  administering first aid to passengers in distress;\n(i)  attending pre-flight briefings concerning weather, altitudes, routes, emergency procedures, crew coordination, lengths of flights, food and beverage services offered, and numbers of passengers;\n(j)  preparing passengers and aircraft for take-off and landing;\n(k)  determining special assistance needs of passengers such as small children, the elderly, or disabled persons.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Attendant, cabin', 'Attendant, flight', 'Hostess, air', 'Purser, aircraft', 'Purser, flight', 'Steward, cabin', 'Steward, chief: ship', "Steward, ship's", 'Stewardess, cabin', 'Stewardess, chief: ship', 'Stewardess, ship'],
        parent: '511',
        ancestors: ['5', '51', '511'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5111 = '5111';

    #[Isco08Info(
        level: 4,
        code: '5112',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '511',
        unit_group: '5112',
        title: 'Transport Conductors',
        definition: 'Transport conductors check and issue tickets and ensure the safety and comfort of passengers on trains, trams, buses and other public transport vehicles.',
        tasks_include: "Tasks include -\n(a)  collecting and issuing tickets, passes or fares, and checking the validity of tickets issued previously;\n(b)  attending to sleeping-cars and their occupants on passenger trains;\n(c)  providing assistance with boarding, seating and luggage as required, especially to elderly, sick, or injured people;\n(d)  opening and closing doors for passengers;\n(e)  performing equipment safety checks prior to departure;\n(f)  signalling to drivers to stop or proceed;\n(g)  greeting passengers boarding transportation equipment, and announcing routes and stops.\n(h)  ensuring that safety regulations are respected;\n(i)  responding to passengers requests and complaints and providing information about stops and connections;\n(j)  taking appropriate action in case of emergencies or accidents.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Attendant, pullman car', 'Attendant, sleeping car', 'Conductor, bus', 'Conductor, cable car', 'Conductor, ferryboat', 'Conductor, hovercraft', 'Conductor, pullman car', 'Conductor, sleeping car', 'Conductor, train', 'Conductor, tram', 'Conductor, trolley-bus', 'Guard, train: passengers', 'Inspector, ticket: public transport'],
        parent: '511',
        ancestors: ['5', '51', '511'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5112 = '5112';

    #[Isco08Info(
        level: 4,
        code: '5113',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '511',
        unit_group: '5113',
        title: 'Travel Guides',
        definition: 'Travel guides accompany individuals or groups on trips, sightseeing tours and excursions and on tours of places of interest such as historical sites, industrial establishments and theme parks. They describe points of interest and provide background information on interesting features.',
        tasks_include: "Tasks include -\n(a)  escorting and guiding tourists on cruises and sightseeing tours;\n(b)  escorting visitors through places of interest such as museums, exhibitions, theme parks, factories and other industrial establishments;\n(c)  describing and providing information on points of interest and exhibits and responding to questions;\n(d)  conducting educational activities for school children;\n(e)  monitoring visitors' activities to ensure compliance with establishment or tour regulations and safety practices;\n(f)  greeting and registering visitors and tour participants, and issuing any required identification badges or safety devices;\n(g)  distributing brochures, showing audiovisual presentations, and explaining procedures and operations at tour sites;\n(h)  providing for physical safety of groups, and performing activities such as providing first aid and directing emergency evacuations;\n(i)  resolving any problems with tour itineraries, service, or accommodation.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Director, tour', 'Docent', 'Educator, museum', 'Escort, tour', 'Guide, art gallery', 'Guide, discovery', 'Guide, industrial establishment', 'Guide, museum', 'Guide, nature park', 'Guide, safari', 'Guide, sightseeing', 'Guide, theme park', 'Guide, tour', 'Guide, tourist', 'Guide, travel', 'Interpreter, historical', 'Interpreter, science', 'Manager, tour'],
        parent: '511',
        ancestors: ['5', '51', '511'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5113 = '5113';

    #[Isco08Info(
        level: 4,
        code: '5120',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '512',
        unit_group: '5120',
        title: 'Cooks',
        definition: 'Cooks plan, organize, prepare and cook meals, according to recipes or under the supervision of chefs, in hotels, restaurants and other eating places, on board ships, on passenger trains and in private households.',
        tasks_include: "Tasks include -\n(a)  planning meals, preparing and cooking foodstuffs;\n(b)  planning, supervising and coordinating the work of kitchen helpers;\n(c)  checking the quality of food;\n(d)  weighing, measuring and mixing ingredients according to recipes and personal judgement;\n(e)  regulating the temperature of ovens, grills, roasters and other cooking equipment\n(f)  inspecting and cleaning the kitchen, kitchen equipment and serving areas, to ensure safe and sanitary food handling practices;\n(g)  operating large-volume cooking equipment such as grills, deep-fat fryers or griddles.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Cafe manager - 1412 \n- Restaurant manager - 1412\n- Chef - 3434\n- Fast food preparer - 9411",
        notes: 'Operators of small cafes, restaurants and bars for whom the management and supervision of staff is not a significant component of the work, are classified in Unit Groups 5120: Cooks, 5131: Waiters or 5132: Bartenders, depending on the main tasks performed.',
        occupational_titles: ['Cook', 'Cook, mess', 'Cook, restaurant', 'Cook, ship', 'Cook, special diets', 'Cook, vegetable', 'Cook, work camp'],
        parent: '512',
        ancestors: ['5', '51', '512'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5120 = '5120';

    #[Isco08Info(
        level: 4,
        code: '5131',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '513',
        unit_group: '5131',
        title: 'Waiters',
        definition: 'Waiters serve food and beverages at tables in dining and drinking places, clubs, institutions and canteens, on board ships and on passenger trains.',
        tasks_include: "Tasks include -\n(a)  setting tables with clean linen, cutlery, crockery and glassware;\n(b)  greeting customers and presenting them with menus and beverage lists;\n(c)  advising on food and beverage choices;\n(d)  taking orders for food and drinks and passing order to kitchen or bar staff;\n(e)  serving food and beverages to clients at tables;\n(f)  clearing tables and returning dishes and cutlery to kitchen;\n(g)  presenting bills, accepting payment and operating point of sales machines and cash registers.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Cafe manager -1412 \n- Restaurant manager - 1412\n- Bartender - 5132",
        notes: 'Operators of small cafes, restaurants and bars for whom the management and supervision of staff is not a significant component of the work, are classified in Unit Groups 5120: Cooks, 5131: Waiters or 5132: Bartenders, depending on the main tasks performed.',
