    #[Isco08Info(
        level: 4,
        code: '5132',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '513',
        unit_group: '5132',
        title: 'Bartenders',
        definition: 'Bartenders prepare, mix and serve alcoholic and non-alcoholic drinks directly to customers over a bar or counter, or through waiters.',
        tasks_include: "Tasks include -\n(a)  taking beverage orders from serving staff or directly from patrons;\n(b)  preparing and serving alcoholic and non-alcoholic drinks at a bar;\n(c)  washing used glassware, cleaning and maintaining bar service areas, tea and coffee-making areas and equipment such as espresso machines;\n(d)  collecting payment for sales, operating cash registers and balancing cash receipts;\n(e)  tapping kegs and attaching supply lines;\n(f)  assisting in keeping bar properly stocked and arranging bottles and glasses;\n(g)  checking identification of customers to verify age requirements for purchase of alcohol;\n(h)  taking steps to limit problems related to excessive drinking such, as persuading customers to stop drinking, declining further service and ordering transportation;\n(i)  mixing ingredients to prepare cocktails and other drinks;\n(j)  serving snacks or other food items to customers at the bar.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Café manager -1412 \n- Restaurant manager - 1412\n- Waiter - 5131",
        notes: 'Operators of small cafes, restaurants and bars for whom the management and supervision of staff is not a significant component of the work, are classified in Unit groups 5120: Cooks, 5131: Waiters or 5132: Bartenders, depending on the main tasks performed.',
        occupational_titles: ['Attendant, bar: drinks service', 'Barista', 'Barkeeper', 'Barmaid', 'Barman', 'Bartender'],
        parent: '513',
        ancestors: ['5', '51', '513'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5132 = '5132';

    #[Isco08Info(
        level: 4,
        code: '5141',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '514',
        unit_group: '5141',
        title: 'Hairdressers',
        definition: 'Hairdressers cut, style, colour, straighten and permanently wave hair, shave or trim facial hair and treat scalp conditions.',
        tasks_include: "Tasks include -\n(a)  cutting, washing, tinting and waving hair;\n(b)  shaving or trimming beards and moustaches;\n(c)  giving scalp treatment;\n(d)  fitting wigs according to customers’ requirements;\n(e)  providing advice on hair care, beauty products and hairstyles;\n(f)  styling hair into dreadlocks and braids and adding hair extensions;\n(g)  arranging appointments and collecting payments;\n(h)  cleaning work areas and sanitizing instruments.",
        excluded_occupations: null,
