    #[Isco08Info(
        level: 4,
        code: '5152',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '515',
        unit_group: '5152',
        title: 'Domestic Housekeepers',
        definition: 'Domestic housekeepers organize, supervise and carry out housekeeping functions in private households and small accommodation establishments with or without the support of subordinate staff.',
        tasks_include: "Tasks include -\n(a)  supervising workers employed in households as domestic staff;\n(b)  purchasing or controlling the purchase of supplies;\n(c)  controlling storage and issue of supplies;\n(d)  assisting in cases of minor injury or illness by performing tasks such as taking temperature, giving medicine, putting on bandages;\n(e)  sweeping or vacuum-cleaning, washing and polishing floors, furniture and other fixtures.\n(f)  making beds, cleaning bathrooms, supplying towels, soap and related items;\n(g)  taking care of household pets and plants, receiving visitors, answering telephones, delivering messages and shopping for groceries;\n(h)  preparing and cooking meals, setting and clearing tables and serving food and beverages.\n(i)  cleaning kitchens and generally helping with kitchen work, including dishwashing.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Hotel manager - 1411\n- Domestic helper - 9111",
        notes: 'Operators of small accommodation establishments, such as some bed and breakfast establishments and small guest houses, that provide accommodation and limited meal services to clients effectively as paying guests in private households, and for whom the management and supervision of staff is not a significant component of the work, are classified in Unit Group 5152: Domestic housekeepers.',
        occupational_titles: ['Butler', 'Housekeeper, domestic', 'Keeper, house: domestic', 'Operator, bed and breakfast', 'Operator, guest house'],
        parent: '515',
        ancestors: ['5', '51', '515'],
        children: [],
