    #[Isco08Info(
        level: 4,
        code: '5163',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '516',
        unit_group: '5163',
        title: 'Undertakers and Embalmers',
        definition: 'Undertakers and embalmers arrange funerals and  perform various tasks in the disposal of  human bodies.',
        tasks_include: "Tasks include -\n(a)  making arrangements for, and conducting, funerals, cremations and burials;\n(b)  embalming human bodies to retard or arrest the process of decay;\n(c)  conforming to health and sanitation and ensuring that legal requirements concerning embalming are met;\n(d)  incising and closing incisions on various parts of the body and reshaping or reconstructing disfigured or maimed bodies when necessary;\n(e)  dressing bodies and placing them in caskets;\n(f)  conducting interviews to arrange for preparation of obituary notices, to assist with the selection of caskets or urns, and to determine the location and time of burials or cremations.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Attendant, funeral', "Attendant, undertaker's", 'Director, funeral', 'Embalmer', 'Mortician', 'Undertaker'],
        parent: '516',
        ancestors: ['5', '51', '516'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5163 = '5163';

    #[Isco08Info(
        level: 4,
        code: '5164',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '516',
        unit_group: '5164',
        title: 'Pet Groomers and Animal Care Workers',
        definition: 'Pet groomers and animal care workers feed, handle, train and groom animals and assist veterinarians, animal health technologists and technicians in veterinary facilities, animal shelters, breeding and boarding kennels, zoos, laboratories, retail pet shops, riding schools, dog training schools pet grooming and similar establishments.',
        tasks_include: "Tasks include -\n(a)  bathing and feeding animals;\n(b)  leading or carrying animals to treatment room and holding them during treatment;\n(c)  cleaning and sterilising veterinary surgical instruments;\n(d)  labelling drugs, chemicals and other pharmaceutical preparations and replenishing stock;\n(e)  sterilising bottles, beakers and other equipment;\n(f)  cleaning, organizing, and disinfecting animal quarters such as pens, stables, cages and yards, and animal equipment such as saddles and bridles;\n(g)  collecting and recording animal information such as weight, size, physical condition, treatments received, medications given and food intake;\n(h)  training animals to develop and maintain desired behaviours for competition, entertainment, obedience, security, riding and other activities;\n(i)  grooming animals by performing tasks such as washing, brushing, clipping, and trimming coats, cutting nails and cleaning ears.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Aide, veterinary', 'Attendant, animal', 'Attendant, kennel', 'Attendant, laboratory: animal', 'Breaker, horse', 'Breeder, laboratory: animal', 'Gamekeeper', 'Horse-breaker', 'Keeper, animal reserve', 'Keeper, aviary', 'Keeper, kennel', 'Keeper, zoo', 'Raiser, laboratory: animal', 'Trainer, dog', 'Trainer, horse', 'Trainer, horse-breaking', 'Trainer, racehorse', 'Worker, kennel', 'Worker, kennel: skilled', 'Worker, laboratory: skilled (animals)', 'Worker, zoo: skilled', 'Zookeeper'],
        parent: '516',
        ancestors: ['5', '51', '516'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5164 = '5164';

