    #[Isco08Info(
        level: 4,
        code: '5169',
        major_group: '5',
        sub_major_group: '51',
        minor_group: '516',
        unit_group: '5169',
        title: 'Personal Services Workers Not Elsewhere Classified',
        definition: 'This unit group covers personal service workers not classified elsewhere in Sub-major Group 51: Personal Service Workers. For instance, those who provide services and companionship as dancing partners, social escorts and night-club hostesses or hosts are classified here.',
        tasks_include: "In such cases tasks would include -\n(a)  accompanying clients to restaurants and other outings;\n(b)  acting as a dancing partner;\n(c)  welcoming clients to a night-club and ensuring that they are entertained well.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Companion - 5162",
        notes: 'Countries that have a requirement to compile statistics on those who provide sexual services to clients on a commercial basis should include them in Unit Group 5169: Personal Service Workers Not Elsewhere Classified. If there is a need, in national adaptations of ISCO-08, to identify this group separately from other occupations included in Unit Group 5169, use of Unit Group code 5168 is recommended for this purpose.',
        occupational_titles: ['Escort, social', 'Hooker, providing sexual services', 'Host, club', 'Hostess, club', 'Partner, dancing', 'Prostitute', 'Worker, sex: providing sexual services'],
        parent: '516',
        ancestors: ['5', '51', '516'],
