    #[Isco08Info(
        level: 4,
        code: '5230',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '523',
        unit_group: '5230',
        title: 'Cashiers and Ticket Clerks',
        definition: 'Cashiers and ticket clerks operate cash registers, optical price scanners, computers or other equipment to record and accept payment for the purchase of goods, services and admissions in settings such as stores, restaurants and ticket offices.',
        tasks_include: "Tasks include -\n(a)  receiving and verifying payment by cash, cheque, credit card or automatic debit in stores, ticket offices or similar establishments;\n(b)  giving change and issuing receipts;\n(c)  issuing tickets for attendance at sporting and cultural events;\n(d)  counting and recording money received or paid out and balancing against cash register sales records;\n(e)  receiving incoming cash, checking it against sales slips and other documents, and preparing it for deposit at financial institute;\n(f)  operating cash register to calculate total to be paid from or to clients;\n(g)  scanning, weighing and recording prices of goods;\n(h)  wrapping and placing merchandise in bags.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ticket issuing clerk (travel) - 4221\n- Shop sales assistant - 5223\n- Service station attendant - 5245\n- Checkout supervisor - 5222",
