    #[Isco08Info(
        level: 4,
        code: '5244',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '524',
        unit_group: '5244',
        title: 'Contact Centre Salespersons',
        definition: 'Contact centre salespersons contact existing and prospective customers, using the telephone or other electronic communications media, to promote goods and services, obtain sales and arrange sales visits. They may work from a customer contact centre or from non-centralised premises.',
        tasks_include: "Tasks include -\n(a)  promoting goods and services by telephone or electronic mail, following scripts and working from lists of contacts;\n(b)  creating interest in goods and services, and seeking a sale or agreement to see sales representatives;\n(c)  arranging processing and despatch of goods and services, information kits and brochures to customers;\n(d)  arranging appointments for sales representatives;\n(e)  recording notes for follow-up action and updating marketing databases to reflect changes to the status of each customer;\n(f)  reporting competitor activities and issues raised by contacts for attention by managers;\n(g)  maintaining statistics of calls made and successes achieved;\n(h)  submitting periodic reports on telemarketing activities and results.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Contact centre information clerk - 4222",
        notes: null,
        occupational_titles: ['Consultant, sales: outbound calls', 'Consultant, sales: telemarketing', 'Consultant, telesales: cold calling', 'Consultant, telesales: outbound calls', 'Manager, sales: call centre', 'Manager, sales team: call centre', 'Marketer, telemarketing', 'Marketer, telesales', 'Operator, call centre: cold calling', 'Operator, call centre: outbound calls', 'Operator, telephone: canvassing', 'Operator, telephone: telemarketing', 'Representative, telephone: canvassing for donations', 'Salesperson, call centre', 'Salesperson, canvassing on telephone', 'Salesperson, customer contact centre', 'Salesperson, internet', 'Salesperson, telemarketing', 'Salesperson, telephone', 'Seller, Ebay', 'Telemarketer', 'Trader, Ebay', 'Worker, sex: telephone or internet'],
        parent: '524',
        ancestors: ['5', '52', '524'],
