    #[Isco08Info(
        level: 4,
        code: '5245',
        major_group: '5',
        sub_major_group: '52',
        minor_group: '524',
        unit_group: '5245',
        title: 'Service Station Attendants',
        definition: 'Service station attendants sell fuel, lubricants and other automotive products and provide services such as fuelling, cleaning, lubricating and performing minor repairs to motor vehicles.',
        tasks_include: "Tasks include -\n(a)  filling fuel tanks and containers to level specified by customer; \n(b)  checking and replenishing air pressure in vehicle tyres, and oil and other vehicle fluid levels; \n(c)  washing vehicle windscreens and windows;\n(d)  performing minor repair work to vehicles such as replacing tyres, light bulbs and windscreen wiper blades;\n(e)  maintaining and operating automatic car wash facilities;\n(f)  collecting payments from customers for purchases;\n(g)  cleaning petrol pumps and surrounding driveway, shop and facilities; \n(h)  undertaking stock control and preparing reports on fuel, oil, accessories and other items sold.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Shop sales assistant - 5223\n- Service station cashier - 5230\n- Food service counter attendant - 5246",
        notes: 'Workers who accept payment or sell goods in shops at service stations but do not provide forecourt services such as assistance with fuel, lubricants, cleaning and maintenance are excluded from Unit Group 5245: Service Station Attendants.',
        occupational_titles: ['Attendant, driveway', 'Attendant, gas station: gas pump', 'Attendant, marina', 'Attendant, petrol pump', 'Attendant, service station', 'Attendant, service station: petrol pump'],
        parent: '524',
        ancestors: ['5', '52', '524'],
