    #[Isco08Info(
        level: 4,
        code: '5311',
        major_group: '5',
        sub_major_group: '53',
        minor_group: '531',
        unit_group: '5311',
        title: 'Child Care Workers',
        definition: 'Child care workers provide care and supervision for children in residential homes and in before-school, after-school, vacation and day care centres.',
        tasks_include: "Tasks include -\n(a)  assisting children to wash, dress and feed themselves;\n(b)  taking children to and from school or outdoors for recreation;\n(c)  playing games with children, or entertaining them by reading or storytelling;\n(d)  assisting in the preparation of materials and equipment for children's education and recreational activities;\n(e)  managing children's behaviour and guiding their social development;\n(f)  disciplining children and recommending or initiating other measures to control behaviour, such as caring for own clothing and picking up toys and books;\n(g)  observing and monitoring children's play activities;\n(h)  keeping records on individual children, including daily observations and information about activities, meals served, and medications administered.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Early childhood educator - 2342",
        notes: null,
        occupational_titles: ['Assistant, day care: children', 'Ayah, creche', 'Ayah, home', 'Babysitter', 'Carer, child', 'Governess, children', 'Nanny', 'Nursemaid', 'Sitter, baby', 'Worker, child care', 'Worker, family day care', 'Worker, out of school hours care'],
        parent: '531',
        ancestors: ['5', '53', '531'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5311 = '5311';

    #[Isco08Info(
        level: 4,
        code: '5312',
        major_group: '5',
        sub_major_group: '53',
        minor_group: '531',
        unit_group: '5312',
        title: "Teachers' Aides",
        definition: "Teachers' aides perform non-teaching duties to assist teaching staff, and provide care and supervision for children in schools and pre-schools.",
        tasks_include: "Tasks include -\n(a)  demonstrating, supervising and participating in activities that enhance the physical, social, emotional and intellectual development of children in schools and pre-schools;\n(b)  preparing indoor and outdoor areas for learning and recreational activities;\n(c)  assisting children with intellectual, physical, behavioural and other learning difficulties with their studies;\n(d)  assisting children individually to learn social skills;\n(e)  assisting with preparing teaching materials, and copying and collating written and printed material;\n(f)  operating audio-visual equipment, computers and other teaching aides;\n(g)  distributing and collecting lesson material.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Aide, pre-school', "Aide, teacher's", 'Assistant, pre-school', "Assistant, teacher's", 'Attendant, schoolchildren', 'Helper, pre-school', "Helper, teacher's", 'Invigilator'],
        parent: '531',
        ancestors: ['5', '53', '531'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5312 = '5312';

    #[Isco08Info(
        level: 4,
        code: '5321',
        major_group: '5',
        sub_major_group: '53',
        minor_group: '532',
        unit_group: '5321',
        title: 'Health Care Assistants',
        definition: 'Health care assistants provide direct personal care and assistance with activities of daily living to patients and residents in a variety of health care settings such as hospitals, clinics and residential nursing care facilities. They generally work in implementation of established care plans and practices, and under the direct supervision of medical, nursing or other health professionals or associate professionals.',
        tasks_include: "Tasks include -\n(a) providing care, support and treatment to patients and residents of medical, rehabilitative and residential care facilities according to treatment plans established by medical, nursing and other health professionals;\n(b)  assisting patients with personal and therapeutic care needs such as personal hygiene, feeding, dressing, physical mobility and exercise, communication, taking oral medications and changing dressings;\n(c)  positioning, lifting and turning patients and transporting them in wheelchairs or on movable beds;\n(d)  maintaining patients' environmental hygiene standards, such as cleaning patient rooms and changing bed linen;\n(e)  providing massage and other non-pharmacological pain relief measures, such as during pregnancy and labour;\n(f)  observing patients’ condition, responses and behaviour and reporting changes to a health professional.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Nurse (professional) - 2221\n- Nurse (associate professional) - 3221\n- Ambulance worker - 3258\n- Nursing aide (home) - 5322",
        notes: 'Workers who provide personal care to residents of institutions and facilities that have permanent medical or nursing supervision (such as hospitals, rehabilitation centres, residential nursing care facilities and nursing homes), and therefore work under the direct supervision of nurses, medical doctors or other health professionals or associate professionals are classified in Unit Group 5321: Health Care Assistants. Workers who provide personal care to residents of independent living units, generally without permanent medical or nursing supervision, should be classified in Unit Group 5322: Home-based personal care workers. In general, workers classified in Minor Group 532: Personal Care Workers in Health Services, do not perform tasks requiring extensive medical knowledge or training, such as administering medications and cleaning and dressing wounds: where tasks of this type are performed they are of a simple and routine nature.',
        occupational_titles: ['Aide, nursing: clinic', 'Aide, nursing: hospital', 'Aide, psychiatric', 'Assistant, birth: clinic or hospital', 'Assistant, midwifery: clinic or hospital', 'Assistant, patient care', 'Attendant, birth: clinic or hospital', 'Attendant, hospital', 'Attendant, midwifery: clinic or hospital', 'Attendant, nursing: except home', 'Ayah, hospital'],
        parent: '532',
        ancestors: ['5', '53', '532'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5321 = '5321';

    #[Isco08Info(
        level: 4,
        code: '5322',
        major_group: '5',
        sub_major_group: '53',
        minor_group: '532',
        unit_group: '5322',
        title: 'Home-based Personal Care Workers',
        definition: 'Home-based personal care workers provide routine personal care and assistance with activities of daily living to persons who are in need of such care due to effects of ageing, illness, injury, or other physical or mental condition in private homes and other independent residential settings.',
        tasks_include: "Tasks include -\n(a)  assisting clients with personal and therapeutic care needs such as personal hygiene, feeding, dressing, physical mobility and exercise, communication, taking oral medications and changing dressings, usually as per care plans established by a health professional\n(b)  maintaining records of client care, changes in condition and responses to care and treatment, and reporting concerns or providing referrals to a health or social services professional; \n(c)  positioning and lifting clients with physical mobility challenges, and helping transport them in wheelchairs and motor vehicles; \n(d)  providing clients and families with emotional support and information and advice on topics such as nutrition, hygiene, exercise, caring for infants or adapting to disability or illness; \n(e)  maintaining clients' environmental hygiene standards, such as changing bed linen, washing clothes and dishes, and cleaning living quarters; \n(f)  providing psychological support to clients such as through conversation or reading aloud; \n(g)  planning, purchasing, preparing, or serving meals to meet nutritional requirements and prescribed diets;\n(h)  providing support to parents and care for newborns during the postpartum period\n(i)  scheduling and accompanying clients for appointments with medical doctors and other health professionals or performing other errands.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Nurse (professional) - 2221\n- Social worker (professional) - 2635\n- Nurse (associate professional) - 3221\n- Social worker (associate professional) - 3412\n- Nursing aide (clinic or hospital) - 5321",
        notes: 'Workers who provide personal care to residents of medical and health care facilities that have permanent medical or nursing supervision (such as in hospitals and nursing care homes), and therefore work under the direct supervision of health professionals or associate professionals, are classified in Unit Group 5321: Health Care Assistants. Workers who provide personal care in independent residential settings (including retirement communities with minimal or no on-site medical or nursing supervision), are classified in Unit Group 5322: Home-based Personal Care Workers. Home birth assistants, who provide emotional support and general care and advice to women and families during pregnancy and labour, but not delivery care to reduce health risks, are included here. Care workers who provide care and supervision for children in residential home and care centres are classified in Unit Group 5311: Child Care Workers.',
        occupational_titles: ['Aide, home care', 'Aide, nursing: home', 'Assistant, birth: home', 'Assistant, day care: aged or disabled', 'Assistant, homecare: aged or disabled', 'Assistant, residential care: aged or disabled', 'Assistant, respite care', 'Attendant, birth: home birth', 'Attendant, midwifery: home birth', 'Attendant, nursing: home', 'Carer, home: aged or disabled persons', 'Carer, respite', 'Companion, aged care', 'Companion, disabled', 'Helper, aged care', 'Helper, companion', 'Helper, home: caring for aged or infirm', 'Provider, personal care', 'Worker, home care', 'Worker, home support', 'Worker, personal care: home', 'Worker, respite care'],
        parent: '532',
        ancestors: ['5', '53', '532'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5322 = '5322';

    #[Isco08Info(
        level: 4,
        code: '5329',
        major_group: '5',
        sub_major_group: '53',
        minor_group: '532',
        unit_group: '5329',
        title: 'Personal Care Workers in Health Services Not Elsewhere Classified',
        definition: 'This unit group covers providers of routine health and personal care support services not classified elsewhere in Minor Group 532: Personal Care Workers in Health Services. For instance, the group includes occupations such as dental aide, sterilization aide, hospital orderly, medical imaging assistant and pharmacy aide.',
        tasks_include: "In such cases tasks would include -\n(a)  cleaning and sterilizing surgical, dental and pharmaceutical instruments, bottles, beakers and other equipment;\n(b)  labelling drugs, chemicals and other pharmaceutical preparations and replenishing stock on shelves;\n(c)  lifting, turning and moving patients and transporting them in wheelchairs or on moveable beds;\n(d)  preparing patients for examination or treatment;\n(e)  setting  up instrument trays, preparing materials, and assisting dentists or radiographers during procedures;\n(f)  exposing diagnostic X-rays.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Pharmaceutical assistant - 3213\n- Dental technician - 3214\n- Dental assistant - 3251",
        notes: null,
        occupational_titles: ['Aide, dental', 'Aide, pharmacy', 'Aide, sterilization', 'Assistant, medical imaging', 'Attendant, dental', 'Attendant, first aid', 'Attendant, ward', 'Orderly, hospital', 'Phlebotomist', 'Wardsman', 'Wardswoman'],
        parent: '532',
        ancestors: ['5', '53', '532'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5329 = '5329';

    #[Isco08Info(
        level: 4,
        code: '5411',
        major_group: '5',
        sub_major_group: '54',
        minor_group: '541',
        unit_group: '5411',
        title: 'Fire Fighters',
        definition: 'Fire fighters prevent, fight and extinguish fires and assist in other emergencies, protect life and property and conduct rescue efforts.',
        tasks_include: "Tasks include -\n(a)  responding to fire alarms and other calls for assistance, such as automobile and industrial accidents, bomb threats and other emergencies;\n(b)  controlling and extinguishing fires using manual and power equipment and fire-fighting chemicals;\n(c)  fighting special types of fires and using special equipment in industrial establishments;\n(d)  rescuing people from burning buildings and accident sites and those trapped in dangerous situations;\n(e)  preventing or limiting the spread of dangerous substances in case of fires or accidents;\n(f)  informing the public about fire prevention.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Fire inspector - 3112\n- Fire prevention specialist - 3112\n- Fire investigator - 3119",
        notes: null,
        occupational_titles: ['Fighter, fire', 'Firefighter', 'Firefighter, aircraft accidents', 'Firefighter, forest', 'Fireman', 'Fireman, aircraft accidents', 'Fireman, fighting fires', 'Fireman, forest', 'Firewoman', 'Firewoman, aircraft accidents', 'Firewoman, fighting fires', 'Firewoman, forest', 'Patrolman, forest: fire', 'Patrolwoman, forest: fire', 'Salvageman, fire', 'Salvagewoman, fire'],
        parent: '541',
        ancestors: ['5', '54', '541'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5411 = '5411';

    #[Isco08Info(
        level: 4,
        code: '5412',
        major_group: '5',
        sub_major_group: '54',
        minor_group: '541',
        unit_group: '5412',
        title: 'Police Officers',
        definition: 'Police officers maintain law and order, patrolling public areas, enforcing laws and regulations and arresting suspected offenders.',
        tasks_include: "Tasks include -\n(a)  patrolling a specific area to maintain public order, responding to emergencies, protecting people and property and enforcing laws and regulations;\n(b)  identifying, pursuing and arresting suspects and perpetrators of criminal acts;\n(c)  directing traffic and assuming authority in the event of accidents;\n(d)  providing emergency assistance to victims of accidents, crimes and natural disasters.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Police chief constable - 1112\n- Police commissioner - 1112\n- Police inspector-general - 1112\n- Police detective - 3355\n- Police inspector - 3355",
