    #[Isco08Info(
        level: 4,
        code: '5413',
        major_group: '5',
        sub_major_group: '54',
        minor_group: '541',
        unit_group: '5413',
        title: 'Prison Guards',
        definition: 'Prison guards watch over and maintain order among inmates of prisons, reformatories or penitentiaries.',
        tasks_include: "Tasks include -\n(a)  searching arriving prisoners, putting their valuables in safekeeping, escorting prisoners to cells and locking them in;\n(b)  making periodic inspection tours of cells and inspecting and maintaining the security of locks, windows, doors and gates;\n(c)  supervising prisoners at work and meals, and during recreation periods;\n(d)  observing the conduct and behaviour of prisoners to prevent disturbances and escapes;\n(e)  patrolling prison areas to prevent escapes;\n(f)  assisting with the implementation of rehabilitation programmes;\n(g)  escorting prisoners in transit and during temporary leave.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Gaoler', 'Guard, prison', 'Officer, corrective services: guard', 'Officer, prison: guard', 'Warden, prison', 'Warder, prison'],
        parent: '541',
        ancestors: ['5', '54', '541'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5413 = '5413';

    #[Isco08Info(
        level: 4,
        code: '5414',
        major_group: '5',
        sub_major_group: '54',
        minor_group: '541',
        unit_group: '5414',
        title: 'Security Guards',
        definition: 'Security guards patrol or monitor premises to guard property against theft and vandalism. They control access to establishments and maintain order and enforce regulations at public events and within establishments.',
        tasks_include: "Tasks include -\n(a)  patrolling premises and checking doors, windows and gates to prevent and detect signs of unauthorised entry;\n(b)  controlling access to establishments, monitoring and authorizing the entrance or departure of employees and visitors, checking identification and issuing security passes;\n(c)  circulating among visitors, patrons, or employees to preserve order, protect property from theft or vandalism and enforce the regulations of the establishment;\n(d)  responding to alarms, investigating disturbances and contacting superiors, police or fire fighters as appropriate;\n(e)  performing security checks of passengers and luggage at airports;\n(f)  picking up and ensuring the safe delivery of cash and valuables to banks, automated teller machines and retail establishments.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Beach patrolman\/woman - 5419\n- Lifeguard - 5419",
        notes: null,
        occupational_titles: ['Bodyguard', 'Bouncer', 'Concierge, hotel', 'Consultant, security', 'Doorkeeper', 'Guard, art gallery', 'Guard, body', 'Guard, museum', 'Guard, security', 'Keeper, door', 'Nightwatchman', 'Nightwatchwoman', 'Officer, security: guard', 'Patrolman, security', 'Patrolwoman, security', 'Specialist, security (except computer)', 'Watchman', 'Watchwoman'],
        parent: '541',
        ancestors: ['5', '54', '541'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5414 = '5414';

    #[Isco08Info(
        level: 4,
        code: '5419',
        major_group: '5',
        sub_major_group: '54',
        minor_group: '541',
        unit_group: '5419',
        title: 'Protective Services Workers Not Elsewhere Classified',
        definition: 'This unit group covers protective services workers not classified elsewhere in Minor Group 541: Protective Services Workers. For instance, the unit group includes lifeguards, crossing guards and animal control officers.',
        tasks_include: "Tasks include -\n(a)  patrolling beaches and swimming pools to prevent accidents and to rescue bathers from drowning;\n(b)  monitoring traffic flow to locate safe gaps through which pedestrians can cross streets;\n(c)  responding to citizen complaints concerning stray domestic animals, livestock and wildlife, issuing warnings and citations to owners and impounding lost, homeless and dangerous animals;\n(d)  patrolling an assigned area to enforce parking regulations;\n(e)  directing traffic.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Doorkeeper - 5414\n- Museum guard - 5414\n- Watchman\/woman - 5414",
        notes: null,
        occupational_titles: ['Attendant, pool', 'Attendant, swimming pool', 'Coastguard', 'Gamewarden', 'Guard, beach', 'Guard, crossing', 'Lifeguard', 'Lifesaver, surf', 'Officer, animal control', 'Officer, civil defence', 'Patrolman, beach', 'Patrolwoman, beach', 'Warden, bird sanctuary', 'Warden, game', 'Warden, traffic', 'Warden, wild life'],
        parent: '541',
        ancestors: ['5', '54', '541'],
        children: [],
        descendants: [],
    )]
    case ISCO08_5419 = '5419';

    #[Isco08Info(
        level: 4,
        code: '6111',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '611',
        unit_group: '6111',
        title: 'Field Crop and Vegetable Growers',
        definition: 'Field crop and vegetable growers plan, organize and perform farming operations to grow and harvest various types of field crop such as wheat and other cereals, rice, beetroot, sugar-cane, ground-nuts, tobacco, reed or other field crops and potatoes, cabbages or other field vegetables, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  monitoring market activity and conditions, determining types and quantities of crops to be grown, and planning and coordinating production accordingly;\n(b)  preparing soil by hand or machine, and spreading fertilizers and manure;\n(c)  selecting and sowing seeds, and planting seedlings;\n(d)  maintaining crops by cultivating soil, by transplanting, pruning or thinning plants, and by setting up and operating irrigation equipment;\n(e)  controlling weeds, pests and diseases by applying herbicides and pesticides;\n(f)  harvesting crops and destroying diseased or superfluous crops;\n(g)  inspecting, cleaning, grading, packaging, storing and loading crops for sale or delivery to market;\n(h)  tending working animals and maintaining farm buildings, structures, equipment and water supply systems;\n(i)   storing and carrying out some processing of produce;\n(j)   promoting and marketing products, arranging the sale, purchase and transportation of produce and supplies and maintaining and evaluating records of farm activities and transactions;\n(k)  training and supervising workers in crop production, maintenance duties and health and safety precautions, and hiring and discharging workers and contractors.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Agricultural production manager - 1311\n- Crop farm labourer - 9211",
        notes: 'Growers of vegetables using intensive cultivation techniques are classified in Unit Group 6113: Gardeners, Horticultural and Nursery Growers.',
        occupational_titles: ['Farmer, alfalfa', 'Farmer, cereal', 'Farmer, cereal: market production', 'Farmer, corn', 'Farmer, corn: market production', 'Farmer, cotton', 'Farmer, crop: field crops', 'Farmer, field crop', 'Farmer, field crop (market production)', 'Farmer, field vegetable', 'Farmer, field vegetable: (market production)', 'Farmer, flax', 'Farmer, grain', 'Farmer, grain: market production', 'Farmer, groundnut', 'Farmer, groundnut: market production', 'Farmer, jute', 'Farmer, maize', 'Farmer, maize: market production', 'Farmer, potato', 'Farmer, rice', 'Farmer, rice: market production', 'Farmer, soya-bean', 'Farmer, sugar-beet', 'Farmer, sugar-cane', 'Farmer, tobacco', 'Farmer, vegetable', 'Farmer, vegetable: market production', 'Farmer, wheat', 'Farmer, wheat: market production', 'Grower, cereal', 'Grower, cotton', 'Grower, crop: field crops', 'Grower, field: crop', 'Grower, field: vegetable', 'Grower, potato', 'Grower, rice', 'Grower, soya-bean', 'Grower, sugar-beet', 'Grower, sugar-cane', 'Planter, cotton', 'Planter, sugar-cane', 'Planter, tobacco', 'Worker, farm: skilled (cotton)', 'Worker, farm: skilled (field crops)', 'Worker, farm: skilled (flax)', 'Worker, farm: skilled (groundnut)', 'Worker, farm: skilled (irrigation)', 'Worker, farm: skilled (jute)', 'Worker, farm: skilled (potato)', 'Worker, farm: skilled (rice)', 'Worker, farm: skilled (sugar-beet)', 'Worker, farm: skilled (sugar-cane)', 'Worker, farm: skilled (tobacco)', 'Worker, farm: skilled (vegetables)', 'Worker, farm: skilled (wheat)', 'Worker, irrigation: skilled', 'Worker, plantation: skilled (cotton)'],
        parent: '611',
        ancestors: ['6', '61', '611'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6111 = '6111';

    #[Isco08Info(
        level: 4,
        code: '6112',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '611',
        unit_group: '6112',
        title: 'Tree and Shrub Crop Growers',
        definition: 'Tree and shrub crop growers plan, organize and perform farming operations to grow and harvest trees and shrubs, such as fruit and nut trees, tea and coffee bushes, grape vines, berry-bearing bushes, cocoa trees and rubber trees, and to collect sap, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  monitoring market activity and conditions, determining types and quantities of crops to be grown, and planning and coordinating production accordingly; \n(b)  preparing soil by hand or machine, and spreading fertilizers and manure;\n(c)  selecting and sowing seeds, and planting seedlings;\n(d)  maintaining crops by cultivating soil, by transplanting, pruning or thinning trees and shrubs, and by setting up and operating irrigation equipment;\n(e)  controlling weeds, pests and diseases by applying herbicides and pesticides;\n(f)  tending trees or bushes, collecting sap and harvesting crops;\n(g)  inspecting, cleaning, grading, packaging, storing and loading crops for sale or delivery to market;\n(h)  tending working animals and maintaining farm buildings, structures, equipment and water supply systems;\n(i)  storing and carrying out some processing of produce;\n(j)  promoting and marketing products, arranging the sale, purchase and transportation of produce and supplies and maintaining and evaluating records of farm activities and transactions;\n(k)  training and supervising workers in crop production, maintenance duties, and health and safety precautions, and hiring and discharging workers and contractors.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Plantation manager - 1311\n- Fruit picker - 9211",
        notes: null,
