    #[Isco08Info(
        level: 4,
        code: '6113',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '611',
        unit_group: '6113',
        title: 'Gardeners, Horticultural and Nursery Growers',
        definition: 'Gardeners, horticultural and nursery growers plan, organize and perform operations to cultivate and maintain trees, shrubs, flowers and other plants in parks and private gardens, and to produce saplings, bulbs and seeds or grow vegetables and flowers by intensive cultivation techniques, for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  monitoring market activity and conditions determining kinds and amounts of vegetables, horticultural and nursery products to be grown, and planning and coordinating production accordingly;\n(b)  preparing land by conditioning soil, levelling ground and installing and operating irrigation and drainage systems;\n(c)  planting trees, hedges, garden plants and grass;\n(d)  pruning and trimming trees, shrubs and hedges, installing plant supports and protection, and rolling, mowing, aerating and edging lawns;\n(e)  constructing features and facilities within gardens, such as paths or paved areas, walls, rockeries, garden beds, ponds and water features, sheds and fences;\n(f)  checking the health of plants and trees, identifying and treating weeds, pests and diseases, and applying mulch and fertilizers;\n(g)  producing saplings, bulbs and seeds and raising plants from seeds or cuttings;\n(h)  harvesting crops and inspecting, cleaning, grading, packaging, storing and loading products for sale or delivery to market;\n(i)  maintaining buildings, greenhouses and other structures, equipment and water supply systems;\n(j)  storing and carrying out some processing of produce;\n(k)  promoting and marketing products, arranging the sale, purchase and transportation of produce and supplies, and maintaining and evaluating records of activities and transactions;\n(l)  training and supervising workers in production, maintenance duties, and health and safety precautions, and hiring and discharging workers and contractors.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Horticultural scientist - 2132\n- Garden labourer - 9214\n- Horticultural labourer - 9214",
        notes: 'Growers of berry bearing bushes and tree fruits in orchards are classified in Unit Group 6112: Tree and Shrub Crop Growers unless this is done in combination with general market gardening or horticultural cultivation. Growers of vegetables in fields not using intensive cultivation techniques are classified in Unit Group 6111: Field Crop and Vegetable Growers.',
        occupational_titles: ['Contractor, gardening', 'Contractor, landscaping', 'Cultivator, mushroom', 'Floriculturist', 'Gardener', 'Gardener, landscape', 'Gardener, market', 'Greenkeeper', 'Groundsman', 'Groundswoman', 'Grower, bulbs: nursery', 'Grower, carnation', 'Grower, flower', 'Grower, horticultural', 'Grower, market: gardening', 'Grower, mushroom', 'Grower, nursery', 'Grower, osier', 'Grower, reed', 'Grower, rose', 'Grower, seeds: nursery', 'Grower, spices: nursery', 'Grower, tulip', 'Grower, vegetables: nursery', 'Horticulturist', 'Keeper, green', 'Nurseryman', 'Nurserywoman', 'Worker, farm: skilled (mushroom)', 'Worker, farm: skilled (nursery)', 'Worker, greenhouse: skilled', 'Worker, horticultural: skilled', 'Worker, market gardening: skilled'],
        parent: '611',
        ancestors: ['6', '61', '611'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6113 = '6113';

    #[Isco08Info(
        level: 4,
        code: '6114',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '611',
        unit_group: '6114',
        title: 'Mixed Crop Growers',
        definition: 'Mixed crop growers plan, organize and perform farming operations to grow and harvest specific combinations of field crops, field vegetables, tree and shrub crops, and garden, horticultural and nursery products, for sale or delivery to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  monitoring market activity and conditions, determining types and quantities of crops to be grown, and planning and coordinating production accordingly;\n(b)  preparing soil by hand or machine, and spreading fertilizers and manure;\n(c)  selecting and sowing seeds, and planting seedlings;\n(d)  maintaining crops by cultivating soil, by transplanting, pruning or thinning crops, trees and shrubs, and by setting up and operating irrigation equipment;\n(e)  growing flowers and vegetables by intensive cultivation;\n(f)  producing saplings, bulbs and seeds;\n(g)  harvesting crops and inspecting, cleaning, grading, packaging, storing and loading products for sale or delivery to market;\n(h)  tending working animals and maintaining farm buildings, structures, equipment and water supply systems;\n(i)  storing and carrying out some processing of produce;\n(j)  promoting and marketing products, arranging the sale, purchase and transportation of produce and supplies and maintaining and evaluating records of activities and transactions;\n(k)  training and supervising workers in production, maintenance duties and health and safety precautions, and hiring and discharging workers and contractors.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Agricultural production manager - 1311\n- Plantation manager - 1311\n- Crop farm labourer - 9211\n- Fruit picker - 9211",
        notes: null,
        occupational_titles: ['Farmer, mixed crop', 'Farmer, mixed crop: market production', 'Worker, farm: skilled (mixed crops)'],
        parent: '611',
        ancestors: ['6', '61', '611'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6114 = '6114';

    #[Isco08Info(
        level: 4,
        code: '6121',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '612',
        unit_group: '6121',
        title: 'Livestock and Dairy Producers',
        definition: 'Livestock and dairy producers plan, organize and perform farming operations to breed and raise domesticated animals (excluding poultry), such as cattle, sheep, pigs, goats, horses and camels, for the production of meat, milk and other dairy products, skins and wool or for use as working, sporting or recreational animals, for sale or delivery to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  monitoring market activity and conditions, determining kinds and amounts of stock to produce, planning and coordinating production accordingly;\n(b)  cultivating pastures and providing and monitoring fodder and water supplies to maintain appropriate nutritional levels and condition of livestock;\n(c)  monitoring and examining animals to detect illness, injury or disease, and to check physical condition such as rate of weight gain;\n(d)  grooming, marking, clipping, trimming, drenching and\/or castrating animals and shearing coats to collect hair or wool;\n(e)  herding livestock to pastures for grazing or to scales, sheds, vehicles, or other enclosures;\n(f)  milking animals by hand or using milking machines;\n(g)  mixing feed, additives, and medicines in prescribed portions and distributing or hand feeding to animals for consumption;\n(h)  performing duties related to livestock reproduction, such as breeding, artificial insemination and helping with animal births;\n(i)  maintaining and cleaning farm buildings, machinery, equipment and structures;\n(j)  slaughtering and skinning animals and preparing them for market;\n(k)  storing and carrying out some processing of animal and dairy produce;\n(l)  promoting and marketing products, arranging the sale, purchase and transportation of livestock, produce and supplies, and maintaining and evaluating records of farm activities and transactions;\n(m)  training and supervising workers in animal care procedures, maintenance duties, and health and safety precautions, and hiring and discharging workers and contractors.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Agricultural production manager - 1311\n- Ranch manager - 1311",
        notes: 'Workers who produce a combination of domestic livestock and other animals such as poultry, insects and non-domesticated animals should be classified according to their predominant activity. Those who produce and store hay and other fodder for later consumption, primarily by livestock for which they are responsible, are classified in Unit Group 6121: Livestock and Dairy Producers.',
        occupational_titles: ['Breeder, cat', 'Breeder, cattle', 'Breeder, dog', 'Breeder, horse', 'Breeder, reindeer', 'Breeder, stud', 'Cowboy', 'Cowgirl', 'Cowherd', 'Dairymaid', 'Dairyman', 'Drover', 'Farmer, astrakhan', 'Farmer, cattle', 'Farmer, cattle: market production', 'Farmer, cowherd: market production', 'Farmer, dairy', 'Farmer, fur: domestic animals', 'Farmer, goat', 'Farmer, goat: market production', 'Farmer, horse: breeding', 'Farmer, horse: raising', 'Farmer, livestock', 'Farmer, livestock: market production', 'Farmer, milk', 'Farmer, mixed-animal', 'Farmer, mixed-animal: market production', 'Farmer, pelt: domesticated animals', 'Farmer, pig', 'Farmer, pig: market production', 'Farmer, ranch', 'Farmer, sheep', 'Farmer, sheep: market production', 'Farmer, stud', 'Goatherd', 'Grazier', 'Hand, farm: milch', 'Hand, farm: milking', 'Hand, ranch', 'Milker', 'Milkmaid', 'Pastoralist', 'Producer, animals', 'Raiser, cattle', 'Raiser, pig', 'Raiser, sheep', 'Rancher', 'Shearer, sheep', 'Shepherd', 'Stockman, beef cattle', 'Stockman, livestock', 'Stockman, sheep', 'Stockwoman, beef cattle', 'Stockwoman, livestock', 'Stockwoman, sheep', 'Worker, farm: skilled (cattle)', 'Worker, farm: skilled (dairy)', 'Worker, farm: skilled (domestic fur-bearing animals)', 'Worker, farm: skilled (livestock)', 'Worker, farm: skilled (mixed-animal husbandry)', 'Worker, farm: skilled (pig)', 'Worker, farm: skilled (sheep)'],
        parent: '612',
        ancestors: ['6', '61', '612'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6121 = '6121';

    #[Isco08Info(
        level: 4,
        code: '6122',
        major_group: '6',
        sub_major_group: '61',
        minor_group: '612',
        unit_group: '6122',
        title: 'Poultry Producers',
        definition: 'Poultry producers plan, organize and perform farming operations to breed and raise chickens, turkeys, geese, ducks and other poultry to produce meat, eggs and breeding stock for sale or delivery to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  monitoring market activity, planning and coordinating production accordingly, maintaining and evaluating records of farming activities;\n(b)  growing and purchasing feed and other supplies needed to maintain appropriate nutritional levels and condition of poultry;\n(c)  monitoring and examining poultry to detect illness, injury, or disease and to check physical condition, such as rate of weight gain, and removing weak, ill and dead poultry from flock;\n(d)  mixing feed and feed additives and filling feed and water containers; \n(e)  vaccinating poultry via drinking water, injection or dusting of air; \n(f)  collecting and storing eggs and packaging them for sale or delivery to market;\n(g)  determining sex of chicks and facilitating breeding, artificial insemination and hatching of eggs; \n(h)  renting or investing in, and maintaining and cleaning, farm buildings, machinery, equipment and structures;\n(i)  slaughtering and dressing poultry for sale or delivery to market;\n(j)  storing and carrying out some processing of produce;\n(k)  arranging the sale, purchase and transportation stock, produce and supplies;\n(l)  training and supervising workers in poultry production procedures, maintenance duties and health and safety precautions, and hiring and discharging workers and contractors.",
        excluded_occupations: null,
        notes: 'Workers who produce a combination of domestic livestock and other animals such as poultry, insects and non-domesticated animals should be classified according to their predominant activity.',
        occupational_titles: ['Breeder, poultry', 'Caponizer', 'Debeaker, poultry', 'Farmer, battery', 'Farmer, chicken', 'Farmer, duck', 'Farmer, egg production', 'Farmer, goose', 'Farmer, poultry', 'Farmer, turkey', 'Hatcher-breeder, poultry', 'Operator, incubator: farm', 'Sexer, chicken', 'Tender, poultry', 'Worker, farm: skilled (poultry)', 'Worker, hatchery: skilled (poultry)'],
        parent: '612',
        ancestors: ['6', '61', '612'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6122 = '6122';

    #[Isco08Info(
        level: 4,
        code: '6123',
        major_group: '6',
        sub_major_group: '61',
