    #[Isco08Info(
        level: 4,
        code: '6224',
        major_group: '6',
        sub_major_group: '62',
        minor_group: '622',
        unit_group: '6224',
        title: 'Hunters and Trappers',
        definition: 'Hunters and trappers catch and kill mammals, birds or reptiles mainly for meat, skin, feathers and other products for sale or delivery on a regular basis to wholesale buyers, marketing organizations or at markets.',
        tasks_include: "Tasks include -\n(a)  setting traps to catch mammals, birds or reptiles;\n(b)  killing trapped or free mammals, birds or reptiles with firearms or other weapons;\n(c)  skinning and otherwise treating killed mammals, birds or reptiles to obtain desired products for sale or delivery;\n(d)  delivering or selling trapped live mammals, birds or reptiles;\n(e)  repairing and maintaining equipment.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Beater, game', 'Crewman, whaling vessel', 'Crewwoman, whaling vessel', 'Fisher, seal', 'Fisherman, seal', 'Fisherwoman, seal', 'Flenser, whale', 'Harpooner, whale', 'Hunter', 'Hunter, seal', 'Hunter, whale', 'Stripper, blubber', 'Trapper, fur', 'Trapper-hunter, fur'],
