    #[Isco08Info(
        level: 4,
        code: '6310',
        major_group: '6',
        sub_major_group: '63',
        minor_group: '631',
        unit_group: '6310',
        title: 'Subsistence Crop Farmers',
        definition: 'Subsistence crop farmers grow and harvest field or tree and shrub crops, vegetables and fruit, in order to provide food, shelter and, in some cases, a minimum of cash income for themselves and their households.',
        tasks_include: "Tasks include -\n(a)  preparing the soil and sowing, planting, tending and harvesting field crops;\n(b)  growing vegetables, fruit and other tree and shrub crops;\n(c)  fetching water and gathering firewood;\n(d)  storing for later use and carrying out some processing of produce;\n(e)  building and maintaining houses and other shelters;\n(f)  making tools, clothes and utensils for use by the household;\n(g)  selling or bartering some products at local markets.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Crop farm labourer - 9211\n- Firewood collector- 9624\n- Water collector- 9624",
        notes: 'Workers in a subsistence setting whose main tasks are fetching water and gathering firewood are classified in Unit Group 9624: Water and Firewood Collectors. Workers in subsistence agriculture who perform a limited range of simple and routine tasks, usually under the direction of others, are classified in the relevant unit group in Sub-major Group 92: Agricultural, Forestry and Fishery Labourers.',
        occupational_titles: ['Farmer, cereal: subsistence farming', 'Farmer, corn: subsistence farming', 'Farmer, crop: subsistence', 'Farmer, field: crop (subsistence farming)', 'Farmer, field: vegetable (subsistence farming)', 'Farmer, grain: subsistence farming', 'Farmer, groundnut: subsistence farming', 'Farmer, maize: subsistence farming', 'Farmer, mixed crop: subsistence farming', 'Farmer, rice: subsistence farming', 'Farmer, vegetable: subsistence farming', 'Farmer, wheat: subsistence farming', 'Gardener, subsistence', 'Grower, vegetable: subsistence'],
        parent: '631',
        ancestors: ['6', '63', '631'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6310 = '6310';

    #[Isco08Info(
        level: 4,
        code: '6320',
        major_group: '6',
        sub_major_group: '63',
        minor_group: '632',
        unit_group: '6320',
        title: 'Subsistence Livestock Farmers',
        definition: 'Subsistence livestock farmers breed, raise and tend livestock in order to provide food, shelter and, in some cases, a minimum of cash income for themselves and their households.',
        tasks_include: "Tasks include -\n(a)  cultivating pastures, or managing grazing lands, and monitoring feed and water supplies needed to maintain condition of livestock;\n(b)  monitoring and examining animals to detect illness, injury or disease, and to check physical condition;\n(c)  grooming and marking animals and shearing coats to collect hair or wool;\n(d)  herding or leading livestock to pastures, grazing land and water supplies;\n(e)  raising, tending, feeding and milking animals or draining blood from them;\n(f)  breeding animals and helping with animal births; \n(g)  slaughtering and skinning animals and preparing them and their products for consumption or sale;\n(h)  carrying out some processing of animal products;\n(i)  building and maintaining houses and other shelters;\n(j)  making tools, clothes and utensils for use by the household;\n(k)  fetching water and gathering firewood;\n(l)  buying, bartering and selling animals and some products.",
        excluded_occupations: "Some related occupations classified elsewhere:\n-Livestock farm labourer - 9212\n-Mixed crop and livestock farm labourer - 9213\n-Water and firewood collectors - 9624",
        notes: 'Workers in a subsistence setting whose main tasks are fetching water and gathering firewood, are classified in Unit Group 9624: Water and Firewood Collectors. Workers in subsistence agriculture who perform a limited range of simple and routine tasks, usually under the direction of others, are classified in the relevant unit group in Sub-major Group 92, Agricultural, Forestry and Fishery Labourers.',
        occupational_titles: ['Cowherd: subsistence farming', 'Farmer, cattle: subsistence', 'Farmer, goat: subsistence farming', 'Farmer, livestock: subsistence farming', 'Farmer, mixed-animal: subsistence farming', 'Farmer, pig: subsistence farming', 'Farmer, sheep: subsistence farming', 'Goatherd: subsistence farming', 'Shepherd: subsistence farming'],
        parent: '632',
        ancestors: ['6', '63', '632'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6320 = '6320';

    #[Isco08Info(
        level: 4,
        code: '6330',
        major_group: '6',
        sub_major_group: '63',
        minor_group: '633',
        unit_group: '6330',
        title: 'Subsistence Mixed Crop and Livestock Farmers',
        definition: "Subsistence mixed crop and livestock farmers grow and harvest field or tree and shrub crops, vegetables and fruit; gather wild fruits and medicinal and other plants; tend or hunt animals; and\/or catch fish and gather various forms of aquatic life in order to provide food, shelter and, in some cases, a minimum of cash income for themselves and their households.",
        tasks_include: "Tasks include -\n(a)  preparing the soil and sowing, planting, tending and harvesting field crops;\n(b)  growing vegetables, fruit and other tree and shrub crops;\n(c)  gathering wild fruits and medicinal and other plants;\n(d)  breeding, tending and feeding animals and poultry mainly to obtain meat, eggs, milk, hair, skin or other products;\n(e)  fetching water and gathering firewood;\n(f)  storing produce for later use and carrying out some processing of produce;\n(g)  building and maintaining houses and other shelters;\n(h)  making tools, clothes and utensils for use by the household;\n(i)  selling or bartering some products at local markets.",
        excluded_occupations: null,
        notes: 'Workers in a subsistence setting whose main tasks are fetching water and gathering firewood are classified in Unit Group 9624: Water and Firewood Collectors. Workers in subsistence agriculture who perform a limited range of simple and routine tasks, usually under the direction of others, are classified in the relevant unit group in Sub-major Group 92: Agricultural, Forestry and fishery Labourers.',
        occupational_titles: ['Farmer, mixed: subsistence', 'Farmer, subsistence', 'Worker, farm: skilled (subsistence farming)'],
        parent: '633',
        ancestors: ['6', '63', '633'],
        children: [],
        descendants: [],
    )]
    case ISCO08_6330 = '6330';

    #[Isco08Info(
        level: 4,
        code: '6340',
        major_group: '6',
        sub_major_group: '63',
        minor_group: '634',
        unit_group: '6340',
        title: 'Subsistence Fishers, Hunters, Trappers and Gatherers',
        definition: 'Subsistence fishers, hunters, trappers and gatherers gather wild fruits, medicinal and other plants; hunt and trap animals; catch fish and gather various forms of aquatic life in order to provide food, shelter and, in some cases, a minimum of cash income for themselves and their households.',
        tasks_include: "Tasks include -\n(a)  gathering wild fruits, roots and medicinal and other plants;\n(b)  hunting or trapping animals mainly to obtain meat, milk, hair, skin or other products;\n(c)  fetching water and gathering firewood;\n(d)  catching fish and gathering other forms of aquatic life;\n(e)  storing or carrying out some processing of their produce;\n(f)  building and maintaining houses and other shelters;\n(g)  making tools, clothes and utensils for use by the household;\n(h)  selling or bartering some products at local markets.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Subsistence crop farmer - 6310\n- Subsistence livestock farmer - 6320\n- Livestock farm labourer - 9212\n- Water and firewood collectors - 9624",
        notes: 'Workers in a subsistence setting whose main tasks are fetching water and gathering firewood are classified in Unit Group 9624: Water and Firewood Collectors. Workers in subsistence agriculture who perform a limited range of simple and routine tasks, usually under the direction of others, are classified in the relevant unit group in Sub-major Group 92: Agricultural, Forestry and Fishery Labourers.',
        occupational_titles: ['Collector, subsistence', 'Diver, subsistence', 'Fisher, subsistence', 'Fisherman, subsistence', 'Fisherwoman, subsistence', 'Gatherer, subsistence', 'Hunter, subsistence', 'Hunter-collector', 'Hunter-gatherer', 'Trapper, subsistence'],
