    #[Isco08Info(
        level: 4,
        code: '7113',
        major_group: '7',
        sub_major_group: '71',
        minor_group: '711',
        unit_group: '7113',
        title: 'Stonemasons, Stone Cutters, Splitters and Carvers',
        definition: 'Stonemasons, stone cutters, splitters and carvers cut and shape hard and soft stone blocks and slabs for the construction and maintenance of stone structures and monumental masonry, and carve designs and figures in stone.',
        tasks_include: "Tasks include -\n(a)  driving wedges into quarried stone to break it into slabs or blocks;\n(b)  selecting and grading slabs and blocks of granite, marble, and other stone;\n(c)  cutting, shaping and finishing building and monumental stone such as granite or marble using hand tools or hand-held power tools;\n(d)  making patterns and marking shapes on stone for subsequent sawing, planing, drilling and other dressing and cutting operations;\n(e)  cutting and carving characters, figures or designs on stone blocks used for monuments or memorials;\n(f)  setting stone in the erection of monuments and memorials;\n(g)  repairing and replacing stonework on old buildings, churches and monuments.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Wall and floor tile setters -7122\n- Machine operator (stone cutting or processing) - 8112",
        notes: null,
