    #[Isco08Info(
        level: 4,
        code: '7221',
        major_group: '7',
        sub_major_group: '72',
        minor_group: '722',
        unit_group: '7221',
        title: 'Blacksmiths, Hammersmiths and Forging Press Workers',
        definition: 'Blacksmiths, hammersmiths and forging press workers hammer and forge bars, rods, ingots and plates of iron, steel or other metals, and draw wire to make and repair various kinds of tools, metal articles, pieces of equipment, and agricultural and related implements.',
        tasks_include: "Tasks include -\n(a)  heating metal in forge furnace and manufacturing and repairing articles by drawing, bending, cutting, hammering metal on an anvil, punching, shearing, joining and hardening or tempering;\n(b)  shaping heated metal into forgings on power hammer equipped with open dies;\n(c)  operating closed-die drop hammer to forge metal articles;\n(d)  operating a power-press machine equipped with closed dies to forge metal articles;\n(e)  drawing wire;\n(f)  reading work orders or blueprints to determine specified tolerances and sequences of operations for machine setup;\n(g)  measuring and inspecting machine parts to ensure conformance to product specifications.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Casting machine operator - 7223\n- Machine tool operator - 7223",
        notes: null,
