    #[Isco08Info(
        level: 4,
        code: '7222',
        major_group: '7',
        sub_major_group: '72',
        minor_group: '722',
        unit_group: '7222',
        title: 'Toolmakers and Related Workers',
        definition: 'Toolmakers and related workers make and repair custom-made and specialised tools, sports guns, locks, dies, patterns, machinery components and other metal articles using hand and machine tools to work metal to fine tolerances.',
        tasks_include: "Tasks include -\n(a)  reading and interpreting engineering drawings and specifications of tools, dies, prototypes or models;\n(b)  preparing templates and sketches, and determining work processes;\n(c)  visualizing and computing dimensions, sizes, shapes and tolerances of assemblies, based on specifications;\n(d)  positioning, securing and measuring metal stock or castings to lay out for machining;\n(e)  setting up, operating and maintaining conventional and computer numerically controlled machine tools to cut, turn, mill, plane, drill, bore, grind or otherwise shape work pieces to prescribed dimensions and finish;\n(f)  fitting and assembling parts to make and repair jigs, fixtures and gauges;\n(g)  repairing and modifying sports guns and other small arms;\n(h)  making, fitting, assembling, repairing and installing lock parts and locks;\n(i)  making and repairing metal patterns for preparation of foundry moulds;\n(j)  laying out lines and reference points on metal stock to guide other workers who cut, turn, mill, grind or otherwise shape metal;\n(k)  verifying dimensions, alignments and clearances of finished parts for conformity with specifications, using precision measuring instruments and testing completed items for proper operation.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Tool production machine operator - 7223",
        notes: null,
        occupational_titles: ['Diemaker', 'Finisher, die', 'Gunsmith', 'Jigmaker', 'Locksmith', 'Maker, die', 'Maker, gauge', 'Maker, jig', 'Maker, jig-gauge', 'Maker, pattern', 'Maker, press tool', 'Maker, tap-die', 'Maker, template', 'Maker, tool', 'Marker, metal', 'Patternmaker, metal', 'Smith, gun', 'Smith, lock', 'Toolmaker'],
        parent: '722',
