    #[Isco08Info(
        level: 4,
        code: '7232',
        major_group: '7',
        sub_major_group: '72',
        minor_group: '723',
        unit_group: '7232',
        title: 'Aircraft Engine Mechanics and Repairers',
        definition: 'Aircraft engine mechanics and repairers fit, service, repair and overhaul aircraft engines and assemblies, such as airframes, hydraulic and pneumatic systems.',
        tasks_include: "Tasks include -\n(a)  fitting, examining, testing and servicing aircraft engines; \n(b)  replacing engine components or complete engines;\n(c)  examining  and inspecting airframes and aircraft components, including landing gear, hydraulic systems, and de-icers to detect wear, cracks, breaks, leaks, or other problems;\n(d)  maintaining, repairing, overhauling, modifying and testing aircraft structural, mechanical and hydraulic systems;\n(e)  reading and interpreting manuals, service bulletins, and other specifications to determine the feasibility and method of repairing or replacing malfunctioning or damaged components;\n(f)  maintaining, repairing and rebuilding aircraft structures, functional components and parts such as wings and fuselage, rigging, hydraulic units, oxygen systems, fuel systems, electrical systems, gaskets, and seals;\n(g)  inspecting completed work to certify that maintenance meets standards and the aircraft is ready for operation;\n(h)  maintaining repair logs, documenting all preventive and corrective aircraft maintenance;\n(i)  installing and testing electrical and electronic components, assemblies and systems in aircraft;\n(j)  connecting components to assemblies such as radio systems, instruments, magnetos, inverters, and in-flight refuelling systems.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Aeronautical engineer - 2144\n- Aircraft maintenance engineer (avionics) - 7421\n- Avionics technician - 7421\n- Aircraft engine assembler- 8211",
        notes: null,
        occupational_titles: ['Aeromechanic', 'Engineer, aircraft maintenance: airframe', 'Engineer, aircraft maintenance: engines', 'Erector, metal airframe', 'Fitter, engine: aircraft', 'Fitter-assembler, airframe', 'Mechanic, aircraft', 'Mechanic, airframe', 'Mechanic, airframe and power plant', 'Mechanic, engine: aircraft', 'Mechanic, helicopter', 'Mechanic, jet engine', 'Mechanic, pneudraulic systems: aircraft', 'Mechanic, powerplant: aircraft', 'Mechanic, rocket engine component', 'Repairer, engine: aircraft', 'Restorer, aircraft', 'Supervisor, aircraft maintenance', 'Technician, aircraft service', 'Technician, aviation maintenance'],
        parent: '723',
        ancestors: ['7', '72', '723'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7232 = '7232';

    #[Isco08Info(
        level: 4,
        code: '7233',
        major_group: '7',
        sub_major_group: '72',
        minor_group: '723',
        unit_group: '7233',
        title: 'Agricultural and Industrial Machinery Mechanics and Repairers',
        definition: 'Agricultural and industrial machinery mechanics and repairers fit, install, examine, service and repair engines, agricultural and industrial machinery and mechanical equipment, except motor vehicle, aircraft and electric motors.',
        tasks_include: "Tasks include -\n(a)  fitting, installing, examining, servicing and repairing engines, machinery and mechanical equipment;\n(b)  oiling and greasing stationary engines and machinery;\n(c)  inspecting and testing new machinery and mechanical equipment for conformity with standards and specifications;\n(d)  disassembling machinery and equipment to remove parts and make repairs;\n(e)  examining parts for defects such as breakage and excessive wear;\n(f)  operating newly repaired machinery and equipment to verify the adequacy of repairs;\n(g)  recording repairs and maintenance performed.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Air conditioning equipment mechanic - 7127\n- Electrical mechanic - 7412\n- Mechanical machinery assembler- 8211",
        notes: null,
        occupational_titles: ['Erector-installer, agricultural machinery', 'Erector-installer, industrial machinery', 'Fitter, agricultural machinery', 'Fitter, earth-moving equipment', 'Fitter, engine: agricultural and industrial machinery', 'Fitter, engine: marine', 'Fitter, engine: steam', 'Fitter, industrial machinery', 'Fitter, machine-tool', 'Fitter, metalworking machinery', 'Fitter, mining machinery', 'Fitter, office machinery', 'Fitter, plant maintenance', 'Fitter, printing machinery', 'Fitter, stationary: engine', 'Fitter, textile machinery', 'Fitter, train engine', 'Fitter, turbine', 'Fitter, woodworking machinery', 'Mechanic, agricultural machinery', 'Mechanic, construction machinery', 'Mechanic, earth-moving equipment', 'Mechanic, engine: diesel (except motor vehicle)', 'Mechanic, engine: steam', 'Mechanic, farm machinery', 'Mechanic, industrial machinery', 'Mechanic, machine tool', 'Mechanic, mining machinery', 'Mechanic, plant maintenance', 'Mechanic, printing machinery', 'Mechanic, ship', 'Mechanic, textile machinery', 'Mechanic, turbine', 'Mechanic, typewriter', 'Mechanic, woodworking machinery', 'Millwright', 'Oiler and greaser', 'Oiler and greaser, ship', 'Repairer, construction machinery', 'Repairer, farm machinery', 'Repairer, mining machinery', 'Repairer, stationary engine', 'Repairer, train engine'],
