    #[Isco08Info(
        level: 4,
        code: '7234',
        major_group: '7',
        sub_major_group: '72',
        minor_group: '723',
        unit_group: '7234',
        title: 'Bicycle and Related Repairers',
        definition: 'Bicycle and related repairers fit, maintain, service and repair the mechanical and related equipment of bicycles, rickshaws, baby carriages, wheelchairs and similar non-motorized transport equipment.',
        tasks_include: "Tasks include -\n(a)  examining, servicing and repairing bicycles and other non-motorized transport equipment;\n(b)  cleaning and lubricating bearings and other moving parts;\n(c)  replacing and repairing components and accessories, such as brakes, gears, driving chain mechanism, wheels, and handle bars;\n(d)  changing tyres and controlling air pressure;\n(e)  spray-painting frames;\n(f)  assembling new bicycles, wheelchairs and similar non-motorized equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Moped repairer - 7231\n- Motorized rickshaw mechanic - 7231",
        notes: null,
