    #[Isco08Info(
        level: 4,
        code: '7311',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7311',
        title: 'Precision-instrument Makers and Repairers',
        definition: 'Precision-instrument makers and repairers make, calibrate, repair, maintain, adjust and install mechanical watches and clocks, and nautical, meteorological, optical and other precision instruments and equipment, and set them for correct performance.',
        tasks_include: "Tasks include -\n(a)  repairing, cleaning and adjusting mechanisms of timing instruments such as watches and clocks;\n(b)  adjusting timing regulators, using calipers, watch-rate recorders and tweezers;\n(c)  cleaning, rinsing and drying timepiece parts, using solutions and ultrasonic or mechanical watch-cleaning machines;\n(d)  testing timepiece accuracy and performance, using meters and other electronic instruments;\n(e)  testing accuracy of meters, gauges, indicators or other recording or controlling instruments to locate defective components and for conformance to standards;\n(f)  calibrating instruments or scales, using hand tools and computer or electronic devices;\n(g)  inspecting components, connections and drive mechanisms to detect defects;\n(h)  assembling instruments and devices such as barometers, control valves, gyroscopes, hygrometers, speedometers, tachometers and thermostats;\n(i)  testing, calibrating and adjusting electronic, mercurial, aneroid and other types of meteorological instruments for compliance with printed specifications and schematic diagrams, using voltmeters, oscilloscopes, tube testers, and other test instruments;\n(j)  adjusting and repairing masts, supporting structures, clearance lights, control panels, control cabling and wiring, and other electrical and mechanical devices\n(k)  repairing and setting optical instruments such as microscopes, telescopes, theodolites and sextants;\n(l)  checking whether assembled units conform to specifications and ensuring stipulated performance and sensitivity by standard tests.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Orthopaedic appliance maker -3214\n- Locksmith - 7222\n- Machine tool operator - 7223\n- Watch assembler- 8212",
        notes: null,
        occupational_titles: ['Adjuster, precision instrument', 'Adjuster, watch', 'Balancer, scale', 'Calibrator, precision instrument', 'Calibrator, weights and measures', 'Maker, barometer', 'Maker, clock', 'Maker, instrument: dental', 'Maker, instrument: meteorological', 'Maker, instrument: nautical', 'Maker, instrument: optical', 'Maker, instrument: precision', 'Maker, instrument: scientific', 'Maker, instrument: surgical', 'Maker, photographic equipment', 'Maker, precision instrument', 'Maker, watch', 'Repairer, camera', 'Repairer, clock', 'Repairer, instrument: dental', 'Repairer, instrument: optical', 'Repairer, instrument: precision', 'Repairer, instrument: scientific', 'Repairer, instrument: surgical', 'Repairer, photographic equipment', 'Repairer, watch', 'Watchmaker'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7311 = '7311';

    #[Isco08Info(
        level: 4,
        code: '7312',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7312',
        title: 'Musical Instrument Makers and Tuners',
        definition: 'Musical instrument makers and tuners make, assemble, repair, adjust and restore musical instruments and tune them to the required pitch with hand or power tools. They usually specialize in one type of instrument, such as stringed instruments, brass instruments, reed instruments, pianos, or percussion instruments.',
        tasks_include: "Tasks include -\n(a)  fabricating and assembling musical instruments and instrument parts of wood, ebonite, metal, leather and other materials;\n(b)  repairing or replacing musical instrument parts and components, such as strings, bridges, felts and keys, using hand and power tools;\n(c)  playing and inspecting instruments to evaluate their sound quality and to locate any defects; \n(d)  adjusting string tensions to achieve proper tone or pitch of stringed instruments;\n(e)  adjusting lips, reeds or toe hole of organ pipes, using hand tools, to regulate airflow and loudness of sound;\n(f)  tuning and servicing pipe organs by adjusting pitch of organ A pipes to conform with pitch of tuning fork and adjusting pitch of other pipes with reference to pitch of tuned pipes;\n(g)  installing new drumheads in percussion instruments;\n(h)  tuning accordions by aurally comparing pitch of reeds with master reeds and filing reeds to obtain standard pitch;\n(i)  aligning pads and keys on reed or wind instruments;\n(j)  tuning percussion instruments to required pitch by tightening or loosening cords holding leather pieces fixed atop or at both ends of instrument;\n(k)  assembling and installing new pipe organs and pianos in buildings.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Builder, organ', 'Maker, accordion', 'Maker, drum', 'Maker, instrument: stringed', 'Maker, instrument: woodwind', 'Maker, key: piano', 'Maker, organ', 'Maker, piano', 'Maker, piano accordion', 'Maker, sound-board: piano', 'Maker, violin', 'Maker, xylophone', 'Regulator, tone: musical instruments', 'Repairer, instrument: brass', 'Repairer, instrument: musical', 'Repairer, instrument: percussion', 'Repairer, instrument: stringed', 'Repairer, instrument: wind', 'Stringer, piano', 'Tuner, accordion', 'Tuner, musical instrument', 'Tuner, organ', 'Tuner, piano', 'Voicer, organ'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7312 = '7312';

    #[Isco08Info(
        level: 4,
        code: '7313',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7313',
        title: 'Jewellery and Precious Metal Workers',
        definition: 'Jewellery and precious metal workers design, fabricate, adjust, repair or appraise jewellery, ceremonial or religious items, gold, silver, other precious metals, or gems. They cut, file, polish and set precious and semi-precious stones including gems and diamonds and engrave designs on jewellery and precious metal articles. They cut and polish diamonds for industrial purposes.',
        tasks_include: "Tasks include -\n(a)  casting jewellery and other non-ferrous metal articles by hand;\n(b)  creating new jewellery designs and modifying existing designs, using computers as necessary;\n(c)  cutting designs in moulds or other materials to be used as models in the fabrication of metal and jewellery products;\n(d)  altering existing jewellery mountings in order to reposition jewels or to adjust mountings; \n(e)  repairing, reshaping and restyling old jewellery or precious metal ware following designs or instructions;\n(f)  making complete jewellery articles such as rings, necklaces, bangles, brooches and bracelets from materials such as gold, silver, platinum and precious or semi-precious stones; \n(g)  examining gem surfaces and internal structures, using polariscopes, refractometers, microscopes, and other optical instruments to differentiate between stones, to identify rare specimens, or to detect flaws, defects or peculiarities affecting gem values;\n(h)  cutting and polishing gems and setting them in jewellery articles;\n(i)  engraving or embossing letters, designs or decorative lines on jewellery and precious metal ware;\n(j)  grinding, drilling and finishing jewel bearings for use in precision instruments such as compasses and chronometers; \n(k)  examining assembled or finished products to ensure conformance to specifications, using magnifying glasses or precision measuring instruments.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Beater, gold', 'Caster, jewellery moulds', 'Cutter, precious metal', 'Cutter-polisher, gems', 'Cutter-polisher, jewels', 'Driller, precious metals', 'Enameller, jewellery', 'Engraver, jewellery', 'Goldsmith', 'Hammersmith, precious-metal articles', 'Jeweller', 'Lapidary', 'Maker, jewellery', 'Maker, precious-metal chain', 'Maker, precious-metal leaf', 'Mounter, jewellery', 'Pewtersmith', 'Polisher, gem', 'Polisher, jewellery', 'Polisher, jewels', 'Repairer, jewellery', 'Roller, precious metal', 'Setter, gem', 'Setter, jewels', 'Silversmith', 'Smith, gold', 'Smith, hammer: precious-metal articles', 'Smith, pewter', 'Smith, silver', 'Spinner, precious metal'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7313 = '7313';

    #[Isco08Info(
        level: 4,
        code: '7314',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7314',
        title: 'Potters and Related Workers',
        definition: 'Potters and related workers prepare pottery, porcelain ware, sanitary ware, bricks, tiles and abrasive wheels by hand or by machine.',
        tasks_include: "Tasks include -\n(a)  making articles of pottery and porcelain;\n(b)  making clay or plaster-of-Paris moulds;\n(c)  reading technical drawings to know customer’s requirements;\n(d)  forming articles on potter's wheel by pressing thumbs into centres of revolving clay to form hollows, and press on the inside and outside of emerging clay cylinders with hands and fingers, gradually raising and shaping clay to desired forms and sizes;\n(e)  adjusting wheel speeds according to the feel of the clay as pieces enlarge and walls become thinner;\n(f)  operating jigger machines to form ceramic ware, such as bowls, cups, plates and saucers; \n(g)  adjusting and setting controls of pug mill that mix, extrudes, cuts, and deposits clay charges in or over moulds as specified;\n(h)  smoothening surfaces of finished pieces, using rubber scrapers and wet sponges; \n(i)  forming abrasive wheels by moulding and pressing an abrasive mixture by hand or by machine;\n(j)  examining finished ware for defects verifying accuracy of shapes and sizes of objects, using callipers and templates; \n(k)  preparing work for sale or exhibition, and maintaining relationships with retail, pottery, art and resource networks that can facilitate sale or exhibition of work.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ceramic artist - 2651\n- Kiln operator (brick and tile) - 8181\n- Kiln operator (pottery and porcelain) – 8181",
        notes: null,
        occupational_titles: ['Burnisher, ceramics', 'Caster, pottery and porcelain', 'Dipper, ceramics', 'Driller, pottery', 'Handler, pottery', 'Jiggerer, pottery and porcelain', 'Jollier, pottery and porcelain', 'Maker, pottery and porcelain mould', 'Maker, pottery spout', 'Modeller, pottery and porcelain', 'Moulder, abrasive wheel', 'Moulder, brick and tile', 'Potter', 'Presser, clay extruding', 'Presser, pottery and porcelain', 'Sticker-up, pottery', 'Thrower, pottery and porcelain', 'Turner, pottery and porcelain'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7314 = '7314';

    #[Isco08Info(
        level: 4,
        code: '7315',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7315',
        title: 'Glass Makers, Cutters, Grinders and Finishers',
        definition: 'Glass makers, cutters, grinders and finishers blow, mould, press, cut, trim, grind and polish glass, and shape molten glass according to patterns.',
        tasks_include: "Tasks include -\n(a)  heating glass to pliable stage using gas flames or ovens, and rotating glass to heat it uniformly;\n(b)  blowing and bending glass tubing into specified shapes to form scientific apparatus such as flasks, retorts and pipettes;\n(c)  grinding and polishing glass objects or parts to correct defects or to prepare surfaces for further finishing and smoothing and polishing rough edges, using belt sander or polishing wheels;\n(d)  examining glass stock and finished products and marking or discarding items with defects such as spots, stains, scars, snags, chips, scratches, or unacceptable shapes or finishes;\n(e)  reading work orders to determine dimensions, cutting locations and quantities to cut;\n(f)  observing gauges, computer printouts and video monitors to verify specified processing conditions and make adjustments as necessary;\n(g)  positioning pattern or drawing on glass, measuring dimensions, and marking cutting lines, using glass cutting tools and cutting glass along marked outlines or around pattern;\n(h)  setting up, operating and adjusting computerized or robotic glass cutting equipment;\n(i)  inspecting, weighing and measuring products to verify conformance to specifications, using instruments such as micrometers, callipers, magnifiers and rulers;\n(j)  regulating oven temperatures according to glass types to be processed;\n(k)  transferring pattern for individual stained glass parts from full size drawing to pattern paper, using stylus to trace drawings;\n(l)  spraying silver solution on glass to provide mirrored surface, using spray gun;\n(m)  laying out cutting and grinding optical and other glass to specified dimensions and weight for moulding into lens blanks and for use as watch crystals.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Glass production furnace operator - 8181",
        notes: null,
        occupational_titles: ['Bender, glass', 'Beveller, glass', 'Blower, glass', 'Borer, glass', 'Cutter, glass', 'Cutter, optical glass', 'Driller, glass', 'Finisher, glass', 'Froster, glass sandblasting', 'Gatherer, glass', 'Grinder, glass', 'Grinder, glass edge', 'Ladler, glass', 'Moulder, glass', 'Polisher, glass', 'Setter-operator, lathe: glass', 'Silverer, glass', 'Silverer, mirror', 'Worker, glass'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7315 = '7315';

    #[Isco08Info(
        level: 4,
        code: '7316',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7316',
        title: 'Sign Writers, Decorative Painters, Engravers and Etchers',
        definition: 'Sign writers, decorative painters, engravers and etchers decorate articles made of wood, metal, textiles, glass, ceramics and other materials. They plan, lay out and paint letters, figures, monograms and designs to make signs and engrave and etch ornamental and floral designs on glass and other articles.',
        tasks_include: "Tasks include -\n(a)  painting decorative freehand designs on objects, such as pottery, glass, cigarette cases, lampshades;\n(b)  transferring from paper transfers decorative or ornamental designs on articles;\n(c)  integrating and developing visual elements, such as line, space, mass, colour, and perspective, in order to produce desired effects such as the illustration of ideas, emotions or moods;\n(d)  laying out and painting in one or more languages letters, figures, monograms and designs to make signs;\n(e)  sketching or tracing design or lettering onto work piece or pattern material to prepare pattern or stencil;\n(f)  designing pattern or lettering to paint work pieces such as signs, glassware, pottery or zinc plates;\n(g)  using software and routing equipment to produce three-dimensional Carved images for application onto larger signage as well as engraved and inlaid signs;\n(h)  designing and producing normal flat cut lettering, or lettering that is shadowed with applied vinyl or lettering that is ready cut for  application; \n(i)  writing, painting or printing signs or show cards used for display or other purposes;\n(j)  cutting out letters and signs for display purposes from wallboard or cardboard, by hand or machines such as electrically powered jigsaw or bandsaw;\n(k)  examining sketches, diagrams, samples, blueprints, or photographs to decide how designs are to be etched, cut or engraved onto work pieces; \n(l)  measuring and computing dimensions of lettering, designs, or patterns to be engraved; \n(m)  engraving and printing patterns, ornamental designs, etchings, trademarks, figures or lettering onto flat or curved surfaces of a wide variety of metal, glass, plastic, or ceramic items;\n(n)  etching decorative designs, calibration markings and other figures on glass articles.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Building painter -7131\n- Manufactured articles painter - 7132\n- Vehicle painter - 7132\n- Ceramics painting machine operator- 8181\n- Glass painting machine operator - 8181",
        notes: null,
        occupational_titles: ['Calligrapher', 'Cutter, crystal glass', 'Cutter, intaglio glass', 'Cutter-shaper, decorative glass', 'Decorator, ceramics', 'Decorator, pottery', 'Enameller, ceramics', 'Enameller, glass', 'Engraver, decorative', 'Engraver, glass', 'Etcher, glass', 'Letterer, sign-writing', 'Marker, glass engraving', 'Painter, brush: except construction', 'Painter, decorative', 'Painter, decorative: ceramics', 'Painter, decorative: glass', 'Painter, decorative: sign', 'Sandblaster, glass decorating', 'Signpainter', 'Signwriter', 'Spray-painter, decorative painting', 'Stamper, rubber: ceramics', 'Stenciller, ceramics decoration', 'Toucher-up, ceramics decoration', 'Tracer, ceramics decoration', 'Transferrer, ceramics decoration', 'Waxer, glass sandblasting'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7316 = '7316';

    #[Isco08Info(
        level: 4,
        code: '7317',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7317',
        title: 'Handicraft Workers in Wood, Basketry and Related Materials',
        definition: 'Handicraft workers in wood, basketry and related materials apply traditional techniques such as seasoning, impregnation to prepare wood, straw, rattan, reeds, clay, shells and other materials, and carve, mould, assemble, weave or paint and decorate various articles for personal or household use or for decorative purposes. Basketry weavers, brush makers and related workers select and prepare materials such as bristles, nylon, fibre, bass, whisker and wire to make wicker furniture, brushes and brooms, and weave various kinds of baskets.',
        tasks_include: "Tasks include -\n(a)  preparing wood, straw, rattan, reeds, shells, or similar materials;\n(b)  carving floral and artistic designs on wooden surfaces for decorative purposes;\n(c)  painting freehand decorative designs on glass and pottery or porcelain ware;\n(d)  carving, assembling, weaving, painting and decorating various articles for personal or household use such as salad bowls, serving-spoons, cutting-boards, trays, vases, jugs, baskets, straw hats, straw mats and similar objects;\n(e)  carving, assembling, weaving and painting various decorative articles such as statues and other sculptures, chess pieces, jewellery and similar objects;\n(f)  making wicker furniture from peeled and softened rattan, reeds, rushes, willow branches and similar materials;\n(g)  making various kinds of baskets by interlacing osier, rattan, reeds, rushes or similar materials;\n(h)  forming bottom of basket by interlacing strips of rattan, wood veneer or other material with framework of rods of material such as willow;\n(i)  inserting rods around edge of bottom between woven sections of bottom and bending them upright to serve as framework for sides;\n(j)  selecting and preparing brush materials, such as bristles, nylon, fibres and wire, and setting them in brush base;\n(k)  selecting and preparing materials, such as broom corn, bass, whisker and fibre, and fastening them to broom handles.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Machine operator (wood products) - 7523",
        notes: null,
        occupational_titles: ['Creeler', 'Maker, basket', 'Maker, broom', 'Maker, brush', 'Maker, footwear: raffia', 'Maker, furniture: basketry', 'Maker, furniture: wicker', 'Maker, paper', 'Maker, toy: wooden', 'Toymaker, wooden', 'Weaver, basket', 'Weaver, straw', 'Worker, handicraft: basketry', 'Worker, handicraft: paper articles', 'Worker, handicraft: reed weaving', 'Worker, handicraft: straw articles', 'Worker, handicraft: wooden articles'],
        parent: '731',
        ancestors: ['7', '73', '731'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7317 = '7317';

    #[Isco08Info(
        level: 4,
        code: '7318',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '731',
        unit_group: '7318',
        title: 'Handicraft Workers in Textile, Leather and Related Materials',
        definition: 'Handicraft workers in textile, leather and related materials apply traditional techniques and patterns to produce woven fabrics, knitted, embroidered, woven and other garments and articles for household use, as  well as traditional footwear, handbags, belts and other accessories.',
        tasks_include: "Tasks include -\n(a)  spinning and dyeing with natural dyestuffs, wool, cotton and other fibres;\n(b)  lace-making and weaving, knitting or embroidering various garments and articles for household use;\n(c)  preparing and dyeing hides with natural dyestuffs and making traditional footwear or handbags, belts and other accessories;\n(d)  spinning and winding yarn by hand;\n(e)  drawing warp threads into loom by hand;\n(f)  weaving plain or figured cloth, tapestry, lace, carpet or other fabrics on hand looms;\n(g)  making carpets by using a knotting technique;\n(h)  knitting garments and other articles on hand-operated machine or by hand;\n(i)  crocheting or making braid by hand;\n(j)  making nets by hand;\n(k)  grading and classifying natural textile fibres;\n(l)  washing wool fibres;\n(m)  cleaning and fluffing textile fibres;\n(n)  forming fibres into sliver, combing them, combining sliver into sliver laps or forming sliver into rove.",
