    #[Isco08Info(
        level: 4,
        code: '7321',
        major_group: '7',
        sub_major_group: '73',
        minor_group: '732',
        unit_group: '7321',
        title: 'Pre-press Technicians',
        definition: 'Pre-press technicians proof, format, set and compose text and graphics into a form suitable for use in various printing processes and representation in other visual media.',
        tasks_include: "Tasks include -\n(a)  operating graphic cameras and other photographic equipment to reproduce camera-ready copy onto films, plates and digital output devices; \n(b)  using computer applications to generate images, text, layouts and impositions for print and other visual media displays;\n(c)  operating plate making equipment to reproduce images from film to printing plates, digital output devices and presses;\n(d)  operating computer screen-based equipment for scanning, colour separation, colour correction, masking, creative design, combining, imposing, retouching, and other processes used to transfer copy to film and produce film for plate, digital output and cylinder productions;\n(e)  carrying out digital and chemical proofing from digital systems, and negative and positive films;\n(f)  evaluating printed proofs, checking and correcting them for quality;\n(g)  preparing and exposing carbon tissue for laying on cylinders by transfer method, and developing images.",
        excluded_occupations: null,
