    #[Isco08Info(
        level: 4,
        code: '7411',
        major_group: '7',
        sub_major_group: '74',
        minor_group: '741',
        unit_group: '7411',
        title: 'Building and Related Electricians',
        definition: 'Building and related electricians install, maintain and repair electrical wiring systems and related equipment and fixtures.',
        tasks_include: "Tasks include -\n(a)  installing, maintaining and repairing electrical wiring systems and related equipment in various buildings such as schools, hospitals, commercial establishments, residential buildings and other structures;\n(b)  examining blueprints, wiring diagrams and specifications to determine sequences and methods of operation;\n(c)  planning layout and installation of electrical wiring, equipment and fixtures, based on job specifications and relevant standards; \n(d)  inspecting electrical systems, equipment and components to identify hazards, defects and the need for adjustment or repair;\n(e)  selecting, cutting and connecting wire and cable to terminals and connectors;\n(f)  measuring and laying out installation reference points;\n(g)  positioning and installing electrical switchboards;\n(h)  testing continuity of circuit.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Electrical fitter - 7412\n- Electrical mechanic - 7412\n- Electrical line installer - 7413",
        notes: null,
        occupational_titles: ['Electrician', 'Electrician, building', 'Electrician, building maintenance', 'Electrician, building repairs', 'Electrician, electrical installation: building', 'Electrician, electrical maintenance:  building', 'Electrician, neon-lighting', 'Electrician, stage and studio', 'Electrician, theatre'],
