    #[Isco08Info(
        level: 4,
        code: '7521',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '752',
        unit_group: '7521',
        title: 'Wood Treaters',
        definition: 'Wood treaters season, preserve and treat wood and lumber manually or using wood treatment equipment such as kilns and tanks.',
        tasks_include: "Tasks include -\n(a)  operating and tending kilns, treating tanks and other equipment to dry lumber, prepare and season wood and other wood products, and to impregnate wood products with preservatives;\n(b)  monitoring equipment operation, gauges, and panel lights in order to detect deviations from standards and to ensure that processes are operating according to specifications;\n(c)  operating valves to admit treating solution into treatment vessels, maintain specified heat, vacuum and hydraulic pressure and level of solution during each phase of treatment cycle;\n(d)  activating vacuum and hydraulic pressure pumps that remove air and steam from retort and force treating solution into pores of wood to accelerate treatment process;\n(e)  assisting in maintaining processing equipment and machines as required;\n(f)  cleaning, lubricating and adjusting equipment;\n(g)  transporting materials and products to and from work areas, manually or using carts, handtrucks, or hoists;\n(h)  completing and maintaining production reports.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Wood processing plant operator - 8172",
        notes: null,
        occupational_titles: ['Dipper, wood treatment', 'Grader, wood', 'Impregnator, wood', 'Operator, kiln: dry (wood)', 'Operator, kiln: lumber', 'Operator, machine: painting (wood)', 'Operator, machine: seasoning (wood)', 'Operator, machine: tempering (wood)', 'Operator, machine: treating (wood)', 'Operator, tank: timber treating', 'Seasoner, wood', 'Tender, veneer dryer', 'Treater, wood', 'Woodworker, treating', 'Worker, wood: incising', 'Worker, wood: treating'],
        parent: '752',
        ancestors: ['7', '75', '752'],
        children: [],
        descendants: [],
    )]
