    #[Isco08Info(
        level: 4,
        code: '7522',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '752',
        unit_group: '7522',
        title: 'Cabinet-makers and Related Workers',
        definition: 'Cabinet-makers and related workers make, decorate and repair wooden furniture, carts and other vehicles, wheels, parts, fittings, patterns, models and other wooden products using woodworking machines, machine tools and specialized hand tools.',
        tasks_include: "Tasks include -\n(a)  operating woodworking machines, such as power saws, jointers, mortisers and shapers, and using hand tools to cut, shape and form parts and components;\n(b)  studying plans, verifying dimensions of articles to be made, or preparing specifications and checking the quality and fit of pieces in order to ensure adherence to specifications; \n(c)  trimming joints and fitting parts and subassemblies together to form complete units using glue and clamps, and reinforcing joints using nails, screws or other fasteners;\n(d)  making, restyling and repairing various wooden articles, such as cabinets, furniture, vehicles, scale models, sports equipment and other parts or products;\n(e)  decorating furniture and fixtures by inlaying wood, applying veneer and carving designs;\n(f)  finishing surfaces of wooden articles or furniture.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Carpenters - 7115\n- Joiners - 7115\n- Wood and related products assemblers - 8219",
        notes: null,
        occupational_titles: ['Applier, veneer', 'Bender, wood', 'Bodybuilder, vehicle: wooden', 'Builder, body: vehicle (wooden)', 'Builder, coach-body: wooden', 'Builder, vehicle-body: wooden', 'Builder, vehicle-frame: wooden', 'Cabinet-maker', 'Cabinet-maker, furniture', 'Cartwright', 'Carver, wood', 'Cooper', 'Finisher, wooden furniture', 'Inlayer, marquetry', 'Maker, barrel', 'Maker, cabinet', 'Maker, cask', 'Maker, chair', 'Maker, clock case', 'Maker, clog', 'Maker, coffin', 'Maker, furniture: cane', 'Maker, instrument case', 'Maker, ladder: wood', 'Maker, model: wooden', 'Maker, piano case', 'Maker, picture frame', 'Maker, pipe: smoking (wood)', 'Maker, sports equipment: wood', 'Maker, tank: wooden', 'Marker, woodworking', 'Patternmaker, wood', 'Stainer, wooden furniture', 'Tenoner', 'Varnisher, wooden furniture', 'Wheelwright'],
