    #[Isco08Info(
        level: 4,
        code: '7523',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '752',
        unit_group: '7523',
        title: 'Woodworking Machine Tool Setters and Operators',
        definition: 'Woodworking machine tool setters and operators set-up, operate and monitor automatic or semi-automatic woodworking machines, such as precision sawing, shaping, planing, boring, turning and woodcarving machines to fabricate or repair wooden parts for furniture, fixtures and other wooden products.',
        tasks_include: "Tasks include -\n(a)  setting-up, programming, operating and monitoring several types of woodworking machines for sawing, shaping, boring, drilling, planing, pressing, turning, sanding or carving to fabricate or repair wooden parts for furniture, fixtures and other wooden products;\n(b)  operating preset special-purpose woodworking machines to fabricate wooden products such as coat hangers, mop handles, clothes pins and other products;\n(c)  selecting knives, saws, blades, cutter heads, cams, bits or belts according to work piece, machine functions and product specifications;\n(d)  installing and adjusting blades, cutter heads, boring-bits and sanding-belts, and using hand tools and rules;\n(e)  setting and adjusting various kinds of woodworking machines for operation by others;\n(f)  reading and interpreting specifications or following verbal instructions.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Wood and related products assemblers - 8219",
        notes: null,
        occupational_titles: ['Borer, wood', 'Machinist, wood products', 'Operator, lathe: woodworking', 'Operator, machine: bending (wood)', 'Operator, machine: carving (wood)', 'Operator, machine: drilling (wood)', 'Operator, machine: engraving (wood)', 'Operator, machine: etching (wood)', 'Operator, machine: finishing (wood)', 'Operator, machine: furniture production', 'Operator, machine: marking (wood)', 'Operator, machine: planing (wood)', 'Operator, machine: polishing (wood)', 'Operator, machine: sports equipment (wood)', 'Operator, machine: toy production (wood)', 'Operator, machine: wood products', 'Operator, machine: woodworking', 'Operator, set-up: woodworking machine', 'Sawyer, precision woodworking', 'Sawyer, wood', 'Setter, woodworking machine', 'Setter-operator, carving machine: woodworking', 'Setter-operator, fret-saw: woodworking', 'Setter-operator, jigsaw: woodworking', 'Setter-operator, lathe: woodworking', 'Setter-operator, planing machine: woodworking', 'Setter-operator, routing machine: woodworking', 'Setter-operator, shaping machine: woodworking', 'Setter-operator, woodworking machine', 'Tuner, wood', 'Turner, wood', 'Woodworker, dovetailing', 'Woodworker, dowelling', 'Woodworker, morticing', 'Woodworker, sanding', 'Woodworker, tenoning', 'Worker, wood: dovetailing', 'Worker, wood: dowelling', 'Worker, wood: morticing', 'Worker, wood: sanding', 'Worker, wood: tenoning'],
