    case ISCO08_7536 = '7536';

    #[Isco08Info(
        level: 4,
        code: '7541',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '754',
        unit_group: '7541',
        title: 'Underwater Divers',
        definition: 'Underwater divers work under the surface of water, with or without the aid of underwater breathing apparatus, to inspect, install, repair and remove equipment and structures, conduct tests or experiments, rig explosives, photograph structures or marine life, collect various forms of aquatic life for commercial or research purposes, and find and recover missing items and persons.',
        tasks_include: "Tasks include -\n(a)  taking safety precautions, such as monitoring dive lengths and depths, and registering with authorities before diving expeditions begin;\n(b)  checking and maintaining diving equipment such as helmets, masks, air tanks, diving suits, harnesses and gauges;\n(c)  descending into water with the aid of diver helpers, using scuba gear or diving suits;\n(d)  working under water to lay and repair bridges, piers and harbour-wall foundations;\n(e)  inspecting for suspected damage and making minor repairs to ships' hulls and underwater installations;\n(f)  reporting on condition of wrecked ships;\n(g)  removing underwater obstructions;\n(h)  drilling holes for underwater blasting;\n(i)  performing various underwater tasks connected with salvage work or recovering dead bodies;\n(j)  gathering shellfish, sponges and other aquatic life forms\n(j)  communicating with workers on the surface while under water, using signal lines or telephones;\n(k)  obtaining information about diving tasks and environmental conditions.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Subsistence diver - 6340",
        notes: null,
        occupational_titles: ['Diver, abalone', 'Diver, commercial', 'Diver, oyster', 'Diver, pearl', 'Diver, salvage', 'Diver, shell fish', 'Diver, sponge', 'Diver, underwater', 'Frogman', 'Frogman, salvage', 'Frogwoman', 'Frogwoman, salvage', 'Welder, underwater', 'Worker, underwater'],
        parent: '754',
        ancestors: ['7', '75', '754'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7541 = '7541';

    #[Isco08Info(
        level: 4,
        code: '7542',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '754',
        unit_group: '7542',
        title: 'Shotfirers and Blasters',
        definition: 'Shotfirers and blasters position, assemble, and detonate explosives at mining, quarrying and demolition sites.',
        tasks_include: "Tasks include -\n(a)  ensuring workplace safety and explosives handling, storage and transport procedures and regulations are followed;\n(b)  planning and giving instructions for the layout, depth and diameter of blast holes;\n(c)  checking depth and cleanliness of blast holes;\n(d)  determining quantity and type of explosives to be used;\n(e)  loading explosives into blast holes;\n(f)  assembling, or directing other workers to assemble, primer charges using detonators and explosive cartridges, and attaching electrical wires, fuses and detonating cords to primers;\n(g)  connecting wires, fuses and detonator cords into series, testing electrical circuits and repairing malfunctions, and connecting series to blasting machines;\n(h)  covering charges, filling blast holes with rock dust, sand and other materials, and tamping material to compact charges;\n(i)  ensuring all explosives are detonated, and reporting and attending to misfires;\n(j)  declaring blast areas safe before and after detonation of explosives;\n(k)  compiling and maintaining records about usage of explosives in compliance with laws and regulations.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Mining Supervisor - 3121\n- Driller (mining) - 8111\n- Driller (oil or gas well) - 8113\n- Mining labourer - 9311\n- Quarry labourer - 9311",
        notes: null,
        occupational_titles: ['Blaster', 'Monkey, powder', 'Powderman', 'Powderwoman', 'Shotfirer'],
        parent: '754',
        ancestors: ['7', '75', '754'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7542 = '7542';

    #[Isco08Info(
        level: 4,
        code: '7543',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '754',
        unit_group: '7543',
        title: 'Product Graders and Testers (except Foods and Beverages)',
        definition: 'Product graders and testers (except foods and beverages) inspect, test, sort, sample and weigh raw materials, manufactured components and non-comestible goods produced or sold, to ensure compliance with quality standards and to identify defects, wear, and deviations from specifications, and to grade and classify them according to their quality.',
        tasks_include: "Tasks include -\n(a)  inspecting and testing products, parts and materials for conformity with specifications and standards;\n(b)  grading and classifying natural textile fibres for spinning and winding;\n(c)  discarding or rejecting products, materials and equipment not meeting specifications; \n(d)  analysing and interpreting blueprints, data, manuals, and other materials to determine specifications, inspection and testing procedures;\n(e)  notifying supervisors and other personnel of production problems, and assisting in identifying and correcting these problems;\n(f)  recording inspection or test data, such as weights, temperatures, grades or moisture content, and quantities inspected or graded;\n(g)  marking items with details such as grade and acceptance or rejection status; \n(h)  measuring dimensions of products using instruments such as rulers, callipers, gauges, or micrometers;\n (i)  analysing test data and making computations as necessary to determine test results.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Product safety inspector - 3257\n- Food grader - 7515\n- Fur grader - 7531\n- Pelt grader - 7535",
        notes: null,
        occupational_titles: ['Classer, wool', 'Controller, quality', 'Examiner, cloth', 'Examiner, fabrics', 'Grader, products', 'Grader, textile', 'Inspector, electrical products', 'Inspector, electronic products', 'Inspector, fabrics', 'Inspector, products (except food and drinks)', 'Inspector, quality', 'Woolclasser'],
        parent: '754',
        ancestors: ['7', '75', '754'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7543 = '7543';

    #[Isco08Info(
        level: 4,
        code: '7544',
        major_group: '7',
        sub_major_group: '75',
        minor_group: '754',
        unit_group: '7544',
        title: 'Fumigators and Other Pest and Weed Controllers',
        definition: 'Fumigators and other pest and weed controllers use chemicals to remove harmful insects, small animals, wild plants and other unwanted organisms, to prevent damage to crops and to buildings and other structures and their surroundings, and to prevent health risks.',
        tasks_include: "Tasks include -\n(a)  operating and monitoring equipment for spraying pests and weeds;\n(b)  mixing chemicals according to instructions;\n(c)  covering areas to specified depths with pesticides, applying knowledge of weather conditions, droplet sizes, elevation-to-distance ratios, and obstructions;\n(d)  spraying or releasing chemical solutions or toxic gases and setting traps to kill pests and vermin, such as mice, termites and roaches;\n(e)  lifting, pushing and swinging nozzles, hoses and tubes in order to direct spray over designated areas;\n(f)  filling sprayer tanks with water and chemicals;\n(g)  cleaning and servicing machinery to ensure operating efficiency.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Aerial crop sprayer - 3153",
        notes: null,
        occupational_titles: ['Contractor, spraying: pest or weed control', 'Controller, pest', 'Controller, weed', 'Exterminator', 'Fumigator', 'Officer, pest management', 'Sprayer, crops (except aerial)', 'Sprayer, herbicide', 'Sprayer, insecticide', 'Sprayer, malaria control', 'Sprayer, pesticide', 'Sprayer, weed', 'Technician, pest control'],
        parent: '754',
        ancestors: ['7', '75', '754'],
        children: [],
        descendants: [],
    )]
    case ISCO08_7544 = '7544';

