    #[Isco08Info(
        level: 4,
        code: '8111',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '811',
        unit_group: '8111',
        title: 'Miners and Quarriers',
        definition: 'Miners and quarriers operate plant, machinery and hand tools to extract rock, mineral ores and other deposits from underground and surface mines and quarries.',
        tasks_include: "Tasks include -\n(a)  positioning, operating and monitoring the performance of a variety of underground and surface mining equipment including continuous mining, cutting and channelling plant;\n(b)  setting up and operating drilling equipment in underground and surface mines and quarries;\n(c)  operating machinery and using hand or power tools to remove loosened rock, ore, coal and other deposits;\n(d)  preparing, fitting and installing supports in underground workings including rock bolts;\n(e)  operating machinery to open new shafts, drives, air vents and rises;\n(f)  operating auxiliary plant such as pumps to expel air, water and mud;\n(g)  performing minor maintenance and repairs and lubricating and cleaning plant, machines and tools;\n(h)  completing records detailing operations completed during shifts;\n(i)  collecting mineral samples for laboratory analysis.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Mining supervisor - 3121\n- Blaster - 7542\n- Shotfirer - 7542\n- Driller (oil or gas well) - 8113\n- Mining Labourer - 9311\n- Quarry Labourer - 9311",
        notes: null,
        occupational_titles: ['Bolter, roof: mining', 'Clipper, mine', 'Drawer, prop: mine', 'Drawer, prop: quarry', 'Drawer, timber: mine', 'Drawer, timber: quarry', 'Driller, mining', 'Miner', 'Miner, coal', 'Miner, diamond', 'Miner, gold', 'Miner, hydraulic: placer mining', 'Miner, surface', 'Miner, underground', 'Operator, bogger', 'Operator, continuous miner', 'Operator, dragline: mining', 'Operator, jumbo', 'Operator, machine: channelling (mine)', 'Operator, machine: cutting (mine)', 'Operator, machine: drilling (mine)', 'Operator, machine: drilling (quarry)', 'Operator, machine: mining (continuous)', 'Operator, mining plant', 'Piler, mine', 'Quarrier', 'Robber, timber: mine', 'Worker, timbering: mine', 'Worker, timbering: quarry', 'Worker, timbering: underground'],
