    #[Isco08Info(
        level: 4,
        code: '8112',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '811',
        unit_group: '8112',
        title: 'Mineral and Stone Processing Plant Operators',
        definition: 'Mineral and stone processing plant operators operate and monitor machinery and equipment for processing rocks, minerals and stone to recover refined products for immediate use or further processing.',
        tasks_include: "Tasks include -\n(a)  setting up and operating stationary plant and machinery which grind, crush, cut, saw and slice rocks, minerals and stones according to the specifications for the job;\n(b)  positioning blocks and slabs of stone onto machines for sawing, cutting and further working;\n(c)  monitoring and maintaining the flow of unprocessed rocks, minerals and stones from conveyors into machines;\n(d)  operating washing, separating, leaching, precipitating, filtering, extracting and combining equipment to remove waste material and recover minerals;\n(e)  combining mineral ores with solvents to facilitate further processing;\n(f)  separating metal and mineral concentrates from ore and alluvial deposits by thickening, flotation, gravity separation, filtration, and or magnetic and electrostatic separation;\n(g)  observing meters, gauges and control panels, and adjusting valves and controls to ensure the safe and efficient operation of equipment, and detecting malfunctions, and assisting with plant and machinery maintenance and repair;\n(h)  examining processed materials visually or with hands to ensure compliance with established standards and job specifications, and collecting samples for testing in laboratories;\n(i)  recording information about processing completed during shifts, such as quantities, types and dimensions of materials produced;\n(j)  sorting, stacking and moving processed minerals and stone for packaging, further processing or shipping.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Stone cutter (hand or hand-powered tools) – 7113\n- Stonemason - 7113\n- Stone polisher (hand or hand-powered tools) - 7113\n- Stone splitter (hand or hand-powered tools) - 7113 \n- Machine operator (cast stone production) - 8114\n- Stone polishing machine operator - 8114",
        notes: null,
        occupational_titles: ['Operator, breaker: gyratory', 'Operator, cone: mine', 'Operator, crusher: mineral or stone processing', 'Operator, gravitation equipment: mine', 'Operator, machine: crushing (coal)', 'Operator, machine: crushing (mineral ore)', 'Operator, machine: crushing (rock)', 'Operator, machine: crushing (stone)', 'Operator, machine: cutting (stone)', 'Operator, machine: drilling (stone)', 'Operator, machine: grinding (stone)', 'Operator, machine: magnetic ore processing', 'Operator, machine: milling (minerals)', 'Operator, machine: milling (stone)', 'Operator, machine: mineral processing', 'Operator, machine: planing (stone)', 'Operator, machine: pulverising (minerals)', 'Operator, machine: sawing (stone)', 'Operator, machine: splitting (stone)', 'Operator, machine: stone cutting or processing', 'Operator, machine: washing (minerals)', 'Operator, mineral-processing plant', 'Operator, stone-processing plant', 'Precipitator, gold', 'Precipitator, silver', 'Tender, jig', 'Washer, coal', 'Worker, cyanide: separation equipment', 'Worker, flotation: mineral processing'],
        parent: '811',
        ancestors: ['8', '81', '811'],
        children: [],
        descendants: [],
    )]
    case ISCO08_8112 = '8112';

    #[Isco08Info(
        level: 4,
        code: '8113',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '811',
        unit_group: '8113',
        title: 'Well Drillers and Borers and Related Workers',
        definition: 'Well drillers and borers and related workers position, assemble and operate drilling machinery and related equipment to sink wells, extract rock samples, liquids and gases or for a variety of other purposes.',
        tasks_include: "Tasks include -\n(a)  dismantling, moving and assembling drilling rigs and auxiliary equipment;\n(b)  assembling and dismantling pipes, casings and drill heads, and replacing dysfunctional equipment;\n(c)  operating controls to lower and raise drill pipes and casings in and out of wells, regulate pressure in the well and control the speed of tools;\n(d)  preparing drilling fluid and checking the operation of pumps to ensure adequate circulation of fluid in drill pipe and well;\n(e)  monitoring gauges and other indicators and listening to equipment to detect malfunctions and unusual well conditions, and determining the need to change drilling or equipment;\n(f)  maintaining, adjusting, repairing and cleaning drilling rigs, hoisting and other machinery;\n(g)  maintaining records of drilling and servicing operations;\n(h)  operating machines and tools to extract dust, cuttings and lost and broken drilling equipment from holes and wells;\n(i)  closing and sealing wells no longer in use;\n(j)  supervising and training crew members.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Blaster - 7542\n- Miner - 8111\n- Quarrier - 8111",
        notes: null,
        occupational_titles: ['Borer, well', 'Derrickman', 'Derrickwoman', 'Digger, well', 'Driller, developmental', 'Driller, directional', 'Driller, oil or gas well', 'Operator, boring equipment: wells', 'Operator, derrick', 'Operator, drilling equipment: wells', 'Operator, drilling plant', 'Operator, drilling rig', 'Operator, earth-boring machinery: construction', 'Operator, power-tong', 'Operator, pulling equipment: oil and gas wells', 'Sampler, core', 'Sinker, bore', 'Sinker, well', 'Toolpusher', 'Tourpusher'],
        parent: '811',
        ancestors: ['8', '81', '811'],
        children: [],
        descendants: [],
    )]
    case ISCO08_8113 = '8113';

    #[Isco08Info(
        level: 4,
        code: '8114',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '811',
        unit_group: '8114',
        title: 'Cement, Stone and Other Mineral Products Machine Operators',
        definition: 'Cement, stone and other mineral products machine operators monitor and operate machines for manufacturing and finishing precast concrete, bitumen and stone products, and making cast stone for building purposes.',
        tasks_include: "Tasks include -\n(a)  operating extrusion, moulding, mixing, pumping, compacting, grinding and cutting machinery to manufacture and finish precast concrete and stone products;\n(b)  operating plant to produce cement, lime and clinker, including loading and unloading ingredients and operating continuous feed equipment such as pumps and conveyors;\n(c)  operating plant and machines which weigh and mix sand, gravel, cement, water and other ingredients to make concrete;\n(d)  operating plant and machinery which assembles and fills moulds with concrete and artificial stone mixtures, removes castings from moulds and finishes surfaces of precast products;\n(e)  cutting, grinding, drilling, sandblasting and polishing concrete products and stone blocks, slabs and products to the specifications for the job;\n(f)  checking production plans and specifications to determine and select materials, ingredients, procedures, components, settings and adjustments for extrusion, moulding, mixing and compacting machines;\n(g)  monitoring plant and machines during operation by observing instruments such as temperature and pressure gauges, and adjusting controls and reporting malfunctions as necessary;\n(h)  collecting and examining samples of mixtures and finished products for conformity to specifications and adjusting machine settings accordingly;\n(i)  checking and maintaining production records, including information about quantities, dimensions and types of materials and goods produced;\n(j)  arranging and assisting with plant and machinery maintenance and repair.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Stone polisher (hand or hand-powered tools) - 7113\n- Stone processing machine operator - 8112\n- Extruding clay press operator - 8181\n- Kiln operator (brick, pottery or tiles) - 8181",
        notes: 'Examples of products produced by operators of plant and machines in this unit group include: mixed concrete for use in civil engineering and construction projects, flagstones, concrete bricks and tiles, fencing posts, moulded pipe sections and trench liners, concrete railway sleepers, walling and partition slabs, building components, cable conduits, fume and dust extraction conduits, abrasive wheels and outdoor furniture.',
        occupational_titles: ['Cutter-polisher, industrial diamonds', 'Operator, concrete-mixing plant', 'Operator, lathe: stoneworking', 'Operator, machine: abrasive-coatings production', 'Operator, machine: artificial stone products', 'Operator, machine: asbestos-cement products', 'Operator, machine: carving (stone products)', 'Operator, machine: cast-concrete products', 'Operator, machine: cast-stone products', 'Operator, machine: cement products', 'Operator, machine: concrete production', 'Operator, machine: cutting (industrial diamonds)', 'Operator, machine: cutting (mosiac)', 'Operator, machine: cutting (stone products)', 'Operator, machine: engraving (stone)', 'Operator, machine: finishing (concrete)', 'Operator, machine: finishing (stone)', 'Operator, machine: industrial-diamond production', 'Operator, machine: mineral products', 'Operator, machine: polishing (industrial diamond)', 'Operator, machine: polishing (stone)', 'Operator, machine: stone products', 'Polisher, industrial diamonds', 'Sawyer, industrial diamonds'],
        parent: '811',
        ancestors: ['8', '81', '811'],
        children: [],
        descendants: [],
    )]
    case ISCO08_8114 = '8114';

    #[Isco08Info(
