    #[Isco08Info(
        level: 4,
        code: '8151',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '815',
        unit_group: '8151',
        title: 'Fibre Preparing, Spinning and Winding Machine Operators',
        definition: 'Fibre-preparing, spinning and winding machine operators operate and monitor machines which prepare fibres, and spin, double, twist and wind yarn and thread from natural textile fibres. They twist two or more strands of yarn to prepare single stronger, smoother, uniform and heavier strands, and treat textiles to make them stiff and water resistant.',
        tasks_include: "Tasks include -\n(a)  operating and monitoring machines for tearing woollen rags into fibre;\n(b)  operating and monitoring machines for cleaning and turning woollen yarn waste into fluffed wool;\n(c)  operating and monitoring machines which combine textile fibres into uniform blends;\n(d)  operating and monitoring machines which clean and fluff textile fibres, transform them into sliver, comb them into sliver for first drawing, combine slivers into sliver lap or sliver laps into ribbon lap;\n(e)  operating draw frame (machine) having number of drawing sets, each set combining several slivers into one of nearly same weight and thickness as any of original sliver;\n(f)  operating and monitoring machines which spin thread and yarn from roving, wind two or more threads onto bobbin, twist two or more strands of yarn or thread into single strands of yarn to increase strength, smoothness and\/or uniformity of yarn, or wind yarn or thread from one package to another;\n(g)  operating and monitoring spinning frame that draws out and twists roving or sliver into yarn;\n(h)  operating and monitoring machines for drawing slivers received from drawing machine into loosely twisted strands;\n(i)  preparing sizing for use in stiffening and finishing cloth and yarn by mixing ingredients such as starch, tallow, resins, soaps with water and boiling mixture for specified time in steam;\n(j)  treating textiles with chemicals to make them water resistant;\n(k) cleaning rollers and cylinders of carding machines to remove wool waste; \n(l)  operating and resurfacing metal drawing rolls of various spinning, combing and lapping machines with new rubber or leather covers.",
        excluded_occupations: null,
        notes: null,
        occupational_titles: ['Baller, thread and yarn', 'Conditioner, yarn', 'Operator, machine: blending (textile fibres)', 'Operator, machine: combing (fibres)', 'Operator, machine: doubling (thread and yarn)', 'Operator, machine: drawing-frame (textile fibres)', 'Operator, machine: fibre preparing', 'Operator, machine: lapping (ribbon)', 'Operator, machine: lapping (sliver)', 'Operator, machine: lapping (textile fibres)', 'Operator, machine: reeling (thread and yarn)', 'Operator, machine: roving-frame (textile fibres)', 'Operator, machine: skeining (thread and yarn)', 'Operator, machine: spinning (synthetic fibre)', 'Operator, machine: spinning (thread and yarn)', 'Operator, machine: spooling (thread and yarn)', 'Operator, machine: textile fibre preparing', 'Operator, machine: twining (thread and yarn)', 'Operator, machine: twisting (thread and yarn)', 'Operator, machine: washing (textile fibres)', 'Operator, machine: winding (thread and yarn)'],
        parent: '815',
        ancestors: ['8', '81', '815'],
        children: [],
        descendants: [],
    )]
    case ISCO08_8151 = '8151';

    #[Isco08Info(
        level: 4,
        code: '8152',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '815',
        unit_group: '8152',
        title: 'Weaving and Knitting Machine Operators',
        definition: 'Weaving and knitting machine operators set up, operate and monitor weaving and knitting machines which process yarn or thread into woven, non-woven and knitted products such as cloth, lace, carpets, industrial fabric, hosiery and knitted garments or to quilt and embroider fabric.',
        tasks_include: "Tasks include -\n(a)  setting up and operating batteries of automatic, link-type knitting machines to knit garments of specified pattern and design;\n(b)  threading yarn, thread and fabric through guides, needles, and rollers of machines for weaving, knitting or other processing;\n(c)  tending automatic looms that simultaneously weave pile yarn, filling yarn and warp yarn material to produce carpets and rugs with various coloured designs;\n(d)  operating and monitoring loom on which yarn or twist is intersected and knotted at regular intervals to form mesh;\n(e)  operating and monitoring large automatic multi-needle machines to embroider material or to sew lengths of several layers of material to make yard goods, quilts or mattress coverings;\n(f)  tending circular knitting machines with automatic pattern controls that knit seamless hose;\n(g)  operating and monitoring knitting machines to knit hosiery to shape of foot and leg;\n(h)  operating and monitoring machine for knitting heel and toes of socks into ribs or tops cut from circular fabric;\n(i)  operating and monitoring machine which seams openings in toes of socks;\n(j)  operating and monitoring crochet machine to knit lace, trimming etc. of desired pattern or design;\n(k)  examining looms to determine causes of loom stoppage, such as warp filling, harness breaks or mechanical defects;\n(l)  repairing or replacing worn or defective needles and other components;\n(m)  cleaning, oiling, and lubricating machines, using air hoses, cleaning solutions, rags, oil cans, and\/or grease guns.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Carpet weaver - 7318\n- Cloth weaver - 7318\n- Knitter - 7318",
        notes: null,
        occupational_titles: ['Cutter, jacquard card', 'Drawer-in, textile weaving', 'Fixer, loom', 'Lacer, jacquard card', 'Operator, loom: carpet weaving', 'Operator, loom: jacquard', 'Operator, loom: lace production', 'Operator, machine: carpet production', 'Operator, machine: cloth production', 'Operator, machine: crocheting', 'Operator, machine: drawing-in (textile weaving)', 'Operator, machine: knitting', 'Operator, machine: lace production', 'Operator, machine: net production', 'Operator, machine: threading (loom)', 'Operator, machine: warping beam (textile weaving)', 'Operator, machine: weaving', 'Operator, machine: weaving (carpets)', 'Operator, machine: weaving (fabrics)', 'Operator, machine: weaving (jacquard)', 'Operator, machine: weaving (laces)', 'Setter, knitting-machine', 'Setter, loom', 'Threader, loom: machine'],
        parent: '815',
