    case ISCO08_8152 = '8152';

    #[Isco08Info(
        level: 4,
        code: '8153',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '815',
        unit_group: '8153',
        title: 'Sewing Machine Operators',
        definition: 'Sewing machine operators monitor and operate sewing machines to make, repair, darn and renovate textile, fur, synthetic or leather garments or embroider ornamental designs on garments or other materials. They operate buttonhole making and eyelet holing machines to cut holes, stitch around holes, stitch buttons and fix eyelets to garments.',
        tasks_include: "Tasks include -\n(a)  operating or tending sewing machines to perform garment sewing operations, such as joining, reinforcing, seaming or decorating garments or garment parts;\n(b)  attaching buttons, hooks, zippers, fasteners or other accessories to fabric, using feeding hoppers or clamp holders;\n(c)  tending semiautomatic sewing machines with multiple-sewing heads controlled by pattern chain that embroiders various designs on garments;\n(d)  operating machines, such as single or double needle sergers and flat-bed felling machines to automatically join, reinforce, or decorate material or articles;\n(e)  operating fur sewing machines to join fur pelt strips to required size and shape and join pelts into garment sections or shells;\n(f)  operating stitching machines to sew leather parts together for leather garments, handbags , gloves or similar items;\n(g)  monitoring machine operation to detect problems such as defective stitching, breaks in thread, or machine malfunctions;\n(h)  performing equipment maintenance tasks such as replacing needles.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Textile handicraft worker - 7318\n- Furrier – 7531\n- Tailor – 7531\n- Embroiderer - 7533\n- Sewer - 7533",
        notes: null,
        occupational_titles: ['Machinist, sewing', 'Operator, machine: embroidery', 'Operator, machine: sewing'],
        parent: '815',
        ancestors: ['8', '81', '815'],
        children: [],
        descendants: [],
    )]
    case ISCO08_8153 = '8153';

    #[Isco08Info(
        level: 4,
        code: '8154',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '815',
        unit_group: '8154',
        title: 'Bleaching, Dyeing and Fabric Cleaning Machine Operators',
        definition: 'Bleaching, dyeing and fabric cleaning machine operators operate and monitor machines that bleach, shrink, dye and otherwise treat fibres, yarn or cloth.',
        tasks_include: "Tasks include -\n(a)  starting and controlling machines and equipment to bleach, dye or otherwise process and finish fabric, yarn, thread and\/or other textile goods;\n(b)  tending machines that shrink woven or knitted cloth to predetermined size or strengthen the weave by interlocking the fibres;\n(c)  tending a variety of automatic machines that comb and polish furs;\n(d)  operating and monitoring machines that treat silk to give it body and weight;\n(e)  operating and monitoring machines that impregnate textiles with chemicals to render them waterproof;\n(f)  dyeing articles to change or restore their colours;\n(g)  operating and monitoring machines that stretch or impart lustre or other type of finish to textiles;\n(h)  tending and regulating equipment that fumigates and removes foreign matter from furs;\n(i)  operating machines that comb, dry and polish furs, and clean, sterilize and fluff feathers and blankets;\n(j)  keying in processing instructions to programme electronic equipment;\n(k)  observing display screens, control panels, equipment, and cloth entering or exiting processes to determine if equipment is operating correctly;\n(l)  cleaning machine filters and lubricating equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Textile printer - 7322\n- Laundry machine operator - 8157\n- Hand launderer - 9121\n- Hand presser - 9121",
