    #[Isco08Info(
        level: 4,
        code: '8155',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '815',
        unit_group: '8155',
        title: 'Fur and Leather Preparing Machine Operators',
        definition: 'Fur and leather preparing machine operators monitor and operate various machines that prepare leather or treat fur- or wool-bearing pelts. They trim, scrape, clean, tan, buff and dye animal hides, pelts or skins to produce leather stock and finished furs.',
        tasks_include: "Tasks include -\n(a)  operating and monitoring machines which remove flesh and fat from hides or pelts to clean and soften them prior to processing;\n(b)  operating and monitoring machines which remove long coarse hair from fur pelts, trim hair to even length and dye, stretch and smooth dressed pelts;\n(c)  operating and monitoring machines to remove epidermis hair roots, pigment cells and lime salts from grain side of skin;\n(d)  operating and monitoring machines to reduce thickness of hide or skin to uniform size;\n(e)  operating and monitoring machines to polish or roughen hides or skins to specified finishes;\n(f)  operating and monitoring machines which separate residual wool from skins, or flesh and hair from hides;\n(g)  operating and monitoring machines in which hides are split edgeways to form two or more pieces or to give uniform thickness;\n(h)  operating and monitoring machines which treat hides and skins in solutions to convert them into leather;\n(i)  treating surface of leather with oil and operating glazing machine to give glossy finishes to leather;\n(j)  operating and monitoring machines which apply dyes and stains to leather\n(k)  maintaining and repairing vats and other machinery",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Pelt dyer - 7535\n- Tanner - 7535",
        notes: null,
        occupational_titles: ['Operator, machine: cutting (leather)', 'Operator, machine: dehairing (hide)', 'Operator, machine: finishing (pelt)', 'Operator, machine: fleshing (hide)', 'Operator, machine: fleshing (pelt)', 'Operator, machine: fur preparing', 'Operator, machine: hide processing', 'Operator, machine: leather preparing', 'Operator, machine: leather sewing', 'Operator, machine: mixing (fur fibre)', 'Operator, machine: pelt processing', 'Operator, machine: staining (leather)', 'Operator, machine: tanning', 'Operator, machine: washing (hide)'],
