    #[Isco08Info(
        level: 4,
        code: '8171',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '817',
        unit_group: '8171',
        title: 'Pulp and Papermaking Plant Operators',
        definition: 'Pulp and papermaking plant operators operate and monitor equipment to process wood, pulp and other cellulose materials in the production of pulp and to produce coat and finish paper.',
        tasks_include: "Tasks include -\n(a)  operating and monitoring screening and bleaching equipment, digesters, mixing tanks, washers and other pulp processing machinery and equipment to carry out one or more cellulose processing steps; \n(b)  operating and monitoring papermaking and finishing process machinery and equipment to dry, calender, laminate, coat, slit, trim, wind or carry out other papermaking and finishing process steps;\n(c)  controlling start-up and shut-down of machinery and equipment, and observing equipment and machinery panel indicators, gauges, and other equipment to detect machinery and equipment malfunctions and ensure process steps are carried out according to specifications;\n(d) communicating with process control operators to make process adjustments and start up or shut down machinery and equipment as required;\n(e)  analysing instrument readings and production test samples and making adjustments to production process and equipment as required;\n(f)  mounting, positioning and threading paper rolls using a hoist;\n(g)  inspecting paper visually for wrinkles, holes, discoloration, streaks or other defects and taking corrective action;\n(h)  completing and maintaining production reports.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Paper pulp refinery operator - 3139\n- Pulping control operator- 3139\n- Pulping technician - 3139",
        notes: null,
        occupational_titles: ['Calenderer, pulp and paper', 'Finisher, paper', 'Operator, beater: paper pulp', 'Operator, bleacher: paper', 'Operator, boiler: paper pulp', 'Operator, calender: pulp and paper', 'Operator, combiner: paper production', 'Operator, digester: paper pulp', 'Operator, grinder: pulp and paper', 'Operator, machine: cardboard production', 'Operator, machine: coating (paper)', 'Operator, machine: papermaking', 'Operator, machine: pulping (wood)', 'Operator, machine: wood grinding (pulpmaking)', 'Operator, papermaking plant', 'Operator, press: hardboard', 'Operator, repulper', 'Operator, screener: paper pulp', 'Operator, sheeter: pulp and paper', 'Operator, supercalender'],
