    #[Isco08Info(
        level: 4,
        code: '8172',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '817',
        unit_group: '8172',
        title: 'Wood Processing Plant Operators',
        definition: 'Wood processing plant operators monitor, operate, and control lumber mill equipment for sawing timber logs into rough lumber, cutting veneer, making plywood and particle board, and otherwise preparing wood for further use.',
        tasks_include: "Tasks include -\n(a)  examining logs and rough lumber to determine size, condition, quality and other characteristics to decide best lumber cuts to carry out, or operating automated equipment to convey logs through laser scanners which determine the most productive and profitable cutting patterns;\n(b)  operating and monitoring log in-feed and conveyor systems;\n(c)  operating and monitoring head saws, resaws and multiblade saws to saw logs, cants, flitches, slabs or wings and remove rough edges from sawn timber into dressed lumber of various sizes, and saw or split shingles and shakes; \n(d)  operating and monitoring plywood core-laying machines and hot-plate plywood presses and machines which cut veneer;\n(e)  cleaning and lubricating sawmill equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Timber treating tank operator - 7521\n- Veneer dryer tender - 7521\n- Wood working machine operator - 7523",
        notes: null,
        occupational_titles: ['Assembler, plywood panel', 'Operator, barker', 'Operator, chipper: wood', 'Operator, cut-off: log', 'Operator, cut-off saw', 'Operator, lathe: cutting (veneer)', 'Operator, lathe: cutting (wood)', 'Operator, lathe: veneer', 'Operator, machine: boring (wood)', 'Operator, machine: chipping (wood)', 'Operator, machine: cutting (veneer)', 'Operator, machine: cutting (wood)', 'Operator, machine: milling (wood)', 'Operator, machine: plywood core laying', 'Operator, machine: sawing (wood)', 'Operator, machine: shaping (wood)', 'Operator, machine: shaving (wood)', 'Operator, machine: wood processing', 'Operator, planer: sawmill', 'Operator, press: plywood', 'Operator, press: veneer', 'Operator, press: waferboard', 'Operator, saw: circular', 'Operator, sawmill', 'Operator, trimmer: sawmill', 'Operator, wood-processing plant', 'Press-operator, plywood', 'Sawyer, edge', 'Sawyer, sawmill', 'Sawyer, wood processing plant'],
