    #[Isco08Info(
        level: 4,
        code: '8181',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '818',
        unit_group: '8181',
        title: 'Glass and Ceramics Plant Operators',
        definition: 'Glass and ceramics plant operators operate and monitor kilns, furnaces and other machinery and equipment used in the manufacture of glass, ceramics, porcelain, tiles or bricks. They operate machines to anneal, harden or decorate glass and ceramics.',
        tasks_include: "Tasks include -\n(a)  operating and monitoring glass-making furnaces to make glass by melting and fusing pre-mixed ingredients;\n(b)  tending hot- or cold-end spray equipment used to coat glassware with surface hardener;\n(c)  operating and maintaining machines that press or blow molten glass in moulds to form or shape containers, such as bottles, jars and drinking glasses;\n(d)  operating hand press to mould glass into required shape;\n(e)  operating drawing kiln to process molten glass into continuous sheet of flat glass;\n(f)  operating and monitoring floating-glass production plant;\n(g)  operating and maintaining finishing machines to grind, drill, sand, bevel, decorate, wash or polish glass or glass products; \n(h)  setting and operating press machines to mould ceramic articles from moist clay;\n(i)  operating machines to mix clay with water to knead it into a suitable plastic condition or semi-liquid form for making ceramic products;\n(j)  operating and monitoring kilns which bake pottery, porcelain ware bricks and tiles;\n(k)  operating and monitoring machines for making glaze or abrasives;\n(l)  operating and monitoring machines which extrude molten glass to form fibreglass filaments;\n(m)  observing finished products to identify splits, cracks, breaks, colour and other imperfections.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Brick and tile moulder - 7314\n- Glass blower- 7315\n- Glass cutter -7315",
        notes: null,
        occupational_titles: ['Operator, die-press: pottery and porcelain', 'Operator, furnace: annealing (glass)', 'Operator, furnace: glass production', 'Operator, furnace: lehr', 'Operator, furnace: smelting (glass)', 'Operator, furnace: tempering (glass)', 'Operator, kiln: biscuit (pottery and porcelain)', 'Operator, kiln: biscuit (tile)', 'Operator, kiln: brick', 'Operator, kiln: dry (brick and tile)', 'Operator, kiln: dry (pottery and porcelain)', 'Operator, kiln: float-glass bath', 'Operator, kiln: frit', 'Operator, kiln: glost (pottery and porcelain)', 'Operator, kiln: glost (tile)', 'Operator, kiln: oven (brick and tile)', 'Operator, kiln: oven (pottery and porcelain)', 'Operator, kiln: porcelain', 'Operator, kiln: pottery', 'Operator, kiln: retort (brick and tile)', 'Operator, kiln: tile', 'Operator, ladle: glass', 'Operator, machine: bending (glass)', 'Operator, machine: blowing (glass)', 'Operator, machine: casting (pottery and porcelain)', 'Operator, machine: ceramics production', 'Operator, machine: clay slips production', 'Operator, machine: cutting (glass)', 'Operator, machine: drawing (glass)', 'Operator, machine: drilling (glass)', 'Operator, machine: drilling (pottery)', 'Operator, machine: engraving (glass)', 'Operator, machine: etching (glass)', 'Operator, machine: finishing (glass)', 'Operator, machine: glass-fibre production', 'Operator, machine: glass bottle production', 'Operator, machine: glass production', 'Operator, machine: glass products', 'Operator, machine: glass rod production', 'Operator, machine: glass tube production', 'Operator, machine: glaze production', 'Operator, machine: grinding (clay)', 'Operator, machine: grinding (glass)', 'Operator, machine: grinding (glaze)', 'Operator, machine: mixing (abrasives)', 'Operator, machine: mixing (clay)', 'Operator, machine: mixing (glass)', 'Operator, machine: mixing (glaze)', 'Operator, machine: moulding (glass)', 'Operator, machine: painting (ceramics)', 'Operator, machine: painting (glass)', 'Operator, machine: plating (glass)', 'Operator, machine: polishing (glass)', 'Operator, machine: polishing (glass lens)', 'Operator, machine: polishing (plate-glass)', 'Operator, machine: pottery and porcelain production', 'Operator, machine: pressing (glass)', 'Operator, machine: rolling (plate-glass)', 'Operator, machine: tempering (glass)', 'Operator, press: extruding (clay)', 'Operator, press: filtering (clay)', 'Operator, pug-mill: clay', 'Operator, sandblasting equipment: glass'],
