    #[Isco08Info(
        level: 4,
        code: '8182',
        major_group: '8',
        sub_major_group: '81',
        minor_group: '818',
        unit_group: '8182',
        title: 'Steam Engine and Boiler Operators',
        definition: 'Steam engine and boiler operators maintain and operate various types of steam engines, boilers, turbines and auxiliary equipment to provide power and other utility services for commercial, industrial and institutional buildings, at work sites and aboard ships or self-propelled vessels.',
        tasks_include: "Tasks include -\n(a)  operating, cleaning, lubricating and monitoring steam engines, boilers and auxiliary equipment such as pumps, compressors and air-conditioning equipment to supply and maintain steam and power for buildings, marine vessels or pneumatic tools;\n(b)  analysing and recording instrument readings, troubleshooting and performing minor repairs to prevent equipment or system failure; \n(c)  monitoring and inspecting performance of equipment for efficient operation and ensuring boiler water, chemical, and fuel are maintained at required levels;\n(d)  firing coal furnaces by hand or with stokers and gas- or oil-fed boilers, using automatic gas feeds or oil pumps;\n(e)  testing boiler water quality or arrange for testing, adjusting and taking necessary corrective action, such as adding chemicals to prevent corrosion and harmful deposits;\n(f)  monitoring ship’s engine, machinery and equipment indicators, recording variables and reporting abnormalities to ship’s engineer officer on watch;\n(g)  operating and maintaining off-loading liquid pumps and valves.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Ship's engineer - 3151\n- Stationary engine fitter - 7233",
        notes: null,
        occupational_titles: ['Engineer, stationary', 'Fireman, boiler plant', 'Fireman, locomotive boiler', "Fireman, ship's boiler", 'Firewoman, boiler plant', 'Firewoman, locomotive boiler', "Firewoman, ship's boiler", 'Operator, boiler: locomotive', "Operator, boiler: ships'", 'Operator, boiler plant: steam', 'Operator, steam engine', 'Stoker, ship', 'Tender, boiler'],
        parent: '818',
        ancestors: ['8', '81', '818'],
        children: [],
        descendants: [],
    )]
    case ISCO08_8182 = '8182';

