    #[Isco08Info(
        level: 4,
        code: '9215',
        major_group: '9',
        sub_major_group: '92',
        minor_group: '921',
        unit_group: '9215',
        title: 'Forestry Labourers',
        definition: 'Forestry labourers perform simple and routine tasks to cultivate and maintain natural and plantation forests, and log, fell and saw trees.',
        tasks_include: "Tasks include -\n(a)  digging holes for tree planting;\n(b)  stacking and loading logs and timber;\n(c)  clearing undergrowth in forest stands and thinning young plantations;\n(d)  maintaining look-out for fires in forests;\n(e)  removing major branches and tree tops, trimming branches and sawing trunks into logs;\n(f)  operating and maintaining manual and hand-held machine saws to fell trees and cut felled trees and branches into logs;\n(g)  collecting seeds, and planting seedlings;\n(h)  performing minor repairs and maintenance of forest roads, buildings, facilities, and equipment.",
        excluded_occupations: "Some related occupations classified elsewhere:\n- Forestry worker (skilled) - 6210",
        notes: null,
        occupational_titles: ['Axeman', 'Axewoman', 'Chokerman', 'Chokerwoman', 'Clearer, tree', 'Climber, tree', 'Labourer, forestry', 'Planter, tree', 'Stacker, timber: forestry', 'Stump-grubber', 'Swamper, logging', 'Worker, timber: forestry'],
