    #[Isco08Info(
        level: 4,
        code: '9520',
        major_group: '9',
        sub_major_group: '95',
        minor_group: '952',
        unit_group: '9520',
        title: 'Street Vendors (excluding Food)',
        definition: 'Street vendors (excluding food) sell a usually limited range of goods (excluding food for immediate consumption) in streets and public places such as stations, cinemas or theatres.',
